# 统一缓存入口。保留这些函数名，避免改动现有业务调用方。
# 测试和开发工具仍可通过 _memory_cache 清理本地 L1 缓存。
_memory_cache = cache_backend.memory_cache


def cache_get(key: str):
    return cache_backend.get(key)


def cache_set(key: str, value: str, ex: int = 60):
    # 认证状态和验证码必须严格遵循配置 TTL，其它热点数据允许抖动，
    # 避免大量键在同一秒同时失效。
    no_jitter = str(key).startswith(("auth:", "oauth:", "blacklist:"))
    return cache_backend.set(key, value, ex=ex, jitter=not no_jitter)


def cache_delete(key: str):
    return cache_backend.delete(key)


_CACHE_JSON_MISS = object()


def _cache_json_get(key: str, expected_type=None):
    raw = cache_get(key)
    if not raw:
        return _CACHE_JSON_MISS
    try:
        payload = json.loads(raw)
    except Exception:
        cache_delete(key)
        return _CACHE_JSON_MISS
    if expected_type is not None and not isinstance(payload, expected_type):
        cache_delete(key)
        return _CACHE_JSON_MISS
    return payload


def _stale_cache_payload(payload):
    if isinstance(payload, dict):
        return {**payload, "stale": True, "cache_state": "stale"}
    return payload


def _coalesced_cached_json(
    cache_key: str,
    loader: Callable[[], Any],
    *,
    ttl: int,
    stale_ttl: int,
    expected_type=None,
    lock_timeout: int = 30,
    wait_timeout: float = 1.5,
    busy_message: str = "系统数据正在刷新，请稍后重试",
):
    """Serve cached JSON while one process refreshes a shared hot value."""
    cached = _cache_json_get(cache_key, expected_type)
    if cached is not _CACHE_JSON_MISS:
        return cached

    stale_key = f"{cache_key}:stale"
    with cache_backend.lock(cache_key, timeout=lock_timeout) as acquired:
        if not acquired:
            stale = _cache_json_get(stale_key, expected_type)
            if stale is not _CACHE_JSON_MISS:
                return _stale_cache_payload(stale)
            filled = cache_backend.wait_for_value(
                cache_key,
                timeout=wait_timeout,
            )
            if filled:
                try:
                    payload = json.loads(filled)
                    if expected_type is None or isinstance(payload, expected_type):
                        return payload
                except Exception:
                    pass
            raise HTTPException(status_code=503, detail=busy_message)

        # Another thread in this process may have filled the value before the
        # local fallback lock was acquired.
        cached = _cache_json_get(cache_key, expected_type)
        if cached is not _CACHE_JSON_MISS:
            return cached
        try:
            payload = loader()
        except Exception:
            stale = _cache_json_get(stale_key, expected_type)
            if stale is not _CACHE_JSON_MISS:
                return _stale_cache_payload(stale)
            raise
        if expected_type is not None and not isinstance(payload, expected_type):
            raise ValueError(f"cache loader returned invalid type for {cache_key}")
        serialized = json.dumps(payload, ensure_ascii=False, default=str)
        cache_set(cache_key, serialized, ex=max(1, int(ttl)))
        cache_set(
            stale_key,
            serialized,
            ex=max(int(ttl), int(stale_ttl)),
        )
        return payload


def model_to_jsonable(value: BaseModel) -> Dict[str, Any]:
    if hasattr(value, "model_dump"):
        return value.model_dump(mode="json")
    return value.dict()


QUEUE_ACTIVE_STATUSES = ("queued", "running", "retryable")


def _long_task_queue_depth(db: Session) -> int:
    """Count all durable jobs sharing the heavy-task worker capacity."""
    total = 0
    for model in (SmartResearchTask, AIInsightTask, RiskAssessmentTask, ScreenerTask):
        try:
            total += int(
                db.query(func.count(model.id))
                .filter(model.queue_status.in_(QUEUE_ACTIVE_STATUSES))
                .scalar()
                or 0
            )
        except Exception:
            # A legacy database may be between startup migrations. It is safer
            # to let the task-specific endpoint report its own failure than to
            # make the whole API unavailable during that short window.
            db.rollback()
    return total


def _lock_long_task_admission(db: Session) -> None:
    """Serialize queue-depth checks on PostgreSQL to prevent over-admission."""
    if str(engine.url.get_backend_name() or "").lower().startswith("postgres"):
        db.execute(text("SELECT pg_advisory_xact_lock(:lock_id)"), {"lock_id": 7482101})


def _celery_priority_for_user(user: UserModel) -> int:
    return max(0, min(9, int(queue_priority_for_role(getattr(user, "role", None)) // 5)))


