ALGORITHM = settings.JWT_ALGORITHM
ACCESS_TOKEN_EXPIRE_MINUTES = settings.ACCESS_TOKEN_EXPIRE_MINUTES

pwd_context = CryptContext(schemes=["pbkdf2_sha256"], deprecated="auto")
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")


def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


def verify_password(plain_password, hashed_password):
    try:
        return pwd_context.verify(plain_password, hashed_password)
    except UnknownHashError:
        # 兼容旧库中明文或非 passlib 哈希格式
        return plain_password == (hashed_password or "")


def get_password_hash(password):
    return pwd_context.hash(password)


def create_access_token(data: dict, expires_delta: Optional[timedelta] = None):
    to_encode = data.copy()
    if expires_delta:
        expire = datetime.utcnow() + expires_delta
    else:
        expire = datetime.utcnow() + timedelta(minutes=15)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)
    return encoded_jwt


def error_payload(code: str, message: str, details=None):
    return {"error": {"code": code, "message": message, "details": details}}


def serialize_error(code: str, message: str, details=None, status_code: int = 400):
    raise HTTPException(
        status_code=status_code,
        detail=error_payload(code=code, message=message, details=details),
    )


async def get_current_user(
    token: str = Depends(oauth2_scheme), db: Session = Depends(get_db)
):
    credentials_exception = HTTPException(
        status_code=401,
        detail="Could not validate credentials",
        headers={"WWW-Authenticate": "Bearer"},
    )
    # JWT 黑名单检查（Redis 可用时）
    if cache_get(f"blacklist:{token}"):
        raise credentials_exception
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username: str = payload.get("sub")
        if username is None:
            raise credentials_exception
    except JWTError:
        raise credentials_exception
    user = db.query(UserModel).filter(UserModel.username == username).first()
    if user is None:
        raise credentials_exception
    if _expire_elapsed_paid_subscription(db, user):
        db.commit()
        db.refresh(user)
    return user


def _optional_user_from_bearer(token: str, db: Session) -> Optional[UserModel]:
    token_value = str(token or "").strip()
    if not token_value or cache_get(f"blacklist:{token_value}"):
        return None
    try:
        payload = jwt.decode(token_value, SECRET_KEY, algorithms=[ALGORITHM])
        username = str(payload.get("sub") or "").strip()
    except JWTError:
        return None
    if not username:
        return None
    return db.query(UserModel).filter(UserModel.username == username).first()


def _optional_user_from_request(request: Request, db: Session) -> Optional[UserModel]:
    auth_header = str(request.headers.get("authorization") or "").strip()
    if not auth_header.lower().startswith("bearer "):
        return None
    return _optional_user_from_bearer(auth_header.split(" ", 1)[1], db)


