def normalize_user_role(role: Optional[str]) -> str:
    normalized = (role or "user").strip().lower()
    aliases = {
        "user": "normal",
        "free": "normal",
        "basic": "normal",
        "regular": "normal",
        "premium": "svip",
    }
    normalized = aliases.get(normalized, normalized)
    return normalized if normalized in ROLE_PERMISSIONS else "normal"


def permissions_for_role(role: Optional[str]) -> list[str]:
    normalized = normalize_user_role(role)
    return sorted(ROLE_PERMISSIONS.get(normalized, ROLE_PERMISSIONS["normal"]))


def _parse_permission_overrides(user: UserModel) -> Optional[list[str]]:
    raw_value = getattr(user, "permission_overrides_json", None)
    if not raw_value:
        return None
    try:
        parsed = json.loads(raw_value)
    except Exception:
        return None
    values = parsed.get("permissions") if isinstance(parsed, dict) else parsed
    if not isinstance(values, list):
        return None
    permissions = {
        str(item).strip()
        for item in values
        if isinstance(item, str) and str(item).strip() in PERMISSION_DEFINITIONS
    }
    if normalize_user_role(getattr(user, "role", None)) != "admin":
        permissions.difference_update(NON_ADMIN_FORBIDDEN_PERMISSIONS)
    return sorted(permissions)


def permissions_for_user(user: UserModel) -> list[str]:
    role = normalize_user_role(getattr(user, "role", None))
    if role == "admin":
        return permissions_for_role("admin")
    overrides = _parse_permission_overrides(user)
    if overrides is not None:
        return overrides
    return permissions_for_role(role)


def user_has_permission(user: UserModel, permission: str) -> bool:
    return permission in permissions_for_user(user)


def require_permission(permission: str):
    async def dependency(current_user: UserModel = Depends(get_current_user)):
        if not user_has_permission(current_user, permission):
            raise HTTPException(
                status_code=403,
                detail={
                    "code": "PERMISSION_DENIED",
                    "message": "当前账号没有访问该功能的权限",
                    "permission": permission,
                    "role": normalize_user_role(getattr(current_user, "role", None)),
                },
            )
        return current_user

    return dependency


def serialize_user_auth(user: UserModel) -> dict:
    role = normalize_user_role(getattr(user, "role", None))
    has_custom_permissions = bool(getattr(user, "permission_overrides_json", None)) and role != "admin"
    return {
        "id": user.id,
        "username": user.username,
        "email": user.email or "",
        "role": role,
        "permissions": permissions_for_user(user),
        "role_default_permissions": permissions_for_role(role),
        "has_custom_permissions": has_custom_permissions,
        "avatar_url": getattr(user, "avatar_url", None) or "",
    }


