def _utcnow() -> datetime:
    return datetime.utcnow()


def _as_naive_utc(value: Optional[datetime]) -> Optional[datetime]:
    if value is None:
        return None
    if value.tzinfo is None:
        return value
    return value.astimezone(timezone.utc).replace(tzinfo=None)


def _mask_secret(value: Optional[str], visible: int = 4) -> str:
    text_value = str(value or "").strip()
    if not text_value:
        return ""
    if len(text_value) <= visible * 2:
        return f"{text_value[:1]}****{text_value[-1:]}"
    return f"{text_value[:visible]}****{text_value[-visible:]}"


def _mask_url(value: Optional[str]) -> str:
    text_value = str(value or "").strip()
    if not text_value:
        return ""
    parsed = urlparse(text_value)
    if not parsed.scheme or not parsed.netloc:
        return _mask_secret(text_value, 6)
    return f"{parsed.scheme}://{parsed.netloc}/****"


def _json_loads_dict(raw: Optional[str], default: Optional[dict] = None) -> dict:
    if not raw:
        return dict(default or {})
    try:
        parsed = json.loads(raw)
    except Exception:
        return dict(default or {})
    return parsed if isinstance(parsed, dict) else dict(default or {})


def _get_system_setting_json(db: Session, key: str, default: Optional[dict] = None) -> dict:
    row = db.query(SystemSetting).filter(SystemSetting.key == key).first()
    return _json_loads_dict(row.value_json if row else None, default)


def _save_system_setting_json(db: Session, key: str, value: dict) -> dict:
    row = db.query(SystemSetting).filter(SystemSetting.key == key).first()
    if not row:
        row = SystemSetting(key=key)
        db.add(row)
    row.value_json = json.dumps(value, ensure_ascii=False, indent=2)
    db.commit()
    return value


