def _bounded_int(value: Any, default: int, minimum: int, maximum: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        parsed = default
    return max(minimum, min(maximum, parsed))


def _bounded_float(value: Any, default: float, minimum: float, maximum: float) -> float:
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        parsed = default
    return round(max(minimum, min(maximum, parsed)), 4)


def _sanitize_reward_external_provider_config(
    key: str,
    incoming_ads: dict,
    existing_ads: dict,
    *,
    preserve_masked: bool = True,
) -> dict:
    existing = existing_ads.get(key) if isinstance(existing_ads.get(key), dict) else {}
    incoming = incoming_ads.get(key) if isinstance(incoming_ads.get(key), dict) else {}
    callback_secret = str(
        incoming.get("callback_secret", existing.get("callback_secret", "")) or ""
    ).strip()
    if preserve_masked and "****" in callback_secret:
        callback_secret = str(existing.get("callback_secret") or "")
    launch_url = str(incoming.get("launch_url", existing.get("launch_url", "")) or "").strip()
    if launch_url:
        parsed_url = urlparse(launch_url)
        if parsed_url.scheme not in {"http", "https"} or not parsed_url.netloc:
            label = REWARD_AD_EXTERNAL_PROVIDER_LABELS.get(key, key)
            raise HTTPException(status_code=400, detail=f"{label} 广告跳转地址格式无效")
    return {
        "enabled": bool(incoming.get("enabled", existing.get("enabled", False))),
        "app_id": str(incoming.get("app_id", existing.get("app_id", "")) or "").strip()[:200],
        "placement_id": str(
            incoming.get("placement_id", existing.get("placement_id", "")) or ""
        ).strip()[:200],
        "launch_url": launch_url[:1000],
        "callback_secret": callback_secret[:500],
    }


def _reward_external_provider_ready(config: dict) -> bool:
    return bool(
        config
        and config.get("enabled")
        and config.get("placement_id")
        and config.get("launch_url")
        and config.get("callback_secret")
    )


def _sanitize_billing_settings(
    value: Optional[dict],
    *,
    current: Optional[dict] = None,
    preserve_masked: bool = True,
) -> dict:
    defaults = _default_billing_settings()
    raw = value if isinstance(value, dict) else {}
    existing = current if isinstance(current, dict) else {}
    credits_per_cny = _bounded_int(
        raw.get("credits_per_cny", existing.get("credits_per_cny")),
        defaults["credits_per_cny"],
        1,
        100000,
    )
    quarter_discount_pct = _bounded_float(
        raw.get("quarter_discount_pct", existing.get("quarter_discount_pct")),
        defaults["quarter_discount_pct"],
        0.0,
        80.0,
    )
    recharge_min_cents = _bounded_int(
        raw.get("recharge_min_cents", existing.get("recharge_min_cents")),
        defaults["recharge_min_cents"],
        100,
        10000000,
    )
    recharge_max_cents = _bounded_int(
        raw.get("recharge_max_cents", existing.get("recharge_max_cents")),
        defaults["recharge_max_cents"],
        recharge_min_cents,
        10000000,
    )
    preset_source = raw.get("recharge_presets_cents", existing.get("recharge_presets_cents"))
    presets = sorted(
        {
            _bounded_int(item, recharge_min_cents, recharge_min_cents, recharge_max_cents)
            for item in (preset_source or defaults["recharge_presets_cents"])
        }
    )[:8]

    existing_costs = existing.get("module_credit_costs") if isinstance(existing.get("module_credit_costs"), dict) else {}
    incoming_costs = raw.get("module_credit_costs") if isinstance(raw.get("module_credit_costs"), dict) else {}
    module_costs = {
        key: _bounded_int(
            incoming_costs.get(key, existing_costs.get(key, default_cost)),
            default_cost,
            0,
            1000000,
        )
        for key, default_cost in AI_CREDIT_COSTS.items()
    }

    existing_recharge = existing.get("credit_recharge") if isinstance(existing.get("credit_recharge"), dict) else {}
    incoming_recharge = raw.get("credit_recharge") if isinstance(raw.get("credit_recharge"), dict) else {}
    credit_recharge = {
        "enabled": bool(
            incoming_recharge.get(
                "enabled",
                existing_recharge.get("enabled", defaults["credit_recharge"]["enabled"]),
            )
        ),
    }

    existing_enterprise = existing.get("enterprise_plan") if isinstance(existing.get("enterprise_plan"), dict) else {}
    incoming_enterprise = raw.get("enterprise_plan") if isinstance(raw.get("enterprise_plan"), dict) else {}
    enterprise_plan = {
        "enabled": bool(
            incoming_enterprise.get(
                "enabled",
                existing_enterprise.get("enabled", defaults["enterprise_plan"]["enabled"]),
            )
        ),
    }

    existing_ads = existing.get("rewarded_ads") if isinstance(existing.get("rewarded_ads"), dict) else {}
    incoming_ads = raw.get("rewarded_ads") if isinstance(raw.get("rewarded_ads"), dict) else {}
    google_existing = existing_ads.get("google") if isinstance(existing_ads.get("google"), dict) else {}
    google_incoming = incoming_ads.get("google") if isinstance(incoming_ads.get("google"), dict) else {}
    external_providers = {
        key: _sanitize_reward_external_provider_config(
            key,
            incoming_ads,
            existing_ads,
            preserve_masked=preserve_masked,
        )
        for key in REWARD_AD_EXTERNAL_PROVIDER_ORDER
    }

    rewarded_ads = {
        "enabled": bool(incoming_ads.get("enabled", existing_ads.get("enabled", False))),
        "free_only": True,
        "reward_credits": _bounded_int(
            incoming_ads.get("reward_credits", existing_ads.get("reward_credits")),
            defaults["rewarded_ads"]["reward_credits"],
            1,
            10000,
        ),
        "daily_limit": _bounded_int(
            incoming_ads.get("daily_limit", existing_ads.get("daily_limit")),
            defaults["rewarded_ads"]["daily_limit"],
            1,
            50,
        ),
        "cooldown_seconds": _bounded_int(
            incoming_ads.get("cooldown_seconds", existing_ads.get("cooldown_seconds")),
            defaults["rewarded_ads"]["cooldown_seconds"],
            15,
            3600,
        ),
        "session_ttl_seconds": _bounded_int(
            incoming_ads.get("session_ttl_seconds", existing_ads.get("session_ttl_seconds")),
            defaults["rewarded_ads"]["session_ttl_seconds"],
            120,
            1800,
        ),
        "google": {
            "enabled": bool(google_incoming.get("enabled", google_existing.get("enabled", False))),
            "publisher_id": str(google_incoming.get("publisher_id", google_existing.get("publisher_id", "")) or "").strip()[:200],
            "ad_unit_path": str(google_incoming.get("ad_unit_path", google_existing.get("ad_unit_path", "")) or "").strip()[:300],
        },
        **external_providers,
    }
    if rewarded_ads["enabled"]:
        google_ready = bool(
            rewarded_ads["google"]["enabled"]
            and rewarded_ads["google"]["ad_unit_path"]
        )
        external_ready = any(
            _reward_external_provider_ready(rewarded_ads.get(key) or {})
            for key in REWARD_AD_EXTERNAL_PROVIDER_ORDER
        )
        if not google_ready and not external_ready:
            raise HTTPException(status_code=400, detail="启用奖励广告前至少配置一个可用广告商")

    return {
        "credits_per_cny": credits_per_cny,
        "quarter_discount_pct": quarter_discount_pct,
        "recharge_min_cents": recharge_min_cents,
        "recharge_max_cents": recharge_max_cents,
        "recharge_presets_cents": presets,
        "module_credit_costs": module_costs,
        "credit_recharge": credit_recharge,
        "enterprise_plan": enterprise_plan,
        "rewarded_ads": rewarded_ads,
    }


def _billing_settings(db: Session, masked: bool = False) -> dict:
    raw = _get_system_setting_json(db, BILLING_SETTINGS_KEY, _default_billing_settings())
    settings_value = _sanitize_billing_settings(raw, current=_default_billing_settings())
    if not masked:
        return settings_value
    result = json.loads(json.dumps(settings_value))
    rewarded_ads = result.get("rewarded_ads", {})
    for provider_key in REWARD_AD_EXTERNAL_PROVIDER_ORDER:
        provider = rewarded_ads.get(provider_key, {})
        if provider:
            provider["callback_secret"] = _mask_secret(provider.get("callback_secret"))
    return result


def _ai_credit_cost(db: Session, key: str) -> int:
    costs = _billing_settings(db).get("module_credit_costs") or {}
    return int(costs.get(key, AI_CREDIT_COSTS.get(key, 0)) or 0)


def _llm_role_rank(role: Optional[str]) -> int:
    return {"normal": 0, "vip": 1, "svip": 2, "admin": 99}.get(
        normalize_user_role(role), 0
    )


def _llm_model_tier_key(value: Any) -> Optional[str]:
    key = str(value or "").strip().lower()
    return LLM_MODEL_TIER_ALIASES.get(key)


def _llm_tier_multiplier(value: Any, default: float = 1.0) -> float:
    try:
        return round(max(0.1, min(float(value or default), 20.0)), 3)
    except (TypeError, ValueError):
        return default


def _default_llm_model_tiers(default_model: str = DEFAULT_LLM_MODEL, default_provider: str = "openai") -> dict:
    provider = _normalize_llm_provider(default_provider)
    model = str(default_model or DEFAULT_LLM_MODEL).strip() or DEFAULT_LLM_MODEL
    return {
        "smart": {
            **LLM_MODEL_TIER_LABELS["smart"],
            "provider": provider,
            "model": model,
            "multiplier": 1.0,
            "min_role": "normal",
            "enabled": True,
        },
        "advanced": {
            **LLM_MODEL_TIER_LABELS["advanced"],
            "provider": provider,
            "model": model,
            "multiplier": 1.25,
            "min_role": "vip",
            "enabled": True,
        },
        "ultra": {
            **LLM_MODEL_TIER_LABELS["ultra"],
            "provider": provider,
            "model": model,
            "multiplier": 1.75,
            "min_role": "vip",
            "enabled": True,
        },
    }


def _sanitize_llm_model_tiers(raw: Any, default_model: str, default_provider: str) -> dict:
    source = raw if isinstance(raw, dict) else {}
    defaults = _default_llm_model_tiers(default_model, default_provider)
    result: dict[str, dict[str, Any]] = {}
    for key in LLM_MODEL_TIERS:
        incoming = source.get(key) if isinstance(source.get(key), dict) else {}
        default = defaults[key]
        min_role = normalize_user_role(incoming.get("min_role") or default.get("min_role"))
        if key == "smart":
            min_role = "normal"
        if min_role == "admin":
            min_role = LLM_MODEL_TIER_MIN_ROLE.get(key, "normal")
        multiplier = _llm_tier_multiplier(incoming.get("multiplier"), default["multiplier"])
        if key == "advanced" and math.isclose(multiplier, 1.5, rel_tol=0, abs_tol=0.0001):
            multiplier = 1.25
        if key == "ultra" and math.isclose(multiplier, 2.0, rel_tol=0, abs_tol=0.0001):
            multiplier = 1.75
        result[key] = {
            "label": str(incoming.get("label") or default["label"]).strip()[:30],
            "label_en": str(incoming.get("label_en") or default["label_en"]).strip()[:30],
            "provider": _normalize_llm_provider(incoming.get("provider"), default["provider"]),
            "model": str(incoming.get("model") or default["model"]).strip()[:200] or default["model"],
            "multiplier": multiplier,
            "min_role": min_role,
            "enabled": bool(incoming.get("enabled", default["enabled"])),
        }
    if not result["smart"]["enabled"]:
        result["smart"]["enabled"] = True
    return result


def _sanitize_module_model_tiers(raw: Any, default_tier: str = "smart") -> dict[str, str]:
    source = raw if isinstance(raw, dict) else {}
    fallback = _llm_model_tier_key(default_tier) or "smart"
    result: dict[str, str] = {}
    for key in AI_MODULE_MODEL_KEYS:
        result[key] = _llm_model_tier_key(source.get(key)) or fallback
    return result


def _allowed_llm_model_tiers(options: dict, role: Optional[str]) -> dict[str, dict[str, Any]]:
    normalized_role = normalize_user_role(role)
    if normalized_role == "admin":
        return {
            key: value
            for key, value in (options.get("model_tiers") or {}).items()
            if key in LLM_MODEL_TIERS
        }
    rank = _llm_role_rank(normalized_role)
    allowed: dict[str, dict[str, Any]] = {}
    for key, value in (options.get("model_tiers") or {}).items():
        if key not in LLM_MODEL_TIERS or not value.get("enabled", True):
            continue
        if rank >= _llm_role_rank(value.get("min_role") or LLM_MODEL_TIER_MIN_ROLE.get(key)):
            allowed[key] = value
    if "smart" not in allowed:
        allowed["smart"] = (options.get("model_tiers") or {}).get("smart") or _default_llm_model_tiers()["smart"]
    return allowed


def _public_llm_model_options(options: dict, user: UserModel) -> dict:
    role = normalize_user_role(getattr(user, "role", None))
    if role == "admin":
        return options
    allowed = _allowed_llm_model_tiers(options, role)
    module_model_tiers = _sanitize_module_model_tiers(options.get("module_model_tiers"), "smart")
    module_model_tiers = {
        key: tier if tier in allowed else "smart"
        for key, tier in module_model_tiers.items()
    }
    return {
        "default_model": module_model_tiers.get("assistant") or "smart",
        "models": list(allowed.keys()),
        "module_models": module_model_tiers,
        "module_model_tiers": module_model_tiers,
        "tier_options": [
            {
                "value": key,
                "label": value.get("label") or LLM_MODEL_TIER_LABELS[key]["label"],
                "label_en": value.get("label_en") or LLM_MODEL_TIER_LABELS[key]["label_en"],
                "multiplier": value.get("multiplier", 1),
                "min_role": value.get("min_role") or LLM_MODEL_TIER_MIN_ROLE.get(key, "normal"),
            }
            for key, value in allowed.items()
        ],
        "scope": "tier_selection",
        "notes": "用户侧只显示模型强度等级，真实模型由系统管理员配置。",
    }


def _llm_tier_credit_cost(
    db: Session,
    key: str,
    model_or_tier: Optional[str],
    user: Optional[UserModel],
) -> int:
    return int(_llm_tier_billing_details(db, key, model_or_tier, user)["unit_credits"])


def _llm_tier_billing_details(
    db: Session,
    key: str,
    model_or_tier: Optional[str],
    user: Optional[UserModel],
) -> dict:
    base = _ai_credit_cost(db, key)
    if base <= 0:
        return {
            "module_key": key,
            "base_unit_credits": base,
            "unit_credits": base,
            "model_tier": "smart",
            "model_multiplier": 1.0,
        }
    options = _sanitize_llm_model_options(
        _get_system_setting_json(db, LLM_MODEL_OPTIONS_KEY, _default_llm_model_options())
    )
    role = normalize_user_role(getattr(user, "role", None))
    allowed = _allowed_llm_model_tiers(options, role)
    tier_key = _llm_model_tier_key(model_or_tier) or "smart"
    if tier_key not in allowed:
        tier_key = "smart"
    multiplier = _llm_tier_multiplier(
        (options.get("model_tiers") or {}).get(tier_key, {}).get("multiplier"),
        1.0,
    )
    return {
        "module_key": key,
        "base_unit_credits": int(base),
        "unit_credits": int(math.ceil(base * multiplier)),
        "model_tier": tier_key,
        "model_multiplier": multiplier,
    }


def _ai_context_multiplier(context_chars: int) -> float:
    chars = max(0, int(context_chars or 0))
    for threshold, multiplier in AI_DYNAMIC_CONTEXT_THRESHOLDS:
        if chars <= threshold:
            return multiplier
    return 1.75


def _ai_data_retrieval_multiplier(source_count: int) -> float:
    count = max(0, int(source_count or 0))
    if count <= 1:
        return 1.0
    return round(min(1.45, 1.0 + (count - 1) * 0.08), 3)


def _ai_deep_research_multiplier(deep_units: int) -> float:
    units = max(0, int(deep_units or 0))
    if units <= 0:
        return 1.0
    return round(min(2.5, 1.0 + units * 0.18), 3)


def _dynamic_ai_credit_estimate(
    base_credits: int,
    *,
    user: Optional[UserModel],
    model_details: Optional[dict] = None,
    context_chars: int = 0,
    data_sources: int = 0,
    deep_units: int = 0,
    quantity: int = 1,
) -> dict:
    base_total = max(0, int(base_credits or 0)) * max(1, int(quantity or 1))
    context_multiplier = _ai_context_multiplier(context_chars)
    data_multiplier = _ai_data_retrieval_multiplier(data_sources)
    deep_multiplier = _ai_deep_research_multiplier(deep_units)
    raw_estimated = int(math.ceil(base_total * context_multiplier * data_multiplier * deep_multiplier))
    role = normalize_user_role(getattr(user, "role", None))
    chargeable = role != "admin"
    estimated = raw_estimated if chargeable else 0
    multipliers = {
        "model": float((model_details or {}).get("model_multiplier") or 1.0),
        "context": context_multiplier,
        "data_retrieval": data_multiplier,
        "deep_research": deep_multiplier,
        "total_after_model": round(context_multiplier * data_multiplier * deep_multiplier, 4),
    }
    return {
        "billing_mode": "dynamic_estimated_prepaid",
        "chargeable": chargeable,
        "role": role,
        "base_credits": base_total,
        "estimated_credits": estimated,
        "raw_estimated_credits": raw_estimated,
        "context_chars": max(0, int(context_chars or 0)),
        "data_sources": max(0, int(data_sources or 0)),
        "deep_units": max(0, int(deep_units or 0)),
        "quantity": max(1, int(quantity or 1)),
        "model": model_details or {},
        "multipliers": multipliers,
        "notes": "套餐包含 AI 使用额度，额度用于不同 AI 功能消耗；本次按模型、上下文、数据检索和深度研究倍率预估并预扣。",
    }


def _pricing_provider(value: Any) -> str:
    provider = str(value or "openai").strip().lower()
    return {
        "claude": "anthropic",
        "gemini": "google",
    }.get(provider, provider if provider in {"openai", "custom", "anthropic", "google", "*"} else "openai")


def _pricing_rate(value: Any) -> float:
    try:
        return round(max(0.0, min(float(value or 0), 1_000_000.0)), 8)
    except (TypeError, ValueError):
        return 0.0


def _pricing_multiplier(value: Any, default: float = 1.0) -> float:
    try:
        return round(max(0.0, min(float(value), 100.0)), 6)
    except (TypeError, ValueError):
        return default


def _sanitize_llm_pricing_settings(value: Optional[dict]) -> dict:
    raw = value if isinstance(value, dict) else {}
    models: list[dict] = []
    seen: set[tuple[str, str]] = set()
    for item in raw.get("models") or []:
        if not isinstance(item, dict):
            continue
        model = str(item.get("model") or "").strip()[:200]
        if not model:
            continue
        provider = _pricing_provider(item.get("provider"))
        key = (provider, model)
        if key in seen:
            continue
        seen.add(key)
        models.append(
            {
                "provider": provider,
                "model": model,
                "input_per_million": _pricing_rate(item.get("input_per_million")),
                "output_per_million": _pricing_rate(item.get("output_per_million")),
                "cache_read_per_million": _pricing_rate(item.get("cache_read_per_million")),
                "cache_write_per_million": _pricing_rate(item.get("cache_write_per_million")),
                "cost_multiplier": _pricing_multiplier(item.get("cost_multiplier"), 1.0),
                "enabled": bool(item.get("enabled", True)),
            }
        )
        if len(models) >= 200:
            break
    return {"currency": "USD", "models": models}


def _configured_llm_pricing_models(db: Session) -> list[dict]:
    options = _get_system_setting_json(db, "llm_model_options", {})
    shared = db.query(LLMConfig).filter(LLMConfig.user_id.is_(None)).first()
    default_provider = _pricing_provider(getattr(shared, "provider", None))
    pairs: list[tuple[str, str]] = []

    def add(provider: Any, model: Any):
        model_name = str(model or "").strip()
        pair = (_pricing_provider(provider or default_provider), model_name)
        if model_name and pair not in pairs:
            pairs.append(pair)

    for model in options.get("models") or []:
        add(default_provider, model)
    add(default_provider, options.get("default_model"))
    module_models = options.get("module_models") or {}
    if isinstance(module_models, dict):
        for value in module_models.values():
            if isinstance(value, dict):
                add(value.get("provider"), value.get("model"))
            else:
                add(default_provider, value)
    module_configs = _json_loads_dict(
        getattr(shared, "module_models_json", None) if shared else None,
        {},
    )
    for value in module_configs.values():
        if isinstance(value, dict):
            add(value.get("provider"), value.get("model"))
        else:
            add(default_provider, value)
    if not pairs:
        add(default_provider, getattr(shared, "model", None) or DEFAULT_LLM_MODEL)
    return [{"provider": provider, "model": model} for provider, model in pairs]


def _llm_pricing_settings(db: Session) -> dict:
    settings_value = _sanitize_llm_pricing_settings(
        _get_system_setting_json(db, LLM_PRICING_SETTINGS_KEY, {})
    )
    existing = {
        (item["provider"], item["model"])
        for item in settings_value["models"]
    }
    for configured in _configured_llm_pricing_models(db):
        key = (configured["provider"], configured["model"])
        if key in existing:
            continue
        settings_value["models"].append(
            {
                **configured,
                "input_per_million": 0.0,
                "output_per_million": 0.0,
                "cache_read_per_million": 0.0,
                "cache_write_per_million": 0.0,
                "cost_multiplier": 1.0,
                "enabled": True,
            }
        )
        existing.add(key)
    return settings_value


def _llm_model_price(settings_value: dict, provider: str, model: str) -> dict:
    normalized_provider = _pricing_provider(provider)
    normalized_model = str(model or "").strip()
    candidates = [
        (normalized_provider, normalized_model),
        (normalized_provider, "*"),
        ("*", normalized_model),
        ("*", "*"),
    ]
    rows = settings_value.get("models") or []
    for candidate in candidates:
        for item in rows:
            if not item.get("enabled", True):
                continue
            if (_pricing_provider(item.get("provider")), str(item.get("model") or "").strip()) == candidate:
                return item
    return {
        "provider": normalized_provider,
        "model": normalized_model,
        "input_per_million": 0.0,
        "output_per_million": 0.0,
        "cache_read_per_million": 0.0,
        "cache_write_per_million": 0.0,
        "cost_multiplier": 1.0,
        "enabled": True,
    }


def _effective_llm_price(price: dict) -> dict:
    multiplier = _pricing_multiplier(price.get("cost_multiplier"), 1.0)
    effective = dict(price)
    for field in (
        "input_per_million",
        "output_per_million",
        "cache_read_per_million",
        "cache_write_per_million",
    ):
        effective[field] = _pricing_rate(float(price.get(field) or 0.0) * multiplier)
    effective["cost_multiplier"] = multiplier
    return effective


def _serialize_llm_usage_record(row: LLMUsageRecord, username: str = "") -> dict:
    return {
        "id": row.id,
        "user_id": row.user_id,
        "username": username or getattr(getattr(row, "user", None), "username", "") or "",
        "module_key": row.module_key,
        "module_label": LLM_USAGE_MODULE_LABELS.get(row.module_key, row.module_key),
        "provider": row.provider,
        "model": row.model,
        "request_id": row.request_id,
        "input_tokens": int(row.input_tokens or 0),
        "output_tokens": int(row.output_tokens or 0),
        "cache_read_tokens": int(row.cache_read_tokens or 0),
        "cache_write_tokens": int(row.cache_write_tokens or 0),
        "total_tokens": int(row.total_tokens or 0),
        "credits_charged": int(row.credits_charged or 0),
        "input_cost_micros": int(row.input_cost_micros or 0),
        "output_cost_micros": int(row.output_cost_micros or 0),
        "cache_read_cost_micros": int(row.cache_read_cost_micros or 0),
        "cache_write_cost_micros": int(row.cache_write_cost_micros or 0),
        "total_cost_micros": int(row.total_cost_micros or 0),
        "cost_usd": round(int(row.total_cost_micros or 0) / 1_000_000.0, 8),
        "usage_source": row.usage_source or "estimated",
        "status": row.status or "success",
        "latency_ms": int(row.latency_ms or 0),
        "created_at": row.created_at.isoformat() if row.created_at else None,
    }


def _truncate_audit_text(value: Any, limit: int = 24000) -> str:
    text_value = str(value or "").strip()
    if len(text_value) <= limit:
        return text_value
    return text_value[:limit] + "\n...[truncated]"


def _record_ai_output_audit(
    db: Session,
    *,
    user_id: Optional[int],
    module_key: str,
    request_id: Optional[str],
    output_text: Any,
    provider: str = "",
    model: str = "",
    data_source: str = "",
    status: str = "success",
    meta: Optional[dict] = None,
) -> Optional[AIOutputAudit]:
    module = str(module_key or "unknown").strip()[:80]
    request = str(request_id or f"ai-output:{uuid.uuid4().hex}")[:128]
    row = AIOutputAudit(
        user_id=int(user_id) if user_id else None,
        module_key=module,
        provider=_pricing_provider(provider)[:40] if provider else "",
        model=str(model or "")[:200],
        request_id=request,
        data_source=str(data_source or "")[:160],
        output_text=_truncate_audit_text(output_text),
        disclaimer_version=AI_OUTPUT_DISCLAIMER_VERSION,
        status=str(status or "success")[:24],
        meta_json=json.dumps(
            {
                **(meta or {}),
                "disclaimer_text": AI_OUTPUT_DISCLAIMER_TEXT,
            },
            ensure_ascii=False,
            default=str,
        ),
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    return row


def _persist_llm_usage(
    db: Session,
    *,
    user_id: int,
    module_key: str,
    provider: str,
    model: str,
    usage: dict,
    request_id: Optional[str] = None,
    credits_charged: int = 0,
    latency_ms: int = 0,
    status: str = "success",
    meta: Optional[dict] = None,
    output_text: Any = None,
    data_source: str = "",
) -> Optional[LLMUsageRecord]:
    user = db.query(UserModel).filter(UserModel.id == int(user_id)).first()
    if not user:
        return None
    pricing_settings = _llm_pricing_settings(db)
    price = _llm_model_price(pricing_settings, provider, model)
    effective_price = _effective_llm_price(price)
    costs = usage_metering.calculate_cost_micros(usage, effective_price)
    effective_credits = 0 if normalize_user_role(user.role) == "admin" else max(0, int(credits_charged or 0))
    metadata = {
        **(meta or {}),
        "pricing": {
            key: price.get(key)
            for key in (
                "provider",
                "model",
                "input_per_million",
                "output_per_million",
                "cache_read_per_million",
                "cache_write_per_million",
                "cost_multiplier",
            )
        }
        | {
            f"effective_{key}": effective_price.get(key)
            for key in (
                "input_per_million",
                "output_per_million",
                "cache_read_per_million",
                "cache_write_per_million",
            )
        },
    }
    row = LLMUsageRecord(
        user_id=user.id,
        module_key=str(module_key or "unknown")[:80],
        provider=_pricing_provider(provider)[:40],
        model=str(model or "unknown")[:200],
        request_id=str(request_id or f"llm:{uuid.uuid4().hex}")[:128],
        input_tokens=int(usage.get("input_tokens") or 0),
        output_tokens=int(usage.get("output_tokens") or 0),
        cache_read_tokens=int(usage.get("cache_read_tokens") or 0),
        cache_write_tokens=int(usage.get("cache_write_tokens") or 0),
        total_tokens=int(usage.get("total_tokens") or 0),
        credits_charged=effective_credits,
        input_cost_micros=costs["input_cost_micros"],
        output_cost_micros=costs["output_cost_micros"],
        cache_read_cost_micros=costs["cache_read_cost_micros"],
        cache_write_cost_micros=costs["cache_write_cost_micros"],
        total_cost_micros=costs["total_cost_micros"],
        usage_source=str(usage.get("source") or "estimated")[:40],
        status=str(status or "success")[:24],
        latency_ms=max(0, int(latency_ms or 0)),
        meta_json=json.dumps(metadata, ensure_ascii=False, default=str),
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    if output_text not in (None, ""):
        try:
            _record_ai_output_audit(
                db,
                user_id=user.id,
                module_key=module_key,
                provider=provider,
                model=model,
                request_id=row.request_id,
                output_text=output_text,
                data_source=data_source or str((meta or {}).get("data_source") or ""),
                status=status,
                meta={
                    **(meta or {}),
                    "llm_usage_record_id": row.id,
                },
            )
        except Exception as exc:
            db.rollback()
            print(f"[ai_output_audit] record failed: {exc}")
    return row


def _record_llm_call_usage(
    cfg: dict,
    *,
    messages: Any,
    output_text: Any,
    raw_usage: Any = None,
    latency_ms: int = 0,
    status: str = "success",
    meta: Optional[dict] = None,
) -> Optional[dict]:
    user_id = int(cfg.get("_usage_user_id") or 0)
    module_key = str(cfg.get("_usage_module") or "").strip()
    if user_id <= 0 or not module_key:
        return None
    usage = usage_metering.normalize_token_usage(
        raw_usage,
        provider=str(cfg.get("provider") or ""),
        input_text=usage_metering.messages_text(messages),
        output_text=output_text,
    )
    session = SessionLocal()
    try:
        row = _persist_llm_usage(
            session,
            user_id=user_id,
            module_key=module_key,
            provider=str(cfg.get("provider") or "openai"),
            model=str(cfg.get("model") or "unknown"),
            usage=usage,
            request_id=str(cfg.get("_usage_reference_id") or "") or None,
            credits_charged=int(
                cfg.get("_usage_credits")
                if cfg.get("_usage_credits") is not None
                else LLM_USAGE_DEFAULT_CREDITS.get(module_key, 0)
            ),
            latency_ms=latency_ms,
            status=status,
            meta=meta,
            output_text=output_text,
            data_source=str((meta or {}).get("data_source") or ""),
        )
        return _serialize_llm_usage_record(row) if row else None
    except Exception as exc:
        session.rollback()
        print(f"[llm_usage] record failed: {exc}")
        return None
    finally:
        session.close()


