def _deep_merge_dict(defaults: dict, incoming: Optional[dict]) -> dict:
    result = json.loads(json.dumps(defaults))
    if not isinstance(incoming, dict):
        return result
    for key, value in incoming.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = _deep_merge_dict(result[key], value)
        else:
            result[key] = value
    return result


AUTH_SECRET_FIELDS = {
    ("oauth", "providers", "github", "client_secret"),
    ("oauth", "providers", "discord", "client_secret"),
    ("oauth", "providers", "oidc", "client_secret"),
    ("oauth", "providers", "telegram", "bot_token"),
    ("oauth", "providers", "linuxdo", "client_secret"),
    ("oauth", "providers", "wechat", "client_secret"),
    ("oauth", "providers", "qq", "client_secret"),
    ("bot_protection", "secret_key"),
    ("smtp", "password"),
}


def _set_nested_value(data: dict, path: tuple[str, ...], value: Any):
    cursor = data
    for key in path[:-1]:
        cursor = cursor.setdefault(key, {})
    cursor[path[-1]] = value


def _get_nested_value(data: dict, path: tuple[str, ...]):
    cursor = data
    for key in path:
        if not isinstance(cursor, dict):
            return None
        cursor = cursor.get(key)
    return cursor


def _sanitize_auth_security_settings(
    raw: Optional[dict],
    *,
    existing: Optional[dict] = None,
    preserve_masked: bool = True,
) -> dict:
    defaults = _default_auth_security_settings()
    merged = _deep_merge_dict(defaults, existing or {})
    merged = _deep_merge_dict(merged, raw or {})
    if preserve_masked and existing:
        for path in AUTH_SECRET_FIELDS:
            value = _get_nested_value(merged, path)
            if isinstance(value, str) and "****" in value:
                _set_nested_value(merged, path, _get_nested_value(existing, path) or "")

    merged["basic_auth"]["enabled"] = bool(merged["basic_auth"].get("enabled", True))
    merged["basic_auth"]["registration_enabled"] = bool(
        merged["basic_auth"].get("registration_enabled", True)
    )
    raw_domains = merged["basic_auth"].get("allowed_email_domains") or []
    if isinstance(raw_domains, str):
        raw_domains = re.split(r"[\s,;]+", raw_domains)
    allowed_domains: list[str] = []
    for item in raw_domains if isinstance(raw_domains, list) else []:
        domain = str(item or "").strip().lower().lstrip("@")
        if re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+", domain):
            if domain not in allowed_domains:
                allowed_domains.append(domain)
        if len(allowed_domains) >= 100:
            break
    merged["basic_auth"]["allowed_email_domains"] = allowed_domains
    merged["oauth"]["enabled"] = bool(merged["oauth"].get("enabled", True))
    merged["oauth"]["auto_register"] = bool(merged["oauth"].get("auto_register", True))
    merged["passkey"]["enabled"] = bool(merged["passkey"].get("enabled", False))
    merged["bot_protection"]["enabled"] = bool(merged["bot_protection"].get("enabled", False))
    merged["bot_protection"]["apply_login"] = bool(merged["bot_protection"].get("apply_login", True))
    merged["bot_protection"]["apply_register"] = bool(merged["bot_protection"].get("apply_register", True))
    merged["smtp"]["enabled"] = bool(merged["smtp"].get("enabled", False))
    merged["smtp"]["require_email_verification"] = bool(
        merged["smtp"].get("require_email_verification", False)
    )
    try:
        merged["smtp"]["port"] = int(merged["smtp"].get("port") or 465)
    except Exception:
        merged["smtp"]["port"] = 465
    merged["smtp"]["use_tls"] = bool(merged["smtp"].get("use_tls", True))
    merged["checkin"]["enabled"] = bool(merged["checkin"].get("enabled", True))
    for key, fallback in (("min_credits", 5), ("max_credits", 20)):
        try:
            merged["checkin"][key] = max(0, int(merged["checkin"].get(key, fallback)))
        except Exception:
            merged["checkin"][key] = fallback
    if merged["checkin"]["max_credits"] < merged["checkin"]["min_credits"]:
        merged["checkin"]["max_credits"] = merged["checkin"]["min_credits"]
    merged["ssrf"]["enabled"] = bool(merged["ssrf"].get("enabled", True))
    merged["ssrf"]["allow_private_ip"] = bool(merged["ssrf"].get("allow_private_ip", False))
    merged["ssrf"]["apply_ip_filter_for_domain"] = bool(
        merged["ssrf"].get("apply_ip_filter_for_domain", True)
    )
    for key in ("domain_list", "ip_list", "allowed_ports"):
        value = merged["ssrf"].get(key)
        merged["ssrf"][key] = value if isinstance(value, list) else []
    merged["logging"]["export_enabled"] = bool(merged["logging"].get("export_enabled", True))
    try:
        merged["logging"]["max_export_lines"] = max(
            100, min(50000, int(merged["logging"].get("max_export_lines") or 5000))
        )
    except Exception:
        merged["logging"]["max_export_lines"] = 5000
    return merged


def _auth_security_settings(db: Session, masked: bool = False) -> dict:
    settings_value = _sanitize_auth_security_settings(
        _get_system_setting_json(
            db,
            AUTH_SECURITY_SETTINGS_KEY,
            _default_auth_security_settings(),
        )
    )
    if not masked:
        return settings_value
    masked_value = json.loads(json.dumps(settings_value))
    for path in AUTH_SECRET_FIELDS:
        value = _get_nested_value(masked_value, path)
        if value:
            _set_nested_value(masked_value, path, _mask_secret(str(value)))
    return masked_value


