def _client_ip(request: Request) -> str:
    forwarded = request.headers.get("x-forwarded-for") or ""
    if forwarded:
        return forwarded.split(",")[0].strip()
    return request.client.host if request.client else "unknown"


def _parse_allowed_ports(values: list[Any]) -> set[int]:
    ports: set[int] = set()
    for item in values or []:
        text_value = str(item or "").strip()
        if not text_value:
            continue
        if "-" in text_value:
            start, end = text_value.split("-", 1)
            start_i = int(start.strip())
            end_i = int(end.strip())
            if start_i > end_i:
                raise ValueError("端口范围起始值不能大于结束值")
            for port in range(start_i, end_i + 1):
                if 1 <= port <= 65535:
                    ports.add(port)
        else:
            port = int(text_value)
            if not 1 <= port <= 65535:
                raise ValueError("端口必须在 1-65535 范围内")
            ports.add(port)
    return ports


def _is_private_or_reserved_ip(ip_text: str) -> bool:
    try:
        ip = ipaddress.ip_address(ip_text)
    except ValueError:
        return True
    return any(
        [
            ip.is_private,
            ip.is_loopback,
            ip.is_link_local,
            ip.is_multicast,
            ip.is_reserved,
            ip.is_unspecified,
        ]
    )


def _domain_matches(domain: str, rules: list[Any]) -> bool:
    domain = domain.lower().strip(".")
    for item in rules or []:
        rule = str(item or "").lower().strip().strip(".")
        if not rule:
            continue
        if rule.startswith("*."):
            suffix = rule[2:]
            if domain == suffix or domain.endswith("." + suffix):
                return True
        if domain == rule:
            return True
    return False


def _ip_matches(ip_text: str, rules: list[Any]) -> bool:
    try:
        ip = ipaddress.ip_address(ip_text)
    except ValueError:
        return False
    for item in rules or []:
        rule = str(item or "").strip()
        if not rule:
            continue
        try:
            if "/" in rule:
                if ip in ipaddress.ip_network(rule, strict=False):
                    return True
            elif ip == ipaddress.ip_address(rule):
                return True
        except ValueError:
            continue
    return False


def _validate_url_with_ssrf(settings_value: dict, url_value: str) -> None:
    ssrf = settings_value.get("ssrf") or {}
    if not ssrf.get("enabled", True):
        return
    parsed = urlparse(str(url_value or ""))
    if parsed.scheme not in {"http", "https"} or not parsed.hostname:
        raise HTTPException(status_code=400, detail="URL 仅支持 http/https 且必须包含域名")
    try:
        port = parsed.port or (443 if parsed.scheme == "https" else 80)
    except ValueError:
        raise HTTPException(status_code=400, detail="URL 端口格式无效")
    allowed_ports = _parse_allowed_ports(ssrf.get("allowed_ports") or [])
    if allowed_ports and port not in allowed_ports:
        raise HTTPException(status_code=400, detail=f"SSRF 防护已阻止端口 {port}")

    host = parsed.hostname
    domain_mode = str(ssrf.get("domain_filter_mode") or "blacklist").lower()
    domain_list = ssrf.get("domain_list") or []
    if domain_list:
        listed = _domain_matches(host, domain_list)
        if domain_mode == "whitelist" and not listed:
            raise HTTPException(status_code=400, detail=f"SSRF 防护已阻止未在白名单的域名：{host}")
        if domain_mode != "whitelist" and listed:
            raise HTTPException(status_code=400, detail=f"SSRF 防护已阻止黑名单域名：{host}")

    resolved_ips: list[str] = []
    if re.match(r"^[0-9a-fA-F:.]+$", host):
        resolved_ips = [host]
    elif ssrf.get("apply_ip_filter_for_domain", True):
        try:
            resolved_ips = sorted({item[4][0] for item in socket.getaddrinfo(host, port)})
        except Exception as err:
            raise HTTPException(status_code=400, detail=f"DNS 解析失败：{err}")

    ip_mode = str(ssrf.get("ip_filter_mode") or "blacklist").lower()
    ip_list = ssrf.get("ip_list") or []
    for ip_text in resolved_ips:
        if _is_private_or_reserved_ip(ip_text) and not ssrf.get("allow_private_ip", False):
            raise HTTPException(status_code=400, detail=f"SSRF 防护已阻止私有或保留地址：{ip_text}")
        if ip_list:
            listed = _ip_matches(ip_text, ip_list)
            if ip_mode == "whitelist" and not listed:
                raise HTTPException(status_code=400, detail=f"SSRF 防护已阻止未在白名单的 IP：{ip_text}")
            if ip_mode != "whitelist" and listed:
                raise HTTPException(status_code=400, detail=f"SSRF 防护已阻止黑名单 IP：{ip_text}")


def _verify_bot_protection(db: Session, request: Request, token: Optional[str], action: str):
    settings_value = _auth_security_settings(db)
    bot = settings_value.get("bot_protection") or {}
    if not bot.get("enabled"):
        return
    if action == "login" and not bot.get("apply_login", True):
        return
    if action == "register" and not bot.get("apply_register", True):
        return
    secret_key = str(bot.get("secret_key") or "").strip()
    if not secret_key:
        raise HTTPException(status_code=400, detail="机器人保护已启用，但服务端密钥未配置")
    if not token:
        raise HTTPException(status_code=400, detail="请先完成人机校验")
    provider = str(bot.get("provider") or "turnstile").lower()
    if provider == "turnstile":
        verify_url = "https://challenges.cloudflare.com/turnstile/v0/siteverify"
    elif provider == "recaptcha":
        verify_url = "https://www.google.com/recaptcha/api/siteverify"
    else:
        raise HTTPException(status_code=400, detail="不支持的机器人保护服务")
    _validate_url_with_ssrf(settings_value, verify_url)
    try:
        res = requests.post(
            verify_url,
            data={"secret": secret_key, "response": token, "remoteip": _client_ip(request)},
            timeout=8,
        )
        payload = res.json()
    except Exception as err:
        raise HTTPException(status_code=400, detail=f"机器人保护校验失败：{err}")
    if not payload.get("success"):
        raise HTTPException(status_code=400, detail="人机校验未通过，请刷新后重试")


EMAIL_LOGO_CID = "quartsys-logo"


def _email_logo_path() -> Optional[Path]:
    return None


def _build_branded_email_html(content: str, brand_name: str, *, include_logo: bool) -> str:
    logo_html = (
        f'<img src="cid:{EMAIL_LOGO_CID}" width="44" height="44" '
        'alt="AIQuartSmart Community Edition" style="display:block;width:44px;height:44px;border-radius:10px;object-fit:cover;" />'
        if include_logo
        else '<div style="width:44px;height:44px;border-radius:10px;background:#2563eb;color:#ffffff;display:inline-flex;align-items:center;justify-content:center;font-weight:800;">AQ</div>'
    )
    brand = html.escape(brand_name or "AIQuartSmart Community Edition")
    return f"""<!doctype html>
<html>
  <body style="margin:0;padding:0;background:#f4f6f8;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',Arial,sans-serif;color:#111827;">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f4f6f8;padding:28px 12px;">
      <tr>
        <td align="center">
          <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:560px;background:#ffffff;border:1px solid #e5e7eb;border-radius:14px;overflow:hidden;">
            <tr>
              <td style="padding:22px 24px;border-bottom:1px solid #eef2f7;background:#ffffff;">
                <table role="presentation" cellspacing="0" cellpadding="0">
                  <tr>
                    <td style="vertical-align:middle;">{logo_html}</td>
                    <td style="vertical-align:middle;padding-left:12px;">
                      <div style="font-size:18px;font-weight:800;line-height:1.2;color:#111827;">{brand}</div>
                      <div style="font-size:12px;line-height:1.5;color:#64748b;margin-top:3px;">量化投研与交易系统</div>
                    </td>
                  </tr>
                </table>
              </td>
            </tr>
            <tr>
              <td style="padding:24px;color:#111827;font-size:14px;line-height:1.75;">
                {content}
              </td>
            </tr>
            <tr>
              <td style="padding:14px 24px;border-top:1px solid #eef2f7;color:#94a3b8;font-size:12px;line-height:1.6;background:#fbfdff;">
                此邮件由 {brand} 系统自动发送，请勿直接回复。
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>"""


def _build_smtp_message(
    *,
    from_name: str,
    from_email: str,
    receiver: str,
    subject: str,
    content: str,
) -> MIMEMultipart:
    logo_path = _email_logo_path()
    msg = MIMEMultipart("related")
    msg["Subject"] = str(Header(subject, "utf-8"))
    msg["From"] = formataddr((str(Header(from_name, "utf-8")), from_email))
    msg["To"] = formataddr(("", receiver))

    alternative = MIMEMultipart("alternative")
    alternative.attach(
        MIMEText(
            _build_branded_email_html(
                content,
                from_name,
                include_logo=bool(logo_path),
            ),
            "html",
            "utf-8",
        )
    )
    msg.attach(alternative)

    if logo_path:
        try:
            if logo_path.suffix.lower() == ".svg":
                logo = MIMEBase("image", "svg+xml")
                logo.set_payload(logo_path.read_bytes())
                encoders.encode_base64(logo)
            else:
                logo = MIMEImage(logo_path.read_bytes(), _subtype="png")
            logo.add_header("Content-ID", f"<{EMAIL_LOGO_CID}>")
            logo.add_header("Content-Disposition", "inline", filename=logo_path.name)
            msg.attach(logo)
        except Exception:
            pass

    return msg


def _send_smtp_email(settings_value: dict, receiver: str, subject: str, content: str):
    smtp_cfg = settings_value.get("smtp") or {}
    if not smtp_cfg.get("enabled"):
        raise HTTPException(status_code=400, detail="SMTP 邮箱注册未启用")
    host = str(smtp_cfg.get("host") or "").strip()
    username = str(smtp_cfg.get("username") or "").strip()
    password = str(smtp_cfg.get("password") or "").strip()
    from_email = str(smtp_cfg.get("from_email") or username).strip()
    from_name = str(smtp_cfg.get("from_name") or "AIQuartSmart Community Edition").strip()
    port = int(smtp_cfg.get("port") or 465)
    if not host or not from_email:
        raise HTTPException(status_code=400, detail="SMTP 主机或发件邮箱未配置")
    msg = _build_smtp_message(
        from_name=from_name,
        from_email=from_email,
        receiver=receiver,
        subject=subject,
        content=content,
    )
    stage = "连接 SMTP 服务器"
    try:
        use_tls = bool(smtp_cfg.get("use_tls", True))
        if port == 465:
            context = ssl.create_default_context()
            with smtplib.SMTP_SSL(host, port, context=context, timeout=12) as server:
                stage = "登录 SMTP 服务器"
                if username:
                    server.login(username, password)
                stage = "发送邮件"
                server.sendmail(from_email, [receiver], msg.as_string())
        else:
            with smtplib.SMTP(host, port, timeout=12) as server:
                if use_tls:
                    stage = "启动 STARTTLS 加密"
                    server.starttls(context=ssl.create_default_context())
                    server.ehlo()
                stage = "登录 SMTP 服务器"
                if username:
                    server.login(username, password)
                stage = "发送邮件"
                server.sendmail(from_email, [receiver], msg.as_string())
    except smtplib.SMTPAuthenticationError as err:
        detail = err.smtp_error.decode(errors="ignore") if isinstance(err.smtp_error, bytes) else str(err.smtp_error)
        raise HTTPException(
            status_code=400,
            detail=(
                "邮件发送失败：SMTP 认证失败。请确认账号、SMTP 授权码和发件邮箱一致；"
                f"服务端返回：{detail or err.smtp_code}"
            ),
        )
    except smtplib.SMTPServerDisconnected as err:
        hint = ""
        if stage == "登录 SMTP 服务器":
            hint = "。服务器在认证阶段断开连接，常见原因是邮箱未开启 SMTP、授权码错误/过期，或账号触发安全拦截"
        elif port != 465 and bool(smtp_cfg.get("use_tls", True)):
            hint = "。如果使用 587，请确认服务商支持 STARTTLS；如果使用 465，请切换到 465 端口"
        raise HTTPException(status_code=400, detail=f"邮件发送失败：{stage}失败{hint}：{err}")
    except (socket.timeout, TimeoutError) as err:
        raise HTTPException(status_code=400, detail=f"邮件发送失败：{stage}超时：{err}")
    except (ConnectionError, OSError, ssl.SSLError) as err:
        raise HTTPException(status_code=400, detail=f"邮件发送失败：{stage}失败：{err}")
    except Exception as err:
        raise HTTPException(status_code=400, detail=f"邮件发送失败：{stage}失败：{err}")


def _issue_auth_token(user: UserModel) -> dict:
    access_token = create_access_token(
        data={"sub": user.username},
        expires_delta=timedelta(days=7),
    )
    return {"token": access_token, "user": serialize_user_auth(user)}


def _find_user_by_login_identifier(db: Session, identifier: str) -> Optional[UserModel]:
    value = str(identifier or "").strip()
    if not value:
        return None
    email_value = value.lower()
    return (
        db.query(UserModel)
        .filter(
            or_(
                UserModel.username == value,
                func.lower(UserModel.email) == email_value,
            )
        )
        .first()
    )


def _provider_callback_url(request: Request, settings_value: dict, provider: str) -> str:
    base_url = str(settings_value.get("oauth", {}).get("callback_base_url") or "").strip()
    if base_url:
        return f"{base_url.rstrip('/')}/api/auth/oauth/{provider}/callback"
    return str(request.url_for("auth_oauth_callback", provider=provider))


def _oauth_provider_config(settings_value: dict, provider: str) -> dict:
    providers = (settings_value.get("oauth") or {}).get("providers") or {}
    cfg = providers.get(provider)
    if not isinstance(cfg, dict) or not cfg.get("enabled"):
        raise HTTPException(status_code=404, detail="该登录方式未启用")
    return cfg


def _oauth_endpoints(settings_value: dict, provider: str, cfg: dict) -> dict:
    if provider == "github":
        return {
            "authorization_endpoint": "https://github.com/login/oauth/authorize",
            "token_endpoint": "https://github.com/login/oauth/access_token",
            "userinfo_endpoint": "https://api.github.com/user",
        }
    if provider == "discord":
        return {
            "authorization_endpoint": "https://discord.com/api/oauth2/authorize",
            "token_endpoint": "https://discord.com/api/oauth2/token",
            "userinfo_endpoint": "https://discord.com/api/users/@me",
        }
    if provider == "oidc" and cfg.get("issuer") and not cfg.get("authorization_endpoint"):
        issuer = str(cfg["issuer"]).rstrip("/")
        discovery_url = f"{issuer}/.well-known/openid-configuration"
        _validate_url_with_ssrf(settings_value, discovery_url)
        try:
            discovered = requests.get(discovery_url, timeout=8).json()
        except Exception as err:
            raise HTTPException(status_code=400, detail=f"OIDC discovery 失败：{err}")
        return {
            "authorization_endpoint": discovered.get("authorization_endpoint"),
            "token_endpoint": discovered.get("token_endpoint"),
            "userinfo_endpoint": discovered.get("userinfo_endpoint"),
        }
    return {
        "authorization_endpoint": cfg.get("authorization_endpoint"),
        "token_endpoint": cfg.get("token_endpoint"),
        "userinfo_endpoint": cfg.get("userinfo_endpoint"),
        "openid_endpoint": cfg.get("openid_endpoint"),
    }


def _normalize_oauth_user(provider: str, payload: dict, extra: Optional[dict] = None) -> dict:
    extra = extra or {}
    if provider == "github":
        provider_user_id = str(payload.get("id") or "")
        username = payload.get("login") or f"github_{provider_user_id}"
        return {
            "provider_user_id": provider_user_id,
            "username": username,
            "display_name": payload.get("name") or username,
            "email": payload.get("email") or "",
            "avatar_url": payload.get("avatar_url") or "",
            "raw": payload,
        }
    if provider == "discord":
        provider_user_id = str(payload.get("id") or "")
        username = payload.get("username") or f"discord_{provider_user_id}"
        return {
            "provider_user_id": provider_user_id,
            "username": username,
            "display_name": payload.get("global_name") or username,
            "email": payload.get("email") or "",
            "avatar_url": (
                f"https://cdn.discordapp.com/avatars/{provider_user_id}/{payload.get('avatar')}.png"
                if payload.get("avatar")
                else ""
            ),
            "raw": payload,
        }
    if provider == "qq":
        provider_user_id = str(extra.get("openid") or payload.get("openid") or "")
        username = payload.get("nickname") or f"qq_{provider_user_id}"
        return {
            "provider_user_id": provider_user_id,
            "username": username,
            "display_name": payload.get("nickname") or username,
            "email": "",
            "avatar_url": payload.get("figureurl_qq_2") or payload.get("figureurl_qq_1") or "",
            "raw": {**payload, **extra},
        }
    if provider == "wechat":
        provider_user_id = str(payload.get("unionid") or payload.get("openid") or "")
        username = payload.get("nickname") or f"wechat_{provider_user_id}"
        return {
            "provider_user_id": provider_user_id,
            "username": username,
            "display_name": payload.get("nickname") or username,
            "email": "",
            "avatar_url": payload.get("headimgurl") or "",
            "raw": payload,
        }
    provider_user_id = str(payload.get("sub") or payload.get("id") or payload.get("uid") or "")
    username = (
        payload.get("preferred_username")
        or payload.get("login")
        or payload.get("username")
        or payload.get("name")
        or f"{provider}_{provider_user_id}"
    )
    return {
        "provider_user_id": provider_user_id,
        "username": username,
        "display_name": payload.get("name") or username,
        "email": payload.get("email") or "",
        "avatar_url": payload.get("picture") or payload.get("avatar_url") or "",
        "raw": payload,
    }


def _safe_oauth_username(provider: str, preferred: str) -> str:
    cleaned = re.sub(r"[^a-zA-Z0-9_\-\u4e00-\u9fff]", "_", preferred or "").strip("_")
    if len(cleaned) < 2:
        cleaned = f"{provider}_{secrets.token_hex(4)}"
    return cleaned[:32]


def _find_or_create_oauth_user(
    db: Session,
    provider: str,
    oauth_user: dict,
    auto_register: bool,
) -> UserModel:
    provider_user_id = str(oauth_user.get("provider_user_id") or "").strip()
    if not provider_user_id:
        raise HTTPException(status_code=400, detail="第三方账号没有返回有效用户 ID")
    identity = (
        db.query(AuthIdentity)
        .filter(
            AuthIdentity.provider == provider,
            AuthIdentity.provider_user_id == provider_user_id,
        )
        .first()
    )
    if identity:
        user = db.query(UserModel).filter(UserModel.id == identity.user_id).first()
        if user:
            identity.raw_json = json.dumps(oauth_user.get("raw") or {}, ensure_ascii=False)
            identity.display_name = oauth_user.get("display_name") or identity.display_name
            identity.email = oauth_user.get("email") or identity.email
            identity.avatar_url = oauth_user.get("avatar_url") or identity.avatar_url
            db.commit()
            return user
    email = _normalized_registration_email(oauth_user.get("email"))
    user = (
        db.query(UserModel).filter(func.lower(UserModel.email) == email).first()
        if email
        else None
    )
    if not user:
        if not auto_register:
            raise HTTPException(status_code=403, detail="当前系统未开放第三方账号自动注册")
        username = _safe_oauth_username(provider, oauth_user.get("username") or "")
        base_username = username
        index = 1
        while db.query(UserModel).filter(UserModel.username == username).first():
            suffix = f"_{index}"
            username = f"{base_username[:32 - len(suffix)]}{suffix}"
            index += 1
        user = UserModel(
            username=username,
            email=email or None,
            password_hash=get_password_hash(secrets.token_urlsafe(24)),
            avatar_url=oauth_user.get("avatar_url") or None,
            role="normal",
        )
        db.add(user)
        db.flush()
    identity = AuthIdentity(
        user_id=user.id,
        provider=provider,
        provider_user_id=provider_user_id,
        email=email or None,
        display_name=oauth_user.get("display_name") or "",
        avatar_url=oauth_user.get("avatar_url") or "",
        raw_json=json.dumps(oauth_user.get("raw") or {}, ensure_ascii=False),
    )
    db.add(identity)
    if oauth_user.get("avatar_url") and not user.avatar_url:
        user.avatar_url = oauth_user["avatar_url"]
    db.commit()
    db.refresh(user)
    return user


def _default_payment_settings() -> dict:
    return {
        "epay": {
            "enabled": False,
            "gateway_url": "",
            "merchant_id": "",
            "secret_key": "",
            # Public origin used for ePay callbacks when the API is behind a proxy.
            # Leave blank in local development to use the browser's local origin.
            "public_site_url": "",
            # Optional separate API origin. Defaults to public_site_url when omitted.
            "public_api_url": "",
            "return_url": "",
            "notify_url": "",
            "default_method": "alipay",
        },
        "stripe": {
            "enabled": False,
            "secret_key": "",
            "webhook_secret": "",
            "success_url": "",
            "cancel_url": "",
            "checkout_url": "",
        },
    }


def _merge_payment_settings(current: dict, patch: dict, *, preserve_masked: bool = True) -> dict:
    merged = _default_payment_settings()
    for provider, defaults in merged.items():
        existing = current.get(provider) if isinstance(current.get(provider), dict) else {}
        incoming = patch.get(provider) if isinstance(patch.get(provider), dict) else {}
        next_provider = {**defaults, **existing}
        for key, value in incoming.items():
            if preserve_masked and isinstance(value, str) and "****" in value:
                continue
            next_provider[key] = value
        next_provider["enabled"] = bool(next_provider.get("enabled"))
        merged[provider] = next_provider
    return merged


def _payment_settings(db: Session, masked: bool = False) -> dict:
    settings_value = _merge_payment_settings(
        _get_system_setting_json(db, PAYMENT_SETTINGS_KEY, _default_payment_settings()),
        {},
    )
    if not masked:
        return settings_value
    result = json.loads(json.dumps(settings_value))
    if result.get("epay"):
        result["epay"]["secret_key"] = _mask_secret(result["epay"].get("secret_key"))
    if result.get("stripe"):
        result["stripe"]["secret_key"] = _mask_secret(result["stripe"].get("secret_key"))
        result["stripe"]["webhook_secret"] = _mask_secret(result["stripe"].get("webhook_secret"))
    return result


def _payment_channel_status(db: Session) -> dict:
    settings_value = _payment_settings(db, masked=False)
    epay = settings_value.get("epay") or {}
    stripe = settings_value.get("stripe") or {}
    epay_ready = bool(
        epay.get("enabled")
        and epay.get("gateway_url")
        and epay.get("merchant_id")
        and epay.get("secret_key")
    )
    stripe_ready = bool(
        stripe.get("enabled")
        and stripe.get("secret_key")
        and stripe.get("webhook_secret")
    )
    return {
        "epay": {
            "enabled": epay_ready,
            "label": "ePay",
            "methods": sorted(EPAY_PAYMENT_METHODS),
            "default_method": epay.get("default_method") if epay.get("default_method") in EPAY_PAYMENT_METHODS else "alipay",
        },
        "stripe": {
            "enabled": stripe_ready,
            "label": "Stripe",
            "methods": ["card"],
            "default_method": "card",
        },
        "any_enabled": epay_ready or stripe_ready,
    }


def _validate_payment_settings_for_save(settings_value: dict) -> None:
    epay = settings_value.get("epay") or {}
    if epay.get("enabled"):
        if not epay.get("gateway_url") or not epay.get("merchant_id") or not epay.get("secret_key"):
            raise HTTPException(status_code=400, detail="启用 ePay 时必须配置网关地址、商户 ID 和密钥")
        parsed = urlparse(str(epay.get("gateway_url") or ""))
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise HTTPException(status_code=400, detail="ePay 网关地址格式无效")
        if epay.get("default_method") and epay.get("default_method") not in EPAY_PAYMENT_METHODS:
            raise HTTPException(status_code=400, detail="ePay 默认支付方式必须是 alipay、wxpay 或 qqpay")
        for field_name in ("public_site_url", "public_api_url"):
            public_url = str(epay.get(field_name) or "").strip()
            if public_url and not _normalize_payment_site_url(public_url):
                raise HTTPException(
                    status_code=400,
                    detail="公开站点地址必须是 HTTPS 根地址；本地调试可使用 http://127.0.0.1:端口",
                )
    stripe = settings_value.get("stripe") or {}
    if stripe.get("enabled"):
        secret_key = str(stripe.get("secret_key") or "")
        if not secret_key.startswith(("sk_", "rk_")):
            raise HTTPException(status_code=400, detail="Stripe Secret Key 未配置或格式无效")
        if not stripe.get("webhook_secret"):
            raise HTTPException(status_code=400, detail="启用 Stripe 时必须配置 Webhook Secret")


def _serialize_plan(plan: SubscriptionPlan) -> dict:
    try:
        features = json.loads(plan.features_json or "[]")
    except Exception:
        features = []
    role = normalize_user_role(plan.role)
    interval = (plan.interval or "month").lower()
    return {
        "id": plan.id,
        "key": plan.key,
        "name": plan.name,
        "description": plan.description or "",
        "role": role,
        "price_cents": int(plan.price_cents or 0),
        "price": round((plan.price_cents or 0) / 100, 2),
        "currency": plan.currency or "CNY",
        "interval": interval,
        "duration_days": _plan_duration_days(plan),
        "is_trial": interval == "trial" or "trial" in (plan.key or "").lower(),
        "tier": "svip" if role == "svip" else "vip" if role == "vip" else "free",
        "credits": int(plan.credits or 0),
        "enabled": bool(plan.enabled),
        "sort_order": int(plan.sort_order or 0),
        "features": features if isinstance(features, list) else [],
        "stripe_price_id": plan.stripe_price_id or "",
    }


def _normalize_redeem_code(value: Optional[str]) -> str:
    return re.sub(r"\s+", "", str(value or "")).strip().upper()


def _generate_redeem_code(db: Session) -> str:
    for _ in range(12):
        raw = secrets.token_hex(6).upper()
        code = f"JM-{raw[:4]}-{raw[4:8]}-{raw[8:]}"
        if not db.query(RedeemCode.id).filter(RedeemCode.code == code).first():
            return code
    return f"JM-{uuid.uuid4().hex[:12].upper()}"


def _serialize_redeem_code(row: RedeemCode) -> dict:
    plan = row.plan
    return {
        "id": row.id,
        "code": row.code,
        "plan_id": row.plan_id,
        "plan_key": row.plan_key or (plan.key if plan else ""),
        "plan_name": row.plan_name or (plan.name if plan else ""),
        "plan_role": normalize_user_role(plan.role) if plan else "normal",
        "credits": int(row.credits or 0),
        "duration_days": int(row.duration_days or 0) if row.duration_days else None,
        "max_uses": int(row.max_uses or 0),
        "used_count": int(row.used_count or 0),
        "remaining_uses": max(0, int(row.max_uses or 0) - int(row.used_count or 0)),
        "per_user_limit": int(row.per_user_limit or 1),
        "enabled": bool(row.enabled),
        "description": row.description or "",
        "starts_at": row.starts_at.isoformat() if row.starts_at else None,
        "expires_at": row.expires_at.isoformat() if row.expires_at else None,
        "last_used_at": row.last_used_at.isoformat() if row.last_used_at else None,
        "created_by_user_id": row.created_by_user_id,
        "created_at": row.created_at.isoformat() if row.created_at else None,
        "updated_at": row.updated_at.isoformat() if row.updated_at else None,
    }


def _plan_for_redeem_payload(db: Session, payload: Any) -> SubscriptionPlan:
    plan = None
    if payload.plan_id:
        plan = db.query(SubscriptionPlan).filter(SubscriptionPlan.id == payload.plan_id).first()
    if not plan and payload.plan_key:
        plan = (
            db.query(SubscriptionPlan)
            .filter(SubscriptionPlan.key == str(payload.plan_key).strip())
            .first()
        )
    if not plan:
        raise HTTPException(status_code=404, detail="兑换码关联的订阅套餐不存在")
    return plan


def _apply_redeem_code_payload(
    row: RedeemCode,
    payload: Any,
    plan: SubscriptionPlan,
) -> None:
    row.plan_id = plan.id
    row.plan_key = plan.key
    row.plan_name = plan.name
    row.credits = max(0, int(payload.credits if payload.credits is not None else plan.credits or 0))
    row.duration_days = (
        max(1, int(payload.duration_days))
        if payload.duration_days is not None and int(payload.duration_days or 0) > 0
        else None
    )
    row.max_uses = max(1, int(payload.max_uses or 1))
    row.per_user_limit = max(1, int(payload.per_user_limit or 1))
    row.enabled = 1 if payload.enabled else 0
    row.description = (payload.description or "").strip()
    row.starts_at = _as_naive_utc(payload.starts_at) if payload.starts_at else None
    row.expires_at = _as_naive_utc(payload.expires_at) if payload.expires_at else None


def _quarter_plan_price_cents(monthly_price_cents: int, discount_pct: float) -> int:
    discount = max(0.0, min(float(discount_pct or 0.0), 80.0))
    return max(0, int(round(int(monthly_price_cents or 0) * 3 * (1 - discount / 100.0))))


def _sync_quarter_subscription_plans(
    db: Session,
    billing_settings: Optional[dict] = None,
    *,
    commit: bool = True,
) -> None:
    settings_value = billing_settings if isinstance(billing_settings, dict) else _billing_settings(db)
    discount_pct = _bounded_float(
        settings_value.get("quarter_discount_pct"),
        _default_billing_settings()["quarter_discount_pct"],
        0.0,
        80.0,
    )
    quarterly_specs = {
        "vip-quarter": {
            "monthly_key": "vip",
            "name": "专业版·季付",
            "description": f"一次购买 3 个月专业版，按月付价格优惠 {discount_pct:g}%",
            "role": "vip",
            "sort_order": 35,
            "features": [
                "包含专业版全部能力",
                f"有效期 90 天，季度价格优惠 {discount_pct:g}%",
                "每月发放 10000 AI 使用额度",
                "支持升级旗舰版时按剩余价值补差价",
            ],
        },
        "svip-quarter": {
            "monthly_key": "svip",
            "name": "旗舰版·季付",
            "description": f"一次购买 3 个月旗舰版，按月付价格优惠 {discount_pct:g}%",
            "role": "svip",
            "sort_order": 55,
            "features": [
                "包含旗舰版全部能力",
                f"有效期 90 天，季度价格优惠 {discount_pct:g}%",
                "每月发放 50000 AI 使用额度",
                "高额度批量研究、AI分析师和风险评估",
            ],
        },
    }
    for key, spec in quarterly_specs.items():
        monthly = db.query(SubscriptionPlan).filter(SubscriptionPlan.key == spec["monthly_key"]).first()
        if not monthly:
            continue
        plan = db.query(SubscriptionPlan).filter(SubscriptionPlan.key == key).first()
        if not plan:
            plan = SubscriptionPlan(key=key)
            db.add(plan)
            plan.enabled = 1 if monthly.enabled else 0
        plan.name = spec["name"]
        plan.description = spec["description"]
        plan.role = spec["role"]
        plan.currency = monthly.currency or "CNY"
        plan.interval = "quarter"
        plan.price_cents = _quarter_plan_price_cents(int(monthly.price_cents or 0), discount_pct)
        plan.credits = max(0, int(monthly.credits or 0))
        plan.sort_order = int(spec["sort_order"])
        monthly_credits = max(0, int(monthly.credits or 0))
        features = [
            feature
            .replace("10000", str(monthly_credits))
            .replace("50000", str(monthly_credits))
            for feature in spec["features"]
        ]
        plan.features_json = json.dumps(features, ensure_ascii=False)
    if commit:
        db.commit()


def _refresh_legacy_plan_copy(plan: SubscriptionPlan, defaults: dict) -> None:
    key = str(plan.key or "").lower()
    name = str(plan.name or "")
    description = str(plan.description or "")
    if key == "vip" and name in {"专业版", "VIP"}:
        plan.name = defaults["name"]
    if key in {"svip", "svip-year"} and ("机构" in name or name in {"SVIP", "旗舰版"}):
        plan.name = defaults["name"]
    if key in {"vip-year"} and "机构" in description:
        plan.description = defaults["description"]
    if key in {"svip", "svip-year"} and ("机构" in description or "团队和机构" in description):
        plan.description = defaults["description"]
    if plan.features_json:
        next_features = (
            plan.features_json
            .replace("AI 积分", "AI 使用额度")
            .replace("按积分计费", "按额度计费")
            .replace("升级机构版", "升级旗舰版")
            .replace("包含机构版全部能力", "包含旗舰版全部能力")
            .replace("每周期 500 AI 使用额度", "每月 500 AI 使用额度")
            .replace("30 天专业版完整功能", "1 个月专业版完整功能")
            .replace("每周期 10000 AI 使用额度", "每月发放 10000 AI 使用额度")
            .replace("全年共 120000 AI 使用额度", "每月发放 10000 AI 使用额度")
            .replace("每周期 30000 AI 使用额度", "每月发放 10000 AI 使用额度")
            .replace("每周期 70000 AI 使用额度", "每月发放 50000 AI 使用额度")
            .replace("全年共 840000 AI 使用额度", "每月发放 50000 AI 使用额度")
            .replace("每周期 210000 AI 使用额度", "每月发放 50000 AI 使用额度")
            .replace("智能推荐", "AI 观察池")
            .replace("推荐股票", "观察样本")
            .replace("推荐个股", "观察样本")
            .replace("推荐数量", "观察额度")
            .replace("推荐额度", "观察额度")
            .replace("买入建议", "观察理由")
        )
        if key == "svip" and "团队和机构" in next_features:
            next_features = next_features.replace(
                "团队和机构",
                "高频和大资金投资者",
            )
        if next_features != plan.features_json:
            plan.features_json = next_features


def ensure_default_subscription_plans():
    db = SessionLocal()
    try:
        for item in DEFAULT_PLAN_DEFINITIONS:
            plan = db.query(SubscriptionPlan).filter(SubscriptionPlan.key == item["key"]).first()
            if not plan:
                plan = SubscriptionPlan(
                    key=item["key"],
                    name=item["name"],
                    description=item["description"],
                    role=item["role"],
                    price_cents=int(item["price_cents"] or 0),
                    currency="CNY",
                    interval=item.get("interval") or "month",
                    credits=int(item["credits"] or 0),
                    enabled=1,
                    sort_order=int(item["sort_order"] or 100),
                    features_json=json.dumps(item["features"], ensure_ascii=False),
                )
                db.add(plan)
                continue
            if not plan.name:
                plan.name = item["name"]
            if not plan.description:
                plan.description = item["description"]
            if not plan.role:
                plan.role = item["role"]
            if not plan.currency:
                plan.currency = "CNY"
            if not plan.interval:
                plan.interval = item.get("interval") or "month"
            if not plan.features_json:
                plan.features_json = json.dumps(item["features"], ensure_ascii=False)
            _refresh_legacy_plan_copy(plan, item)
            if plan.key in DEFAULT_PLAN_PRICE_UPGRADES:
                old_prices, new_price = DEFAULT_PLAN_PRICE_UPGRADES[plan.key]
                if int(plan.price_cents or 0) in old_prices:
                    plan.price_cents = new_price
            if plan.key in DEFAULT_PLAN_CREDIT_UPGRADES:
                old_credits, new_credits = DEFAULT_PLAN_CREDIT_UPGRADES[plan.key]
                if int(plan.credits or 0) in old_credits:
                    plan.credits = new_credits
            if plan.key == "free":
                if int(plan.credits or 0) == 1000:
                    plan.credits = int(item["credits"] or 0)
                if plan.features_json and "每周期 1000 AI 积分" in plan.features_json:
                    plan.features_json = plan.features_json.replace("每周期 1000 AI 积分", "每月 500 AI 使用额度")
                old_free_subscriptions = (
                    db.query(UserSubscription)
                    .filter(
                        UserSubscription.plan_key == "free",
                        UserSubscription.status == "active",
                        UserSubscription.credits_total == 1000,
                    )
                    .all()
                )
                for subscription in old_free_subscriptions:
                    subscription.credits_total = max(
                        int(item["credits"] or 0),
                        int(subscription.credits_used or 0),
                    )
        _sync_quarter_subscription_plans(
            db,
            _billing_settings(db),
            commit=False,
        )
        db.commit()
    except Exception as e:
        db.rollback()
        print(f"[subscription] seed default plans failed: {e}")
    finally:
        db.close()


def _plan_duration_days(plan: SubscriptionPlan) -> int:
    key = (getattr(plan, "key", "") or "").lower()
    if key == "vip-full-trial":
        return 30
    interval = (plan.interval or "month").lower()
    if interval in {"trial", "14day", "14-day"}:
        return 14
    if interval in {"quarter", "quarterly", "season"}:
        return 90
    if interval in {"year", "annual", "annually"}:
        return 365
    if interval in {"week", "weekly"}:
        return 7
    return 30


def _add_calendar_months(value: datetime, months: int) -> datetime:
    source = _as_naive_utc(value) or _utcnow()
    month_index = source.month - 1 + max(0, int(months or 0))
    year = source.year + month_index // 12
    month = month_index % 12 + 1
    day = min(source.day, calendar.monthrange(year, month)[1])
    return source.replace(year=year, month=month, day=day)


def _plan_monthly_credit_cycles(plan: Optional[SubscriptionPlan]) -> int:
    if not plan:
        return 1
    key = (getattr(plan, "key", "") or "").lower()
    interval = (getattr(plan, "interval", "") or "month").lower()
    if interval in {"quarter", "quarterly", "season"} or "quarter" in key:
        return 3
    if interval in {"year", "annual", "annually"} or "year" in key:
        return 12
    return 1


def _subscription_monthly_credit_cycles_due(
    sub: UserSubscription,
    *,
    now: Optional[datetime] = None,
) -> int:
    total_cycles = _plan_monthly_credit_cycles(sub.plan)
    if total_cycles <= 1:
        return 1
    current_time = _as_naive_utc(now) or _utcnow()
    started_at = (
        _as_naive_utc(sub.started_at)
        or _as_naive_utc(getattr(sub, "created_at", None))
        or current_time
    )
    expires_at = _as_naive_utc(sub.expires_at)
    effective_time = min(current_time, expires_at) if expires_at else current_time
    if effective_time < started_at:
        return 0
    due_cycles = 1
    for cycle in range(1, total_cycles):
        if _add_calendar_months(started_at, cycle) <= effective_time:
            due_cycles += 1
        else:
            break
    return due_cycles


def _grant_due_subscription_monthly_credits(
    db: Session,
    sub: Optional[UserSubscription],
    *,
    now: Optional[datetime] = None,
) -> int:
    if not sub or sub.status != "active" or not sub.plan:
        return 0
    total_cycles = _plan_monthly_credit_cycles(sub.plan)
    if total_cycles <= 1:
        return 0
    monthly_credits = max(0, int(sub.plan.credits or 0))
    if monthly_credits <= 0:
        return 0

    upfront_reference = (
        db.query(CreditLedger)
        .filter(
            CreditLedger.subscription_id == sub.id,
            CreditLedger.action == "subscription_grant",
            CreditLedger.status == "granted",
        )
        .order_by(CreditLedger.id.asc())
        .first()
    )
    full_cycle_total = monthly_credits * total_cycles
    if upfront_reference and int(upfront_reference.amount or 0) >= full_cycle_total:
        return 0
    if not upfront_reference and int(sub.credits_total or 0) >= full_cycle_total:
        return 0

    due_cycles = _subscription_monthly_credit_cycles_due(sub, now=now)
    granted = 0
    for cycle in range(2, due_cycles + 1):
        reference_id = f"subscription-monthly:{sub.id}:{cycle}"
        existing = (
            db.query(CreditLedger.id)
            .filter(
                CreditLedger.subscription_id == sub.id,
                CreditLedger.reference_id == reference_id,
                CreditLedger.status == "granted",
            )
            .first()
        )
        if existing:
            continue
        sub.credits_total = int(sub.credits_total or 0) + monthly_credits
        granted += monthly_credits
        db.add(
            CreditLedger(
                user_id=sub.user_id,
                subscription_id=sub.id,
                action="subscription_monthly_grant",
                amount=monthly_credits,
                balance_after=max(0, int(sub.credits_total or 0) - int(sub.credits_used or 0)),
                reference_id=reference_id,
                status="granted",
                meta_json=json.dumps(
                    {
                        "plan_key": sub.plan_key,
                        "monthly_credits": monthly_credits,
                        "cycle": cycle,
                        "total_cycles": total_cycles,
                    },
                    ensure_ascii=False,
                ),
            )
        )
    if granted:
        db.flush()
    return granted


def _active_subscription_query(db: Session, user_id: int):
    now = _utcnow()
    return (
        db.query(UserSubscription)
        .filter(
            UserSubscription.user_id == user_id,
            UserSubscription.status == "active",
            or_(UserSubscription.expires_at.is_(None), UserSubscription.expires_at > now),
        )
        .order_by(UserSubscription.created_at.desc())
    )


def _expire_elapsed_paid_subscription(db: Session, user: UserModel) -> bool:
    """Downgrade a paid account once its last active paid term has elapsed."""
    role = normalize_user_role(user.role)
    if role not in {"vip", "svip"}:
        return False

    now = _utcnow()
    expired_rows = (
        db.query(UserSubscription)
        .filter(
            UserSubscription.user_id == user.id,
            UserSubscription.status == "active",
            UserSubscription.expires_at.is_not(None),
            UserSubscription.expires_at <= now,
        )
        .all()
    )
    if not expired_rows:
        return False

    for row in expired_rows:
        row.status = "expired"

    still_active = (
        db.query(UserSubscription.id)
        .filter(
            UserSubscription.user_id == user.id,
            UserSubscription.status == "active",
            UserSubscription.role == role,
            or_(UserSubscription.expires_at.is_(None), UserSubscription.expires_at > now),
        )
        .first()
    )
    if not still_active:
        user.role = "normal"
    return True


def _plan_key_for_role(role: Optional[str]) -> str:
    return {
        "normal": "free",
        "vip": "vip",
        "svip": "svip",
    }.get(normalize_user_role(role), "free")


def _subscription_plan_for_role(db: Session, role: Optional[str]) -> SubscriptionPlan:
    role_plan_key = _plan_key_for_role(role)
    plan = (
        db.query(SubscriptionPlan)
        .filter(SubscriptionPlan.key == role_plan_key, SubscriptionPlan.enabled == 1)
        .first()
        or db.query(SubscriptionPlan)
        .filter(SubscriptionPlan.enabled == 1)
        .order_by(SubscriptionPlan.sort_order.asc())
        .first()
    )
    if not plan:
        raise HTTPException(status_code=503, detail="subscription plans not initialized")
    return plan


def _new_user_subscription_for_plan(
    db: Session,
    user: UserModel,
    plan: SubscriptionPlan,
    source_order_no: str,
) -> UserSubscription:
    now = _utcnow()
    sub = UserSubscription(
        user_id=user.id,
        plan_id=plan.id,
        plan_key=plan.key,
        plan_name=plan.name,
        role=normalize_user_role(plan.role),
        credits_total=int(plan.credits or 0),
        credits_used=0,
        status="active",
        source_order_no=source_order_no,
        started_at=now,
        expires_at=now + timedelta(days=_plan_duration_days(plan)),
    )
    db.add(sub)
    db.flush()
    return sub


def _sync_user_subscription_to_role(
    db: Session,
    user: UserModel,
    source_order_no: str = "auto-role-plan",
) -> Optional[UserSubscription]:
    role = normalize_user_role(user.role)
    active_rows = _active_subscription_query(db, user.id).all()
    if role == "admin":
        for active in active_rows:
            active.status = "replaced"
        db.flush()
        return None

    plan = _subscription_plan_for_role(db, role)
    active = active_rows[0] if active_rows else None
    if (
        active
        and normalize_user_role(active.role) == role
    ):
        return active

    if not active and role in {"vip", "svip"} and source_order_no == "auto-role-plan":
        latest = (
            db.query(UserSubscription)
            .filter(UserSubscription.user_id == user.id)
            .order_by(UserSubscription.created_at.desc())
            .first()
        )
        latest_source = str(getattr(latest, "source_order_no", "") or "")
        if latest and latest_source and not latest_source.startswith(("auto-role-plan", "admin-role-sync:")):
            if latest.status == "active":
                latest.status = "expired"
            user.role = "normal"
            role = "normal"
            plan = _subscription_plan_for_role(db, role)

    for active_row in active_rows:
        active_row.status = "replaced"
    return _new_user_subscription_for_plan(db, user, plan, source_order_no)


def _ensure_user_subscription(
    db: Session,
    user: UserModel,
    *,
    commit: bool = True,
) -> Optional[UserSubscription]:
    if normalize_user_role(user.role) == "admin":
        return None
    sub = _sync_user_subscription_to_role(db, user, source_order_no="auto-role-plan")
    _grant_due_subscription_monthly_credits(db, sub)
    if commit:
        db.commit()
    else:
        db.flush()
    if commit and sub is not None:
        db.refresh(sub)
    return sub


def _serialize_subscription(sub: Optional[UserSubscription]) -> Optional[dict]:
    if not sub:
        return None
    return {
        "id": sub.id,
        "plan_id": sub.plan_id,
        "plan_key": sub.plan_key,
        "plan_name": sub.plan_name,
        "role": normalize_user_role(sub.role),
        "interval": (sub.plan.interval or "month") if sub.plan else "month",
        "duration_days": _plan_duration_days(sub.plan) if sub.plan else 30,
        "credits_total": int(sub.credits_total or 0),
        "credits_used": int(sub.credits_used or 0),
        "credits_remaining": max(0, int(sub.credits_total or 0) - int(sub.credits_used or 0)),
        "status": sub.status,
        "started_at": sub.started_at.isoformat() if sub.started_at else None,
        "expires_at": sub.expires_at.isoformat() if sub.expires_at else None,
        "source_order_no": sub.source_order_no or "",
    }


def _role_rank(role: Optional[str]) -> int:
    return {"normal": 0, "vip": 1, "svip": 2, "admin": 99}.get(
        normalize_user_role(role), 0
    )


def _is_trial_plan(plan: SubscriptionPlan) -> bool:
    return (plan.interval or "").lower() == "trial" or "trial" in (plan.key or "").lower()


def _trial_purchase_eligibility(
    db: Session,
    user: UserModel,
) -> tuple[bool, str]:
    prior_trial = (
        db.query(UserSubscription.id)
        .join(SubscriptionPlan, SubscriptionPlan.id == UserSubscription.plan_id)
        .filter(
            UserSubscription.user_id == user.id,
            or_(
                SubscriptionPlan.interval == "trial",
                SubscriptionPlan.key.ilike("%trial%"),
            ),
        )
        .first()
    )
    if prior_trial:
        return False, "每个账号仅可订阅一次试用版"

    overrides = _get_system_setting_json(
        db,
        TRIAL_ELIGIBILITY_OVERRIDES_KEY,
        {"users": []},
    )
    allowed_users = {
        str(item).strip().lower()
        for item in (overrides.get("users") or [])
        if str(item).strip()
    }
    if str(user.id) in allowed_users or (user.username or "").strip().lower() in allowed_users:
        return True, ""

    prior_paid_tier = (
        db.query(UserSubscription.id)
        .filter(
            UserSubscription.user_id == user.id,
            UserSubscription.role.in_(["vip", "svip"]),
        )
        .first()
    )
    if prior_paid_tier or _role_rank(user.role) > 0:
        return False, "试用版仅面向从未订阅过付费版本的免费新用户"
    return True, ""


def _subscription_checkout_quote(
    db: Session,
    user: UserModel,
    plan: SubscriptionPlan,
) -> dict:
    now = _utcnow()
    target_price = max(0, int(plan.price_cents or 0))
    target_role = normalize_user_role(plan.role)
    target_duration = _plan_duration_days(plan)
    is_trial = _is_trial_plan(plan)
    result = {
        "plan_id": plan.id,
        "plan_key": plan.key,
        "base_amount_cents": target_price,
        "credit_cents": 0,
        "amount_cents": target_price,
        "currency": plan.currency or "CNY",
        "eligible": True,
        "reason": "",
        "is_upgrade": False,
        "is_renewal": False,
        "is_trial": is_trial,
        "upgrade_from_subscription_id": None,
        "carryover_credits": 0,
        "duration_days": target_duration,
    }
    if normalize_user_role(user.role) == "admin":
        result.update({"eligible": False, "reason": "系统管理员无需购买套餐"})
        return result
    if target_price <= 0:
        result.update({"eligible": False, "reason": "免费套餐无需购买"})
        return result

    if is_trial:
        eligible, reason = _trial_purchase_eligibility(db, user)
        if not eligible:
            result.update({"eligible": False, "reason": reason})
            return result

    active = _active_subscription_query(db, user.id).first()
    if not active or not active.plan:
        return result
    _grant_due_subscription_monthly_credits(db, active, now=now)
    current_plan = active.plan
    current_rank = _role_rank(active.role)
    target_rank = _role_rank(target_role)
    current_duration = _plan_duration_days(current_plan)
    remaining_credits = max(
        0, int(active.credits_total or 0) - int(active.credits_used or 0)
    )

    if target_rank < current_rank:
        result.update({"eligible": False, "reason": "当前订阅到期后可切换到较低套餐"})
        return result
    if target_rank == current_rank and active.plan_id == plan.id:
        result.update(
            {
                "is_renewal": True,
                "carryover_credits": remaining_credits,
                "upgrade_from_subscription_id": active.id,
            }
        )
        return result
    if target_rank == current_rank and target_duration < current_duration:
        result.update({"eligible": False, "reason": "当前长周期套餐到期后可切换为短周期套餐"})
        return result

    if target_rank > current_rank or target_duration > current_duration:
        active_expires_at = _as_naive_utc(active.expires_at)
        remaining_seconds = max(
            0.0,
            ((active_expires_at or now) - now).total_seconds(),
        )
        total_seconds = max(1.0, current_duration * 86400.0)
        unused_value = min(
            max(0, int(current_plan.price_cents or 0)),
            int(round(max(0, int(current_plan.price_cents or 0)) * remaining_seconds / total_seconds)),
        )
        result.update(
            {
                "credit_cents": unused_value,
                "amount_cents": max(0, target_price - unused_value),
                "is_upgrade": True,
                "upgrade_from_subscription_id": active.id,
                "carryover_credits": remaining_credits,
            }
        )
    return result


def _create_subscription_for_plan(
    db: Session,
    user: UserModel,
    plan: SubscriptionPlan,
    *,
    source_order_no: str,
    credits_total: int,
    duration_days: Optional[int] = None,
    carryover_credits: int = 0,
    action: str = "subscription_grant",
    meta: Optional[dict] = None,
    expires_base: Optional[datetime] = None,
    replace_active: bool = True,
    plan_name: Optional[str] = None,
) -> UserSubscription:
    now = _utcnow()
    active_rows = _active_subscription_query(db, user.id).all() if replace_active else []
    for active in active_rows:
        _grant_due_subscription_monthly_credits(db, active, now=now)
    if replace_active:
        for active in active_rows:
            active.status = "replaced"

    user.role = normalize_user_role(plan.role)
    base_time = _as_naive_utc(expires_base) or now
    duration = max(1, int(duration_days or _plan_duration_days(plan)))
    plan_credits = max(0, int(credits_total or 0))
    carryover = max(0, int(carryover_credits or 0))
    sub = UserSubscription(
        user_id=user.id,
        plan_id=plan.id,
        plan_key=plan.key,
        plan_name=plan_name or plan.name,
        role=normalize_user_role(plan.role),
        credits_total=plan_credits + carryover,
        credits_used=0,
        status="active",
        source_order_no=source_order_no,
        started_at=now,
        expires_at=base_time + timedelta(days=duration),
    )
    db.add(sub)
    db.flush()
    db.add(
        CreditLedger(
            user_id=user.id,
            subscription_id=sub.id,
            action=action,
            amount=plan_credits,
            balance_after=int(sub.credits_total or 0),
            reference_id=source_order_no,
            status="granted",
            meta_json=json.dumps(
                {
                    "plan_key": plan.key,
                    "plan_credits": plan_credits,
                    "carryover_credits": carryover,
                    "duration_days": duration,
                    **(meta or {}),
                },
                ensure_ascii=False,
            ),
        )
    )
    return sub


def _redeem_subscription_code(
    db: Session,
    user: UserModel,
    *,
    code_value: str,
    request: Optional[Request] = None,
) -> dict:
    if normalize_user_role(user.role) == "admin":
        raise HTTPException(status_code=400, detail="系统管理员无需兑换套餐")
    code = _normalize_redeem_code(code_value)
    if not code:
        raise HTTPException(status_code=400, detail="请输入兑换码")
    row = (
        db.query(RedeemCode)
        .filter(RedeemCode.code == code)
        .with_for_update()
        .first()
    )
    if not row:
        raise HTTPException(status_code=404, detail="兑换码不存在")
    now = _utcnow()
    if not row.enabled:
        raise HTTPException(status_code=400, detail="兑换码已停用")
    starts_at = _as_naive_utc(row.starts_at)
    expires_at = _as_naive_utc(row.expires_at)
    if starts_at and now < starts_at:
        raise HTTPException(status_code=400, detail="兑换码尚未生效")
    if expires_at and now > expires_at:
        raise HTTPException(status_code=400, detail="兑换码已过期")
    if int(row.used_count or 0) >= int(row.max_uses or 1):
        raise HTTPException(status_code=400, detail="兑换码使用次数已用完")
    user_use_count = (
        db.query(func.count(RedeemCodeUse.id))
        .filter(RedeemCodeUse.code_id == row.id, RedeemCodeUse.user_id == user.id)
        .scalar()
        or 0
    )
    if int(user_use_count) >= int(row.per_user_limit or 1):
        raise HTTPException(status_code=400, detail="该兑换码已被当前账号使用")
    plan = row.plan or db.query(SubscriptionPlan).filter(SubscriptionPlan.id == row.plan_id).first()
    if not plan:
        raise HTTPException(status_code=404, detail="兑换码关联套餐不存在")
    if not plan.enabled:
        raise HTTPException(status_code=400, detail="兑换码关联套餐未启用")

    active_rows = _active_subscription_query(db, user.id).all()
    for active in active_rows:
        _grant_due_subscription_monthly_credits(db, active, now=now)
    carryover_credits = sum(
        max(0, int(active.credits_total or 0) - int(active.credits_used or 0))
        for active in active_rows
    )
    duration_days = int(row.duration_days or _plan_duration_days(plan))
    source_order_no = f"redeem:{row.code}:{uuid.uuid4().hex[:10]}"
    sub = _create_subscription_for_plan(
        db,
        user,
        plan,
        source_order_no=source_order_no,
        credits_total=int(row.credits or plan.credits or 0),
        duration_days=duration_days,
        carryover_credits=carryover_credits,
        action="redeem_code_grant",
        meta={
            "redeem_code_id": row.id,
            "redeem_code": row.code,
            "plan_key": plan.key,
        },
    )
    row.used_count = int(row.used_count or 0) + 1
    row.last_used_at = now
    db.add(
        RedeemCodeUse(
            code_id=row.id,
            code=row.code,
            user_id=user.id,
            subscription_id=sub.id,
            ip_hash=_request_ip_hash(request) if request is not None else None,
            meta_json=json.dumps(
                {
                    "plan_key": plan.key,
                    "plan_name": plan.name,
                    "credits": int(row.credits or plan.credits or 0),
                    "duration_days": duration_days,
                    "carryover_credits": carryover_credits,
                },
                ensure_ascii=False,
            ),
        )
    )
    db.commit()
    db.refresh(sub)
    return {
        "status": "ok",
        "message": "兑换成功，订阅权益已更新",
        "redeem_code": _serialize_redeem_code(row),
        "subscription": _serialize_subscription(sub),
        "subscription_state": _subscription_self_payload(db, user),
    }


def _grant_email_registration_bonus_subscription(
    db: Session,
    user: UserModel,
) -> None:
    email_value = (getattr(user, "email", "") or "").strip().lower()
    if not email_value:
        return
    reference_id = f"email-register-bonus:{user.id}"
    existing = (
        db.query(UserSubscription.id)
        .filter(
            UserSubscription.user_id == user.id,
            UserSubscription.source_order_no == reference_id,
        )
        .first()
    )
    if existing:
        return
    plan = _subscription_plan_for_role(db, "normal")
    bonus_credits = 300
    base_credits = max(0, int(plan.credits or 0))
    _create_subscription_for_plan(
        db,
        user,
        plan,
        source_order_no=reference_id,
        credits_total=base_credits + bonus_credits,
        duration_days=14,
        action="email_register_bonus",
        meta={
            "email": email_value,
            "base_credits": base_credits,
            "bonus_credits": bonus_credits,
            "bonus_days": 14,
        },
        replace_active=True,
        plan_name="邮箱注册体验权益",
    )


def _grant_user_credits(
    db: Session,
    user: UserModel,
    *,
    action: str,
    credits: int,
    reference_id: str,
    meta: Optional[dict] = None,
) -> dict:
    credits = max(0, int(credits or 0))
    if credits <= 0 or normalize_user_role(user.role) == "admin":
        return _credit_summary(db, user)
    existing = (
        db.query(CreditLedger)
        .filter(
            CreditLedger.user_id == user.id,
            CreditLedger.reference_id == reference_id,
            CreditLedger.status == "granted",
        )
        .first()
    )
    if existing:
        return _credit_summary(db, user)
    sub = _ensure_user_subscription(db, user, commit=False)
    sub.credits_total = int(sub.credits_total or 0) + credits
    balance_after = int(sub.credits_total or 0) - int(sub.credits_used or 0)
    db.add(
        CreditLedger(
            user_id=user.id,
            subscription_id=sub.id,
            action=action,
            amount=credits,
            balance_after=balance_after,
            reference_id=reference_id,
            status="granted",
            meta_json=json.dumps(meta or {}, ensure_ascii=False),
        )
    )
    db.commit()
    return _credit_summary(db, user)


def _credit_summary(db: Session, user: UserModel) -> dict:
    if normalize_user_role(user.role) == "admin":
        return {
            "unlimited": True,
            "role": "admin",
            "credits_total": None,
            "credits_used": 0,
            "credits_remaining": None,
            "subscription": None,
        }
    sub = _ensure_user_subscription(db, user)
    total = int(sub.credits_total or 0)
    used = int(sub.credits_used or 0)
    return {
        "unlimited": False,
        "role": normalize_user_role(user.role),
        "credits_total": total,
        "credits_used": used,
        "credits_remaining": max(0, total - used),
        "subscription": _serialize_subscription(sub),
    }


def _consume_user_credits(
    db: Session,
    user: UserModel,
    action: str,
    cost: int,
    reference_id: Optional[str] = None,
    meta: Optional[dict] = None,
) -> dict:
    cost = int(cost or 0)
    if cost <= 0 or normalize_user_role(user.role) == "admin":
        summary = _credit_summary(db, user)
        summary["last_charge"] = {"action": action, "cost": 0, "charged": False}
        return summary
    sub = _ensure_user_subscription(db, user, commit=False)
    updated = (
        db.query(UserSubscription)
        .filter(
            UserSubscription.id == sub.id,
            UserSubscription.status == "active",
            UserSubscription.credits_used <= UserSubscription.credits_total - cost,
        )
        .update(
            {UserSubscription.credits_used: UserSubscription.credits_used + cost},
            synchronize_session=False,
        )
    )
    if updated != 1:
        db.rollback()
        summary = _credit_summary(db, user)
        raise HTTPException(
            status_code=402,
            detail={
                "code": "INSUFFICIENT_CREDITS",
                "message": "AI 使用额度不足，请升级订阅或等待额度重置",
                "action": action,
                "cost": cost,
                "credit_summary": summary,
            },
        )
    db.flush()
    sub = db.query(UserSubscription).filter(UserSubscription.id == sub.id).first()
    balance_after = int(sub.credits_total or 0) - int(sub.credits_used or 0)
    db.add(
        CreditLedger(
            user_id=user.id,
            subscription_id=sub.id,
            action=action,
            amount=cost,
            balance_after=balance_after,
            reference_id=reference_id or f"{action}:{uuid.uuid4().hex}",
            status="consumed",
            meta_json=json.dumps(meta or {}, ensure_ascii=False),
        )
    )
    db.commit()
    summary = _credit_summary(db, user)
    summary["last_charge"] = {
        "action": action,
        "cost": cost,
        "charged": True,
        "balance_after": balance_after,
    }
    return summary


def _refund_consumed_credits(
    db: Session,
    user: UserModel,
    *,
    action: str,
    reference_id: str,
    meta: Optional[dict] = None,
) -> int:
    """Refund one idempotent charge when infrastructure prevents execution."""
    if normalize_user_role(user.role) == "admin":
        return 0
    refund_reference = f"{reference_id}:refund"
    if (
        db.query(CreditLedger)
        .filter(
            CreditLedger.user_id == user.id,
            CreditLedger.reference_id == refund_reference,
            CreditLedger.status == "refunded",
        )
        .first()
    ):
        return 0
    charge = (
        db.query(CreditLedger)
        .filter(
            CreditLedger.user_id == user.id,
            CreditLedger.reference_id == reference_id,
            CreditLedger.status == "consumed",
        )
        .with_for_update()
        .first()
    )
    if not charge or int(charge.amount or 0) <= 0:
        return 0
    subscription = (
        db.query(UserSubscription)
        .filter(UserSubscription.id == charge.subscription_id)
        .with_for_update()
        .first()
    )
    if not subscription:
        return 0
    refund_amount = min(int(charge.amount or 0), int(subscription.credits_used or 0))
    if refund_amount <= 0:
        return 0
    subscription.credits_used = max(0, int(subscription.credits_used or 0) - refund_amount)
    balance_after = int(subscription.credits_total or 0) - int(subscription.credits_used or 0)
    db.add(
        CreditLedger(
            user_id=user.id,
            subscription_id=subscription.id,
            action=f"{action}_refund",
            amount=-refund_amount,
            balance_after=balance_after,
            reference_id=refund_reference,
            status="refunded",
            meta_json=json.dumps(meta or {}, ensure_ascii=False),
        )
    )
    # Keep the charge row, subscription balance and task refund marker in the
    # caller's transaction. Committing here released the task row lock before
    # refunded_credits was updated, allowing concurrent retries to overwrite
    # the marker even though the ledger refund itself was idempotent.
    db.flush()
    return refund_amount


def _refund_smart_research_task(task_id: int, failure_class: str = "system_error") -> int:
    """Refund a queued research batch exactly once after infrastructure failure."""
    db = SessionLocal()
    try:
        task = (
            db.query(SmartResearchTask)
            .filter(SmartResearchTask.id == int(task_id))
            .with_for_update()
            .first()
        )
        if not task or int(getattr(task, "charged_credits", 0) or 0) <= 0:
            return 0
        if int(getattr(task, "refunded_credits", 0) or 0) >= int(task.charged_credits or 0):
            return 0
        user = db.query(UserModel).filter(UserModel.id == task.user_id).first()
        if not user:
            return 0
        refunded = _refund_consumed_credits(
            db,
            user,
            action="smart_research",
            reference_id=f"smart_research:{task.id}",
            meta={"task_id": task.id, "failure_class": failure_class},
        )
        task.refunded_credits = int(task.refunded_credits or 0) + refunded
        task.failure_class = failure_class
        db.commit()
        return refunded
    finally:
        db.close()


def _refund_background_credit_task(
    model,
    task_id: int,
    *,
    action: str,
    reference_prefix: str,
    failure_class: str = "system_error",
) -> int:
    """Refund a charged AI job once when infrastructure prevents completion."""
    db = SessionLocal()
    try:
        task = db.query(model).filter(model.id == int(task_id)).with_for_update().first()
        charged = int(getattr(task, "charged_credits", 0) or 0) if task else 0
        refunded = int(getattr(task, "refunded_credits", 0) or 0) if task else 0
        if not task or charged <= 0 or refunded >= charged:
            return 0
        user = db.query(UserModel).filter(UserModel.id == task.user_id).first()
        if not user:
            return 0
        amount = _refund_consumed_credits(
            db,
            user,
            action=action,
            reference_id=f"{reference_prefix}:{task.id}",
            meta={"task_id": task.id, "failure_class": failure_class},
        )
        task.refunded_credits = refunded + amount
        task.failure_class = failure_class
        db.commit()
        return amount
    finally:
        db.close()


def _refund_ai_insight_task(task_id: int, failure_class: str = "system_error") -> int:
    return _refund_background_credit_task(
        AIInsightTask,
        task_id,
        action="ai_insights",
        reference_prefix="ai_insights",
        failure_class=failure_class,
    )


def _refund_risk_assessment_task(task_id: int, failure_class: str = "system_error") -> int:
    return _refund_background_credit_task(
        RiskAssessmentTask,
        task_id,
        action="risk_ai_assessment",
        reference_prefix="risk_ai_assessment",
        failure_class=failure_class,
    )


def _assistant_conversation_quota(db: Session, user: UserModel) -> dict:
    role = normalize_user_role(getattr(user, "role", None))
    limit = ASSISTANT_CONVERSATION_LIMITS.get(role, ASSISTANT_CONVERSATION_LIMITS["normal"])
    if role == "admin" or limit is None:
        return {
            "unlimited": True,
            "role": role,
            "limit": None,
            "used": 0,
            "remaining": None,
            "cycle_started_at": None,
            "cycle_expires_at": None,
        }

    sub = _ensure_user_subscription(db, user)
    cycle_started_at = sub.started_at or _utcnow() - timedelta(
        days=_plan_duration_days(sub.plan) if getattr(sub, "plan", None) else 30
    )
    query = db.query(func.count(CreditLedger.id)).filter(
        CreditLedger.user_id == user.id,
        CreditLedger.action == ASSISTANT_CONVERSATION_ACTION,
        CreditLedger.status == "consumed",
        CreditLedger.subscription_id == sub.id,
    )
    used = int(query.scalar() or 0)
    return {
        "unlimited": False,
        "role": role,
        "limit": int(limit),
        "used": used,
        "remaining": max(0, int(limit) - used),
        "cycle_started_at": cycle_started_at.isoformat() if cycle_started_at else None,
        "cycle_expires_at": sub.expires_at.isoformat() if sub.expires_at else None,
    }


def _consume_assistant_conversation(
    db: Session,
    user: UserModel,
    reference_id: Optional[str] = None,
    meta: Optional[dict] = None,
) -> dict:
    quota = _assistant_conversation_quota(db, user)
    if quota.get("unlimited"):
        quota["last_charge"] = {"action": ASSISTANT_CONVERSATION_ACTION, "charged": False}
        return quota
    if int(quota.get("remaining") or 0) <= 0:
        raise HTTPException(
            status_code=402,
            detail={
                "code": "ASSISTANT_QUOTA_EXCEEDED",
                "message": "量化投研助手对话次数已用完，请升级订阅或等待额度重置",
                "assistant_quota": quota,
            },
        )

    sub = _ensure_user_subscription(db, user)
    db.add(
        CreditLedger(
            user_id=user.id,
            subscription_id=sub.id,
            action=ASSISTANT_CONVERSATION_ACTION,
            amount=0,
            balance_after=max(0, int(sub.credits_total or 0) - int(sub.credits_used or 0)),
            reference_id=reference_id or f"{ASSISTANT_CONVERSATION_ACTION}:{uuid.uuid4().hex}",
            status="consumed",
            meta_json=json.dumps(meta or {}, ensure_ascii=False),
        )
    )
    db.commit()
    quota = _assistant_conversation_quota(db, user)
    quota["last_charge"] = {"action": ASSISTANT_CONVERSATION_ACTION, "charged": True}
    return quota


def _complete_subscription_order(
    db: Session,
    trade_no: str,
    provider: str,
    provider_payload: Optional[dict] = None,
    provider_trade_no: Optional[str] = None,
) -> dict:
    order = (
        db.query(SubscriptionOrder)
        .filter(SubscriptionOrder.trade_no == trade_no)
        .with_for_update()
        .first()
    )
    if not order:
        raise ValueError("order not found")
    if order.provider != provider:
        raise ValueError("provider mismatch")
    if order.status == "paid":
        return {"order": order, "completed": False}
    if order.status == "refund_required":
        return {
            "order": order,
            "completed": False,
            "rejected": True,
            "refund_required": True,
            "reason": "试用资格已被其他订单使用",
        }
    if order.status not in {"pending", "created"}:
        raise ValueError("order status invalid")
    plan = db.query(SubscriptionPlan).filter(SubscriptionPlan.id == order.plan_id).first()
    user = (
        db.query(UserModel)
        .filter(UserModel.id == order.user_id)
        .with_for_update()
        .first()
    )
    if not plan or not user:
        raise ValueError("plan or user missing")
    now = _utcnow()
    order_meta = _subscription_order_meta(order)
    if _is_trial_plan(plan):
        eligible, reason = _trial_purchase_eligibility(db, user)
        if not eligible:
            order.status = "refund_required"
            order.provider_trade_no = provider_trade_no or order.provider_trade_no
            order.provider_payload = json.dumps(
                {
                    "order_meta": order_meta,
                    "callback": provider_payload or {},
                    "rejection": {
                        "code": "TRIAL_ALREADY_USED_OR_INELIGIBLE",
                        "reason": reason,
                    },
                },
                ensure_ascii=False,
            )
            order.paid_at = now
            db.commit()
            db.refresh(order)
            return {
                "order": order,
                "completed": False,
                "rejected": True,
                "refund_required": True,
                "reason": reason,
            }
    active_rows = _active_subscription_query(db, user.id).all()
    for active in active_rows:
        _grant_due_subscription_monthly_credits(db, active, now=now)
    source_subscription_id = order_meta.get("upgrade_from_subscription_id")
    source_subscription = next(
        (row for row in active_rows if row.id == source_subscription_id),
        active_rows[0] if active_rows else None,
    )
    carryover_credits = (
        max(
            0,
            int(source_subscription.credits_total or 0)
            - int(source_subscription.credits_used or 0),
        )
        if source_subscription
        else 0
    )
    is_renewal = bool(
        order_meta.get("is_renewal")
        and source_subscription
        and source_subscription.plan_id == plan.id
    )
    if is_renewal and source_subscription.expires_at:
        expires_base = max(now, _as_naive_utc(source_subscription.expires_at) or now)
    else:
        expires_base = now
    for active in active_rows:
        active.status = "replaced"
    order.status = "paid"
    order.provider_trade_no = provider_trade_no or order.provider_trade_no
    order.provider_payload = json.dumps(
        {"order_meta": order_meta, "callback": provider_payload or {}},
        ensure_ascii=False,
    )
    order.paid_at = now
    user.role = normalize_user_role(plan.role)
    sub = UserSubscription(
        user_id=user.id,
        plan_id=plan.id,
        plan_key=plan.key,
        plan_name=plan.name,
        role=normalize_user_role(plan.role),
        credits_total=int(plan.credits or 0) + carryover_credits,
        credits_used=0,
        status="active",
        source_order_no=order.trade_no,
        started_at=now,
        expires_at=expires_base + timedelta(days=_plan_duration_days(plan)),
    )
    db.add(sub)
    db.flush()
    db.add(
        CreditLedger(
            user_id=user.id,
            subscription_id=sub.id,
            action="subscription_grant",
            amount=int(plan.credits or 0),
            balance_after=int(sub.credits_total or 0),
            reference_id=f"subscription:{order.trade_no}",
            status="granted",
            meta_json=json.dumps(
                {
                    "plan_key": plan.key,
                    "plan_credits": int(plan.credits or 0),
                    "carryover_credits": carryover_credits,
                    "quota_grant_period": "month"
                    if _plan_monthly_credit_cycles(plan) > 1
                    else "cycle",
                    "quota_grant_cycle": 1,
                    "quota_total_cycles": _plan_monthly_credit_cycles(plan),
                    "is_upgrade": bool(order_meta.get("is_upgrade")),
                    "is_renewal": is_renewal,
                },
                ensure_ascii=False,
            ),
        )
    )
    db.commit()
    db.refresh(order)
    return {"order": order, "subscription": sub, "completed": True}


def _epay_sign(params: dict, key: str) -> str:
    sign_items = []
    for k in sorted(params.keys()):
        if k in {"sign", "sign_type"}:
            continue
        value = params.get(k)
        if value is None or value == "":
            continue
        sign_items.append(f"{k}={value}")
    raw = "&".join(sign_items) + str(key or "")
    return hashlib.md5(raw.encode("utf-8")).hexdigest()


def _verify_epay_payload(params: dict, secret_key: str) -> bool:
    provided = str(params.get("sign") or "").lower()
    if not provided or not secret_key:
        return False
    expected = _epay_sign(params, secret_key).lower()
    return hmac.compare_digest(provided, expected)


def _normalize_payment_site_url(value: str) -> str:
    """Normalize a configured site origin after it has passed settings validation."""
    parsed = urlparse(str(value or "").strip())
    hostname = (parsed.hostname or "").lower()
    is_local = hostname in {"localhost", "127.0.0.1", "::1"}
    if (
        parsed.scheme not in {"http", "https"}
        or not parsed.netloc
        or parsed.username
        or parsed.password
        or parsed.path not in {"", "/"}
        or parsed.query
        or parsed.fragment
        or (parsed.scheme != "https" and not is_local)
    ):
        return ""
    return urlunparse((parsed.scheme, parsed.netloc, "", "", "", "")).rstrip("/")


def _request_browser_origin(request: Request) -> str:
    """Return a safe browser Origin header for local checkout return pages."""
    parsed = urlparse(str(request.headers.get("origin") or "").strip())
    if (
        parsed.scheme not in {"http", "https"}
        or not parsed.netloc
        or parsed.username
        or parsed.password
        or parsed.path not in {"", "/"}
        or parsed.query
        or parsed.fragment
    ):
        return ""
    return urlunparse((parsed.scheme, parsed.netloc, "", "", "", "")).rstrip("/")


def _payment_callback_base_url(request: Request, settings_value: Optional[dict] = None) -> str:
    configured = _normalize_payment_site_url(
        (settings_value or {}).get("public_api_url", "")
        or (settings_value or {}).get("public_site_url", "")
    )
    if configured:
        return configured
    base_url = str(request.base_url).rstrip("/")
    parsed = urlparse(base_url)
    if (parsed.hostname or "").lower() == "localhost":
        netloc = "127.0.0.1"
        if parsed.port:
            netloc = f"{netloc}:{parsed.port}"
        return urlunparse((parsed.scheme, netloc, parsed.path.rstrip("/"), "", "", "")).rstrip("/")
    return base_url


def _payment_return_url(request: Request, settings_value: dict) -> str:
    """Build a same-site return page; client supplied return_url is intentionally ignored."""
    browser_origin = _request_browser_origin(request)
    browser_host = (urlparse(browser_origin).hostname or "").lower()
    if browser_host in {"localhost", "127.0.0.1", "::1"}:
        base_url = browser_origin
    else:
        base_url = _normalize_payment_site_url(settings_value.get("public_site_url", ""))
    if not base_url:
        base_url = browser_origin or _payment_callback_base_url(request, settings_value)
    return f"{base_url}/settings?tab=subscription"


def _payment_local_callback_notice(request: Request, settings_value: dict) -> bool:
    if settings_value.get("notify_url") or _normalize_payment_site_url(
        settings_value.get("public_api_url", "") or settings_value.get("public_site_url", "")
    ):
        return False
    callback_host = (urlparse(_payment_callback_base_url(request, settings_value)).hostname or "").lower()
    return callback_host in {"localhost", "127.0.0.1", "::1"}


def _epay_payment_method(requested: Optional[str], settings_value: dict) -> str:
    method = (requested or settings_value.get("default_method") or "alipay").strip().lower()
    if method not in EPAY_PAYMENT_METHODS:
        raise HTTPException(status_code=400, detail="不支持的 ePay 方式")
    return method


def _verify_stripe_signature(payload: bytes, signature_header: str, webhook_secret: str) -> bool:
    if not signature_header or not webhook_secret:
        return False
    timestamp = ""
    signatures: list[str] = []
    for part in signature_header.split(","):
        key, _, value = part.partition("=")
        if key == "t":
            timestamp = value
        elif key == "v1":
            signatures.append(value)
    if not timestamp or not signatures:
        return False
    signed_payload = f"{timestamp}.{payload.decode('utf-8')}".encode("utf-8")
    expected = hmac.new(
        webhook_secret.encode("utf-8"), signed_payload, hashlib.sha256
    ).hexdigest()
    return any(hmac.compare_digest(expected, sig) for sig in signatures)


def _stripe_success_cancel_url(base: str, trade_no: str, status_value: str) -> str:
    separator = "&" if "?" in base else "?"
    return f"{base}{separator}{urlencode({'pay': status_value, 'trade_no': trade_no})}"


def _create_stripe_checkout_session(
    *,
    secret_key: str,
    price_id: str = "",
    trade_no: str,
    success_url: str,
    cancel_url: str,
    email: Optional[str] = None,
    amount_cents: Optional[int] = None,
    currency: str = "CNY",
    product_name: str = "AIQuartSmart Community Edition",
) -> str:
    if not (secret_key or "").startswith(("sk_", "rk_")):
        raise HTTPException(status_code=400, detail="Stripe Secret Key 未配置或格式无效")
    if amount_cents is None and not price_id:
        raise HTTPException(status_code=400, detail="该套餐未配置 Stripe Price ID")
    if amount_cents is not None and int(amount_cents) <= 0:
        raise HTTPException(status_code=400, detail="Stripe 支付金额必须大于 0")
    if amount_cents is None:
        line_item_data = {
            "mode": "subscription",
            "line_items[0][price]": price_id,
            "line_items[0][quantity]": "1",
        }
    else:
        line_item_data = {
            "mode": "payment",
            "line_items[0][price_data][currency]": str(currency or "CNY").lower(),
            "line_items[0][price_data][unit_amount]": str(int(amount_cents)),
            "line_items[0][price_data][product_data][name]": str(product_name or "AIQuartSmart Community Edition")[:200],
            "line_items[0][quantity]": "1",
        }
    response = requests.post(
        "https://api.stripe.com/v1/checkout/sessions",
        headers={"Authorization": f"Bearer {secret_key}"},
        data={
            "client_reference_id": trade_no,
            "success_url": success_url,
            "cancel_url": cancel_url,
            "metadata[trade_no]": trade_no,
            **line_item_data,
            **({"customer_email": email} if email else {}),
        },
        timeout=10,
    )
    try:
        payload = response.json()
    except Exception:
        payload = {}
    if response.status_code >= 400:
        message = str(payload.get("error", {}).get("message") or "Stripe Checkout 创建失败")
        raise HTTPException(status_code=502, detail=message[:200])
    checkout_url = str(payload.get("url") or "").strip()
    if not checkout_url:
        raise HTTPException(status_code=502, detail="Stripe 未返回 Checkout URL")
    return checkout_url


def migrate_watchlist_columns():
    from sqlalchemy import text

    try:
        dialect = engine.url.get_backend_name()
        with engine.connect() as conn:
            if dialect == "sqlite":
                result = conn.execute(text("PRAGMA table_info(watchlist_sql)")).fetchall()
                if result:
                    columns = {row[1] for row in result}
                    if "color" not in columns:
                        conn.execute(text("ALTER TABLE watchlist_sql ADD COLUMN color VARCHAR"))
                    if "user_id" not in columns:
                        conn.execute(text("ALTER TABLE watchlist_sql ADD COLUMN user_id INTEGER"))
                    conn.commit()
            elif dialect == "postgresql":
                table_exists = conn.execute(text("SELECT to_regclass('public.watchlist_sql')")).scalar()
                if table_exists:
                    result = conn.execute(
                        text(
                            "SELECT column_name FROM information_schema.columns "
                            "WHERE table_name='watchlist_sql' AND column_name IN ('color', 'user_id')"
                        )
                    ).fetchall()
                    columns = {row[0] for row in result}
                    if "color" not in columns:
                        conn.execute(text("ALTER TABLE watchlist_sql ADD COLUMN color VARCHAR"))
                    if "user_id" not in columns:
                        conn.execute(text("ALTER TABLE watchlist_sql ADD COLUMN user_id INTEGER"))
                    conn.commit()
    except Exception as e:
        print(f"watchlist migration check failed: {e}")


migrate_watchlist_columns()


