def migrate_short_background_task_queue_fields():
    """Add durable queue metadata to the shorter AI and screening jobs."""
    table_columns = {
        "ai_insight_tasks": {
            "error": "TEXT",
            "queue_task_id": "VARCHAR",
            "queue_payload_json": "TEXT",
            "queue_status": "VARCHAR DEFAULT 'inline'",
            "queue_priority": "INTEGER DEFAULT 10",
            "attempt_count": "INTEGER DEFAULT 0",
            "started_at": "TIMESTAMP WITH TIME ZONE",
            "heartbeat_at": "TIMESTAMP WITH TIME ZONE",
            "finished_at": "TIMESTAMP WITH TIME ZONE",
            "failure_class": "VARCHAR",
            "charged_credits": "INTEGER DEFAULT 0",
            "refunded_credits": "INTEGER DEFAULT 0",
        },
        "risk_assessment_tasks": {
            "queue_task_id": "VARCHAR",
            "queue_payload_json": "TEXT",
            "queue_status": "VARCHAR DEFAULT 'inline'",
            "queue_priority": "INTEGER DEFAULT 10",
            "attempt_count": "INTEGER DEFAULT 0",
            "started_at": "TIMESTAMP WITH TIME ZONE",
            "heartbeat_at": "TIMESTAMP WITH TIME ZONE",
            "finished_at": "TIMESTAMP WITH TIME ZONE",
            "failure_class": "VARCHAR",
            "charged_credits": "INTEGER DEFAULT 0",
            "refunded_credits": "INTEGER DEFAULT 0",
        },
        "screener_tasks": {
            "queue_task_id": "VARCHAR",
            "queue_payload_json": "TEXT",
            "queue_status": "VARCHAR DEFAULT 'inline'",
            "queue_priority": "INTEGER DEFAULT 10",
            "attempt_count": "INTEGER DEFAULT 0",
            "started_at": "TIMESTAMP WITH TIME ZONE",
            "heartbeat_at": "TIMESTAMP WITH TIME ZONE",
            "finished_at": "TIMESTAMP WITH TIME ZONE",
            "failure_class": "VARCHAR",
        },
    }
    try:
        with engine.begin() as conn:
            dialect = str(engine.url.get_backend_name() or "").lower()
            for table_name, columns in table_columns.items():
                if dialect == "sqlite":
                    existing = {
                        str(row[1])
                        for row in conn.execute(text(f"PRAGMA table_info({table_name})"))
                    }
                    if not existing:
                        continue
                    for name, definition in columns.items():
                        if name not in existing:
                            sqlite_definition = definition.replace(
                                "TIMESTAMP WITH TIME ZONE", "DATETIME"
                            )
                            conn.execute(
                                text(
                                    f"ALTER TABLE {table_name} ADD COLUMN "
                                    f"{name} {sqlite_definition}"
                                )
                            )
                else:
                    exists = conn.execute(
                        text("SELECT to_regclass(:table_name)"),
                        {"table_name": f"public.{table_name}"},
                    ).scalar()
                    if not exists:
                        continue
                    for name, definition in columns.items():
                        conn.execute(
                            text(
                                f"ALTER TABLE {table_name} ADD COLUMN IF NOT EXISTS "
                                f"{name} {definition}"
                            )
                        )
                conn.execute(
                    text(
                        f"UPDATE {table_name} SET queue_status='inline' "
                        "WHERE queue_status IS NULL OR queue_status=''"
                    )
                )
                conn.execute(
                    text(
                        f"CREATE INDEX IF NOT EXISTS ix_{table_name}_queue_status "
                        f"ON {table_name}(queue_status)"
                    )
                )
                conn.execute(
                    text(
                        f"CREATE INDEX IF NOT EXISTS ix_{table_name}_queue_task_id "
                        f"ON {table_name}(queue_task_id)"
                    )
                )
    except Exception as exc:
        print(f"[migrate_short_background_task_queue_fields] {exc}")


