def backfill_stock_board_cache():
    """Populate deterministic listing board cache without touching external APIs."""
    db = SessionLocal()
    try:
        rows = (
            db.query(Stock)
            .filter((Stock.board.is_(None)) | (func.trim(Stock.board) == ""))
            .all()
        )
        if not rows:
            return
        for stock in rows:
            stock.board = data_sources.infer_listing_board(stock.code)
        db.commit()
        print(f"[stock-cache] backfilled board for {len(rows)} stocks")
    except Exception as e:
        db.rollback()
        print(f"[stock-cache] board backfill failed: {e}")
    finally:
        db.close()


def backfill_stock_market_cache():
    """Backfill deterministic market metadata and repair legacy asset types."""
    db = SessionLocal()
    try:
        rows = db.query(Stock).all()
        changed = 0
        for stock in rows:
            inferred_asset_type = data_sources.infer_asset_type(
                stock.code,
                stock.name,
                stock.board,
                stock.asset_type,
            )
            if stock.asset_type != inferred_asset_type:
                stock.asset_type = inferred_asset_type
                changed += 1
            current_market = str(getattr(stock, "market", None) or "").strip().upper()
            inferred_market = data_sources.infer_equity_market(
                stock.code,
                market=current_market if current_market in {"HK", "US"} else None,
                exchange=getattr(stock, "exchange", None),
                board=stock.board,
                area=stock.area,
            )
            next_market = current_market if current_market in {"CN", "HK", "US"} else inferred_market
            if current_market == "CN" and inferred_market in {"HK", "US"}:
                next_market = inferred_market
            if next_market not in {"CN", "HK", "US"}:
                next_market = inferred_market
            if getattr(stock, "market", None) != next_market:
                stock.market = next_market
                changed += 1
            expected_currency = data_sources.market_currency(next_market)
            if not getattr(stock, "currency", None):
                stock.currency = expected_currency
                changed += 1
            if not getattr(stock, "exchange", None):
                stock.exchange = data_sources.infer_exchange(
                    stock.code,
                    market=next_market,
                )
                changed += 1
        if changed:
            db.commit()
            print(f"[stock-cache] backfilled market metadata fields={changed}")
    except Exception as e:
        db.rollback()
        print(f"[stock-cache] market metadata backfill failed: {e}")
    finally:
        db.close()


