ANALYTICS_API_LOG_QUEUE_KEY = "analytics:api-log:queue:v1"
ANALYTICS_API_LOG_BATCH_SIZE = max(
    10, min(1000, int(os.getenv("ANALYTICS_API_LOG_BATCH_SIZE") or 250))
)


def _analytics_cached_user_id(request: Request) -> Optional[int]:
    auth_header = str(request.headers.get("authorization") or "").strip()
    if not auth_header.lower().startswith("bearer "):
        return None
    token_value = auth_header.split(" ", 1)[1].strip()
    token_hash = hashlib.sha256(token_value.encode("utf-8")).hexdigest()[:32]
    cache_key = f"analytics:auth-user:{token_hash}"
    cached = cache_get(cache_key)
    if cached:
        try:
            return int(cached)
        except Exception:
            pass
    db = SessionLocal()
    try:
        user = _optional_user_from_bearer(token_value, db)
        if not user:
            return None
        cache_set(cache_key, str(user.id), ex=300)
        return int(user.id)
    finally:
        db.close()


def _enqueue_analytics_api_log(payload: dict) -> bool:
    client = cache_backend.redis
    if client is None:
        return False
    try:
        client.rpush(
            ANALYTICS_API_LOG_QUEUE_KEY,
            json.dumps(payload, ensure_ascii=False, default=str),
        )
        client.ltrim(ANALYTICS_API_LOG_QUEUE_KEY, -100000, -1)
        client.expire(ANALYTICS_API_LOG_QUEUE_KEY, 7 * 86400)
        return True
    except Exception as exc:
        cache_backend._mark_redis_failed(exc)
        return False


def _flush_analytics_api_logs() -> int:
    client = cache_backend.redis
    if client is None:
        return 0
    script = """
    local items = {}
    local count = tonumber(ARGV[1])
    for index = 1, count do
      local item = redis.call('lpop', KEYS[1])
      if not item then break end
      table.insert(items, item)
    end
    return items
    """
    try:
        raw_items = client.eval(
            script,
            1,
            ANALYTICS_API_LOG_QUEUE_KEY,
            ANALYTICS_API_LOG_BATCH_SIZE,
        )
    except Exception as exc:
        cache_backend._mark_redis_failed(exc)
        return 0
    mappings = []
    valid_raw = []
    for raw in raw_items or []:
        try:
            item = json.loads(raw)
            valid_raw.append(raw)
            mappings.append(
                {
                    "method": str(item.get("method") or "GET")[:16],
                    "path": str(item.get("path") or "")[:800],
                    "status_code": int(item.get("status_code") or 0),
                    "duration_ms": float(item.get("duration_ms") or 0),
                    "success": bool(item.get("success")),
                    "user_id": item.get("user_id"),
                    "session_key": _analytics_text(item.get("session_key"), 120),
                    "visitor_key": _analytics_text(item.get("visitor_key"), 120),
                    "ip_hash": _analytics_text(item.get("ip_hash"), 128),
                    "user_agent": _analytics_text(item.get("user_agent"), 500),
                }
            )
        except Exception:
            continue
    if not mappings:
        return 0
    db = SessionLocal()
    try:
        db.bulk_insert_mappings(AnalyticsApiLog, mappings)
        db.commit()
        return len(mappings)
    except Exception:
        db.rollback()
        try:
            pipeline = client.pipeline()
            for raw in reversed(valid_raw):
                pipeline.lpush(ANALYTICS_API_LOG_QUEUE_KEY, raw)
            pipeline.execute()
        except Exception:
            pass
        return 0
    finally:
        db.close()


@app.middleware("http")
async def perf_monitor(request: Request, call_next):
    import time

    if COMMUNITY_EDITION and any(
        request.url.path == prefix or request.url.path.startswith(prefix + "/")
        for prefix in COMMUNITY_EXCLUDED_PREFIXES
    ):
        return JSONResponse(
            status_code=404,
            content={
                "detail": {
                    "code": "COMMUNITY_FEATURE_UNAVAILABLE",
                    "message": "This capability is not included in the community edition.",
                }
            },
        )

    start = time.time()
    response = await call_next(request)
    elapsed = round((time.time() - start) * 1000, 1)
    response.headers["X-Response-Time"] = f"{elapsed}ms"
    path = request.url.path
    if (
        path.startswith("/api/")
        and not path.startswith("/api/public/analytics")
        and not path.startswith("/api/health")
    ):
        _enqueue_analytics_api_log(
            {
                "method": request.method.upper(),
                "path": path[:800],
                "status_code": int(getattr(response, "status_code", 0) or 0),
                "duration_ms": elapsed,
                "success": 200 <= int(getattr(response, "status_code", 0) or 0) < 400,
                "user_id": _analytics_cached_user_id(request),
                "session_key": request.headers.get("x-quartsys-session"),
                "visitor_key": request.headers.get("x-quartsys-visitor"),
                "ip_hash": _request_ip_hash(request),
                "user_agent": request.headers.get("user-agent"),
            }
        )
    if elapsed > 2000:
        print(f"[SLOW] {request.method} {request.url.path} {elapsed}ms")
    return response


@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception):
    if isinstance(exc, HTTPException):
        raise exc
    return JSONResponse(status_code=500, content={"detail": "Internal server error"})


# 登录限速：每个IP每分钟最多10次尝试
_login_attempts: dict = {}  # {ip: [timestamp, ...]}


def _check_rate_limit(ip: str, max_attempts: int = 10, window: int = 60):
    now = datetime.now().timestamp()
    attempts = [t for t in _login_attempts.get(ip, []) if now - t < window]
    if len(attempts) >= max_attempts:
        raise HTTPException(
            status_code=429, detail="Too many login attempts, please try again later"
        )
    attempts.append(now)
    _login_attempts[ip] = attempts


