# --- 数据模型 ---
def _validate_password_strength(value: str) -> str:
    password = str(value or "")
    if not 8 <= len(password) <= 20:
        raise ValueError("密码长度须为 8-20 位")
    if not re.search(r"[a-z]", password):
        raise ValueError("密码须包含小写字母")
    if not re.search(r"[A-Z]", password):
        raise ValueError("密码须包含大写字母")
    if not re.search(r"\d", password):
        raise ValueError("密码须包含数字")
    return password


def _normalized_registration_email(value: Optional[str]) -> str:
    email = str(value or "").strip().lower()
    if not email:
        return ""
    if not re.fullmatch(r"[^\s@]+@[^\s@]+\.[^\s@]+", email):
        raise HTTPException(status_code=400, detail="邮箱格式不正确")
    return email


class UserRegister(BaseModel):
    username: str
    password: str
    email: Optional[str] = None
    email_code: Optional[str] = None
    captcha_token: Optional[str] = None

    @field_validator("username")
    @classmethod
    def username_valid(cls, v: str) -> str:
        if not v or len(v) < 2 or len(v) > 32:
            raise ValueError("用户名长度须在2-32字符之间")
        return v.strip()

    @field_validator("password")
    @classmethod
    def password_valid(cls, v: str) -> str:
        return _validate_password_strength(v)

    @field_validator("email")
    @classmethod
    def email_valid(cls, v: Optional[str]) -> Optional[str]:
        return _normalized_registration_email(v) or None


class UserLogin(BaseModel):
    username: str
    password: str
    captcha_token: Optional[str] = None

    @field_validator("username")
    @classmethod
    def username_or_email_valid(cls, v: str) -> str:
        value = str(v or "").strip()
        if not value or len(value) > 254:
            raise ValueError("请输入用户名或邮箱")
        return value

    @field_validator("password")
    @classmethod
    def login_password_valid(cls, v: str) -> str:
        if not v:
            raise ValueError("请输入密码")
        return v


class UserResetPassword(BaseModel):
    username: str
    old_password: Optional[str] = None
    new_password: str
    email: Optional[str] = None
    email_code: Optional[str] = None

    @field_validator("new_password")
    @classmethod
    def new_password_valid(cls, v: str) -> str:
        return _validate_password_strength(v)


class UserRoleUpdate(BaseModel):
    role: str
    permissions: Optional[List[str]] = None

    @field_validator("role")
    @classmethod
    def role_valid(cls, value: str) -> str:
        normalized = normalize_user_role(value)
        if normalized != (value or "").strip().lower():
            raise ValueError("角色不存在")
        return normalized

    @field_validator("permissions")
    @classmethod
    def permissions_valid(cls, value: Optional[List[str]]) -> Optional[List[str]]:
        if value is None:
            return None
        cleaned: list[str] = []
        seen: set[str] = set()
        for item in value:
            permission = str(item).strip()
            if permission not in PERMISSION_DEFINITIONS:
                raise ValueError(f"权限不存在: {permission}")
            if permission not in seen:
                seen.add(permission)
                cleaned.append(permission)
        return sorted(cleaned)


class AnalyticsEventRequest(BaseModel):
    event_type: str = "page_view"
    session_key: Optional[str] = None
    visitor_key: Optional[str] = None
    path: Optional[str] = None
    title: Optional[str] = None
    referrer: Optional[str] = None
    source_type: Optional[str] = None
    source: Optional[str] = None
    device_type: Optional[str] = None
    browser: Optional[str] = None
    os: Optional[str] = None
    region: Optional[str] = None
    duration_seconds: Optional[float] = None
    is_entry: Optional[bool] = None
    is_exit: Optional[bool] = None
    module_key: Optional[str] = None
    module_label: Optional[str] = None
    action: Optional[str] = None
    success: Optional[bool] = True
    result_count: Optional[int] = None
    duration_ms: Optional[float] = None
    meta: Optional[dict] = None

    @field_validator("event_type")
    @classmethod
    def analytics_event_type_valid(cls, value: str) -> str:
        normalized = str(value or "page_view").strip().lower()
        allowed = {"page_view", "page_leave", "page_duration", "module_usage", "funnel"}
        if normalized not in allowed:
            raise ValueError("统计事件类型无效")
        return normalized


