def normalize_factor_map(
    factors: List[FactorConfigItem],
) -> Dict[str, Dict[str, float]]:
    result: Dict[str, Dict[str, float]] = {}
    for item in factors or []:
        result[item.factor] = {p.name: p.value for p in item.params or []}
    return result


def get_factor_float(
    params: Dict[str, float], *names: str, default: Optional[float] = None
) -> Optional[float]:
    for name in names:
        value = params.get(name)
        if value is None:
            continue
        try:
            return float(value)
        except Exception:
            continue
    return default


def get_factor_int(
    params: Dict[str, float], *names: str, default: Optional[int] = None
) -> Optional[int]:
    value = get_factor_float(params, *names, default=None)
    if value is None:
        return default
    return int(value)


def normalize_percent_threshold(value: Optional[float]) -> Optional[float]:
    """Accept ratio-style inputs such as 0.15 and percent inputs such as 15."""
    if value is None:
        return None
    return value * 100.0 if 0 < value <= 1 else value


def normalize_market_cap_yi(value) -> Optional[float]:
    """Return market cap in 100M CNY units.

    Current providers store this field in 亿元. This guard also handles old/raw
    yuan values so the UI never displays raw yuan with an extra 亿 suffix.
    """
    parsed = data_sources.safe_float(value)
    if parsed is None or parsed <= 0:
        return None
    return round(parsed / 100000000, 2) if parsed > 1000000 else parsed


def positive_float(value) -> Optional[float]:
    parsed = data_sources.safe_float(value)
    if parsed is None or parsed <= 0:
        return None
    return parsed


def _json_safe_value(value):
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    if hasattr(value, "isoformat"):
        return value.isoformat()
    if isinstance(value, (int, float, str, bool)):
        return value
    return str(value)


def _df_payload(
    df: pd.DataFrame | None,
    *,
    columns: list[str] | None = None,
    limit: int = 20,
    source: str,
) -> dict:
    if df is None or df.empty:
        return {"status": "empty", "source": source, "columns": columns or [], "rows": []}
    selected = [col for col in (columns or list(df.columns)) if col in df.columns]
    if not selected:
        selected = list(df.columns[: min(8, len(df.columns))])
    frame = df[selected].head(limit).copy()
    rows = [
        {col: _json_safe_value(row.get(col)) for col in selected}
        for _, row in frame.iterrows()
    ]
    return {"status": "ok", "source": source, "columns": selected, "rows": rows}


def _empty_section(source: str, error: str | None = None) -> dict:
    payload = {"status": "failed" if error else "empty", "source": source, "columns": [], "rows": []}
    if error:
        payload["error"] = error[:240]
    return payload


def _em_prefix_code(code: str) -> str:
    normalized = data_sources.normalize_stock_code(code)
    if normalized.startswith("6"):
        return f"SH{normalized}"
    if normalized.startswith(("4", "8", "9")):
        return f"BJ{normalized}"
    return f"SZ{normalized}"


def _em_secu_code(code: str) -> str:
    normalized = data_sources.normalize_stock_code(code)
    if normalized.startswith("6"):
        return f"{normalized}.SH"
    if normalized.startswith(("4", "8", "9")):
        return f"{normalized}.BJ"
    return f"{normalized}.SZ"


def _f10_call(label: str, source: str, fn):
    try:
        return fn()
    except Exception as err:
        print(f"[f10][{label}] {err}")
        return _empty_section(source, str(err))


def _rename_df_columns(df: pd.DataFrame | None, mapping: dict[str, str]) -> pd.DataFrame | None:
    if df is None or df.empty:
        return df
    return df.rename(columns={k: v for k, v in mapping.items() if k in df.columns})


_f10_cache: dict[str, tuple[datetime, dict]] = {}
_F10_CACHE_TTL_SECONDS = 15 * 60


def _get_f10_cache(code: str) -> dict | None:
    cached = _f10_cache.get(code)
    if not cached:
        return None
    ts, payload = cached
    if (datetime.now() - ts).total_seconds() > _F10_CACHE_TTL_SECONDS:
        _f10_cache.pop(code, None)
        return None
    return payload


def _set_f10_cache(code: str, payload: dict):
    _f10_cache[code] = (datetime.now(), payload)


_DOCUMENT_PREVIEW_MAX_BYTES = 30 * 1024 * 1024
_DOCUMENT_PREVIEW_DOMAINS = ("eastmoney.com", "dfcfw.com")


def _is_allowed_document_url(raw_url: str) -> bool:
    parsed = urlparse(raw_url or "")
    host = (parsed.hostname or "").lower()
    if parsed.scheme not in {"http", "https"} or not host:
        return False
    return any(host == domain or host.endswith(f".{domain}") for domain in _DOCUMENT_PREVIEW_DOMAINS)


def _read_limited_response(upstream: requests.Response) -> bytes:
    total = 0
    chunks: list[bytes] = []
    for chunk in upstream.iter_content(chunk_size=65536):
        if not chunk:
            continue
        total += len(chunk)
        if total > _DOCUMENT_PREVIEW_MAX_BYTES:
            raise HTTPException(status_code=413, detail="文档超过预览大小限制")
        chunks.append(chunk)
    return b"".join(chunks)


def _inject_html_base(content: bytes, final_url: str, content_type: str) -> bytes:
    charset = "utf-8"
    for part in content_type.split(";"):
        part = part.strip()
        if part.lower().startswith("charset="):
            charset = part.split("=", 1)[1].strip() or charset
    text = content.decode(charset, errors="replace")
    lower = text.lower()
    head_start = lower.find("<head")
    if head_start >= 0:
        head_end = lower.find(">", head_start)
        if head_end >= 0 and "<base " not in lower[: min(len(lower), head_end + 200)]:
            text = f'{text[: head_end + 1]}<base href="{final_url}">{text[head_end + 1:]}'
    return text.encode(charset, errors="replace")


def _document_fallback_html(target_url: str, reason: str) -> bytes:
    safe_url = html.escape(target_url, quote=True)
    safe_reason = html.escape(reason, quote=True)
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <style>
    html, body {{ margin: 0; width: 100%; height: 100%; background: #f8fafc; font-family: Arial, sans-serif; }}
    .fallback {{ min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; padding: 24px; box-sizing: border-box; color: #1f2937; text-align: center; }}
    .fallback h2 {{ margin: 0; font-size: 18px; }}
    .fallback p {{ max-width: 560px; margin: 0; color: #6b7280; font-size: 13px; line-height: 1.7; }}
    .fallback a {{ margin-top: 8px; padding: 9px 14px; border-radius: 8px; background: #0052ff; color: #fff; text-decoration: none; font-size: 13px; }}
  </style>
</head>
<body>
  <div class="fallback">
    <h2>文档暂时无法内嵌预览</h2>
    <p>{safe_reason}</p>
    <p>源站可能启用了反爬校验、Cookie 校验或限制后端代理访问。你仍可以在浏览器中打开原始链接查看。</p>
    <a href="{safe_url}" target="_blank" rel="noreferrer">打开原始链接</a>
  </div>
</body>
</html>""".encode("utf-8")


def _document_response(content: bytes, content_type: str, request: Request) -> Response:
    stripped = content.lstrip()[:32].lower()
    if content.startswith(b"%PDF"):
        content_type = "application/pdf"
    elif stripped.startswith((b"<script", b"<!doctype", b"<html")):
        content_type = "text/html"
    headers = {
        "Accept-Ranges": "bytes",
        "Cache-Control": "public, max-age=600",
        "Content-Disposition": 'inline; filename="preview.pdf"'
        if content_type == "application/pdf"
        else "inline",
        "X-Content-Type-Options": "nosniff",
    }
    range_header = request.headers.get("range")
    if content_type == "application/pdf" and range_header:
        try:
            unit, range_value = range_header.split("=", 1)
            start_text, end_text = range_value.split("-", 1)
            if unit.strip().lower() == "bytes" and start_text.strip():
                start = int(start_text)
                end = int(end_text) if end_text.strip() else len(content) - 1
                start = max(0, min(start, len(content) - 1))
                end = max(start, min(end, len(content) - 1))
                partial = content[start : end + 1]
                headers["Content-Range"] = f"bytes {start}-{end}/{len(content)}"
                return Response(
                    content=partial,
                    media_type=content_type,
                    status_code=206,
                    headers=headers,
                )
        except Exception:
            pass
    return Response(content=content, media_type=content_type, headers=headers)


def cap_post_spike_days(check_days: int, observe_days: int) -> int:
    return max(1, min(observe_days, max(1, check_days - 1)))


def factor_items_to_dict(params: List[FactorParamItem]) -> Dict[str, float]:
    return {p.name: p.value for p in params or []}


def pop_custom_factor_filters(params: Dict[str, float]) -> tuple[Optional[float], Optional[float]]:
    filter_min = params.pop("__filter_min", None)
    filter_max = params.pop("__filter_max", None)
    return filter_min, filter_max


def default_filter_bounds(default_filter: Optional[str]) -> tuple[Optional[float], Optional[float]]:
    if not default_filter:
        return None, None
    try:
        parsed = json.loads(default_filter)
        return parsed.get("min"), parsed.get("max")
    except Exception:
        return None, None


def custom_factor_default_params(params_json: Optional[str]) -> Dict[str, float]:
    if not params_json:
        return {}
    try:
        parsed = json.loads(params_json)
    except Exception:
        return {}
    if isinstance(parsed, dict):
        return {str(k): v for k, v in parsed.items() if isinstance(v, (int, float))}
    if not isinstance(parsed, list):
        return {}
    params: Dict[str, float] = {}
    for item in parsed:
        if not isinstance(item, dict) or not item.get("name"):
            continue
        default = item.get("default")
        if isinstance(default, (int, float)):
            params[str(item["name"])] = default
    return params


def custom_factor_model_to_spec(factor: CustomFactorModel) -> Dict[str, object]:
    default_min, default_max = default_filter_bounds(factor.default_filter)
    return {
        "id": factor.id,
        "name": factor.name,
        "display_name": factor.display_name or factor.name,
        "expression": factor.expression,
        "params": custom_factor_default_params(factor.params_json),
        "params_json": factor.params_json,
        "output_type": factor.output_type or "scalar",
        "default_filter": factor.default_filter,
        "filter_min": default_min,
        "filter_max": default_max,
    }


def normalize_custom_factor_spec(spec: Dict[str, object]) -> Dict[str, object]:
    params = spec.get("params")
    if not isinstance(params, dict):
        params = custom_factor_default_params(
            spec.get("params_json") if isinstance(spec.get("params_json"), str) else None
        )
    default_min, default_max = default_filter_bounds(
        spec.get("default_filter") if isinstance(spec.get("default_filter"), str) else None
    )
    return {
        "id": spec.get("id"),
        "name": spec.get("name") or "custom_factor",
        "display_name": spec.get("display_name") or spec.get("name") or "custom_factor",
        "expression": spec.get("expression") or "",
        "params": params,
        "output_type": spec.get("output_type") or "scalar",
        "filter_min": spec.get("filter_min") if spec.get("filter_min") is not None else default_min,
        "filter_max": spec.get("filter_max") if spec.get("filter_max") is not None else default_max,
    }


def prepare_factor_dataframe(hist_df: pd.DataFrame) -> pd.DataFrame:
    factor_df = hist_df.rename(
        columns={
            "日期": "date",
            "开盘": "open",
            "收盘": "close",
            "最高": "high",
            "最低": "low",
            "成交量": "volume",
            "成交额": "amount",
        }
    ).copy()
    for col in ("open", "close", "high", "low", "volume", "amount"):
        if col in factor_df.columns:
            factor_df[col] = pd.to_numeric(factor_df[col], errors="coerce")
    if "close" in factor_df.columns:
        factor_df["ma60"] = factor_df["close"].rolling(window=60, min_periods=1).mean()
    return factor_df


def factor_spec_passes(factor_df: pd.DataFrame, spec: Dict[str, object]) -> bool:
    try:
        series = factor_engine.evaluate_factor(
            expression=str(spec["expression"]),
            df=factor_df,
            params=spec.get("params") or {},
            output_type=str(spec.get("output_type") or "scalar"),
        )
        if series is None or len(series) == 0:
            return False
        latest_value = series.iloc[-1]
        if pd.isna(latest_value):
            return False
        latest_value = float(latest_value)
        if spec.get("output_type") == "boolean":
            return latest_value > 0.5
        filter_min = spec.get("filter_min")
        filter_max = spec.get("filter_max")
        if filter_min is not None and latest_value < float(filter_min):
            return False
        if filter_max is not None and latest_value > float(filter_max):
            return False
        return True
    except Exception:
        return False


def factor_spec_pass_series(
    factor_df: pd.DataFrame, spec: Dict[str, object]
) -> pd.Series:
    try:
        series = factor_engine.evaluate_factor(
            expression=str(spec["expression"]),
            df=factor_df,
            params=spec.get("params") or {},
            output_type=str(spec.get("output_type") or "scalar"),
        )
        if series is None or len(series) == 0:
            return pd.Series(False, index=factor_df.index)
        series = pd.to_numeric(series.reindex(factor_df.index), errors="coerce")
        valid = series.notna()
        if spec.get("output_type") == "boolean":
            return valid & (series > 0.5)
        filter_min = spec.get("filter_min")
        filter_max = spec.get("filter_max")
        passed = valid.copy()
        if filter_min is not None:
            passed = passed & (series >= float(filter_min))
        if filter_max is not None:
            passed = passed & (series <= float(filter_max))
        return passed.fillna(False)
    except Exception:
        return pd.Series(False, index=factor_df.index)


def load_screening_histories(
    db: Session, codes: List[str], target_date, days: int
) -> Dict[str, pd.DataFrame]:
    if not codes:
        return {}
    requested_codes = set(codes)
    anchor_date = target_date or datetime.now().date()
    cutoff_date = anchor_date - timedelta(days=days)
    query = db.query(
        DailyPrice.stock_code,
        DailyPrice.date,
        DailyPrice.open,
        DailyPrice.close,
        DailyPrice.high,
        DailyPrice.low,
        DailyPrice.volume,
        DailyPrice.amount,
    ).filter(
        DailyPrice.date >= cutoff_date,
    )
    # 全市场筛选时几千个 code 的 IN 条件会拖慢 PostgreSQL 计划和执行；
    # 直接按日期范围扫描，再在 Python 侧丢弃非候选股票通常更快。
    if len(requested_codes) <= 1000:
        query = query.filter(DailyPrice.stock_code.in_(requested_codes))
    if target_date is not None:
        query = query.filter(DailyPrice.date <= target_date)

    buckets: Dict[str, List[dict]] = {}
    for record in query.order_by(DailyPrice.stock_code.asc(), DailyPrice.date.asc()).all():
        if record.stock_code not in requested_codes:
            continue
        buckets.setdefault(record.stock_code, []).append(
            {
                "日期": record.date,
                "开盘": float(record.open or 0),
                "收盘": float(record.close or 0),
                "最高": float(record.high or 0),
                "最低": float(record.low or 0),
                "成交量": float(record.volume or 0),
                "成交额": float(record.amount or 0),
            }
        )
    return {code: pd.DataFrame(rows) for code, rows in buckets.items()}


def build_prev_close_map_from_history(
    history_cache: Dict[str, pd.DataFrame], rows: List[object]
) -> Dict[str, float]:
    target_dates = {r.code: r.date for r in rows if getattr(r, "date", None)}
    prev_close_map: Dict[str, float] = {}
    for code, hist_df in history_cache.items():
        target_date = target_dates.get(code)
        if target_date is None or hist_df.empty:
            continue
        prior_rows = hist_df[hist_df["日期"] < target_date]
        if prior_rows.empty:
            continue
        prev_close_map[code] = float(prior_rows["收盘"].iloc[-1] or 0)
    return prev_close_map


def latest_moving_average_from_history(
    hist_df: pd.DataFrame, days: int
) -> Optional[float]:
    if hist_df.empty or "收盘" not in hist_df.columns:
        return None
    closes = pd.to_numeric(hist_df["收盘"], errors="coerce").dropna()
    if len(closes) < days:
        return None
    value = float(closes.tail(days).mean())
    return value if value > 0 else None


def estimate_history_days(params: Dict[str, object], has_custom_factors: bool) -> int:
    if has_custom_factors:
        return 220
    required_trading_days = 30
    enabled_conditions = params.get("enabled_conditions", [])
    if "ma60" in enabled_conditions:
        required_trading_days = max(
            required_trading_days,
            int(params.get("ma_days", 60)) + int(params.get("ma_trend_days", 30)),
        )
    if "volume" in enabled_conditions:
        required_trading_days = max(
            required_trading_days, int(params.get("volume_check_days", 15)) + 1
        )
    if "yin_yang" in enabled_conditions:
        required_trading_days = max(
            required_trading_days, int(params.get("yin_yang_check_days", 10))
        )
    if "deviation" in enabled_conditions:
        required_trading_days = max(
            required_trading_days,
            int(params.get("ma_long_days", 60)) + 2,
            int(params.get("ma_short_days", 20)) + 2,
        )
    return min(220, max(90, int(required_trading_days * 1.55) + 15))


def build_advanced_screen_params(
    factor_map: Dict[str, Dict[str, float]], logic: str
) -> Dict[str, object]:
    params: Dict[str, object] = {
        "enabled_conditions": [],
        "match_mode": "any" if (logic or "and").lower() == "or" else "all",
    }

    if "ma60_gap" in factor_map:
        cfg = factor_map["ma60_gap"]
        proximity = get_factor_float(cfg, "max_deviation", "value", "max", default=0.10)
        if proximity is not None and proximity > 1:
            proximity /= 100.0
        params["enabled_conditions"].append("ma60")
        params["ma_days"] = get_factor_int(cfg, "period", "ma_days", default=60)
        params["ma_proximity_threshold"] = proximity if proximity is not None else 0.10
        params["ma_trend_days"] = get_factor_int(
            cfg, "trend_lookback", "ma_trend_days", default=30
        )

    if "volume_spike" in factor_map:
        cfg = factor_map["volume_spike"]
        params["enabled_conditions"].append("volume")
        check_days = get_factor_int(
            cfg, "check_days", "volume_check_days", default=15
        )
        observe_days = get_factor_int(
            cfg, "observe_days", "post_spike_days_count", default=5
        )
        params["volume_check_days"] = check_days
        params["volume_spike_ratio"] = get_factor_float(
            cfg, "volume_multiplier", "volume_spike_ratio", default=2.0
        )
        params["post_spike_days_count"] = cap_post_spike_days(
            check_days or 15, observe_days or 5
        )

    if "consecutive_yin_hold" in factor_map:
        cfg = factor_map["consecutive_yin_hold"]
        params["enabled_conditions"].append("yin_yang")
        params["yin_yang_check_days"] = get_factor_int(
            cfg, "check_days", "yin_yang_check_days", default=10
        )

    if "ma_deviation_strategy" in factor_map:
        cfg = factor_map["ma_deviation_strategy"]
        params["enabled_conditions"].append("deviation")
        params["ma_short_days"] = get_factor_int(
            cfg, "short_ma", "ma_short_days", default=20
        )
        params["ma_long_days"] = get_factor_int(
            cfg, "long_ma", "ma_long_days", default=60
        )
        params["slope_threshold"] = get_factor_float(
            cfg, "slope_degrees", "slope_threshold", default=15.0
        )

    return params


def get_next_table_id(db: Session, model_cls) -> int:
    current = db.query(func.max(model_cls.id)).scalar()
    return int(current or 0) + 1


# 筛选函数
def perform_screening(params: dict):
    print(f"开始执行筛选，参数: {params}")
    try:
        # 调用 screener 中的纯计算逻辑 (不含网络请求)
        results = screener.run_screener_task(params)

        # 保存结果到数据库 (ScreeningResult 表)
        # 注意：这里我们覆盖当天的记录，或者每次都存新的? 覆盖比较合理
        db = SessionLocal()
        today = datetime.now().date()

        # 清除今日旧结果
        db.query(ScreeningResult).filter(ScreeningResult.date == today).delete()

        if results:
            new_results = []
            for r in results:
                new_results.append(
                    ScreeningResult(
                        date=today,
                        code=r["代码"],
                        name=r["名称"],
                        price=r["最新价"],
                        ma60=r["MA60"],
                    )
                )

            db.bulk_save_objects(new_results)
            db.commit()
            print(f"筛选结果已保存到数据库，共 {len(results)} 条")
        else:
            db.commit()
            print("筛选完成，无匹配结果")
        db.close()

    except Exception as e:
        print(f"筛选出错: {e}")


