DAILY_MARKET_UPDATE_MINUTE = int(os.getenv("DAILY_MARKET_UPDATE_MINUTE", "0"))
DAILY_MARKET_UPDATE_WORKERS = int(os.getenv("DAILY_MARKET_UPDATE_WORKERS", "4"))
DAILY_MARKET_BACKFILL_LIMIT = int(os.getenv("DAILY_MARKET_BACKFILL_LIMIT", "500"))


# --- 任务管理 ---
def background_update_task(
    max_workers: int = DAILY_MARKET_UPDATE_WORKERS,
    backfill_limit: int = DAILY_MARKET_BACKFILL_LIMIT,
    include_roe: bool = False,
    roe_limit: int = 200,
):
    """基于现有数据源链路执行每日收盘后市场数据更新。"""
    started_at = datetime.now()
    errors: list[str] = []
    safe_workers = max(1, min(int(max_workers or 4), 12))
    safe_backfill_limit = None if int(backfill_limit or 0) <= 0 else int(backfill_limit)
    print(
        "[daily-market-update] 开始执行 "
        f"workers={safe_workers} backfill_limit={safe_backfill_limit or 'all'} "
        f"include_roe={include_roe}"
    )

    try:
        market_data_adapter.run_update(max_workers=safe_workers)
    except Exception as err:
        errors.append(f"daily_kline:{err}")
        print(f"[daily-market-update] 日线更新失败: {err}")

    try:
        market_data_adapter.backfill_missing_daily_fields(
            max_workers=safe_workers,
            limit=safe_backfill_limit,
        )
    except Exception as err:
        errors.append(f"daily_backfill:{err}")
        print(f"[daily-market-update] 日线字段回填失败: {err}")

    try:
        update_stock_fundamentals(
            update_roe=include_roe,
            roe_limit=(roe_limit if include_roe else None),
        )
    except Exception as err:
        errors.append(f"fundamentals:{err}")
        print(f"[daily-market-update] 股票基础字段更新失败: {err}")

    elapsed = (datetime.now() - started_at).total_seconds()
    status = "failed" if errors else "ok"
    print(
        f"[daily-market-update] 完成 status={status} elapsed={elapsed:.1f}s"
        + (f" errors={'; '.join(errors[:3])}" if errors else "")
    )
    return {"status": status, "errors": errors, "elapsed_seconds": elapsed}


def update_stock_fundamentals(update_roe: bool = False, roe_limit: int | None = None):
    """从腾讯财经公开接口更新股票常用查询字段；ROE仅在手动开启时补齐。"""

    db = SessionLocal()
    try:
        stock_map = {s.code: s for s in db.query(Stock).all()}
        updated = 0

        print(
            f"[fundamentals] 正在从腾讯刷新 {len(stock_map)} 只股票基础字段...",
            flush=True,
        )
        snapshot_map = data_sources.fetch_tencent_fundamentals(
            list(stock_map.keys()), batch_size=200
        )
        print(f"[fundamentals] 腾讯返回 {len(snapshot_map)} 条基础字段", flush=True)
        for code, item in snapshot_map.items():
            stock = stock_map.get(code)
            if not stock:
                continue
            changed = False
            name = item.get("name")
            if name and stock.name != name:
                stock.name = name
                changed = True
            board = item.get("board") or data_sources.infer_listing_board(code)
            if board and stock.board != board:
                stock.board = board
                changed = True
            for attr in (
                "pe_ratio",
                "pb_ratio",
                "market_cap",
                "circulating_market_cap",
            ):
                value = item.get(attr)
                if value is not None and getattr(stock, attr) != value:
                    setattr(stock, attr, value)
                    changed = True
            if changed:
                updated += 1

        cross_market_targets = [
            stock
            for stock in stock_map.values()
            if data_sources.equity_market(stock.code) in {"HK", "US"}
            and (
                not stock.industry
                or not stock.sector
                or stock.pb_ratio is None
                or stock.roe is None
                or stock.market_cap is None
            )
        ]
        if cross_market_targets:
            profile_workers = max(1, min(6, len(cross_market_targets)))
            with concurrent.futures.ThreadPoolExecutor(max_workers=profile_workers) as executor:
                future_map = {
                    executor.submit(data_sources.fetch_yfinance_equity_profile, stock.code): stock
                    for stock in cross_market_targets
                }
                for future in concurrent.futures.as_completed(future_map):
                    stock = future_map[future]
                    try:
                        profile = future.result()
                    except Exception as exc:
                        print(f"[fundamentals][hk-us] {stock.code} 获取失败: {exc}")
                        continue
                    changed = False
                    for attr in (
                        "name",
                        "industry",
                        "sector",
                        "pe_ratio",
                        "pb_ratio",
                        "market_cap",
                        "circulating_market_cap",
                        "roe",
                    ):
                        value = profile.get(attr)
                        if value not in (None, "") and getattr(stock, attr) != value:
                            setattr(stock, attr, value)
                            changed = True
                    if changed:
                        updated += 1

        db.commit()

        roe_updated = 0
        if update_roe:
            target_stocks = list(stock_map.values())
            if roe_limit is not None:
                target_stocks = target_stocks[:roe_limit]
            for stock in target_stocks:
                try:
                    roe_df = ak.stock_financial_analysis_indicator(
                        symbol=stock.code, start_year=str(datetime.now().year - 1)
                    )
                except Exception as e:
                    print(f"[fundamentals][roe] {stock.code} 获取失败: {e}")
                    continue
                if roe_df is None or roe_df.empty:
                    continue
                latest_row = roe_df.sort_values("日期").iloc[-1]
                roe_value = data_sources.safe_float(
                    latest_row.get("加权净资产收益率(%)")
                    if "加权净资产收益率(%)" in latest_row
                    else latest_row.get("净资产收益率(%)")
                )
                if roe_value is None:
                    roe_value = data_sources.safe_float(latest_row.get("净资产收益率(%)"))
                if roe_value is not None and stock.roe != roe_value:
                    stock.roe = roe_value
                    roe_updated += 1
            db.commit()

        print(
            f"[fundamentals] 更新 {updated} 只股票常用字段"
            + (f"，补齐 {roe_updated} 只股票ROE" if update_roe else "")
        )
    except Exception as e:
        db.rollback()
        print(f"[fundamentals] 更新失败: {e}")
    finally:
        db.close()


