def _dispatch_research_task_recovery() -> None:
    if not queue_enabled() or not broker_ready():
        return
    try:
        from celery_app import celery_app

        celery_app.send_task("quantsys.recover_tasks", queue="maintenance")
    except Exception as exc:
        print(f"[queue] recovery dispatch skipped: {_assistant_sanitize_error(exc)}")


scheduler.add_job(
    _dispatch_research_task_recovery,
    "interval",
    minutes=1,
    id="recover_background_tasks",
    replace_existing=True,
    max_instances=1,
    coalesce=True,
    misfire_grace_time=90,
)


