def scheduled_ai_insights():
    """每小时自动执行AI洞察分析"""
    import concurrent.futures as _cf
    import json as _json

    db = None
    task = None
    try:
        db = SessionLocal()
        from crews.ai_insights_crew import (
            build_ai_insights_error_result,
            run_ai_insights,
        )
        from llm_factory import build_crewai_llm
        from models import AIInsightTask

        task = AIInsightTask(status="running")
        db.add(task)
        db.commit()
        db.refresh(task)
        llm = build_crewai_llm(db)
        with _cf.ThreadPoolExecutor(max_workers=1) as ex:
            future = ex.submit(run_ai_insights, llm)
            try:
                result = future.result(timeout=120)  # 2分钟超时
            except _cf.TimeoutError:
                result = build_ai_insights_error_result(
                    RuntimeError("AI洞察超时（>120s）")
                )
                task.status = "failed"
                task.dimensions = _json.dumps(
                    result.get("dimensions", {}), ensure_ascii=False
                )
                task.summary = result.get("summary", "")
                task.analysis_list = _json.dumps(
                    result.get("analysis_list", []), ensure_ascii=False
                )
                db.commit()
                return
        task.status = result.get("status", "done")
        task.dimensions = _json.dumps(result.get("dimensions", {}), ensure_ascii=False)
        task.summary = result.get("summary", "")
        task.analysis_list = _json.dumps(
            result.get("analysis_list", []), ensure_ascii=False
        )
        db.commit()
    except Exception as e:
        if db is not None and task is not None:
            try:
                from crews.ai_insights_crew import build_ai_insights_error_result

                result = build_ai_insights_error_result(e)
                task.status = "failed"
                task.dimensions = _json.dumps(
                    result.get("dimensions", {}), ensure_ascii=False
                )
                task.summary = result.get("summary", "")
                task.analysis_list = _json.dumps(
                    result.get("analysis_list", []), ensure_ascii=False
                )
                db.commit()
            except Exception:
                db.rollback()
        print(f"scheduled_ai_insights failed: {e}")
    finally:
        if db is not None:
            db.close()


