def _parse_tencent_quote_date(raw_value: object):
    raw_text = str(raw_value or "").strip()
    if len(raw_text) < 8 or not raw_text[:8].isdigit():
        return None
    try:
        return datetime.strptime(raw_text[:8], "%Y%m%d").date()
    except Exception:
        return None


def _round_optional(value, digits: int = 2):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(number):
        return None
    return round(number, digits)


def _market_volume_summary(
    db: Session,
    market: str,
    *,
    current_amount: Optional[float] = None,
    current_date=None,
    source: Optional[str] = None,
) -> dict:
    market_code = _normalize_market_code(market)
    currency = data_sources.market_currency(market_code).lower()
    lower_code = func.lower(Stock.code)
    amount_condition = (
        or_(lower_code.like("6%"), lower_code.like("0%"), lower_code.like("3%"))
        if market_code == "CN"
        else _stock_market_condition(market_code)
    )

    def daily_amount_sum(target_date) -> tuple[float, bool]:
        direct_amount = (
            db.query(func.coalesce(func.sum(DailyPrice.amount), 0))
            .join(Stock, Stock.code == DailyPrice.stock_code)
            .filter(
                DailyPrice.date == target_date,
                amount_condition,
                DailyPrice.amount.isnot(None),
            )
            .scalar()
        )
        direct_value = data_sources.safe_float(direct_amount) or 0.0
        if direct_value > 0 or market_code == "CN":
            return direct_value, False

        derived_amount = (
            db.query(
                func.coalesce(
                    func.sum(DailyPrice.close * DailyPrice.volume),
                    0,
                )
            )
            .join(Stock, Stock.code == DailyPrice.stock_code)
            .filter(
                DailyPrice.date == target_date,
                amount_condition,
                DailyPrice.close > 0,
                DailyPrice.volume > 0,
            )
            .scalar()
        )
        return data_sources.safe_float(derived_amount) or 0.0, True

    data_date = current_date
    amount_value = data_sources.safe_float(current_amount)
    volume_source = source or f"database.daily_prices.{market_code.lower()}.amount.{currency}"

    if amount_value is None:
        if data_date is None:
            data_date = (
                db.query(func.max(DailyPrice.date))
                .join(Stock, Stock.code == DailyPrice.stock_code)
                .filter(amount_condition)
                .scalar()
            )
        if data_date is not None:
            amount_value, amount_is_derived = daily_amount_sum(data_date)
            if amount_is_derived and amount_value > 0:
                volume_source = (
                    f"database.daily_prices.{market_code.lower()}.amount.{currency}"
                    ".derived_close_volume"
                )
            else:
                volume_source = f"database.daily_prices.{market_code.lower()}.amount.{currency}"

    prev_date = None
    prev_amount = None
    if data_date is not None:
        prev_date = (
            db.query(func.max(DailyPrice.date))
            .join(Stock, Stock.code == DailyPrice.stock_code)
            .filter(
                DailyPrice.date < data_date,
                amount_condition,
            )
            .scalar()
        )
        if prev_date is not None:
            prev_amount, _prev_amount_is_derived = daily_amount_sum(prev_date)

    current = data_sources.safe_float(amount_value) or 0.0
    previous = data_sources.safe_float(prev_amount) or 0.0
    change = current - previous if previous > 0 else None
    change_pct = (change / previous * 100) if change is not None and previous > 0 else None
    if change is None:
        direction = "unknown"
    elif change > 0:
        direction = "up"
    elif change < 0:
        direction = "down"
    else:
        direction = "flat"

    return {
        "market_volume": _round_optional(current, 2),
        "market_volume_prev": _round_optional(previous, 2),
        "market_volume_change": _round_optional(change, 2),
        "market_volume_change_pct": _round_optional(change_pct, 2),
        "market_volume_direction": direction,
        "market_volume_source": volume_source,
        "market_volume_date": data_date,
        "market_volume_prev_date": prev_date,
    }


def _serialize_market_volume_fields(payload: dict) -> dict:
    current = payload.get("market_volume")
    previous = payload.get("market_volume_prev")
    change = payload.get("market_volume_change")
    change_pct = payload.get("market_volume_change_pct")
    direction = payload.get("market_volume_direction") or "unknown"
    source = payload.get("market_volume_source")
    date_value = payload.get("market_volume_date")
    prev_date_value = payload.get("market_volume_prev_date")
    return {
        "market_volume": payload.get("market_volume"),
        "market_volume_prev": payload.get("market_volume_prev"),
        "market_volume_change": payload.get("market_volume_change"),
        "market_volume_change_pct": payload.get("market_volume_change_pct"),
        "market_volume_direction": payload.get("market_volume_direction") or "unknown",
        "market_volume_source": payload.get("market_volume_source"),
        "market_volume_date": date_value.isoformat() if date_value else None,
        "market_volume_prev_date": prev_date_value.isoformat() if prev_date_value else None,
        "market_amount": current,
        "market_amount_prev": previous,
        "market_amount_change": change,
        "market_amount_change_pct": change_pct,
        "market_amount_direction": direction,
        "market_amount_source": source,
        "market_amount_date": date_value.isoformat() if date_value else None,
        "market_amount_prev_date": prev_date_value.isoformat() if prev_date_value else None,
    }


def _empty_market_volume_summary() -> dict:
    return {
        "market_volume": 0,
        "market_volume_prev": 0,
        "market_volume_change": None,
        "market_volume_change_pct": None,
        "market_volume_direction": "unknown",
        "market_volume_source": "unavailable",
        "market_volume_date": None,
        "market_volume_prev_date": None,
    }


def _market_temperature_response_with_volume(
    db: Session,
    payload: dict,
    market: str,
) -> dict:
    result = dict(payload or {})
    market_code = _normalize_market_code(market)
    volume_source = str(result.get("market_volume_source") or "")
    expected_currency = data_sources.market_currency(market_code).lower()
    has_legacy_market_turnover = (
        f".amount.{expected_currency}" not in volume_source
    )
    needs_volume = (
        result.get("market_volume") is None
        or result.get("market_volume_direction") in {None, "", "unknown"}
        or has_legacy_market_turnover
    )
    if needs_volume:
        try:
            summary = _serialize_market_volume_fields(_market_volume_summary(db, market))
            for key, value in summary.items():
                if has_legacy_market_turnover or result.get(key) in (None, "", "unknown"):
                    result[key] = value
        except Exception:
            for key, value in _serialize_market_volume_fields(_empty_market_volume_summary()).items():
                result.setdefault(key, value)
    result.setdefault("market_amount", result.get("market_volume"))
    result.setdefault("market_amount_prev", result.get("market_volume_prev"))
    result.setdefault("market_amount_change", result.get("market_volume_change"))
    result.setdefault("market_amount_change_pct", result.get("market_volume_change_pct"))
    result.setdefault("market_amount_direction", result.get("market_volume_direction") or "unknown")
    result.setdefault("market_amount_source", result.get("market_volume_source"))
    result.setdefault("market_amount_date", result.get("market_volume_date"))
    result.setdefault("market_amount_prev_date", result.get("market_volume_prev_date"))
    if not result.get("heatmap_stats") and result.get("heatmap_data"):
        try:
            stats = _market_temperature_stats_from_latest_daily(
                db,
                market_code,
                data_date=result.get("data_date"),
            )
            if stats:
                result["heatmap_stats"] = stats
        except Exception:
            result.setdefault("heatmap_stats", {})
    return result


GENERIC_MARKET_GROUP_NAMES = {
    "",
    "未分类",
    "港股未分类",
    "美股未分类",
    "hk unclassified",
    "us unclassified",
}


def _is_generic_market_group(name: Any) -> bool:
    value = str(name or "").strip()
    if not value:
        return True
    return value in GENERIC_MARKET_GROUP_NAMES or value.lower() in GENERIC_MARKET_GROUP_NAMES


def _market_temperature_payload(
    *,
    calc_time: datetime,
    data_date,
    source: str,
    changes_by_industry: list[tuple[str, float]],
    volume_summary: Optional[dict] = None,
) -> dict:
    changes = [change for _industry, change in changes_by_industry]
    rise = sum(1 for change in changes if change > 0)
    fall = sum(1 for change in changes if change < 0)
    flat = sum(1 for change in changes if change == 0)
    avg = sum(changes) / len(changes) if changes else 0
    avg_rise = sum(change for change in changes if change > 0) / max(rise, 1)
    avg_fall = sum(change for change in changes if change < 0) / max(fall, 1)

    heatmap: dict[str, list[float]] = {}
    for industry, change in changes_by_industry:
        group_name = str(industry or "").strip() or "其他"
        if _is_generic_market_group(group_name):
            continue
        heatmap.setdefault(group_name, []).append(change)
    heatmap_data = {
        industry: round(sum(values) / len(values), 2)
        for industry, values in heatmap.items()
        if values
    }
    heatmap_stats = {
        industry: {
            "rise_count": sum(1 for value in values if value > 0),
            "fall_count": sum(1 for value in values if value < 0),
            "flat_count": sum(1 for value in values if value == 0),
            "total_count": len(values),
            "rise_ratio": round(
                sum(1 for value in values if value > 0) / len(values) * 100, 2
            )
            if values
            else 0,
            "fall_ratio": round(
                sum(1 for value in values if value < 0) / len(values) * 100, 2
            )
            if values
            else 0,
        }
        for industry, values in heatmap.items()
        if values
    }

    return {
        "calc_time": calc_time,
        "data_date": data_date,
        "source": source,
        "rise_count": rise,
        "fall_count": fall,
        "flat_count": flat,
        "total_count": len(changes),
        "avg_change": round(avg, 2),
        "avg_rise": round(avg_rise, 2),
        "avg_fall": round(avg_fall, 2),
        "heatmap_data": heatmap_data,
        "heatmap_stats": heatmap_stats,
        **(volume_summary or _empty_market_volume_summary()),
    }


def _market_temperature_group_name(
    *,
    code: str,
    industry: Any,
    sector: Any,
    board: Any,
    market: str,
) -> str:
    market_code = _normalize_market_code(market)
    values = {
        "industry": str(industry or "").strip(),
        "sector": str(sector or "").strip(),
        "board": str(board or "").strip(),
    }
    generic_values = {
        "",
        "其他",
        "未分类",
        "港股",
        "香港",
        "hk",
        "美股",
        "美国",
        "us",
        "united states",
    }
    priority = (
        ("sector", "industry", "board") if market_code in {"HK", "US"} else ("industry", "sector", "board")
    )
    for key in priority:
        value = values.get(key, "")
        if value and value.lower() not in generic_values:
            return value
    fallback_board = values.get("board") or data_sources.infer_listing_board(code)
    if fallback_board and fallback_board.lower() not in generic_values:
        return fallback_board
    return {"HK": "港股未分类", "US": "美股未分类"}.get(market_code, "其他")


def _persist_market_temperature(db: Session, payload: dict):
    t = MarketTemperature(
        market=_normalize_market_code(payload.get("market")),
        calc_time=payload["calc_time"],
        data_date=payload.get("data_date"),
        source=payload.get("source", "database.daily_prices"),
        rise_count=payload["rise_count"],
        fall_count=payload["fall_count"],
        flat_count=payload.get("flat_count", 0),
        total_count=payload.get("total_count", 0),
        avg_change=payload["avg_change"],
        avg_rise=payload["avg_rise"],
        avg_fall=payload["avg_fall"],
        market_volume=payload.get("market_volume"),
        market_volume_prev=payload.get("market_volume_prev"),
        market_volume_change=payload.get("market_volume_change"),
        market_volume_change_pct=payload.get("market_volume_change_pct"),
        market_volume_direction=payload.get("market_volume_direction"),
        market_volume_source=payload.get("market_volume_source"),
        market_volume_date=payload.get("market_volume_date"),
        market_volume_prev_date=payload.get("market_volume_prev_date"),
        heatmap_data=json.dumps(payload.get("heatmap_data") or {}, ensure_ascii=False),
        heatmap_stats=json.dumps(payload.get("heatmap_stats") or {}, ensure_ascii=False),
    )
    db.add(t)
    db.commit()
    db.refresh(t)
    return t


def _serialize_market_temperature(t) -> dict:
    heatmap_data = {}
    heatmap_stats = {}
    try:
        heatmap_data = json.loads(t.heatmap_data or "{}")
    except Exception:
        heatmap_data = {}
    try:
        heatmap_stats = json.loads(getattr(t, "heatmap_stats", None) or "{}")
    except Exception:
        heatmap_stats = {}
    return {
        "market": _normalize_market_code(getattr(t, "market", "CN")),
        "calc_time": t.calc_time.isoformat() if t.calc_time else None,
        "data_date": t.data_date.isoformat() if getattr(t, "data_date", None) else None,
        "source": getattr(t, "source", None) or "database.daily_prices",
        "rise_count": t.rise_count,
        "fall_count": t.fall_count,
        "flat_count": getattr(t, "flat_count", 0) or 0,
        "total_count": getattr(t, "total_count", 0) or (
            (t.rise_count or 0) + (t.fall_count or 0) + (getattr(t, "flat_count", 0) or 0)
        ),
        "avg_change": t.avg_change,
        "avg_rise": t.avg_rise,
        "avg_fall": t.avg_fall,
        "market_volume": getattr(t, "market_volume", None),
        "market_volume_prev": getattr(t, "market_volume_prev", None),
        "market_volume_change": getattr(t, "market_volume_change", None),
        "market_volume_change_pct": getattr(t, "market_volume_change_pct", None),
        "market_volume_direction": getattr(t, "market_volume_direction", None) or "unknown",
        "market_volume_source": getattr(t, "market_volume_source", None),
        "market_volume_date": getattr(t, "market_volume_date", None).isoformat()
        if getattr(t, "market_volume_date", None)
        else None,
        "market_volume_prev_date": getattr(t, "market_volume_prev_date", None).isoformat()
        if getattr(t, "market_volume_prev_date", None)
        else None,
        "heatmap_data": heatmap_data,
        "heatmap_stats": heatmap_stats,
    }


def _market_temperature_stats_from_latest_daily(
    db: Session,
    market: str,
    *,
    data_date: Optional[Any] = None,
) -> dict:
    market_code = _normalize_market_code(market)
    target_date = data_date
    if isinstance(target_date, str):
        try:
            target_date = date.fromisoformat(target_date[:10])
        except Exception:
            target_date = None
    if target_date is None:
        target_date = (
            db.query(func.max(DailyPrice.date))
            .join(Stock, Stock.code == DailyPrice.stock_code)
            .filter(_stock_market_condition(market_code))
            .scalar()
        )
    if target_date is None:
        return {}
    rows = (
        db.query(
            DailyPrice.stock_code,
            DailyPrice.close,
            DailyPrice.open,
            DailyPrice.change_pct,
            Stock.industry,
            Stock.sector,
            Stock.board,
        )
        .join(Stock, Stock.code == DailyPrice.stock_code)
        .filter(
            DailyPrice.date == target_date,
            _stock_market_condition(market_code),
        )
        .all()
    )
    if not rows:
        return {}
    stock_codes = [row.stock_code for row in rows]
    prev_close_map: dict[str, float] = {}
    prev_date = target_date - timedelta(days=1)
    for _ in range(10):
        prev_rows = (
            db.query(DailyPrice.stock_code, DailyPrice.close)
            .filter(DailyPrice.stock_code.in_(stock_codes), DailyPrice.date == prev_date)
            .all()
        )
        if prev_rows:
            prev_close_map = {
                row.stock_code: float(row.close or 0)
                for row in prev_rows
                if row.close is not None
            }
            break
        prev_date -= timedelta(days=1)

    grouped: dict[str, list[float]] = {}
    for row in rows:
        change = data_sources.safe_float(row.change_pct)
        if change is None:
            close_value = data_sources.safe_float(row.close)
            previous = prev_close_map.get(row.stock_code) or data_sources.safe_float(row.open)
            if close_value is None or not previous:
                continue
            change = (close_value - previous) / previous * 100
        group_name = _market_temperature_group_name(
            code=row.stock_code,
            industry=row.industry,
            sector=row.sector,
            board=row.board,
            market=market_code,
        )
        if _is_generic_market_group(group_name):
            continue
        grouped.setdefault(group_name or "其他", []).append(float(change))
    return {
        name: {
            "rise_count": sum(1 for value in values if value > 0),
            "fall_count": sum(1 for value in values if value < 0),
            "flat_count": sum(1 for value in values if value == 0),
            "total_count": len(values),
            "rise_ratio": round(
                sum(1 for value in values if value > 0) / len(values) * 100,
                2,
            )
            if values
            else 0,
            "fall_ratio": round(
                sum(1 for value in values if value < 0) / len(values) * 100,
                2,
            )
            if values
            else 0,
        }
        for name, values in grouped.items()
        if values
    }


def _latest_daily_market_temperature(
    db: Session,
    *,
    persist: bool = True,
    market: str = "CN",
):
    market_code = _normalize_market_code(market)
    latest_date = (
        db.query(func.max(DailyPrice.date))
        .join(Stock, Stock.code == DailyPrice.stock_code)
        .filter(_stock_market_condition(market_code), _stock_data_available_condition())
        .scalar()
    )
    if latest_date is None:
        return None
    rows = (
        db.query(
            DailyPrice.stock_code,
            DailyPrice.close,
            DailyPrice.open,
            DailyPrice.change_pct,
            Stock.industry,
            Stock.sector,
            Stock.board,
        )
        .join(Stock, Stock.code == DailyPrice.stock_code)
        .filter(
            DailyPrice.date == latest_date,
            _stock_market_condition(market_code),
        )
        .all()
    )
    if not rows:
        return None

    stock_codes = [row.stock_code for row in rows]
    prev_close_map: dict[str, float] = {}
    prev_date = latest_date - timedelta(days=1)
    for _ in range(8):
        prev_rows = (
            db.query(DailyPrice.stock_code, DailyPrice.close)
            .filter(DailyPrice.stock_code.in_(stock_codes), DailyPrice.date == prev_date)
            .all()
        )
        if prev_rows:
            prev_close_map = {
                row.stock_code: float(row.close or 0)
                for row in prev_rows
                if row.close is not None
            }
            break
        prev_date -= timedelta(days=1)

    changes_by_industry: list[tuple[str, float]] = []
    for row in rows:
        change = data_sources.safe_float(row.change_pct)
        if change is None:
            close_v = data_sources.safe_float(row.close)
            prev_close = prev_close_map.get(row.stock_code) or data_sources.safe_float(row.open)
            if close_v is None or not prev_close:
                continue
            change = (close_v - prev_close) / prev_close * 100
        group_name = _market_temperature_group_name(
            code=row.stock_code,
            industry=row.industry,
            sector=row.sector,
            board=row.board,
            market=market_code,
        )
        changes_by_industry.append((group_name, float(change)))

    payload = _market_temperature_payload(
        calc_time=datetime.now(),
        data_date=latest_date,
        source=f"database.daily_prices.{market_code.lower()}",
        changes_by_industry=changes_by_industry,
        volume_summary=_market_volume_summary(
            db,
            market_code,
            current_date=latest_date,
        ),
    )
    payload["market"] = market_code
    return _persist_market_temperature(db, payload) if persist else payload


def _realtime_market_temperature_from_tencent(db: Session, *, persist: bool = True):
    stocks = (
        db.query(Stock.code, Stock.industry, Stock.sector, Stock.board)
        .filter(_stock_market_condition("CN"))
        .all()
    )
    industry_map = {
        row.code: _market_temperature_group_name(
            code=row.code,
            industry=row.industry,
            sector=row.sector,
            board=row.board,
            market="CN",
        )
        for row in stocks
        if row.code
    }
    codes = sorted(code for code in industry_map if data_sources.is_a_share_code(code))
    if not codes:
        return None
    code_chunks = [codes[i : i + 250] for i in range(0, len(codes), 250)]
    snapshot_map: dict[str, dict] = {}
    executor = concurrent.futures.ThreadPoolExecutor(max_workers=8)
    futures = []
    try:
        futures = [
            executor.submit(data_sources.fetch_tencent_fundamentals, chunk, len(chunk))
            for chunk in code_chunks
            if chunk
        ]
        done, _pending = concurrent.futures.wait(futures, timeout=16)
        for future in done:
            try:
                snapshot_map.update(future.result(timeout=0))
            except Exception:
                continue
    finally:
        for future in futures:
            future.cancel()
        executor.shutdown(wait=False, cancel_futures=True)
    if not snapshot_map:
        return None

    trade_dates = []
    changes_by_industry: list[tuple[str, float]] = []
    for code, item in snapshot_map.items():
        price = data_sources.safe_float(item.get("price"))
        prev_close = data_sources.safe_float(item.get("prev_close"))
        if price is None or not prev_close:
            continue
        trade_date = _parse_tencent_quote_date(item.get("trade_time"))
        if trade_date:
            trade_dates.append(trade_date)
        change = (price - prev_close) / prev_close * 100
        changes_by_industry.append((industry_map.get(code, "其他"), change))

    if not changes_by_industry:
        return None
    data_date = max(set(trade_dates), key=trade_dates.count) if trade_dates else datetime.now().date()
    realtime_amount = sum(
        data_sources.safe_float(item.get("amount")) or 0
        for item in snapshot_map.values()
    )
    payload = _market_temperature_payload(
        calc_time=datetime.now(),
        data_date=data_date,
        source="tencent.quote.realtime",
        changes_by_industry=changes_by_industry,
        volume_summary=_market_volume_summary(
            db,
            "CN",
            current_amount=realtime_amount if realtime_amount > 0 else None,
            current_date=data_date,
            source="tencent.quote.realtime.amount.cny",
        ),
    )
    payload["market"] = "CN"
    return _persist_market_temperature(db, payload) if persist else payload


def _market_temperature_snapshot_is_fresh(t, *, now: datetime) -> bool:
    if not t or not t.calc_time:
        return False
    if (now - t.calc_time.replace(tzinfo=None)).total_seconds() > MARKET_TEMPERATURE_REFRESH_SECONDS:
        return False
    if _is_cn_stock_market_open(now):
        return getattr(t, "source", "") == "tencent.quote.realtime" and getattr(t, "data_date", None) == now.date()
    return True


