def scheduled_market_temperature():
    """开盘连续竞价时段每30分钟计算市场温度计。"""
    now = datetime.now()
    if not _is_cn_stock_market_open(now):
        return
    db = SessionLocal()
    try:
        t = _realtime_market_temperature_from_tencent(db, persist=True)
        if t:
            print(
                "[market-temperature] realtime "
                f"date={t.data_date} rise={t.rise_count} fall={t.fall_count}"
            )
    except Exception as e:
        db.rollback()
        print(f"scheduled_market_temperature failed: {e}")
    finally:
        db.close()


_market_temperature_refresh_lock = threading.Lock()
_market_temperature_refreshing: set[str] = set()
_market_temperature_last_attempt: dict[str, float] = {}
MARKET_TEMPERATURE_BACKGROUND_RETRY_SECONDS = int(
    os.getenv("MARKET_TEMPERATURE_BACKGROUND_RETRY_SECONDS", "60")
)


def _background_refresh_market_temperature(market_code: str):
    normalized_market = _normalize_market_code(market_code)
    db = SessionLocal()
    try:
        if normalized_market == "CN" and _is_cn_stock_market_open(datetime.now()):
            _realtime_market_temperature_from_tencent(db, persist=True)
        else:
            _latest_daily_market_temperature(
                db,
                persist=True,
                market=normalized_market,
            )
        cache_delete(f"market:temperature:snapshot:v3:{normalized_market}")
    except Exception as err:
        db.rollback()
        print(f"[market-temperature] background refresh failed: {err}")
    finally:
        db.close()
        with _market_temperature_refresh_lock:
            _market_temperature_refreshing.discard(normalized_market)


def _schedule_market_temperature_refresh(
    background_tasks: BackgroundTasks,
    market_code: str,
    *,
    force: bool = False,
) -> bool:
    normalized_market = _normalize_market_code(market_code)
    if normalized_market == "CN" and not _is_cn_stock_market_open(datetime.now()) and not force:
        return False
    now_ts = time.time()
    with _market_temperature_refresh_lock:
        if normalized_market in _market_temperature_refreshing:
            return False
        last_attempt = _market_temperature_last_attempt.get(normalized_market, 0)
        if (
            not force
            and now_ts - last_attempt < MARKET_TEMPERATURE_BACKGROUND_RETRY_SECONDS
        ):
            return False
        _market_temperature_refreshing.add(normalized_market)
        _market_temperature_last_attempt[normalized_market] = now_ts
    background_tasks.add_task(_background_refresh_market_temperature, normalized_market)
    return True


scheduler.add_job(
    scheduled_market_temperature,
    "cron",
    minute="*/30",
    id="market_temperature_realtime",
    replace_existing=True,
    max_instances=1,
    coalesce=True,
)


_active_kline_codes: dict[str, float] = {}
_active_kline_last_refresh: dict[str, float] = {}
_active_kline_lock = threading.RLock()
ACTIVE_KLINE_TTL_SECONDS = int(os.getenv("ACTIVE_KLINE_TTL_SECONDS", "7200"))
ACTIVE_KLINE_REFRESH_MIN_INTERVAL_SECONDS = int(
    os.getenv("ACTIVE_KLINE_REFRESH_MIN_INTERVAL_SECONDS", "50")
)
ACTIVE_KLINE_MAX_CODES_PER_MINUTE = int(
    os.getenv("ACTIVE_KLINE_MAX_CODES_PER_MINUTE", "40")
)
MARKET_INTRADAY_SNAPSHOT_MIN_INTERVAL_SECONDS = int(
    os.getenv("MARKET_INTRADAY_SNAPSHOT_MIN_INTERVAL_SECONDS", "50")
)
MARKET_INTRADAY_SNAPSHOT_BATCH_SIZE = int(
    os.getenv("MARKET_INTRADAY_SNAPSHOT_BATCH_SIZE", "200")
)
MARKET_INTRADAY_SNAPSHOT_CODES_PER_RUN = int(
    os.getenv("MARKET_INTRADAY_SNAPSHOT_CODES_PER_RUN", "240")
)
_market_intraday_snapshot_last_ts = 0.0
_market_intraday_snapshot_cursor = 0
_market_intraday_snapshot_lock = threading.RLock()


def _is_cn_stock_market_open(now: Optional[datetime] = None) -> bool:
    """A股连续竞价时段。节假日暂不判断，非交易日由数据源空返回兜底。"""
    current = now or datetime.now()
    if current.weekday() >= 5:
        return False
    minutes = current.hour * 60 + current.minute
    morning = 9 * 60 + 30 <= minutes <= 11 * 60 + 30
    afternoon = 13 * 60 <= minutes <= 15 * 60
    return morning or afternoon


def _register_active_kline_code(code: str) -> Optional[str]:
    normalized_code = data_sources.normalize_stock_code(code)
    if not data_sources.is_a_share_code(normalized_code):
        return None
    now_ts = time.time()
    with _active_kline_lock:
        _active_kline_codes[normalized_code] = now_ts
    return normalized_code


def _active_kline_codes_snapshot() -> list[str]:
    now_ts = time.time()
    with _active_kline_lock:
        expired = [
            code
            for code, touched_at in _active_kline_codes.items()
            if now_ts - touched_at > ACTIVE_KLINE_TTL_SECONDS
        ]
        for code in expired:
            _active_kline_codes.pop(code, None)
            _active_kline_last_refresh.pop(code, None)
        return sorted(
            _active_kline_codes,
            key=lambda item: _active_kline_codes[item],
            reverse=True,
        )[:ACTIVE_KLINE_MAX_CODES_PER_MINUTE]


def _safe_min(values: list[Optional[float]]) -> Optional[float]:
    nums = [float(v) for v in values if v is not None]
    return min(nums) if nums else None


def _safe_max(values: list[Optional[float]]) -> Optional[float]:
    nums = [float(v) for v in values if v is not None]
    return max(nums) if nums else None


def _recent_close_map_for_ma60(
    session: Session,
    codes: list[str],
    today,
) -> dict[str, list[float]]:
    if not codes:
        return {}
    recent_dates = [
        row[0]
        for row in (
            session.query(DailyPrice.date)
            .filter(DailyPrice.date < today)
            .group_by(DailyPrice.date)
            .order_by(DailyPrice.date.desc())
            .limit(59)
            .all()
        )
    ]
    if not recent_dates:
        return {}
    rows = (
        session.query(DailyPrice.stock_code, DailyPrice.date, DailyPrice.close)
        .filter(DailyPrice.stock_code.in_(codes), DailyPrice.date.in_(recent_dates))
        .all()
    )
    grouped: dict[str, list[tuple[object, float]]] = {}
    for code, dt, close in rows:
        value = data_sources.safe_float(close)
        if value is None:
            continue
        grouped.setdefault(code, []).append((dt, value))
    return {
        code: [value for _, value in sorted(items, key=lambda item: item[0])]
        for code, items in grouped.items()
    }


def refresh_tencent_intraday_market_snapshot(
    db: Optional[Session] = None,
    *,
    force: bool = False,
    max_codes: Optional[int] = None,
) -> dict:
    """开盘期间用腾讯公开行情批量刷新当天市场快照。"""
    if not force and not _is_cn_stock_market_open():
        return {"status": "market_closed"}

    global _market_intraday_snapshot_cursor, _market_intraday_snapshot_last_ts
    lock_acquired = _market_intraday_snapshot_lock.acquire(blocking=False)
    if not lock_acquired:
        return {"status": "running"}
    now_ts = time.time()
    try:
        if (
            not force
            and now_ts - _market_intraday_snapshot_last_ts
            < MARKET_INTRADAY_SNAPSHOT_MIN_INTERVAL_SECONDS
        ):
            return {"status": "recently_refreshed"}
        _market_intraday_snapshot_last_ts = now_ts

        return _refresh_tencent_intraday_market_snapshot_locked(
            db=db,
            max_codes=max_codes,
        )
    finally:
        _market_intraday_snapshot_lock.release()


def _refresh_tencent_intraday_market_snapshot_locked(
    db: Optional[Session] = None,
    *,
    max_codes: Optional[int] = None,
) -> dict:
    global _market_intraday_snapshot_cursor

    close_session = db is None
    session = db or SessionLocal()
    today = datetime.now().date()
    try:
        stocks = session.query(Stock).all()
        stock_map = {stock.code: stock for stock in stocks if stock.code}
        codes = sorted(code for code in stock_map if data_sources.is_a_share_code(code))
        if not codes:
            return {"status": "empty_universe", "updated": 0}

        effective_limit = max(
            1,
            int(
                max_codes
                if max_codes is not None
                else MARKET_INTRADAY_SNAPSHOT_CODES_PER_RUN
            ),
        )
        if effective_limit < len(codes):
            start = _market_intraday_snapshot_cursor % len(codes)
            end = start + effective_limit
            selected_codes = codes[start:end]
            if end > len(codes):
                selected_codes.extend(codes[: end - len(codes)])
            _market_intraday_snapshot_cursor = end % len(codes)
        else:
            selected_codes = codes

        snapshot_map = data_sources.fetch_tencent_fundamentals(
            selected_codes,
            batch_size=max(20, min(MARKET_INTRADAY_SNAPSHOT_BATCH_SIZE, 500)),
        )
        if not snapshot_map:
            print(
                f"[market-intraday-snapshot] empty snapshot batch={len(selected_codes)} "
                f"cursor={_market_intraday_snapshot_cursor}/{len(codes)}"
            )
            return {
                "status": "empty_snapshot",
                "updated": 0,
                "batch_count": len(selected_codes),
                "universe_count": len(codes),
            }

        existing_rows = (
            session.query(DailyPrice)
            .filter(DailyPrice.date == today, DailyPrice.stock_code.in_(snapshot_map.keys()))
            .all()
        )
        existing_map = {row.stock_code: row for row in existing_rows}
        ma_inputs_map = _recent_close_map_for_ma60(session, list(snapshot_map.keys()), today)

        updated = 0
        inserted = 0
        stock_updated = 0
        for code, item in snapshot_map.items():
            stock = stock_map.get(code)
            if not stock:
                continue
            price = data_sources.safe_float(item.get("price"))
            open_v = data_sources.safe_float(item.get("open")) or price
            close_v = price
            high_v = _safe_max([data_sources.safe_float(item.get("high")), open_v, close_v])
            low_v = _safe_min([data_sources.safe_float(item.get("low")), open_v, close_v])
            volume_v = data_sources.safe_float(item.get("volume"))
            amount_v = data_sources.safe_float(item.get("amount"))
            if None in (open_v, close_v, high_v, low_v, volume_v):
                continue

            prev_inputs = ma_inputs_map.get(code, [])
            prev_close = data_sources.safe_float(item.get("prev_close")) or (
                prev_inputs[-1] if prev_inputs else None
            )
            change_amount = close_v - prev_close if prev_close else None
            change_pct = (
                change_amount / prev_close * 100
                if prev_close and change_amount is not None
                else None
            )
            amplitude = (
                (high_v - low_v) / prev_close * 100
                if prev_close and high_v is not None and low_v is not None
                else None
            )
            ma_inputs = list(prev_inputs)
            ma_inputs.append(float(close_v))
            ma60 = sum(ma_inputs[-60:]) / 60 if len(ma_inputs) >= 60 else None
            payload = {
                "stock_code": code,
                "date": today,
                "open": open_v,
                "close": close_v,
                "high": high_v,
                "low": low_v,
                "volume": volume_v,
                "amount": amount_v,
                "amplitude": amplitude,
                "change_pct": change_pct,
                "change_amount": change_amount,
                "turnover_rate": data_sources.safe_float(item.get("turnover_rate")),
                "ma60": ma60,
            }
            row = existing_map.get(code)
            if row:
                for key, value in payload.items():
                    setattr(row, key, value)
                updated += 1
            else:
                session.add(DailyPrice(**payload))
                inserted += 1

            changed = False
            name = item.get("name")
            if name and stock.name != name:
                stock.name = name
                changed = True
            board = item.get("board") or data_sources.infer_listing_board(code)
            if board and stock.board != board:
                stock.board = board
                changed = True
            for attr in ("pe_ratio", "pb_ratio", "market_cap", "circulating_market_cap"):
                value = item.get(attr)
                if value is not None and getattr(stock, attr) != value:
                    setattr(stock, attr, value)
                    changed = True
            if changed:
                stock_updated += 1

        session.commit()
        total = updated + inserted
        print(
            f"[market-intraday-snapshot] refreshed={total} inserted={inserted} "
            f"updated={updated} stock_fields={stock_updated} "
            f"batch={len(selected_codes)} cursor={_market_intraday_snapshot_cursor}/{len(codes)}"
        )
        return {
            "status": "updated" if total else "empty_rows",
            "updated": updated,
            "inserted": inserted,
            "stock_fields_updated": stock_updated,
            "batch_count": len(selected_codes),
            "universe_count": len(codes),
            "date": today.isoformat(),
            "source": "tencent.quote.snapshot",
        }
    except Exception as err:
        session.rollback()
        print(f"[market-intraday-snapshot] failed: {err}")
        return {"status": "error", "error": str(err)}
    finally:
        if close_session:
            session.close()


def _median_positive(values: list[float]) -> Optional[float]:
    cleaned = sorted(float(value) for value in values if value and value > 0)
    if not cleaned:
        return None
    mid = len(cleaned) // 2
    if len(cleaned) % 2:
        return cleaned[mid]
    return (cleaned[mid - 1] + cleaned[mid]) / 2


def _normalize_volume_to_hands(
    volume: Any,
    amount: Any = None,
    close: Any = None,
    recent_hands: Optional[list[float]] = None,
) -> Optional[float]:
    """Normalize mixed provider volume units to hands.

    Historical A-share providers in this project may return volume either in
    hands or shares. Amount is CNY. When amount is present:
    amount / (close * volume) is ~100 for hands and ~1 for shares.
    """
    volume_v = data_sources.safe_float(volume)
    if volume_v is None or volume_v <= 0:
        return volume_v

    amount_v = data_sources.safe_float(amount)
    close_v = data_sources.safe_float(close)
    if amount_v and close_v and close_v > 0:
        unit_ratio = amount_v / (close_v * volume_v)
        if 0.2 <= unit_ratio <= 5:
            return volume_v / 100.0
        if 20 <= unit_ratio <= 500:
            return volume_v

    median = _median_positive(recent_hands or [])
    if median and median > 0:
        candidates = [volume_v, volume_v / 100.0, volume_v * 100.0]

        def score(candidate: float) -> float:
            if candidate <= 0:
                return float("inf")
            return abs(math.log(candidate / median))

        return min(candidates, key=score)
    return volume_v


def _estimate_amount_from_hands(close: Any, volume_hands: Any) -> Optional[float]:
    close_v = data_sources.safe_float(close)
    volume_v = data_sources.safe_float(volume_hands)
    if close_v and close_v > 0 and volume_v and volume_v > 0:
        return close_v * volume_v * 100.0
    return None


def refresh_mootdx_intraday_daily_kline(
    code: str,
    db: Optional[Session] = None,
    *,
    force: bool = False,
) -> dict:
    """刷新开市期间当日日K，mootdx 失败时回退腾讯行情。

    盘中日线不能把早盘第一次快照当成整天收盘价。只要当前交易日的
    实时行情可用，就用实时价覆盖当日 K 线的 close，并用日线数据补齐
    其它字段；这样数据源短暂抖动时也不会把旧的 mootdx close 留在库里。
    """
    normalized_code = data_sources.normalize_stock_code(code)
    if not data_sources.is_a_share_code(normalized_code):
        return {"status": "invalid_code", "code": normalized_code}
    if not force and not _is_cn_stock_market_open():
        return {"status": "market_closed", "code": normalized_code}

    now_ts = time.time()
    with _active_kline_lock:
        last_ts = _active_kline_last_refresh.get(normalized_code, 0)
        if now_ts - last_ts < ACTIVE_KLINE_REFRESH_MIN_INTERVAL_SECONDS:
            return {"status": "recently_refreshed", "code": normalized_code}
        _active_kline_last_refresh[normalized_code] = now_ts

    close_session = db is None
    session = db or SessionLocal()
    today = datetime.now().date()
    try:
        quote: dict = {}
        quote_error = None
        quote_source = ""
        try:
            mootdx_quote = data_sources.fetch_mootdx_quote(normalized_code) or {}
            mootdx_price = data_sources.safe_float(mootdx_quote.get("price"))
            if mootdx_price is not None and mootdx_price > 0:
                quote = mootdx_quote
                quote_source = "mootdx.quote"
        except Exception as err:
            quote_error = str(err)

        if not quote:
            try:
                tencent_quote = (
                    data_sources.fetch_tencent_fundamentals([normalized_code]).get(
                        normalized_code
                    )
                    or {}
                )
                tencent_price = data_sources.safe_float(tencent_quote.get("price"))
                if tencent_price is not None and tencent_price > 0:
                    quote = tencent_quote
                    quote_source = "tencent.quote"
            except Exception as err:
                quote_error = f"{quote_error}; tencent: {err}" if quote_error else str(err)

        df = pd.DataFrame()
        daily_error = None
        daily_source = ""
        try:
            df = data_sources.fetch_mootdx_daily_df(
                normalized_code, today - timedelta(days=5), today
            )
        except Exception as err:
            daily_error = str(err)

        latest_daily = None
        if df is not None and not df.empty:
            df = df.copy()
            df["日期"] = pd.to_datetime(df["日期"], errors="coerce")
            df = df[df["日期"].notna()]
            if not df.empty:
                df_today = df[df["日期"].dt.date == today]
                if not df_today.empty:
                    latest_daily = df_today.iloc[-1]
                    daily_source = "mootdx.daily"

        # mootdx 的日线接口可能在盘中报错，或只返回前一交易日。腾讯日线
        # 只作为缺当天数据时的回退，避免无谓地增加每分钟请求量。
        if latest_daily is None:
            try:
                tencent_df = data_sources.fetch_tencent_daily_df(
                    normalized_code, today - timedelta(days=5), today
                )
                if tencent_df is not None and not tencent_df.empty:
                    tencent_df = tencent_df.copy()
                    tencent_df["日期"] = pd.to_datetime(
                        tencent_df["日期"], errors="coerce"
                    )
                    tencent_today = tencent_df[
                        tencent_df["日期"].dt.date == today
                    ]
                    if not tencent_today.empty:
                        latest_daily = tencent_today.iloc[-1]
                        daily_source = "tencent.daily"
            except Exception as err:
                daily_error = (
                    f"{daily_error}; tencent: {err}" if daily_error else str(err)
                )

        # 如果 mootdx 日线本身失败或没有返回今天的数据，重新用腾讯实时
        # 快照覆盖 mootdx quote，避免把同一故障源的旧盘中价格继续写入。
        if latest_daily is None and quote_source == "mootdx.quote":
            try:
                tencent_quote = (
                    data_sources.fetch_tencent_fundamentals([normalized_code]).get(
                        normalized_code
                    )
                    or {}
                )
                tencent_price = data_sources.safe_float(tencent_quote.get("price"))
                if tencent_price is not None and tencent_price > 0:
                    quote = tencent_quote
                    quote_source = "tencent.quote"
            except Exception as err:
                quote_error = f"{quote_error}; tencent: {err}" if quote_error else str(err)

        def first_number(*values):
            for value in values:
                parsed = data_sources.safe_float(value)
                if parsed is not None:
                    return parsed
            return None

        price = first_number(quote.get("price"))
        quote_date = _parse_tencent_quote_date(quote.get("trade_time"))
        quote_is_current = (
            bool(quote)
            and price is not None
            and price > 0
            and (quote_source != "tencent.quote" or quote_date in {None, today})
        )
        daily_open = latest_daily.get("开盘") if latest_daily is not None else None
        daily_close = latest_daily.get("收盘") if latest_daily is not None else None
        daily_high = latest_daily.get("最高") if latest_daily is not None else None
        daily_low = latest_daily.get("最低") if latest_daily is not None else None
        daily_volume = latest_daily.get("成交量") if latest_daily is not None else None
        daily_amount = latest_daily.get("成交额") if latest_daily is not None else None

        open_v = first_number(daily_open, quote.get("open"), price)
        # 实时价必须优先于 mootdx 返回的当日静态 close，避免旧盘中快照残留。
        close_v = first_number(price if quote_is_current else None, daily_close, price)
        high_v = first_number(daily_high, quote.get("high"), close_v)
        low_v = first_number(daily_low, quote.get("low"), close_v)
        volume_v = first_number(daily_volume, quote.get("volume"))
        amount_v = first_number(daily_amount, quote.get("amount"))

        high_v = _safe_max([high_v, open_v, close_v])
        low_v = _safe_min([low_v, open_v, close_v])
        if None in (open_v, close_v, high_v, low_v, volume_v):
            return {
                "status": "empty",
                "code": normalized_code,
                "quote_error": quote_error,
                "daily_error": daily_error,
            }

        prev_close = data_sources.safe_float((quote or {}).get("prev_close"))
        if prev_close is None:
            prev_row = (
                session.query(DailyPrice.close)
                .filter(
                    DailyPrice.stock_code == normalized_code,
                    DailyPrice.date < today,
                )
                .order_by(DailyPrice.date.desc())
                .first()
            )
            prev_close = data_sources.safe_float(prev_row[0]) if prev_row else None

        change_amount = close_v - prev_close if prev_close else None
        change_pct = (
            (change_amount / prev_close * 100)
            if prev_close and change_amount is not None
            else None
        )
        amplitude = (
            ((high_v - low_v) / prev_close * 100)
            if prev_close and high_v is not None and low_v is not None
            else None
        )

        close_rows = (
            session.query(DailyPrice.close)
            .filter(
                DailyPrice.stock_code == normalized_code,
                DailyPrice.date < today,
            )
            .order_by(DailyPrice.date.desc())
            .limit(59)
            .all()
        )
        ma_inputs = [float(row[0]) for row in reversed(close_rows) if row[0] is not None]
        ma_inputs.append(float(close_v))
        ma60 = sum(ma_inputs[-60:]) / 60 if len(ma_inputs) >= 60 else None

        recent_volume_rows = (
            session.query(DailyPrice.volume, DailyPrice.amount, DailyPrice.close)
            .filter(
                DailyPrice.stock_code == normalized_code,
                DailyPrice.date < today,
            )
            .order_by(DailyPrice.date.desc())
            .limit(30)
            .all()
        )
        recent_volume_hands: list[float] = []
        for row_volume, row_amount, row_close in reversed(recent_volume_rows):
            normalized = _normalize_volume_to_hands(
                row_volume,
                row_amount,
                row_close,
                recent_volume_hands[-20:],
            )
            if normalized and normalized > 0:
                recent_volume_hands.append(float(normalized))
        volume_v = _normalize_volume_to_hands(
            volume_v,
            amount_v,
            close_v,
            recent_volume_hands[-20:],
        )
        if amount_v is None:
            amount_v = _estimate_amount_from_hands(close_v, volume_v)

        existing = (
            session.query(DailyPrice)
            .filter(
                DailyPrice.stock_code == normalized_code,
                DailyPrice.date == today,
            )
            .first()
        )
        payload = {
            "stock_code": normalized_code,
            "date": today,
            "open": open_v,
            "close": close_v,
            "high": high_v,
            "low": low_v,
            "volume": volume_v,
            "amount": amount_v,
            "amplitude": amplitude,
            "change_pct": change_pct,
            "change_amount": change_amount,
            "turnover_rate": None,
            "ma60": ma60,
        }
        if existing:
            for key, value in payload.items():
                setattr(existing, key, value)
        else:
            session.add(DailyPrice(**payload))
        session.commit()
        source_parts = [item for item in (daily_source, quote_source) if item]
        source = "+".join(source_parts) or "intraday.quote"
        return {
            "status": "updated",
            "code": normalized_code,
            "date": today.isoformat(),
            "close": close_v,
            "source": source,
        }
    except Exception as err:
        session.rollback()
        return {"status": "error", "code": normalized_code, "error": str(err)}
    finally:
        if close_session:
            session.close()


def scheduled_active_kline_refresh():
    """开市期间每分钟刷新最近查看过的个股当日日K。"""
    if not _is_cn_stock_market_open():
        return
    codes = _active_kline_codes_snapshot()
    if not codes:
        return
    updated = 0
    errors: list[str] = []
    for code in codes:
        result = refresh_mootdx_intraday_daily_kline(code)
        if result.get("status") == "updated":
            updated += 1
        elif result.get("status") == "error":
            errors.append(f"{code}:{result.get('error')}")
    if updated or errors:
        print(
            f"[mootdx-kline] refreshed={updated}/{len(codes)}"
            + (f" errors={'; '.join(errors[:3])}" if errors else "")
        )


def scheduled_market_intraday_snapshot_refresh():
    """开市期间定期刷新全市场当天快照，供行情数据页使用。"""
    if not _is_cn_stock_market_open():
        return
    refresh_tencent_intraday_market_snapshot()


scheduler.add_job(
    scheduled_active_kline_refresh,
    "interval",
    minutes=1,
    id="active_kline_intraday_refresh",
    replace_existing=True,
    max_instances=1,
    coalesce=True,
    misfire_grace_time=60,
)
scheduler.add_job(
    scheduled_market_intraday_snapshot_refresh,
    "interval",
    minutes=1,
    id="market_intraday_snapshot_refresh",
    replace_existing=True,
    max_instances=1,
    coalesce=True,
    misfire_grace_time=90,
)
scheduler.start()

# --- API 接口 ---

from fastapi import Depends


@app.get("/api/health/live")
def api_health_live():
    """Process liveness probe; it intentionally does not require dependencies."""
    return {"status": "ok", "time": datetime.now().isoformat()}


@app.get("/api/health/ready")
def api_health_ready():
    """Readiness probe for the load balancer and systemd watchdog."""
    checks = {"database": False, "cache": False, "queue": True}
    errors: dict[str, str] = {}
    try:
        with engine.connect() as connection:
            connection.execute(text("SELECT 1"))
        checks["database"] = True
    except Exception as exc:
        errors["database"] = _assistant_sanitize_error(exc)
    cache_status = cache_backend.status()
    checks["cache"] = bool(cache_status.get("redis_available"))
    if queue_enabled():
        queue_status = queue_health()
        checks["queue"] = bool(queue_status.get("available")) and int(
            queue_status.get("active_workers") or 0
        ) > 0
    else:
        queue_status = {"available": False, "disabled": True}
    ready = all(checks.values())
    payload = {
        "status": "ready" if ready else "not_ready",
        "time": datetime.now().isoformat(),
        "db": engine.url.get_backend_name(),
        "checks": checks,
        "cache": cache_status,
        "queue": queue_status,
        "errors": errors,
    }
    return JSONResponse(status_code=200 if ready else 503, content=payload)


@app.get("/api/health")
def api_health():
    """Backward-compatible summary plus dependency state."""
    cache_status = cache_backend.status()
    queue_status = queue_health() if queue_enabled() else {"available": False, "disabled": True}
    return {
        "status": "ok",
        "time": datetime.now().isoformat(),
        "db": engine.url.get_backend_name(),
        "cache": cache_status,
        "queue": queue_status,
    }


@app.post("/token")
async def login_for_access_token(
    request: Request,
    form_data: OAuth2PasswordRequestForm = Depends(),
    db: Session = Depends(get_db),
):
    _check_rate_limit(request.client.host if request.client else "unknown")
    user = _find_user_by_login_identifier(db, form_data.username)
    if not user or not verify_password(form_data.password, user.password_hash):
        raise HTTPException(
            status_code=401,
            detail="Incorrect username/email or password",
            headers={"WWW-Authenticate": "Bearer"},
        )
    access_token_expires = timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    access_token = create_access_token(
        data={"sub": user.username}, expires_delta=access_token_expires
    )
    return {
        "access_token": access_token,
        "token_type": "bearer",
        "user": serialize_user_auth(user),
    }


@app.post("/api/register")
def register_user(
    user: UserRegister,
    request: Request,
    db: Session = Depends(get_db),
):
    settings_value = _auth_security_settings(db)
    basic_auth = settings_value.get("basic_auth") or {}
    if not basic_auth.get("enabled", True) or not basic_auth.get("registration_enabled", True):
        raise HTTPException(status_code=403, detail="账号密码注册当前未开放")
    _verify_bot_protection(db, request, user.captcha_token, "register")
    email_value = _normalized_registration_email(user.email)
    allowed_domains = basic_auth.get("allowed_email_domains") or []
    if allowed_domains:
        if not email_value:
            raise HTTPException(status_code=400, detail="当前注册仅允许指定邮箱域名，请填写邮箱")
        email_domain = email_value.rsplit("@", 1)[-1]
        if email_domain not in allowed_domains:
            raise HTTPException(status_code=400, detail="该邮箱域名不在允许注册范围内")
    db_user = db.query(UserModel).filter(UserModel.username == user.username).first()
    if db_user:
        raise HTTPException(status_code=400, detail="Username already registered")
    if email_value and db.query(UserModel).filter(func.lower(UserModel.email) == email_value).first():
        raise HTTPException(status_code=400, detail="Email already registered")
    smtp_cfg = settings_value.get("smtp") or {}
    if smtp_cfg.get("enabled") and smtp_cfg.get("require_email_verification"):
        if not email_value:
            raise HTTPException(status_code=400, detail="请填写邮箱并完成验证码验证")
        expected_code = cache_get(f"auth:email_code:register:{email_value}")
        if not expected_code or str(user.email_code or "").strip() != str(expected_code):
            raise HTTPException(status_code=400, detail="邮箱验证码无效或已过期")
        cache_delete(f"auth:email_code:register:{email_value}")

    hashed_password = get_password_hash(user.password)
    new_user = UserModel(
        username=user.username,
        password_hash=hashed_password,
        email=email_value or None,
    )
    db.add(new_user)
    db.flush()
    if new_user.email:
        _grant_email_registration_bonus_subscription(db, new_user)
    db.commit()
    return {
        "message": "User created successfully",
        "registration_bonus": {
            "enabled": bool(new_user.email),
            "credits": 300 if new_user.email else 0,
            "days": 14 if new_user.email else 0,
        },
    }


@app.post("/api/login")
def login_api(
    user: UserLogin,
    request: Request,
    db: Session = Depends(get_db),
):
    # Custom login endpoint for JSON body if needed, or use /token
    settings_value = _auth_security_settings(db)
    if not (settings_value.get("basic_auth") or {}).get("enabled", True):
        raise HTTPException(status_code=403, detail="账号密码登录当前未开放")
    _check_rate_limit(_client_ip(request))
    _verify_bot_protection(db, request, user.captcha_token, "login")
    db_user = _find_user_by_login_identifier(db, user.username)
    if not db_user or not verify_password(user.password, db_user.password_hash):
        raise HTTPException(status_code=400, detail="Incorrect username/email or password")

    return _issue_auth_token(db_user)


