def _homepage_ad_for_placement(settings_value: dict, placement_key: str) -> Optional[dict]:
    ads = settings_value.get("homepage_ads") if isinstance(settings_value.get("homepage_ads"), dict) else {}
    normalized = str(placement_key or "").strip().lower()
    if normalized == "top_banner":
        item = ads.get("top_banner") if isinstance(ads.get("top_banner"), dict) else {}
        return item if item.get("enabled") and item.get("content") else None
    match = re.match(r"^sponsor_(\d+)$", normalized)
    if not match:
        return None
    index = int(match.group(1)) - 1
    sponsors = ads.get("sponsors") if isinstance(ads.get("sponsors"), list) else []
    if index < 0 or index >= len(sponsors):
        return None
    item = sponsors[index] if isinstance(sponsors[index], dict) else {}
    return item if item.get("enabled") and item.get("content") else None


def _request_ip_hash(request: Request) -> str:
    forwarded = str(request.headers.get("x-forwarded-for") or "").split(",", 1)[0].strip()
    raw_ip = forwarded or (request.client.host if request.client else "")
    if not raw_ip:
        return ""
    return hashlib.sha256(f"{settings.SECRET_KEY}:{raw_ip}".encode("utf-8")).hexdigest()[:32]


def _analytics_text(value: Any, max_length: int = 120, default: str = "") -> str:
    text_value = str(value or "").strip()
    if not text_value:
        return default
    return text_value[:max_length]


def _analytics_duration_seconds(value: Any) -> float:
    try:
        parsed = float(value or 0)
    except (TypeError, ValueError):
        parsed = 0.0
    return round(max(0.0, min(parsed, 24 * 60 * 60)), 3)


def _analytics_duration_ms(value: Any) -> float:
    try:
        parsed = float(value or 0)
    except (TypeError, ValueError):
        parsed = 0.0
    return round(max(0.0, min(parsed, 24 * 60 * 60 * 1000)), 3)


def _analytics_guess_device(user_agent: str) -> str:
    ua = (user_agent or "").lower()
    if any(token in ua for token in ("ipad", "tablet", "pad;")):
        return "pad"
    if any(token in ua for token in ("mobile", "iphone", "android", "phone")):
        return "mobile"
    return "pc"


def _analytics_guess_browser(user_agent: str) -> str:
    ua = user_agent or ""
    lower = ua.lower()
    if "micromessenger" in lower:
        return "WeChat"
    if "edg/" in lower:
        return "Edge"
    if "firefox/" in lower:
        return "Firefox"
    if "chrome/" in lower or "crios/" in lower:
        return "Chrome"
    if "safari/" in lower:
        return "Safari"
    return "Other"


def _analytics_guess_os(user_agent: str) -> str:
    lower = (user_agent or "").lower()
    if "windows" in lower:
        return "Windows"
    if "android" in lower:
        return "Android"
    if "iphone" in lower or "ipad" in lower or "ios" in lower:
        return "iOS"
    if "mac os" in lower or "macintosh" in lower:
        return "macOS"
    if "linux" in lower:
        return "Linux"
    return "Other"


def _analytics_source(payload: AnalyticsEventRequest, request: Request) -> tuple[str, str]:
    allowed = {"direct", "search", "external", "promotion", "internal"}
    source_type = _analytics_text(payload.source_type, 40).lower()
    source = _analytics_text(payload.source, 120)
    referrer = _analytics_text(payload.referrer, 500)
    if source_type in allowed:
        return source_type, source or _analytics_text(urlparse(referrer).netloc, 120)
    if source:
        return "promotion", source
    if not referrer:
        return "direct", "direct"
    parsed = urlparse(referrer)
    host = (parsed.netloc or "").lower()
    current_host = (request.url.hostname or "").lower()
    if current_host and host and current_host in host:
        return "internal", host
    if any(token in host for token in ("baidu.", "google.", "bing.", "sogou.", "so.com", "sm.cn")):
        return "search", host or "search"
    if any(token in referrer.lower() for token in ("utm_", "gdt_vid", "bd_vid", "campaign")):
        return "promotion", host or "promotion"
    return "external", host or "external"


def _analytics_identity(
    request: Request,
    payload: AnalyticsEventRequest,
    ip_hash: str,
    user_agent: str,
) -> tuple[str, str]:
    visitor_key = _analytics_text(payload.visitor_key, 120)
    if not visitor_key:
        visitor_seed = f"{ip_hash}:{user_agent[:160]}"
        visitor_key = hashlib.sha256(visitor_seed.encode("utf-8")).hexdigest()[:32]
    session_key = _analytics_text(payload.session_key, 120)
    if not session_key:
        today = _utcnow().date().isoformat()
        session_seed = f"{visitor_key}:{today}"
        session_key = hashlib.sha256(session_seed.encode("utf-8")).hexdigest()[:32]
    return visitor_key, session_key


def _upsert_analytics_session(
    db: Session,
    *,
    request: Request,
    payload: AnalyticsEventRequest,
    user: Optional[UserModel],
    page_increment: bool,
) -> AnalyticsSession:
    now = _utcnow()
    ip_hash = _request_ip_hash(request)
    user_agent = _analytics_text(request.headers.get("user-agent"), 500)
    visitor_key, session_key = _analytics_identity(request, payload, ip_hash, user_agent)
    source_type, source = _analytics_source(payload, request)
    row = db.query(AnalyticsSession).filter(AnalyticsSession.session_key == session_key).first()
    if not row:
        is_returning = (
            db.query(AnalyticsSession.id)
            .filter(AnalyticsSession.visitor_key == visitor_key)
            .first()
            is not None
        )
        row = AnalyticsSession(
            session_key=session_key,
            visitor_key=visitor_key,
            user_id=user.id if user else None,
            started_at=now,
            last_seen_at=now,
            duration_seconds=0.0,
            page_count=0,
            is_returning=is_returning,
            source_type=source_type,
            source=source,
            device_type=_analytics_text(payload.device_type, 40) or _analytics_guess_device(user_agent),
            browser=_analytics_text(payload.browser, 40) or _analytics_guess_browser(user_agent),
            os=_analytics_text(payload.os, 40) or _analytics_guess_os(user_agent),
            region=_analytics_text(payload.region, 80),
            ip_hash=ip_hash,
            user_agent=user_agent,
        )
        db.add(row)
    elif user and not row.user_id:
        row.user_id = user.id
    row.last_seen_at = now
    duration = _analytics_duration_seconds(payload.duration_seconds)
    if duration > float(row.duration_seconds or 0):
        row.duration_seconds = duration
    if page_increment:
        row.page_count = int(row.page_count or 0) + 1
    if payload.device_type:
        row.device_type = _analytics_text(payload.device_type, 40)
    if payload.browser:
        row.browser = _analytics_text(payload.browser, 40)
    if payload.os:
        row.os = _analytics_text(payload.os, 40)
    if payload.region:
        row.region = _analytics_text(payload.region, 80)
    return row


@app.post("/api/public/analytics/event")
def record_public_analytics_event(
    request: Request,
    payload: AnalyticsEventRequest,
    db: Session = Depends(get_db),
):
    user = _optional_user_from_request(request, db)
    event_type = payload.event_type
    session = _upsert_analytics_session(
        db,
        request=request,
        payload=payload,
        user=user,
        page_increment=event_type == "page_view",
    )
    visitor_key = session.visitor_key
    session_key = session.session_key
    user_id = user.id if user else session.user_id
    source_type, source = _analytics_source(payload, request)
    user_agent = _analytics_text(request.headers.get("user-agent"), 500)
    path = _analytics_text(payload.path, 800, "/")

    try:
        if event_type == "page_view":
            db.add(
                AnalyticsPageView(
                    session_key=session_key,
                    visitor_key=visitor_key,
                    user_id=user_id,
                    path=path,
                    title=_analytics_text(payload.title, 160),
                    referrer=_analytics_text(payload.referrer, 500),
                    source_type=source_type,
                    source=source,
                    device_type=_analytics_text(payload.device_type, 40) or session.device_type,
                    browser=_analytics_text(payload.browser, 40) or session.browser,
                    os=_analytics_text(payload.os, 40) or session.os,
                    region=_analytics_text(payload.region, 80) or session.region,
                    duration_seconds=_analytics_duration_seconds(payload.duration_seconds),
                    is_entry=bool(payload.is_entry),
                    is_exit=bool(payload.is_exit),
                )
            )
        elif event_type in {"page_leave", "page_duration"}:
            latest_view = (
                db.query(AnalyticsPageView)
                .filter(
                    AnalyticsPageView.session_key == session_key,
                    AnalyticsPageView.path == path,
                )
                .order_by(AnalyticsPageView.created_at.desc(), AnalyticsPageView.id.desc())
                .first()
            )
            if latest_view:
                duration = _analytics_duration_seconds(payload.duration_seconds)
                if duration > float(latest_view.duration_seconds or 0):
                    latest_view.duration_seconds = duration
                latest_view.is_exit = bool(payload.is_exit if payload.is_exit is not None else True)
                if user_id and not latest_view.user_id:
                    latest_view.user_id = user_id
        else:
            module_key = _analytics_text(payload.module_key, 80, "funnel" if event_type == "funnel" else "unknown")
            db.add(
                AnalyticsModuleUsage(
                    module_key=module_key,
                    module_label=_analytics_text(payload.module_label, 120),
                    action=_analytics_text(payload.action, 80, event_type),
                    path=path,
                    success=bool(payload.success),
                    result_count=payload.result_count if payload.result_count is not None else None,
                    duration_ms=_analytics_duration_ms(payload.duration_ms),
                    session_key=session_key,
                    visitor_key=visitor_key,
                    user_id=user_id,
                    meta_json=json.dumps(payload.meta or {}, ensure_ascii=False, default=str),
                )
            )
        db.commit()
    except Exception:
        db.rollback()
        raise
    return {"status": "ok"}


@app.post("/api/public/ad-events")
def record_public_ad_event(
    request: Request,
    payload: dict = Body(...),
    db: Session = Depends(get_db),
):
    event_type = str(payload.get("event_type") or "").strip().lower()
    if event_type not in {"impression", "click"}:
        raise HTTPException(status_code=400, detail="广告事件类型无效")
    placement_key = str(payload.get("placement_key") or "").strip().lower()
    settings_value = _public_site_settings(db)
    ad = _homepage_ad_for_placement(settings_value, placement_key)
    if not ad:
        raise HTTPException(status_code=400, detail="广告位未启用")
    sponsor_index = None
    match = re.match(r"^sponsor_(\d+)$", placement_key)
    if match:
        sponsor_index = int(match.group(1))
    session_key = str(payload.get("session_key") or "").strip()[:120]
    row = AdEvent(
        placement_key=placement_key,
        event_type=event_type,
        ad_name=str(ad.get("name") or "")[:80],
        platform=str(ad.get("platform") or "direct")[:40],
        sponsor_index=sponsor_index,
        href=str(ad.get("href") or "")[:500],
        session_key=session_key,
        user_agent=str(request.headers.get("user-agent") or "")[:500],
        ip_hash=_request_ip_hash(request),
        meta_json=json.dumps(
            {
                "format": ad.get("format") or "markdown",
                "configured_href": bool(ad.get("href")),
            },
            ensure_ascii=False,
        ),
    )
    db.add(row)
    db.commit()
    return {"status": "ok"}


