@app.post("/api/auth/email-code")
def send_auth_email_code(
    request: Request,
    payload: dict = Body(...),
    db: Session = Depends(get_db),
):
    email_value = str(payload.get("email") or "").strip().lower()
    purpose = str(payload.get("purpose") or "register").strip().lower()
    username_value = str(payload.get("username") or "").strip()
    captcha_token = payload.get("captcha_token")
    if purpose in {"reset", "forgot", "password_reset"}:
        purpose = "reset_password"
    if purpose not in {"register", "reset_password"}:
        raise HTTPException(status_code=400, detail="不支持的验证码用途")
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email_value):
        raise HTTPException(status_code=400, detail="邮箱格式不正确")
    _verify_bot_protection(
        db,
        request,
        captcha_token,
        "login" if purpose == "reset_password" else "register",
    )
    settings_value = _auth_security_settings(db)
    if not settings_value.get("smtp", {}).get("enabled"):
        raise HTTPException(status_code=400, detail="SMTP 邮箱服务未启用")

    if purpose == "register":
        allowed_domains = (settings_value.get("basic_auth") or {}).get("allowed_email_domains") or []
        if allowed_domains and email_value.rsplit("@", 1)[-1] not in allowed_domains:
            raise HTTPException(status_code=400, detail="该邮箱域名不在允许注册范围内")
        if db.query(UserModel).filter(func.lower(UserModel.email) == email_value).first():
            raise HTTPException(status_code=400, detail="Email already registered")
    else:
        query = db.query(UserModel).filter(func.lower(UserModel.email) == email_value)
        if username_value:
            query = query.filter(UserModel.username == username_value)
        reset_user = query.first()
        if not reset_user:
            return {
                "status": "ok",
                "message": "如果该邮箱已绑定账号，验证码将发送到邮箱。",
            }

    code = f"{secrets.randbelow(900000) + 100000}"
    cache_set(
        f"auth:email_code:{purpose}:{email_value}",
        code,
        ex=AUTH_EMAIL_CODE_TTL_SECONDS,
    )
    _send_smtp_email(
        settings_value,
        email_value,
        "AIQuartSmart Community Edition邮箱验证码" if purpose == "register" else "AIQuartSmart Community Edition密码重设验证码",
        f"<p>你的验证码是：</p><h2>{code}</h2><p>验证码 10 分钟内有效，请勿转发给他人。</p>",
    )
    return {"status": "ok", "message": "验证码已发送"}


@app.get("/api/auth/oauth/{provider}/start")
def auth_oauth_start(
    provider: str,
    request: Request,
    redirect: Optional[str] = None,
    db: Session = Depends(get_db),
):
    provider = provider.lower()
    settings_value = _auth_security_settings(db)
    if not settings_value.get("oauth", {}).get("enabled"):
        raise HTTPException(status_code=404, detail="OAuth 登录未启用")
    cfg = _oauth_provider_config(settings_value, provider)
    if provider == "telegram":
        raise HTTPException(status_code=400, detail="Telegram 登录请使用 Login Widget 回调")
    endpoints = _oauth_endpoints(settings_value, provider, cfg)
    auth_url = endpoints.get("authorization_endpoint")
    token_url = endpoints.get("token_endpoint")
    user_url = endpoints.get("userinfo_endpoint")
    if not auth_url or not token_url or not user_url:
        raise HTTPException(status_code=400, detail="OAuth provider 端点未配置完整")
    for url_value in (auth_url, token_url, user_url):
        _validate_url_with_ssrf(settings_value, url_value)
    state = secrets.token_urlsafe(24)
    frontend_redirect = redirect or str(request.headers.get("referer") or "").split("?")[0] or "/login"
    cache_set(
        f"oauth:state:{state}",
        json.dumps({"provider": provider, "redirect": frontend_redirect}, ensure_ascii=False),
        ex=OAUTH_STATE_TTL_SECONDS,
    )
    params = {
        "client_id": cfg.get("client_id"),
        "redirect_uri": _provider_callback_url(request, settings_value, provider),
        "response_type": "code",
        "scope": cfg.get("scopes") or "openid profile email",
        "state": state,
    }
    if provider == "wechat":
        params["appid"] = params.pop("client_id")
    auth_redirect = f"{auth_url}?{urlencode({k: v for k, v in params.items() if v})}"
    return RedirectResponse(auth_redirect)


@app.get("/api/auth/oauth/{provider}/callback", name="auth_oauth_callback")
def auth_oauth_callback(
    provider: str,
    request: Request,
    code: Optional[str] = None,
    state: Optional[str] = None,
    error: Optional[str] = None,
    db: Session = Depends(get_db),
):
    provider = provider.lower()
    if error:
        raise HTTPException(status_code=400, detail=error)
    if not code or not state:
        raise HTTPException(status_code=400, detail="OAuth 回调缺少 code 或 state")
    state_payload = cache_get(f"oauth:state:{state}")
    if not state_payload:
        raise HTTPException(status_code=403, detail="OAuth state 已过期或无效")
    try:
        state_data = json.loads(state_payload)
    except Exception:
        state_data = {}
    if state_data.get("provider") != provider:
        raise HTTPException(status_code=403, detail="OAuth state 与登录方式不匹配")

    settings_value = _auth_security_settings(db)
    cfg = _oauth_provider_config(settings_value, provider)
    endpoints = _oauth_endpoints(settings_value, provider, cfg)
    token_url = endpoints.get("token_endpoint")
    user_url = endpoints.get("userinfo_endpoint")
    _validate_url_with_ssrf(settings_value, token_url)
    token_payload = {
        "client_id": cfg.get("client_id"),
        "client_secret": cfg.get("client_secret"),
        "code": code,
        "redirect_uri": _provider_callback_url(request, settings_value, provider),
        "grant_type": "authorization_code",
    }
    if provider == "wechat":
        token_payload["appid"] = token_payload.pop("client_id")
        token_payload["secret"] = token_payload.pop("client_secret")
    token_res = None
    try:
        token_res = requests.post(
            token_url,
            data={k: v for k, v in token_payload.items() if v},
            headers={"Accept": "application/json"},
            timeout=12,
        )
        token_data = token_res.json()
    except Exception as err:
        if token_res is None:
            raise HTTPException(status_code=400, detail=f"OAuth token 交换失败：{err}")
        try:
            token_data = dict(
                item.split("=", 1)
                for item in token_res.text.split("&")
                if "=" in item
            )
        except Exception:
            raise HTTPException(status_code=400, detail=f"OAuth token 交换失败：{err}")
    access_token = token_data.get("access_token")
    if not access_token:
        raise HTTPException(status_code=400, detail=f"OAuth token 交换失败：{token_data}")

    extra = {}
    if provider == "qq":
        openid_url = endpoints.get("openid_endpoint")
        _validate_url_with_ssrf(settings_value, openid_url)
        openid_text = requests.get(openid_url, params={"access_token": access_token}, timeout=12).text
        match = re.search(r'"openid"\s*:\s*"([^"]+)"', openid_text)
        if not match:
            raise HTTPException(status_code=400, detail="QQ openid 获取失败")
        extra["openid"] = match.group(1)
    _validate_url_with_ssrf(settings_value, user_url)
    headers = {"Authorization": f"Bearer {access_token}", "Accept": "application/json"}
    params = {}
    if provider == "wechat":
        params = {"access_token": access_token, "openid": token_data.get("openid")}
        headers = {"Accept": "application/json"}
    if provider == "qq":
        params = {
            "access_token": access_token,
            "oauth_consumer_key": cfg.get("client_id"),
            "openid": extra["openid"],
            "format": "json",
        }
        headers = {"Accept": "application/json"}
    try:
        user_payload = requests.get(user_url, headers=headers, params=params, timeout=12).json()
    except Exception as err:
        raise HTTPException(status_code=400, detail=f"OAuth 用户信息获取失败：{err}")
    oauth_user = _normalize_oauth_user(provider, user_payload, extra)
    user = _find_or_create_oauth_user(
        db,
        provider,
        oauth_user,
        auto_register=bool(settings_value.get("oauth", {}).get("auto_register", True)),
    )
    token_payload = _issue_auth_token(user)
    redirect_url = state_data.get("redirect") or "/login"
    html_body = f"""<!doctype html><html><body><script>
localStorage.setItem("quartsys_token", {json.dumps(token_payload["token"])});
localStorage.setItem("token", {json.dumps(token_payload["token"])});
localStorage.setItem("quartsys_auth_user", {json.dumps(json.dumps(token_payload["user"], ensure_ascii=False))});
location.href = {json.dumps(redirect_url)};
</script>登录成功，正在跳转...</body></html>"""
    return Response(content=html_body, media_type="text/html")


@app.post("/api/auth/telegram")
def auth_telegram(payload: dict = Body(...), db: Session = Depends(get_db)):
    settings_value = _auth_security_settings(db)
    cfg = _oauth_provider_config(settings_value, "telegram")
    bot_token = str(cfg.get("bot_token") or "").strip()
    if not bot_token:
        raise HTTPException(status_code=400, detail="Telegram Bot Token 未配置")
    incoming = {k: str(v) for k, v in payload.items() if v is not None}
    received_hash = incoming.pop("hash", "")
    data_check_string = "\n".join(f"{k}={incoming[k]}" for k in sorted(incoming))
    secret_key = hashlib.sha256(bot_token.encode()).digest()
    calculated = hmac.new(secret_key, data_check_string.encode(), hashlib.sha256).hexdigest()
    if not received_hash or not hmac.compare_digest(calculated, received_hash):
        raise HTTPException(status_code=403, detail="Telegram 登录签名校验失败")
    auth_date = int(incoming.get("auth_date") or 0)
    if auth_date and time.time() - auth_date > 86400:
        raise HTTPException(status_code=403, detail="Telegram 登录信息已过期")
    provider_user_id = incoming.get("id") or ""
    oauth_user = {
        "provider_user_id": provider_user_id,
        "username": incoming.get("username") or f"telegram_{provider_user_id}",
        "display_name": " ".join(
            item for item in [incoming.get("first_name"), incoming.get("last_name")] if item
        ),
        "email": "",
        "avatar_url": incoming.get("photo_url") or "",
        "raw": incoming,
    }
    user = _find_or_create_oauth_user(
        db,
        "telegram",
        oauth_user,
        auto_register=bool(settings_value.get("oauth", {}).get("auto_register", True)),
    )
    return _issue_auth_token(user)


