@app.post("/api/auth/passkeys")
def save_passkey_metadata(
    payload: dict = Body(...),
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    settings_value = _auth_security_settings(db)
    if not settings_value.get("passkey", {}).get("enabled"):
        raise HTTPException(status_code=400, detail="通行密钥认证未启用")
    credential_id = str(payload.get("credential_id") or "").strip()
    if not credential_id:
        raise HTTPException(status_code=400, detail="credential_id 不能为空")
    existing = (
        db.query(PasskeyCredential)
        .filter(PasskeyCredential.credential_id == credential_id)
        .first()
    )
    if existing and existing.user_id != current_user.id:
        raise HTTPException(status_code=409, detail="该通行密钥已绑定其它账号")
    row = existing or PasskeyCredential(user_id=current_user.id, credential_id=credential_id)
    row.name = str(payload.get("name") or "通行密钥").strip()[:64]
    row.public_key = str(payload.get("public_key") or row.public_key or "")
    row.transports_json = json.dumps(payload.get("transports") or [], ensure_ascii=False)
    db.add(row)
    db.commit()
    return {"status": "ok", "id": row.id}


