@app.get("/api/checkin")
def get_checkin_status(
    month: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    settings_value = _auth_security_settings(db)
    checkin_cfg = settings_value.get("checkin") or {}
    if not checkin_cfg.get("enabled", True):
        return {"enabled": False, "today_checked": False, "items": []}
    today = datetime.now().date()
    month_prefix = month or today.strftime("%Y-%m")
    start = datetime.strptime(month_prefix + "-01", "%Y-%m-%d").date()
    end = (start + timedelta(days=32)).replace(day=1)
    rows = (
        db.query(UserCheckin)
        .filter(
            UserCheckin.user_id == current_user.id,
            UserCheckin.checkin_date >= start,
            UserCheckin.checkin_date < end,
        )
        .order_by(UserCheckin.checkin_date.asc())
        .all()
    )
    return {
        "enabled": True,
        "today_checked": any(row.checkin_date == today for row in rows),
        "min_credits": checkin_cfg.get("min_credits", 5),
        "max_credits": checkin_cfg.get("max_credits", 20),
        "items": [
            {
                "date": row.checkin_date.isoformat(),
                "credits_awarded": row.credits_awarded,
            }
            for row in rows
        ],
    }


@app.post("/api/checkin")
def do_checkin(
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    settings_value = _auth_security_settings(db)
    checkin_cfg = settings_value.get("checkin") or {}
    if not checkin_cfg.get("enabled", True):
        raise HTTPException(status_code=400, detail="签到奖励未启用")
    today = datetime.now().date()
    existing = (
        db.query(UserCheckin)
        .filter(UserCheckin.user_id == current_user.id, UserCheckin.checkin_date == today)
        .first()
    )
    if existing:
        return {
            "status": "already_checked",
            "message": "今日已签到",
            "credits_awarded": existing.credits_awarded,
            "credit_summary": _credit_summary(db, current_user),
        }
    min_credits = int(checkin_cfg.get("min_credits") or 5)
    max_credits = int(checkin_cfg.get("max_credits") or min_credits)
    awarded = secrets.randbelow(max_credits - min_credits + 1) + min_credits
    sub = None if normalize_user_role(current_user.role) == "admin" else _ensure_user_subscription(db, current_user)
    if sub:
        sub.credits_total = int(sub.credits_total or 0) + awarded
    row = UserCheckin(user_id=current_user.id, checkin_date=today, credits_awarded=awarded)
    db.add(row)
    db.add(
        CreditLedger(
            user_id=current_user.id,
            subscription_id=sub.id if sub else None,
            action="daily_checkin",
            amount=-awarded,
            balance_after=(int(sub.credits_total or 0) - int(sub.credits_used or 0)) if sub else None,
            reference_id=f"checkin:{today.isoformat()}",
            status="granted",
            meta_json=json.dumps({"date": today.isoformat()}, ensure_ascii=False),
        )
    )
    db.commit()
    return {
        "status": "ok",
        "message": "签到成功",
        "credits_awarded": awarded,
        "credit_summary": _credit_summary(db, current_user),
    }


@app.get("/api/admin/users", dependencies=[Depends(require_permission("system.manage"))])
def list_admin_users(
    db: Session = Depends(get_db), current_user: UserModel = Depends(get_current_user)
):
    users = db.query(UserModel).order_by(UserModel.id.asc()).all()
    user_ids = [user.id for user in users]
    subscriptions_by_user: Dict[int, UserSubscription] = {}
    if user_ids:
        rows = (
            db.query(UserSubscription)
            .filter(UserSubscription.user_id.in_(user_ids))
            .order_by(UserSubscription.user_id.asc(), UserSubscription.created_at.desc())
            .all()
        )
        for row in rows:
            subscriptions_by_user.setdefault(row.user_id, row)
    return [
        {
            **serialize_user_auth(user),
            "created_at": user.created_at.isoformat() if user.created_at else None,
            "is_current": user.id == current_user.id,
            "subscription": _serialize_subscription(subscriptions_by_user.get(user.id)),
        }
        for user in users
    ]


@app.put(
    "/api/admin/users/{user_id}/role",
    dependencies=[Depends(require_permission("system.manage"))],
)
def update_admin_user_role(
    user_id: int,
    payload: UserRoleUpdate,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    user = db.query(UserModel).filter(UserModel.id == user_id).first()
    if not user:
        raise HTTPException(status_code=404, detail="用户不存在")
    target_role = normalize_user_role(payload.role)
    if user.id == current_user.id and target_role != "admin":
        raise HTTPException(status_code=400, detail="不能移除自己的系统管理员权限")
    if target_role == "admin":
        existing_admin = (
            db.query(UserModel)
            .filter(UserModel.id != user.id, UserModel.role == "admin")
            .first()
        )
        if existing_admin:
            raise HTTPException(status_code=400, detail="系统管理员只能有 1 个")
    if target_role != "admin" and payload.permissions and "system.manage" in payload.permissions:
        raise HTTPException(status_code=400, detail="非管理员用户不能授予系统管理权限")
    user.role = target_role
    if target_role == "admin":
        user.permission_overrides_json = None
    elif payload.permissions is None:
        user.permission_overrides_json = None
    elif payload.permissions == permissions_for_role(target_role):
        user.permission_overrides_json = None
    else:
        user.permission_overrides_json = json.dumps(payload.permissions, ensure_ascii=False)
    db.flush()
    _sync_user_subscription_to_role(
        db,
        user,
        source_order_no=f"admin-role-sync:{current_user.id}:{uuid.uuid4().hex[:8]}",
    )
    db.commit()
    db.refresh(user)
    active = None if target_role == "admin" else _active_subscription_query(db, user.id).first()
    return {
        **serialize_user_auth(user),
        "subscription": _serialize_subscription(active),
    }


@app.post("/api/reset_password")
def reset_password(data: UserResetPassword, db: Session = Depends(get_db)):
    user = db.query(UserModel).filter(UserModel.username == data.username).first()
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    if data.old_password:
        if not verify_password(data.old_password, user.password_hash):
            raise HTTPException(status_code=400, detail="Old password incorrect")
    else:
        settings_value = _auth_security_settings(db)
        if not settings_value.get("smtp", {}).get("enabled"):
            raise HTTPException(status_code=400, detail="SMTP 邮箱找回密码未启用")
        email_value = (data.email or "").strip().lower()
        if not email_value or not user.email or user.email.lower() != email_value:
            raise HTTPException(status_code=400, detail="账号和邮箱不匹配")
        expected_code = cache_get(f"auth:email_code:reset_password:{email_value}")
        if not expected_code or str(data.email_code or "").strip() != str(expected_code):
            raise HTTPException(status_code=400, detail="邮箱验证码无效或已过期")
        cache_delete(f"auth:email_code:reset_password:{email_value}")
    user.password_hash = get_password_hash(data.new_password)
    db.commit()
    return {"message": "Password updated successfully"}


