@app.delete("/api/watchlist", dependencies=[Depends(require_permission("dashboard.view"))])
def remove_watchlist(
    group_name: Optional[str] = None,
    code: Optional[str] = None,
    payload: Optional[WatchlistDeleteRequest] = Body(default=None),
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    g = payload.group_name if payload else group_name
    c = payload.code if payload else code
    if not g or not c:
        raise HTTPException(status_code=400, detail="group_name 和 code 必填")
    db.query(Watchlist).filter(
        Watchlist.group_name == g,
        Watchlist.code == c,
        (Watchlist.user_id == current_user.id) | (Watchlist.user_id == None),
    ).delete(synchronize_session=False)
    db.commit()
    return {"message": "removed"}


@app.delete("/api/watchlist/group", dependencies=[Depends(require_permission("dashboard.view"))])
def remove_watchlist_group(
    group_name: Optional[str] = None,
    payload: Optional[WatchlistGroupDeleteRequest] = Body(default=None),
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    g = payload.group_name if payload else group_name
    if not g:
        raise HTTPException(status_code=400, detail="group_name 必填")
    try:
        db.query(Watchlist).filter(
            Watchlist.group_name == g,
            Watchlist.user_id == current_user.id,
        ).delete(
            synchronize_session=False
        )
        db.commit()
        return {"message": "group removed"}
    except Exception as e:
        db.rollback()
        print(f"删除分组失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.put("/api/watchlist/group", dependencies=[Depends(require_permission("dashboard.view"))])
def rename_watchlist_group(
    payload: WatchlistGroupRenameRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    old_name = (payload.group_name or "").strip()
    new_name = (payload.new_group_name or "").strip()
    if not old_name or not new_name:
        raise HTTPException(status_code=400, detail="group_name 和 new_group_name 必填")
    if old_name == new_name:
        return {"message": "group renamed", "group_name": new_name}
    exists = (
        db.query(Watchlist)
        .filter(
            Watchlist.group_name == new_name,
            Watchlist.user_id == current_user.id,
        )
        .first()
    )
    if exists:
        raise HTTPException(status_code=400, detail="目标分组已存在")
    updated = (
        db.query(Watchlist)
        .filter(
            Watchlist.group_name == old_name,
            Watchlist.user_id == current_user.id,
        )
        .update({Watchlist.group_name: new_name}, synchronize_session=False)
    )
    if not updated:
        raise HTTPException(status_code=404, detail="分组不存在")
    db.commit()
    return {"message": "group renamed", "group_name": new_name}


@app.get("/api/search", dependencies=[Depends(require_permission("quote.view"))])
def search_stocks(q: str, market: str = "CN", db: Session = Depends(get_db)):
    """根据代码或名称搜索股票"""
    print(f"搜索股票: {q}")
    query = str(q or "").strip()
    market_code = _normalize_market_code(market)
    if not query:
        return []

    try:
        def normalize_full_code(raw_code: str) -> str:
            code = (raw_code or "").strip()
            normalized_code = data_sources.normalize_stock_code(code)
            if normalized_code.startswith(("fund:", "trust:")):
                return normalized_code
            if data_sources.is_hk_stock_code(normalized_code):
                return f"{normalized_code[2:]}.HK"
            if data_sources.is_us_stock_code(normalized_code):
                return f"{normalized_code[2:]}.US"
            if data_sources.is_cn_listed_security_code(normalized_code):
                exchange = data_sources.infer_exchange(normalized_code)
                suffix = {"SSE": "SH", "SZSE": "SZ", "BSE": "BJ"}.get(exchange, "")
                return f"{normalized_code}.{suffix}" if suffix else normalized_code
            digits = "".join(ch for ch in code if ch.isdigit())
            if not digits:
                return code.upper()
            suffix = ""
            if digits.startswith("6") or digits.startswith("688"):
                suffix = "SH"
            elif digits.startswith("0") or digits.startswith("3"):
                suffix = "SZ"
            elif digits.startswith("4") or digits.startswith("8"):
                suffix = "BJ"
            return f"{digits}.{suffix}" if suffix else digits

        def external_equity_candidates(raw_query: str) -> list[str]:
            raw = str(raw_query or "").strip()
            if not raw:
                return []
            candidates: list[str] = []

            def add(value: str):
                try:
                    normalized_value = data_sources.normalize_stock_code(value)
                except Exception:
                    return
                if (
                    data_sources.is_hk_stock_code(normalized_value)
                    or data_sources.is_us_stock_code(normalized_value)
                ) and normalized_value not in candidates:
                    candidates.append(normalized_value)

            add(raw)
            upper = raw.upper()
            digits = re.sub(r"\D", "", raw)
            if (
                re.fullmatch(r"\d{1,5}", raw)
                or upper.endswith(".HK")
                or upper.startswith(("HK", "HK."))
            ) and digits and len(digits) <= 5:
                add(f"hk{digits.zfill(5)}")
                add(f"{digits.zfill(5)}.HK")
            if (
                (re.fullmatch(r"[A-Za-z.]{1,10}", raw) and not upper.endswith(".US"))
                or upper.startswith(("US", "US."))
            ):
                symbol = re.sub(r"(?i)^US\.?", "", raw).upper()
                if symbol.endswith(".US"):
                    symbol = symbol[:-3]
                if symbol:
                    add(f"us{symbol}")
            return [
                code
                for code in candidates
                if data_sources.equity_market(code) == market_code
            ]

        def append_external_equity_results(res: list[dict], raw_query: str) -> list[dict]:
            existing = {str(item.get("code") or "") for item in res}
            all_candidates = external_equity_candidates(raw_query)
            candidates = [code for code in all_candidates if code not in existing]
            if not candidates:
                return prioritize_external_equity_results(res, raw_query, all_candidates)
            try:
                quotes = data_sources.fetch_tencent_fundamentals(candidates)
                for code in candidates:
                    item = quotes.get(code) or {}
                    name = item.get("name") or code
                    price = data_sources.safe_float(item.get("price"))
                    if not name and price is None:
                        continue
                    board = item.get("board") or data_sources.infer_listing_board(code)
                    res.append(
                        {
                            "code": code,
                            "name": name,
                            "full_code": normalize_full_code(code),
                            "industry": "",
                            "sector": "",
                            "board": board,
                            "exchange": item.get("exchange")
                            or data_sources.infer_exchange(code, market=market_code),
                            "currency": item.get("currency")
                            or data_sources.market_currency(market_code),
                            "area": board,
                            "pe_ratio": item.get("pe_ratio"),
                            "pb_ratio": item.get("pb_ratio"),
                            "market_cap": normalize_market_cap_yi(item.get("market_cap")),
                            "circulating_market_cap": normalize_market_cap_yi(
                                item.get("circulating_market_cap")
                            ),
                            "roe": None,
                            "asset_type": data_sources.infer_asset_type(code, name, board),
                            "source": "tencent.quote",
                            "market": market_code,
                        }
                    )
            except Exception as exc:
                print(f"港美股搜索兜底失败: {exc}")
                return res
            return prioritize_external_equity_results(res, raw_query, all_candidates)

        def prioritize_external_equity_results(
            res: list[dict], raw_query: str, candidates: list[str]
        ) -> list[dict]:
            raw = str(raw_query or "").strip()
            upper = raw.upper()
            prefer_external = (
                re.fullmatch(r"\d{1,5}", raw) is not None
                or upper.endswith(".HK")
                or upper.startswith(("HK", "HK."))
                or upper.startswith(("US", "US."))
                or re.fullmatch(r"[A-Za-z.]{1,10}", raw) is not None
            )
            if not prefer_external or not candidates:
                return res
            order = {code: idx for idx, code in enumerate(candidates)}
            return sorted(
                res,
                key=lambda item: (
                    0 if str(item.get("code") or "") in order else 1,
                    order.get(str(item.get("code") or ""), 999),
                ),
            )

        # 简单的模糊查询
        # 注意: 数据库中名称可能存在乱码，暂时优先保证代码查询
        stocks = (
            db.query(Stock)
            .filter(
                _stock_market_condition(market_code),
                _stock_data_available_condition(),
                (Stock.code.like(f"%{query}%")) | (Stock.name.like(f"%{query}%")),
            )
            .limit(20)
            .all()
        )
        print(f"搜索结果: {len(stocks)} 条")

        res = []
        for s in stocks:
            name = s.name
            # 尝试简单修复或占位
            if not name:
                name = "未知"
            res.append(
                {
                    "code": s.code,
                    "name": name,
                    "full_code": normalize_full_code(s.code),
                    "industry": s.industry or "",
                    "sector": s.sector or "",
                    "board": s.board or "",
                    "exchange": s.exchange
                    or data_sources.infer_exchange(s.code, market=market_code),
                    "currency": s.currency
                    or data_sources.market_currency(market_code),
                    "area": s.area or "",
                    "pe_ratio": s.pe_ratio,
                    "pb_ratio": s.pb_ratio,
                    "market_cap": s.market_cap,
                    "circulating_market_cap": s.circulating_market_cap,
                    "roe": s.roe,
                    "asset_type": data_sources.infer_asset_type(
                        s.code, s.name, s.board, s.asset_type
                    ),
                    "market": market_code,
                }
            )

        return append_external_equity_results(res, query)[:20]
    except Exception as e:
        print(f"搜索出错: {e}")
        return []


@app.get("/api/factors/presets", dependencies=[Depends(require_permission("screener.use"))])
def list_factor_presets(
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    rows = db.query(FactorPreset).order_by(desc(FactorPreset.updated_at)).all()
    result = []
    is_admin = normalize_user_role(current_user.role) == "admin"
    for row in rows:
        config = json.loads(row.config_json or "[]")
        if not is_admin:
            config = [
                item
                for item in config
                if str(item.get("factor") or "") not in ADMIN_ONLY_BUILTIN_FACTOR_KEYS
            ]
            if not config:
                continue
        result.append(
            {
                "id": row.id,
                "name": row.name,
                "config": config,
                "updated_at": row.updated_at.isoformat() if row.updated_at else None,
            }
        )
    return result


@app.post("/api/factors/presets", dependencies=[Depends(require_permission("screener.use"))])
def save_factor_preset(
    payload: FactorPresetSaveRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    name = (payload.name or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="preset name 不能为空")
    requested_admin_factors = sorted(
        {
            item.factor
            for item in payload.config
            if item.factor in ADMIN_ONLY_BUILTIN_FACTOR_KEYS
        }
    )
    if requested_admin_factors and normalize_user_role(current_user.role) != "admin":
        raise HTTPException(status_code=403, detail="系统内置因子组合仅供系统管理员保存")

    config_json = json.dumps(
        [model_to_jsonable(item) for item in payload.config], ensure_ascii=False
    )
    row = db.query(FactorPreset).filter(FactorPreset.name == name).first()
    if row:
        row.config_json = config_json
    else:
        row = FactorPreset(
            id=get_next_table_id(db, FactorPreset), name=name, config_json=config_json
        )
        db.add(row)
    db.commit()
    db.refresh(row)
    return {"id": row.id, "name": row.name, "config": payload.config}


@app.get("/api/factors/presets/{preset_id}", dependencies=[Depends(require_permission("screener.use"))])
def get_factor_preset(
    preset_id: int,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    row = db.query(FactorPreset).filter(FactorPreset.id == preset_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="preset not found")
    config = json.loads(row.config_json or "[]")
    if normalize_user_role(current_user.role) != "admin":
        config = [
            item
            for item in config
            if str(item.get("factor") or "") not in ADMIN_ONLY_BUILTIN_FACTOR_KEYS
        ]
        if not config:
            raise HTTPException(status_code=404, detail="preset not found")
    return {
        "id": row.id,
        "name": row.name,
        "config": config,
        "updated_at": row.updated_at.isoformat() if row.updated_at else None,
    }


def _execute_screener_query(
    payload: ScreenerQueryRequest,
    db: Session,
    current_user: UserModel,
):
    requested_admin_factors = sorted(
        {
            item.factor
            for item in payload.factors or []
            if item.factor in ADMIN_ONLY_BUILTIN_FACTOR_KEYS
        }
    )
    if requested_admin_factors and normalize_user_role(current_user.role) != "admin":
        raise HTTPException(status_code=403, detail="所选系统内置因子仅供系统管理员使用")
    # 支持历史日期回填：若指定 date 则用该日期，否则用最新日期
    target_date = None
    if payload.date:
        try:
            target_date = datetime.strptime(payload.date, "%Y-%m-%d").date()
        except Exception:
            target_date = None

    market_code = _normalize_market_code(payload.market)
    effective_date_query = (
        db.query(func.max(DailyPrice.date))
        .join(Stock, Stock.code == DailyPrice.stock_code)
        .filter(_stock_market_condition(market_code), _stock_data_available_condition())
    )
    if target_date:
        effective_date_query = effective_date_query.filter(DailyPrice.date <= target_date)
    effective_date = effective_date_query.scalar()
    effective_date_text = effective_date.isoformat() if effective_date else None

    cache_payload = model_to_jsonable(payload)
    cache_payload["effective_trading_date"] = effective_date_text
    cache_payload["data_revision"] = db.query(func.max(DailyPrice.id)).scalar() or 0
    cache_payload["cache_version"] = "screener-query-v4"
    cache_hash = hashlib.sha256(
        json.dumps(
            cache_payload,
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        ).encode("utf-8")
    ).hexdigest()
    cache_key = f"screener:query:{cache_hash}"
    cached = cache_get(cache_key)
    if cached:
        try:
            cached_data = json.loads(cached)
            cached_data["cache"] = {
                **(cached_data.get("cache") or {}),
                "hit": True,
                "effective_trading_date": effective_date_text,
            }
            return cached_data
        except Exception:
            pass

    if target_date:
        date_sq = (
            db.query(
                DailyPrice.stock_code.label("stock_code"),
                func.max(DailyPrice.date).label("latest_date"),
            )
            .join(Stock, Stock.code == DailyPrice.stock_code)
            .filter(_stock_market_condition(market_code), _stock_data_available_condition())
            .filter(DailyPrice.date <= target_date)
            .group_by(DailyPrice.stock_code)
            .subquery()
        )
    else:
        date_sq = latest_daily_subquery(db)
    latest_sq = date_sq
    factor_map = normalize_factor_map(payload.factors)

    query = (
        db.query(
            Stock.code.label("code"),
            Stock.name.label("name"),
            Stock.industry.label("industry"),
            Stock.sector.label("sector"),
            Stock.concepts_json.label("concepts_json"),
            Stock.board.label("board"),
            Stock.exchange.label("exchange"),
            Stock.currency.label("currency"),
            Stock.area.label("area"),
            Stock.pe_ratio.label("pe_ratio"),
            Stock.pb_ratio.label("pb_ratio"),
            Stock.market_cap.label("market_cap"),
            Stock.circulating_market_cap.label("circulating_market_cap"),
            Stock.roe.label("roe"),
            DailyPrice.open.label("open"),
            DailyPrice.close.label("close"),
            DailyPrice.high.label("high"),
            DailyPrice.low.label("low"),
            DailyPrice.volume.label("volume"),
            DailyPrice.amount.label("amount"),
            DailyPrice.amplitude.label("amplitude"),
            DailyPrice.change_pct.label("change_pct_cached"),
            DailyPrice.change_amount.label("change_amount"),
            DailyPrice.turnover_rate.label("turnover_rate"),
            DailyPrice.ma60.label("ma60"),
            DailyPrice.date.label("date"),
        )
        .join(latest_sq, latest_sq.c.stock_code == Stock.code)
        .join(
            DailyPrice,
            and_(
                DailyPrice.stock_code == latest_sq.c.stock_code,
                DailyPrice.date == latest_sq.c.latest_date,
            ),
        )
    )
    query = query.filter(_stock_market_condition(market_code), _stock_data_available_condition())

    keyword = (payload.keyword or "").strip()
    if keyword:
        query = query.filter(
            (Stock.code.ilike(f"%{keyword}%")) | (Stock.name.ilike(f"%{keyword}%"))
        )

    if "price" in factor_map:
        cfg = factor_map["price"]
        pmin = cfg.get("min")
        # value 语义：最高价上限（close ≤ value）
        pmax = cfg.get("max") if cfg.get("max") is not None else cfg.get("value")
        if pmin is not None:
            query = query.filter(DailyPrice.close >= pmin)
        if pmax is not None:
            query = query.filter(DailyPrice.close <= pmax)

    if "volume" in factor_map:
        cfg = factor_map["volume"]
        # 前端单位：万手；value 兼容旧预设，语义为最低成交量下限。
        raw_vmin = cfg.get("min") if cfg.get("min") is not None else cfg.get("value")
        raw_vmax = cfg.get("max")
        vmin = raw_vmin * 10000 if raw_vmin is not None else None
        vmax = raw_vmax * 10000 if raw_vmax is not None else None
        if vmin is not None:
            query = query.filter(DailyPrice.volume >= vmin)
        if vmax is not None:
            query = query.filter(DailyPrice.volume <= vmax)

    if "ma60_gap" in factor_map:
        cfg = factor_map["ma60_gap"]
        # 同时兼容 max 和 max_deviation 键名
        gap_max = cfg.get("max") if cfg.get("max") is not None else cfg.get("max_deviation")
        gap_max = normalize_percent_threshold(gap_max)
        if gap_max is not None:
            ma_expr = func.coalesce(DailyPrice.ma60, DailyPrice.close)
            gap_expr = (
                func.abs((DailyPrice.close - ma_expr) / func.nullif(ma_expr, 0)) * 100.0
            )
            query = query.filter(gap_expr <= gap_max)

    raw_rows = query.limit(max(10000, payload.offset + payload.limit)).all()
    advanced_screen_params = build_advanced_screen_params(factor_map, payload.logic)
    enabled_advanced_conditions = advanced_screen_params.get("enabled_conditions", [])
    advanced_target_date = None
    if payload.date:
        try:
            advanced_target_date = datetime.strptime(payload.date, "%Y-%m-%d").date()
        except Exception:
            advanced_target_date = None
    custom_factor_specs: List[Dict[str, object]] = []
    for inline_factor in payload.inline_factors or []:
        custom_factor_specs.append(
            {
                "name": inline_factor.name or "inline_factor",
                "expression": inline_factor.expression,
                "params": inline_factor.params or {},
                "output_type": inline_factor.output_type or "scalar",
                "filter_min": inline_factor.filter_min,
                "filter_max": inline_factor.filter_max,
            }
        )
    for factor_config in payload.factors or []:
        if not factor_config.factor.startswith("custom:"):
            continue
        factor_name = factor_config.factor.replace("custom:", "", 1)
        custom_factor_query = db.query(CustomFactorModel).filter(
            CustomFactorModel.name == factor_name
        )
        if normalize_user_role(current_user.role) == "admin":
            custom_factor_query = custom_factor_query.filter(
                or_(
                    CustomFactorModel.user_id.is_(None),
                    CustomFactorModel.user_id == current_user.id,
                )
            )
        else:
            custom_factor_query = custom_factor_query.filter(
                CustomFactorModel.user_id == current_user.id,
                CustomFactorModel.is_builtin != 1,
            )
        cf = custom_factor_query.first()
        if not cf:
            continue
        params = factor_items_to_dict(factor_config.params)
        filter_min, filter_max = pop_custom_factor_filters(params)
        default_min, default_max = default_filter_bounds(cf.default_filter)
        custom_factor_specs.append(
            {
                "name": cf.display_name or cf.name,
                "expression": cf.expression,
                "params": params,
                "output_type": cf.output_type or "scalar",
                "filter_min": filter_min if filter_min is not None else default_min,
                "filter_max": filter_max if filter_max is not None else default_max,
            }
        )

    needs_history = bool(enabled_advanced_conditions or custom_factor_specs)
    max_history_days = estimate_history_days(
        advanced_screen_params, bool(custom_factor_specs)
    )
    history_cache: Dict[str, pd.DataFrame] = (
        load_screening_histories(
            db,
            list({r.code for r in raw_rows}),
            advanced_target_date,
            max_history_days,
        )
        if needs_history
        else {}
    )

    # 批量获取所有涉及股票的前一日收盘价，用于正确计算涨跌幅。
    # 已加载历史缓存时直接复用缓存，避免再次按日期分组查询数据库。
    prev_close_map: dict = (
        build_prev_close_map_from_history(history_cache, raw_rows)
        if needs_history
        else {}
    )
    if raw_rows and not needs_history:
        # 构建每只股票最新日期的映射 (code -> latest_date)
        stock_latest_date_map: dict = {}
        for r in raw_rows:
            if (
                r.code not in stock_latest_date_map
                or r.date > stock_latest_date_map[r.code]
            ):
                stock_latest_date_map[r.code] = r.date

        # 按最新日期分组，批量查询每组的前一日收盘价
        date_groups: dict = {}
        for code, dt in stock_latest_date_map.items():
            date_groups.setdefault(dt, []).append(code)

        for dt, codes in date_groups.items():
            # 子查询：找到每只股票在 dt 之前最近交易日的日期
            prev_date_sq = (
                db.query(
                    DailyPrice.stock_code.label("stock_code"),
                    func.max(DailyPrice.date).label("prev_date"),
                )
                .filter(
                    DailyPrice.stock_code.in_(codes),
                    DailyPrice.date < dt,
                )
                .group_by(DailyPrice.stock_code)
                .subquery()
            )

            # 根据子查询获取前一日收盘价
            prev_close_rows = (
                db.query(DailyPrice.stock_code, DailyPrice.close)
                .join(
                    prev_date_sq,
                    and_(
                        DailyPrice.stock_code == prev_date_sq.c.stock_code,
                        DailyPrice.date == prev_date_sq.c.prev_date,
                    ),
                )
                .all()
            )

            for pr in prev_close_rows:
                prev_close_map[pr.stock_code] = float(pr.close or 0)

    universe_count = len(raw_rows)
    rows = []
    display_ma_days = int(advanced_screen_params.get("ma_days", 60) or 60)
    for r in raw_rows:
        hist_df = (
            history_cache.get(r.code, pd.DataFrame())
            if needs_history
            else pd.DataFrame()
        )
        if enabled_advanced_conditions:
            if hist_df.empty:
                continue
            advanced_check = screener.check_stock(hist_df, advanced_screen_params)
            if not advanced_check.get("passed"):
                continue
        if custom_factor_specs:
            if hist_df.empty:
                continue
            factor_df = prepare_factor_dataframe(hist_df)
            if factor_df.empty or not all(
                factor_spec_passes(factor_df, spec) for spec in custom_factor_specs
            ):
                continue

        open_price = float(r.open or 0)
        close_price = float(r.close or 0)
        cached_ma = float(r.ma60) if r.ma60 is not None else None
        ma60 = cached_ma or latest_moving_average_from_history(
            hist_df, display_ma_days
        ) or close_price or 1
        volume = float(r.volume or 0)
        prev_close = prev_close_map.get(r.code, 0)  # 无前日收盘价则涨跌幅为0
        change_pct = (
            ((close_price - prev_close) / prev_close * 100.0) if prev_close else 0.0
        )
        ma_gap_pct = abs((close_price - ma60) / ma60 * 100.0) if ma60 else 0.0

        pe_ratio = float(r.pe_ratio) if r.pe_ratio is not None else None
        pb_ratio = float(r.pb_ratio) if r.pb_ratio is not None else None
        roe_pct = float(r.roe) if r.roe is not None else None
        market_cap_yi = normalize_market_cap_yi(r.market_cap)
        circulating_market_cap_yi = normalize_market_cap_yi(
            r.circulating_market_cap
        )
        board = r.board or data_sources.infer_listing_board(r.code)
        concepts = _stock_concept_names(r.concepts_json)
        concept_board = " / ".join(concepts[:3]) or r.sector or ""

        if "market_cap" in factor_map:
            if market_cap_yi is None:
                continue
            cfg = factor_map["market_cap"]
            cap_min = cfg.get("min")
            # 前端单位为“亿”；value 兼容旧单值配置，语义为最高市值上限。
            cap_max = cfg.get("max") if cfg.get("max") is not None else cfg.get("value")
            if cap_min is not None and market_cap_yi < cap_min:
                continue
            if cap_max is not None and market_cap_yi > cap_max:
                continue

        if "pe_ratio" in factor_map:
            if pe_ratio is None:
                continue
            cfg = factor_map["pe_ratio"]
            pe_min = cfg.get("min")
            # value 语义：最高 PE 上限（pe ≤ value）
            pe_max = cfg.get("max") if cfg.get("max") is not None else cfg.get("value")
            if pe_min is not None and pe_ratio < pe_min:
                continue
            if pe_max is not None and pe_ratio > pe_max:
                continue

        if "pb_ratio" in factor_map:
            if pb_ratio is None:
                continue
            cfg = factor_map["pb_ratio"]
            pb_min = cfg.get("min")
            # value 语义：最高 PB 上限（pb ≤ value）
            pb_max = cfg.get("max") if cfg.get("max") is not None else cfg.get("value")
            if pb_min is not None and pb_ratio < pb_min:
                continue
            if pb_max is not None and pb_ratio > pb_max:
                continue

        if "roe" in factor_map:
            if roe_pct is None:
                continue
            cfg = factor_map["roe"]
            # value 语义：最低 ROE 下限（roe ≥ value）
            roe_min = cfg.get("min") if cfg.get("min") is not None else cfg.get("value")
            roe_min = normalize_percent_threshold(roe_min)
            roe_max = cfg.get("max")
            roe_max = normalize_percent_threshold(roe_max)
            if roe_min is not None and roe_pct < roe_min:
                continue
            if roe_max is not None and roe_pct > roe_max:
                continue

        score = (
            (100.0 - min(100.0, ma_gap_pct)) * 0.3
            + max(-20.0, min(20.0, change_pct)) * 1.5
            + min(100.0, volume / 1_000_000.0) * 0.4
        )

        rows.append(
            {
                "code": r.code,
                "name": r.name,
                "industry": r.industry,
                "sector": r.sector,
                "concepts": concepts,
                "concept_board": concept_board,
                "board": board,
                "exchange": r.exchange
                or data_sources.infer_exchange(r.code, market=market_code),
                "currency": r.currency
                or data_sources.market_currency(market_code),
                "market": market_code,
                "area": r.area,
                "price": round(close_price, 2),
                "open": round(open_price, 2),
                "high": round(float(r.high or 0), 2),
                "low": round(float(r.low or 0), 2),
                "volume": int(volume),
                "amount": round(float(r.amount or 0), 2),
                "amplitude": round(float(r.amplitude or 0), 2),
                "turnover_rate": round(float(r.turnover_rate or 0), 2),
                "market_cap": round(market_cap_yi, 2) if market_cap_yi is not None else None,
                "circulating_market_cap": (
                    round(circulating_market_cap_yi, 2)
                    if circulating_market_cap_yi is not None
                    else None
                ),
                "ma60": round(ma60, 2),
                "change_pct": round(change_pct, 2),
                "change_amount": round(float(r.change_amount or 0), 2),
                "pe_ratio": round(pe_ratio, 2) if pe_ratio is not None else None,
                "pb_ratio": round(pb_ratio, 2) if pb_ratio is not None else None,
                "roe_pct": round(roe_pct, 2) if roe_pct is not None else None,
                "score": round(score, 2),
                "date": r.date.isoformat() if r.date else None,
            }
        )

    sort_by = (payload.sort_by or "score").lower()
    sort_order = (payload.sort_order or "desc").lower()
    reverse = sort_order != "asc"
    if sort_by in {"score", "price", "volume", "change_pct", "pe_ratio", "roe_pct", "market_cap"}:
        rows.sort(
            key=lambda x: x.get(sort_by) if x.get(sort_by) is not None else 0,
            reverse=reverse,
        )
    elif sort_by in {"code", "name"}:
        rows.sort(key=lambda x: x.get(sort_by) or "", reverse=reverse)

    total = len(rows)
    # 计算 score 百分位排名（0-100）
    if total > 1:
        scores = [r["score"] for r in rows]
        min_s, max_s = min(scores), max(scores)
        rng = max_s - min_s or 1
        for r in rows:
            r["score_pct"] = round((r["score"] - min_s) / rng * 100, 1)
    else:
        for r in rows:
            r["score_pct"] = 50.0
    offset = max(0, payload.offset)
    limit = max(1, min(500, payload.limit))
    page_rows = rows[offset : offset + limit]

    response = {
        "market": market_code,
        "total": total,
        "universe_count": universe_count,
        "hit_rate": round(total / universe_count, 6) if universe_count else 0,
        "offset": offset,
        "limit": limit,
        "date": effective_date_text,
        "rows": page_rows,
        "cache": {
            "hit": False,
            "effective_trading_date": effective_date_text,
        },
    }
    cache_ttl = 1800
    if effective_date and effective_date < datetime.now().date():
        cache_ttl = 24 * 60 * 60
    cache_set(
        cache_key,
        json.dumps(response, ensure_ascii=False, default=str),
        ex=cache_ttl,
    )
    return response


