def _serialize_screener_task(task: ScreenerTask) -> dict:
    result = _json_loads_or(task.result_json, {})
    request_payload = _json_loads_or(task.request_json, {})
    return {
        "task_id": task.id,
        "user_id": task.user_id,
        "market": task.market or "CN",
        "status": task.status,
        "requested_date": task.requested_date,
        "effective_date": task.effective_date,
        "request": request_payload if isinstance(request_payload, dict) else {},
        "result": result if isinstance(result, dict) else {},
        "error": task.error or "",
        "queue_status": task.queue_status or "inline",
        "attempt_count": int(task.attempt_count or 0),
        "failure_class": task.failure_class or "",
        "created_at": task.created_at.isoformat() if task.created_at else None,
        "updated_at": task.updated_at.isoformat() if task.updated_at else None,
    }


def _run_screener_task(task_id: int, user_id: int, payload_data: dict) -> dict:
    db = SessionLocal()
    try:
        task = (
            db.query(ScreenerTask)
            .filter(ScreenerTask.id == task_id, ScreenerTask.user_id == user_id)
            .first()
        )
        if not task:
            return {"status": "missing", "system_failure": False}
        if task.status == "done":
            return {"status": "done", "system_failure": False}
        task.status = "running"
        db.commit()
        payload = ScreenerQueryRequest(**payload_data)
        user = db.query(UserModel).filter(UserModel.id == user_id).first()
        if not user:
            raise ValueError("筛选任务所属用户不存在")
        result = _execute_screener_query(
            payload,
            db,
            user,
        )
        task.status = "done"
        task.result_json = json.dumps(result, ensure_ascii=False, default=str)
        task.effective_date = str(result.get("date") or "")
        task.error = ""
        db.commit()
        return {"status": "done", "system_failure": False}
    except Exception as exc:
        db.rollback()
        task = (
            db.query(ScreenerTask)
            .filter(ScreenerTask.id == task_id, ScreenerTask.user_id == user_id)
            .first()
        )
        if task:
            task.status = "failed"
            task.error = _assistant_sanitize_error(exc)
            db.commit()
        return {
            "status": "failed",
            "system_failure": True,
            "failure_class": "screening_error",
        }
    finally:
        db.close()


@app.post("/api/screener/tasks", dependencies=[Depends(require_permission("screener.use"))])
def create_screener_task(
    payload: ScreenerQueryRequest,
    background_tasks: BackgroundTasks,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    request_data = model_to_jsonable(payload)
    use_durable_queue = bool(queue_enabled())
    if use_durable_queue:
        if not broker_ready():
            raise HTTPException(
                status_code=503,
                detail={
                    "code": "TASK_QUEUE_UNAVAILABLE",
                    "message": "后台任务队列暂不可用，请稍后重试",
                },
            )
        _lock_long_task_admission(db)
        queue_depth = _long_task_queue_depth(db)
        if queue_depth >= QUEUE_MAX_PENDING:
            raise HTTPException(
                status_code=429,
                detail={
                    "code": "TASK_QUEUE_FULL",
                    "message": "后台任务队列已满，请等待已有任务完成",
                    "queue_depth": queue_depth,
                    "queue_limit": QUEUE_MAX_PENDING,
                },
            )
    queue_payload = {
        "user_id": current_user.id,
        "payload": request_data,
    }
    task = ScreenerTask(
        user_id=current_user.id,
        market=_normalize_market_code(payload.market),
        status="pending",
        request_json=json.dumps(request_data, ensure_ascii=False, default=str),
        requested_date=payload.date or "",
        queue_payload_json=json.dumps(queue_payload, ensure_ascii=False, default=str),
        queue_status="queued" if use_durable_queue else "inline",
        queue_priority=queue_priority_for_role(current_user.role),
    )
    db.add(task)
    db.commit()
    db.refresh(task)
    task.queue_payload_json = json.dumps(
        {"task_id": task.id, **queue_payload},
        ensure_ascii=False,
        default=str,
    )
    db.commit()
    if use_durable_queue:
        try:
            task.queue_task_id = enqueue_named_task(
                "quantsys.screener",
                {"task_id": task.id, **queue_payload},
                queue="long_tasks",
                priority=_celery_priority_for_user(current_user),
            )
            db.commit()
        except Exception as exc:
            db.rollback()
            task = db.query(ScreenerTask).filter(ScreenerTask.id == task.id).first()
            if task:
                task.status = "failed"
                task.queue_status = "failed"
                task.failure_class = "queue_submit_error"
                task.error = "后台任务提交失败，请稍后重试"
                task.finished_at = datetime.now(timezone.utc)
                db.commit()
            raise HTTPException(
                status_code=503,
                detail={
                    "code": "TASK_QUEUE_SUBMIT_FAILED",
                    "message": "后台任务提交失败，请稍后重试",
                },
            ) from exc
    else:
        background_tasks.add_task(
            _run_screener_task,
            task.id,
            current_user.id,
            request_data,
        )
    return _serialize_screener_task(task)


