def _market_index_by_code(code: str) -> Optional[dict]:
    normalized = (code or "").strip().lower()
    digits = "".join(ch for ch in normalized if ch.isdigit())
    for item in MARKET_INDEX_CATALOG:
        aliases = [item["code"], *(item.get("aliases") or [])]
        if normalized in {str(alias).lower() for alias in aliases}:
            return item
        item_digits = "".join(ch for ch in item["code"] if ch.isdigit())
        if digits and item_digits and digits == item_digits:
            return item
    return None


def _parse_tencent_index_quotes(symbols: list[str]) -> dict[str, dict]:
    if not symbols:
        return {}
    response = requests.get(
        data_sources.TENCENT_QUOTE_URL.format(symbols=",".join(symbols)),
        timeout=4,
        headers={"User-Agent": "Mozilla/5.0"},
    )
    response.encoding = "gbk"
    quotes: dict[str, dict] = {}
    for match in re.finditer(r'v_([A-Za-z]{2}[A-Za-z0-9.]+)="([^"]*)"', response.text):
        symbol = match.group(1).lower()
        fields = match.group(2).split("~")
        close = data_sources.safe_float(fields[3] if len(fields) > 3 else None)
        prev_close = data_sources.safe_float(fields[4] if len(fields) > 4 else None)
        change_pct = data_sources.safe_float(fields[32] if len(fields) > 32 else None)
        if change_pct is None and close is not None and prev_close:
            change_pct = (close - prev_close) / prev_close * 100
        trade_time = fields[30] if len(fields) > 30 else ""
        quotes[symbol] = {
            "name": fields[1] if len(fields) > 1 else "",
            "close": close,
            "change_pct": change_pct,
            "date": trade_time[:10].replace("/", "-") if trade_time else "",
            "source": "tencent.quote",
        }
    return quotes


def _fetch_eastmoney_index_spot_quote(index_meta: dict) -> Optional[dict]:
    fs = index_meta.get("em_spot_fs")
    if not fs:
        return None
    target_code = "".join(ch for ch in index_meta["code"] if ch.isdigit())
    session = requests.Session()
    session.trust_env = False
    params = {
        "pz": "100",
        "po": "1",
        "np": "1",
        "ut": "bd1d9ddb04089700cf9c27f6f7426281",
        "fltt": "2",
        "invt": "2",
        "fid": "f12",
        "fs": fs,
        "fields": "f2,f3,f4,f5,f6,f7,f12,f14,f15,f16,f17,f18",
    }
    preferred_page = int(index_meta.get("em_spot_page") or 1)
    pages = [preferred_page] + [
        page for page in range(1, 7) if page != preferred_page
    ]
    for page in pages:
        params["pn"] = str(page)
        response = session.get(
            "http://48.push2.eastmoney.com/api/qt/clist/get",
            params=params,
            timeout=6,
            headers={"User-Agent": "Mozilla/5.0"},
        )
        response.raise_for_status()
        rows = ((response.json().get("data") or {}).get("diff") or [])
        for row in rows:
            if str(row.get("f12") or "").zfill(6) != target_code:
                continue
            close = data_sources.safe_float(row.get("f2"))
            change_pct = data_sources.safe_float(row.get("f3"))
            if close is None:
                return None
            return {
                "name": str(row.get("f14") or index_meta["name"]),
                "close": close,
                "change_pct": change_pct or 0,
                "date": datetime.now().date().isoformat(),
                "source": "eastmoney.index_spot",
            }
    return None


def _fetch_em_index_daily(index_meta: dict, days: int = 45) -> tuple[pd.DataFrame, Optional[str]]:
    if index_meta.get("market") != "CN":
        return pd.DataFrame(), "eastmoney CN index adapter not used for this market"
    end_date = datetime.now().date()
    start_date = end_date - timedelta(days=max(days * 2, 45))
    symbol = index_meta.get("em_daily_symbol") or index_meta["code"]

    def _load():
        return ak.stock_zh_index_daily_em(
            symbol=symbol,
            start_date=start_date.strftime("%Y%m%d"),
            end_date=end_date.strftime("%Y%m%d"),
        )

    df, error = _call_with_timeout(_load, 5.5)
    if error or df is None or getattr(df, "empty", True):
        return pd.DataFrame(), error or "empty eastmoney index daily"
    return df, None


def _history_rows_from_index_df(df: pd.DataFrame) -> list[list]:
    if df is None or df.empty:
        return []
    date_col = _pick_df_column(df, ["date", "日期"])
    open_col = _pick_df_column(df, ["open", "开盘"])
    close_col = _pick_df_column(df, ["close", "收盘"])
    high_col = _pick_df_column(df, ["high", "最高"])
    low_col = _pick_df_column(df, ["low", "最低"])
    volume_col = _pick_df_column(df, ["volume", "成交量"])
    if not all([date_col, open_col, close_col, high_col, low_col]):
        return []
    rows = []
    for _, row in df.iterrows():
        dt = row.get(date_col)
        date_text = dt.strftime("%Y-%m-%d") if hasattr(dt, "strftime") else str(dt)[:10]
        open_value = data_sources.safe_float(row.get(open_col))
        close_value = data_sources.safe_float(row.get(close_col))
        high_value = data_sources.safe_float(row.get(high_col))
        low_value = data_sources.safe_float(row.get(low_col))
        volume_value = data_sources.safe_float(row.get(volume_col)) if volume_col else 0
        if not date_text or not all(
            value is not None and value > 0
            for value in [open_value, close_value, high_value, low_value]
        ):
            continue
        rows.append(
            [
                date_text,
                round(open_value, 4),
                round(close_value, 4),
                round(low_value, 4),
                round(high_value, 4),
                round(volume_value or 0, 2),
            ]
        )
    return rows


def _fetch_tencent_index_history(index_meta: dict, days: int) -> list[list]:
    count = min(max(days * 2 + 30, 80), 1200)
    payload = _request_json(
        data_sources.TENCENT_KLINE_URL,
        params={"param": f"{index_meta['code']},day,,,{count}"},
        headers={"User-Agent": "Mozilla/5.0"},
        timeout=4,
    )
    rows = data_sources.extract_tencent_kline_rows(payload, index_meta["code"])
    data = []
    for item in rows:
        if not isinstance(item, list) or len(item) < 6:
            continue
        open_value = data_sources.safe_float(item[1])
        close_value = data_sources.safe_float(item[2])
        high_value = data_sources.safe_float(item[3])
        low_value = data_sources.safe_float(item[4])
        volume_value = data_sources.safe_float(item[5])
        if not item[0] or not all(
            value is not None and value > 0
            for value in [open_value, close_value, high_value, low_value]
        ):
            continue
        data.append(
            [
                str(item[0])[:10],
                round(open_value, 4),
                round(close_value, 4),
                round(low_value, 4),
                round(high_value, 4),
                round(volume_value or 0, 2),
            ]
        )
    return data[-days:]


def _latest_index_history(index_meta: dict, days: int = 180) -> tuple[list[list], str, Optional[str]]:
    try:
        rows = _fetch_tencent_index_history(index_meta, days)
        if len(rows) >= min(10, max(2, days // 30)):
            return rows, "tencent.index_kline", None
    except Exception as exc:
        tencent_error = str(exc)
    else:
        tencent_error = "empty tencent index kline"

    df, em_error = _fetch_em_index_daily(index_meta, days)
    rows = _history_rows_from_index_df(df)
    if rows:
        return rows[-days:], "eastmoney.index_daily", tencent_error

    ak_error = None
    if index_meta.get("market") == "CN":
        try:
            df, ak_error = _call_with_timeout(
                lambda: ak.stock_zh_index_daily(symbol=index_meta["code"]),
                3.5,
            )
            rows = _history_rows_from_index_df(df)
            if rows:
                return rows[-days:], "akshare.stock_zh_index_daily", tencent_error
        except Exception as exc:
            ak_error = str(exc)
    return [], "fallback.empty", "; ".join(
        item
        for item in [
            f"tencent:{tencent_error}" if tencent_error else "",
            f"eastmoney:{em_error}" if em_error else "",
            f"akshare:{ak_error}" if "ak_error" in locals() and ak_error else "",
        ]
        if item
    ) or None


def _fallback_index_constituents_from_db(
    index_meta: dict,
    limit: int,
    db: Session,
) -> list[dict]:
    latest_subq = (
        db.query(
            DailyPrice.stock_code.label("stock_code"),
            func.max(DailyPrice.date).label("latest_date"),
        )
        .group_by(DailyPrice.stock_code)
        .subquery()
    )
    query = (
        db.query(Stock, DailyPrice)
        .join(latest_subq, latest_subq.c.stock_code == Stock.code)
        .join(
            DailyPrice,
            and_(
                DailyPrice.stock_code == Stock.code,
                DailyPrice.date == latest_subq.c.latest_date,
            ),
        )
    )
    query = query.filter(_stock_market_condition(index_meta.get("market")))
    scope = index_meta.get("fallback_scope")
    if scope == "sh_main":
        query = query.filter(Stock.code.like("6%"))
    elif scope == "sz_main":
        query = query.filter(or_(Stock.code.like("0%"), Stock.code.like("3%")))
    elif scope == "chinext":
        query = query.filter(or_(Stock.code.like("300%"), Stock.code.like("301%")))
    elif scope == "bse":
        query = query.filter(
            or_(
                Stock.board == "北交所",
                Stock.code.like("8%"),
                Stock.code.like("4%"),
                Stock.code.like("920%"),
            )
        )
    elif scope == "star50":
        query = query.filter(or_(Stock.board == "科创板", Stock.code.like("688%")))
    rows = (
        query.filter(Stock.market_cap.isnot(None)).order_by(Stock.market_cap.asc()).limit(limit).all()
        if index_meta["code"] == "sh932000"
        else query.order_by(desc(Stock.market_cap.isnot(None)), desc(Stock.market_cap))
        .limit(limit)
        .all()
    )
    result = []
    for stock, price in rows:
        change_pct = price.change_pct
        if change_pct is None and price.close and price.open:
            change_pct = (price.close - price.open) / price.open * 100
        result.append(
            {
                "code": stock.code,
                "name": stock.name,
                "exchange": stock.board or data_sources.infer_listing_board(stock.code),
                "industry": stock.industry or "",
                "board": stock.board or data_sources.infer_listing_board(stock.code),
                "weight": None,
                "price": round(float(price.close or 0), 2),
                "change_pct": round(float(change_pct or 0), 2),
                "volume": round(float(price.volume or 0), 2),
                "amount": round(float(price.amount or 0), 2),
                "turnover_rate": round(float(price.turnover_rate or 0), 2),
                "amplitude": round(float(price.amplitude or 0), 2),
                "pe_ratio": (
                    round(float(stock.pe_ratio), 2)
                    if stock.pe_ratio is not None
                    else None
                ),
                "pb_ratio": (
                    round(float(stock.pb_ratio), 2)
                    if stock.pb_ratio is not None
                    else None
                ),
                "market_cap": normalize_market_cap_yi(stock.market_cap),
                "date": str(price.date) if price.date else "",
                "source": "database.latest_daily",
            }
        )
    return result


def _get_market_indices_uncached(market: str = "CN"):
    """获取主要市场指数。腾讯实时优先，缺失时使用东财/akshare日线兜底。"""
    market_code = _normalize_market_code(market)
    market_catalog = [
        item for item in MARKET_INDEX_CATALOG if item.get("market") == market_code
    ]
    cache_key = f"market:indices:v3:{market_code}"
    cached = cache_get(cache_key)
    if cached:
        try:
            return json.loads(cached)
        except Exception:
            pass

    tencent_symbols = [
        item["code"]
        for item in market_catalog
        if item["code"] != "sh932000"
    ]
    try:
        tencent_quotes = _parse_tencent_index_quotes(tencent_symbols)
    except Exception:
        tencent_quotes = {}

    result = []
    for idx in market_catalog:
        quote = tencent_quotes.get(idx["code"].lower())
        error = None
        if not quote:
            try:
                quote = _fetch_eastmoney_index_spot_quote(idx)
            except Exception as exc:
                error = f"eastmoney.index_spot:{exc}"
        if not quote:
            rows, source, error = _latest_index_history(idx, days=8)
            if rows:
                last = rows[-1]
                prev = rows[-2] if len(rows) > 1 else last
                close = data_sources.safe_float(last[2])
                prev_close = data_sources.safe_float(prev[2])
                quote = {
                    "close": close,
                    "change_pct": (
                        (close - prev_close) / prev_close * 100
                        if close is not None and prev_close
                        else 0
                    ),
                    "date": str(last[0]),
                    "source": source,
                }
        result.append(
            {
                "code": idx["code"],
                "name": idx["name"],
                "name_en": idx.get("name_en") or idx["name"],
                "market": idx.get("market") or market_code,
                "currency": idx.get("currency") or "CNY",
                "primary": bool(idx.get("primary", True)),
                "close": round(float((quote or {}).get("close") or 0), 2),
                "change_pct": round(float((quote or {}).get("change_pct") or 0), 2),
                "date": str((quote or {}).get("date") or ""),
                "source": (quote or {}).get("source") or "fallback.empty",
                **({"error": error} if error else {}),
            }
        )
    serialized = json.dumps(result, ensure_ascii=False, default=str)
    cache_set(cache_key, serialized, ex=45)
    cache_set(f"{cache_key}:stale", serialized, ex=900)
    return result


@app.get("/api/market/indices", dependencies=[Depends(require_permission("dashboard.view"))])
def get_market_indices(market: str = "CN"):
    market_code = _normalize_market_code(market)
    cache_key = f"market:indices:v3:{market_code}"
    cached = cache_get(cache_key)
    if cached:
        try:
            return json.loads(cached)
        except Exception:
            cache_delete(cache_key)
    with cache_backend.lock(cache_key, timeout=20) as acquired:
        if not acquired:
            stale = cache_get(f"{cache_key}:stale")
            if stale:
                try:
                    payload = json.loads(stale)
                    for item in payload if isinstance(payload, list) else []:
                        if isinstance(item, dict):
                            item["stale"] = True
                    return payload
                except Exception:
                    pass
            filled = cache_backend.wait_for_value(cache_key, timeout=1.5)
            if filled:
                return json.loads(filled)
            raise HTTPException(status_code=503, detail="指数行情正在刷新，请稍后重试")
        # A request may have filled the cache while this process waited for the
        # distributed lock.
        cached = cache_get(cache_key)
        if cached:
            try:
                return json.loads(cached)
            except Exception:
                pass
        return _get_market_indices_uncached(market_code)


@app.get("/api/market/index-history", dependencies=[Depends(require_permission("dashboard.view"))])
def get_market_index_history(code: str, days: int = 180):
    index_meta = _market_index_by_code(code)
    if not index_meta:
        raise HTTPException(status_code=404, detail="指数代码不存在")
    days = max(30, min(int(days or 180), 750))
    cache_key = f"market:index-history:{index_meta['code']}:{days}"
    cached = cache_get(cache_key)
    if cached:
        try:
            return json.loads(cached)
        except Exception:
            pass
    rows, source, error = _latest_index_history(index_meta, days=days)
    payload = {
        "code": index_meta["code"],
        "name": index_meta["name"],
        "name_en": index_meta.get("name_en") or index_meta["name"],
        "market": index_meta.get("market") or "CN",
        "currency": index_meta.get("currency") or "CNY",
        "source": source,
        "data": rows,
        **({"error": error} if error else {}),
    }
    cache_set(cache_key, json.dumps(payload, ensure_ascii=False, default=str), ex=180)
    return payload


@app.get("/api/market/index-constituents", dependencies=[Depends(require_permission("dashboard.view"))])
def get_market_index_constituents(
    code: str,
    limit: int = 80,
    db: Session = Depends(get_db),
):
    index_meta = _market_index_by_code(code)
    if not index_meta:
        raise HTTPException(status_code=404, detail="指数代码不存在")
    limit = max(10, min(int(limit or 80), 300))
    cache_key = f"market:index-constituents:{index_meta['code']}:{limit}"
    cached = cache_get(cache_key)
    if cached:
        try:
            return json.loads(cached)
        except Exception:
            pass

    items: list[dict] = []
    source = "fallback.empty"
    error = None
    cs_symbol = index_meta.get("cs_symbol")
    if cs_symbol:
        df, error = _call_with_timeout(
            lambda: ak.index_stock_cons_weight_csindex(symbol=cs_symbol),
            12.0,
        )
        if df is not None and not getattr(df, "empty", True):
            code_col = _pick_df_column(df, ["成分券代码", "品种代码", "证券代码", "代码"])
            name_col = _pick_df_column(df, ["成分券名称", "品种名称", "证券简称", "名称"])
            exchange_col = _pick_df_column(df, ["交易所", "市场"])
            weight_col = _pick_df_column(df, ["权重"])
            date_col = _pick_df_column(df, ["日期"])
            if code_col and name_col:
                work_df = df.copy()
                if weight_col:
                    work_df[weight_col] = pd.to_numeric(work_df[weight_col], errors="coerce")
                    work_df = work_df.sort_values(weight_col, ascending=False)
                base_items = []
                for _, row in work_df.head(limit).iterrows():
                    stock_code = data_sources.normalize_stock_code(row.get(code_col))
                    if not data_sources.is_a_share_code(stock_code):
                        continue
                    base_items.append(
                        {
                            "code": stock_code,
                            "name": str(row.get(name_col) or "").strip(),
                            "exchange": str(row.get(exchange_col) or "").strip()
                            if exchange_col
                            else data_sources.infer_listing_board(stock_code),
                            "weight": round(float(row.get(weight_col)), 4)
                            if weight_col and data_sources.safe_float(row.get(weight_col)) is not None
                            else None,
                            "date": str(row.get(date_col)) if date_col else "",
                        }
                    )
                quote_map = data_sources.fetch_tencent_fundamentals(
                    [item["code"] for item in base_items],
                    batch_size=120,
                )
                stock_codes = [item["code"] for item in base_items]
                latest_sq = latest_daily_subquery(db)
                meta_rows = (
                    db.query(
                        Stock.code.label("code"),
                        Stock.industry.label("industry"),
                        Stock.board.label("board"),
                        Stock.pe_ratio.label("pe_ratio"),
                        Stock.pb_ratio.label("pb_ratio"),
                        Stock.market_cap.label("market_cap"),
                        DailyPrice.date.label("date"),
                        DailyPrice.close.label("price"),
                        DailyPrice.change_pct.label("change_pct"),
                        DailyPrice.volume.label("volume"),
                        DailyPrice.amount.label("amount"),
                        DailyPrice.turnover_rate.label("turnover_rate"),
                        DailyPrice.amplitude.label("amplitude"),
                    )
                    .join(latest_sq, latest_sq.c.stock_code == Stock.code)
                    .join(
                        DailyPrice,
                        and_(
                            DailyPrice.stock_code == Stock.code,
                            DailyPrice.date == latest_sq.c.latest_date,
                        ),
                    )
                    .filter(Stock.code.in_(stock_codes))
                    .all()
                    if stock_codes
                    else []
                )
                meta_map = {
                    row.code: {
                        "industry": row.industry or "",
                        "board": row.board or data_sources.infer_listing_board(row.code),
                        "pe_ratio": data_sources.safe_float(row.pe_ratio),
                        "pb_ratio": data_sources.safe_float(row.pb_ratio),
                        "market_cap": normalize_market_cap_yi(row.market_cap),
                        "date": str(row.date) if row.date else "",
                        "price": data_sources.safe_float(row.price),
                        "change_pct": data_sources.safe_float(row.change_pct),
                        "volume": data_sources.safe_float(row.volume),
                        "amount": data_sources.safe_float(row.amount),
                        "turnover_rate": data_sources.safe_float(row.turnover_rate),
                        "amplitude": data_sources.safe_float(row.amplitude),
                    }
                    for row in meta_rows
                }
                for item in base_items:
                    quote = quote_map.get(item["code"]) or {}
                    meta = meta_map.get(item["code"]) or {}
                    price = data_sources.safe_float(quote.get("price"))
                    prev_close = data_sources.safe_float(quote.get("prev_close"))
                    change_pct = (
                        (price - prev_close) / prev_close * 100
                        if price is not None and prev_close
                        else None
                    )
                    if price is None:
                        price = meta.get("price")
                    if change_pct is None:
                        change_pct = meta.get("change_pct")
                    volume = data_sources.safe_float(quote.get("volume"))
                    amount = data_sources.safe_float(quote.get("amount"))
                    turnover_rate = data_sources.safe_float(quote.get("turnover_rate"))
                    amplitude = data_sources.safe_float(quote.get("amplitude"))
                    pe_ratio = data_sources.safe_float(quote.get("pe_ratio"))
                    pb_ratio = data_sources.safe_float(quote.get("pb_ratio"))
                    market_cap = data_sources.safe_float(quote.get("market_cap"))
                    circulating_market_cap = data_sources.safe_float(
                        quote.get("circulating_market_cap")
                    )
                    items.append(
                        {
                            **item,
                            "exchange": item.get("exchange") or meta.get("board") or data_sources.infer_listing_board(item["code"]),
                            "industry": meta.get("industry") or "",
                            "board": meta.get("board") or data_sources.infer_listing_board(item["code"]),
                            "price": round(price, 2) if price is not None else None,
                            "change_pct": round(change_pct, 2)
                            if change_pct is not None
                            else None,
                            "volume": volume if volume is not None else meta.get("volume"),
                            "amount": amount if amount is not None else meta.get("amount"),
                            "turnover_rate": turnover_rate
                            if turnover_rate is not None
                            else meta.get("turnover_rate"),
                            "amplitude": amplitude
                            if amplitude is not None
                            else meta.get("amplitude"),
                            "pe_ratio": pe_ratio
                            if pe_ratio is not None
                            else meta.get("pe_ratio"),
                            "pb_ratio": pb_ratio
                            if pb_ratio is not None
                            else meta.get("pb_ratio"),
                            "market_cap": (
                                normalize_market_cap_yi(market_cap)
                                if market_cap is not None
                                else meta.get("market_cap")
                            ),
                            "circulating_market_cap": (
                                normalize_market_cap_yi(circulating_market_cap)
                                if circulating_market_cap is not None
                                else None
                            ),
                            "date": item.get("date") or meta.get("date") or "",
                            "source": "csindex.weight+tencent.quote",
                        }
                    )
                source = "csindex.weight+tencent.quote"

    if not items:
        items = _fallback_index_constituents_from_db(index_meta, limit, db)
        source = "database.latest_daily"

    payload = {
        "code": index_meta["code"],
        "name": index_meta["name"],
        "name_en": index_meta.get("name_en") or index_meta["name"],
        "market": index_meta.get("market") or "CN",
        "currency": index_meta.get("currency") or "CNY",
        "constituent_mode": (
            "index_constituents" if index_meta.get("cs_symbol") else "market_leaders"
        ),
        "source": source,
        "items": items,
        **({"error": error} if error else {}),
    }
    cache_set(cache_key, json.dumps(payload, ensure_ascii=False, default=str), ex=600)
    return payload


class WatchlistGroupRequest(BaseModel):
    group_name: str
    color: Optional[str] = None


@app.post("/api/watchlist/group", dependencies=[Depends(require_permission("dashboard.view"))])
def create_watchlist_group(
    payload: WatchlistGroupRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """创建自选分组（若已存在则忽略）"""
    group_name = payload.group_name.strip()
    if not group_name:
        raise HTTPException(status_code=400, detail="group_name 必填")
    exists = (
        db.query(Watchlist)
        .filter(
            Watchlist.group_name == group_name,
            Watchlist.user_id == current_user.id,
        )
        .first()
    )
    if not exists:
        db.add(
            Watchlist(
                group_name=group_name,
                code=WATCHLIST_GROUP_SENTINEL,
                name=WATCHLIST_GROUP_SENTINEL,
                added_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                color=payload.color,
                user_id=current_user.id,
            )
        )
        db.commit()
    return {"message": "ok", "group_name": group_name}


