def _sanitize_assistant_skill(raw: Any, index: int = 0) -> Optional[dict]:
    if not isinstance(raw, dict):
        return None
    raw_key = str(raw.get("key") or f"skill_{index + 1}").strip().lower()
    key = re.sub(r"[^a-z0-9_\-]+", "_", raw_key).strip("_-")[:64]
    if not key:
        return None
    mode = str(raw.get("mode") or "research").strip().lower()
    if mode not in {"research", "chat"}:
        mode = "research"
    prompt_files = raw.get("prompt_files")
    if not isinstance(prompt_files, list):
        prompt_files = DEFAULT_SERENITY_SKILL_FILES if key == "serenity" else ["SKILL.md"]
    prompt_files = [
        str(item).strip().replace("\\", "/")[:180]
        for item in prompt_files
        if isinstance(item, str) and str(item).strip()
    ][:12]
    def clean_list(value: Any, fallback: list[str], limit: int = 20) -> list[str]:
        values = value if isinstance(value, list) else fallback
        result: list[str] = []
        for item in values:
            text = str(item or "").strip().lower()[:80]
            if text and text not in result:
                result.append(text)
            if len(result) >= limit:
                break
        return result
    default_intents = ["stock_research", "industry_research", "event_research"] if key == "serenity" else []
    default_keywords = ["股票", "公司", "财报", "产业链", "行业", "事件", "估值", "风险"] if key == "serenity" else []
    return {
        "key": key,
        "name": str(raw.get("name") or ("Serenity 投研" if key == "serenity" else key)).strip()[:80],
        "name_en": str(raw.get("name_en") or raw.get("nameEn") or "").strip()[:80],
        "enabled": bool(raw.get("enabled", True)),
        "mode": mode,
        "source_url": str(raw.get("source_url") or raw.get("sourceUrl") or "").strip()[:500],
        "local_path": str(raw.get("local_path") or raw.get("localPath") or "").strip()[:500],
        "description": str(raw.get("description") or "").strip()[:500],
        "prompt_files": prompt_files,
        "instructions": str(raw.get("instructions") or "").strip()[:12000],
        "intents": clean_list(raw.get("intents"), default_intents),
        "keywords": clean_list(raw.get("keywords"), default_keywords),
        "markets": clean_list(raw.get("markets"), ["CN", "HK", "US"], 8),
        "categories": clean_list(raw.get("categories"), [], 12),
        "priority": _int_setting(raw.get("priority"), 50, 0, 100),
        "auto_route": _bool_setting(raw.get("auto_route"), True),
    }


def _assistant_skills_settings(db: Session, enabled_only: bool = False) -> dict:
    raw = _get_system_setting_json(
        db,
        ASSISTANT_SKILLS_SETTINGS_KEY,
        _default_assistant_skills_settings(),
    )
    raw_skills = raw.get("skills") if isinstance(raw, dict) else []
    skills = [
        skill
        for idx, item in enumerate(raw_skills if isinstance(raw_skills, list) else [])
        if (skill := _sanitize_assistant_skill(item, idx)) is not None
    ]
    if not skills:
        skills = [
            _sanitize_assistant_skill(item, idx)
            for idx, item in enumerate(_default_assistant_skills_settings()["skills"])
        ]
        skills = [item for item in skills if item is not None]
    if enabled_only:
        skills = [item for item in skills if item.get("enabled")]
    return {"skills": skills}


def _assistant_public_skill(skill: dict) -> dict:
    return {
        "key": skill.get("key"),
        "name": skill.get("name"),
        "name_en": skill.get("name_en"),
        "mode": skill.get("mode") or "research",
        "description": skill.get("description") or "",
        "source_url": skill.get("source_url") or "",
        "intents": skill.get("intents") or [],
        "keywords": skill.get("keywords") or [],
        "markets": skill.get("markets") or [],
        "categories": skill.get("categories") or [],
        "priority": skill.get("priority", 50),
        "auto_route": bool(skill.get("auto_route", True)),
        "enabled": bool(skill.get("enabled")),
    }


def _save_assistant_skills_settings(db: Session, payload: dict) -> dict:
    raw_skills = payload.get("skills") if isinstance(payload, dict) else []
    if not isinstance(raw_skills, list):
        raise HTTPException(status_code=400, detail="skills 必须是数组")
    skills = [
        skill
        for idx, item in enumerate(raw_skills)
        if (skill := _sanitize_assistant_skill(item, idx)) is not None
    ]
    if not skills:
        raise HTTPException(status_code=400, detail="至少需要配置一个助手 Skill")
    saved = {"skills": skills}
    _save_system_setting_json(db, ASSISTANT_SKILLS_SETTINGS_KEY, saved)
    return saved


def _resolve_assistant_skill(
    db: Session,
    skill_key: Optional[str] = None,
    mode: str = "research",
) -> dict:
    skills = _assistant_skills_settings(db, enabled_only=True)["skills"]
    mode = (mode or "research").strip().lower()
    requested = (skill_key or "").strip().lower()
    if requested:
        for skill in skills:
            if skill.get("key") == requested and skill.get("mode") == mode:
                return skill
        raise HTTPException(status_code=400, detail="指定的助手 Skill 未启用或模式不匹配")
    for skill in skills:
        if skill.get("mode") == mode:
            return skill
    raise HTTPException(status_code=400, detail="未启用可用的投研 Skill，请联系系统管理员配置")


def _read_assistant_skill_file(root: Path, rel_path: str, max_chars: int = 14000) -> str:
    rel = str(rel_path or "").strip().replace("\\", "/")
    if not rel or rel.startswith("/") or ".." in Path(rel).parts:
        return ""
    target = (root / rel).resolve()
    try:
        root_resolved = root.resolve()
        if target != root_resolved and root_resolved not in target.parents:
            return ""
        if target.suffix.lower() not in {".md", ".txt", ".json", ".yaml", ".yml"}:
            return ""
        if not target.exists() or not target.is_file() or target.stat().st_size > 512_000:
            return ""
        content = target.read_text(encoding="utf-8", errors="ignore").strip()
        if not content:
            return ""
        return f"\n\n# {rel}\n{content[:max_chars]}"
    except Exception:
        return ""


def _assistant_skill_instruction_text(skill: dict) -> str:
    pieces: list[str] = []
    inline = str(skill.get("instructions") or "").strip()
    if inline:
        pieces.append(f"# 管理员补充指令\n{inline[:12000]}")
    local_path = str(skill.get("local_path") or "").strip()
    if local_path:
        root = Path(local_path).expanduser()
        if root.exists() and root.is_dir():
            for rel in skill.get("prompt_files") or []:
                piece = _read_assistant_skill_file(root, str(rel))
                if piece:
                    pieces.append(piece)
    if not pieces and str(skill.get("key") or "") == "serenity":
        pieces.append(SERENITY_BUILTIN_INSTRUCTIONS)
    if not pieces:
        pieces.append(
            "这是管理员挂载的助手 Skill。请按其名称和说明作为方法框架，结合系统提供的数据上下文进行结构化回答。"
        )
    return "\n".join(pieces)[:42000]


