def _assistant_research_tools_settings(db: Session, masked: bool = True) -> dict:
    raw = _get_system_setting_json(
        db,
        ASSISTANT_RESEARCH_TOOLS_SETTINGS_KEY,
        _default_assistant_research_tools_settings(),
    )
    config = _sanitize_assistant_research_tools_settings(raw)
    if masked and config.get("web_search", {}).get("api_key"):
        config = json.loads(json.dumps(config, ensure_ascii=False))
        config["web_search"]["api_key"] = _mask_secret(config["web_search"]["api_key"])
    if masked:
        config = json.loads(json.dumps(config, ensure_ascii=False))
        reader_cfg = config.get("reader") or {}
        if reader_cfg.get("api_key"):
            reader_cfg["api_key"] = _mask_secret(reader_cfg["api_key"])
        market_cfg = config.get("market_data_sources") or {}
        if market_cfg.get("xueqiu_cookie"):
            market_cfg["xueqiu_cookie"] = _mask_secret(market_cfg["xueqiu_cookie"])
        if market_cfg.get("ths_cookie"):
            market_cfg["ths_cookie"] = _mask_secret(market_cfg["ths_cookie"])
        ta_cfg = config.get("tradingagents") or {}
        if ta_cfg.get("fred_api_key"):
            ta_cfg["fred_api_key"] = _mask_secret(ta_cfg["fred_api_key"])
    return config


def _save_assistant_research_tools_settings(db: Session, payload: dict) -> dict:
    existing = _assistant_research_tools_settings(db, masked=False)
    config = _sanitize_assistant_research_tools_settings(payload, existing=existing)
    _save_system_setting_json(db, ASSISTANT_RESEARCH_TOOLS_SETTINGS_KEY, config)
    safe = json.loads(json.dumps(config, ensure_ascii=False))
    if safe.get("web_search", {}).get("api_key"):
        safe["web_search"]["api_key"] = _mask_secret(safe["web_search"]["api_key"])
    reader_safe = safe.get("reader") or {}
    if reader_safe.get("api_key"):
        reader_safe["api_key"] = _mask_secret(reader_safe["api_key"])
    market_safe = safe.get("market_data_sources") or {}
    if market_safe.get("xueqiu_cookie"):
        market_safe["xueqiu_cookie"] = _mask_secret(market_safe["xueqiu_cookie"])
    if market_safe.get("ths_cookie"):
        market_safe["ths_cookie"] = _mask_secret(market_safe["ths_cookie"])
    ta_safe = safe.get("tradingagents") or {}
    if ta_safe.get("fred_api_key"):
        ta_safe["fred_api_key"] = _mask_secret(ta_safe["fred_api_key"])
    return safe


