def _customer_service_clean_text(value: Any, max_chars: int = 2000) -> str:
    return str(value or "").strip()[:max_chars]


def _sanitize_customer_service_list(value: Any, max_items: int, max_chars: int) -> list[str]:
    if isinstance(value, str):
        raw_items = [item.strip() for item in re.split(r"[\n,;；]+", value) if item.strip()]
    elif isinstance(value, list):
        raw_items = [str(item).strip() for item in value if str(item or "").strip()]
    else:
        raw_items = []
    items: list[str] = []
    seen: set[str] = set()
    for item in raw_items:
        cleaned = item[:max_chars]
        if cleaned and cleaned not in seen:
            seen.add(cleaned)
            items.append(cleaned)
        if len(items) >= max_items:
            break
    return items


def _sanitize_customer_service_faqs(value: Any) -> list[dict]:
    raw_items = value if isinstance(value, list) else []
    faqs: list[dict] = []
    for item in raw_items:
        if not isinstance(item, dict):
            continue
        question = _customer_service_clean_text(item.get("question"), 180)
        answer = _customer_service_clean_text(item.get("answer"), 2000)
        if not question or not answer:
            continue
        faqs.append(
            {
                "question": question,
                "answer": answer,
                "enabled": _bool_setting(item.get("enabled"), True),
            }
        )
        if len(faqs) >= 20:
            break
    return faqs


def _sanitize_customer_service_kb_items(value: Any, max_items: int = 12) -> list[dict]:
    raw_items = value if isinstance(value, list) else []
    items: list[dict] = []
    for index, item in enumerate(raw_items):
        if not isinstance(item, dict):
            continue
        name = _customer_service_clean_text(item.get("name") or f"知识库文件 {index + 1}", 160)
        content = _customer_service_clean_text(item.get("content") or item.get("text"), 12000)
        if not content:
            continue
        items.append(
            {
                "name": name,
                "content": content,
                "type": _customer_service_clean_text(item.get("type") or "text", 40),
                "enabled": _bool_setting(item.get("enabled"), True),
            }
        )
        if len(items) >= max_items:
            break
    return items


def _sanitize_customer_service_graph(value: Any) -> dict:
    raw = value if isinstance(value, dict) else {}
    nodes = raw.get("nodes") if isinstance(raw.get("nodes"), list) else []
    edges = raw.get("edges") if isinstance(raw.get("edges"), list) else []
    return {
        "enabled": _bool_setting(raw.get("enabled"), False),
        "nodes": [item for item in nodes[:80] if isinstance(item, (dict, str, int, float))],
        "edges": [item for item in edges[:120] if isinstance(item, (dict, str, int, float))],
        "notes": _customer_service_clean_text(raw.get("notes"), 8000),
    }


def _sanitize_customer_service_ai_settings(
    value: Optional[dict],
    existing: Optional[dict] = None,
    *,
    masked: bool = False,
) -> dict:
    default = _default_customer_service_ai_settings()
    raw = value if isinstance(value, dict) else {}
    existing = existing if isinstance(existing, dict) else {}
    raw_kb = raw.get("knowledge_base") if isinstance(raw.get("knowledge_base"), dict) else {}
    default_kb = default["knowledge_base"]
    existing_kb = existing.get("knowledge_base") if isinstance(existing.get("knowledge_base"), dict) else {}

    provider = _normalize_llm_provider(raw.get("provider") or default["provider"])
    incoming_api_key = _customer_service_clean_text(raw.get("api_key"), 2000)
    if _is_masked_api_key(incoming_api_key):
        incoming_api_key = _customer_service_clean_text(existing.get("api_key"), 2000)

    external_raw = raw_kb.get("external") if isinstance(raw_kb.get("external"), dict) else {}
    existing_external = existing_kb.get("external") if isinstance(existing_kb.get("external"), dict) else {}
    external_api_key = _customer_service_clean_text(external_raw.get("api_key"), 2000)
    if _is_masked_api_key(external_api_key):
        external_api_key = _customer_service_clean_text(existing_external.get("api_key"), 2000)
    external_method = _customer_service_clean_text(external_raw.get("method") or "GET", 10).upper()
    if external_method not in {"GET", "POST"}:
        external_method = "GET"

    internal_raw = raw_kb.get("internal") if isinstance(raw_kb.get("internal"), dict) else {}
    text_raw = raw_kb.get("text") if isinstance(raw_kb.get("text"), dict) else {}
    config = {
        "enabled": _bool_setting(raw.get("enabled"), False),
        "display_title": _customer_service_clean_text(raw.get("display_title") or default["display_title"], 80),
        "use_system_ai": _bool_setting(raw.get("use_system_ai"), True),
        "provider": provider,
        "model": _customer_service_clean_text(raw.get("model") or default["model"], 160),
        "api_url": _customer_service_clean_text(raw.get("api_url") or raw.get("base_url"), 500),
        "api_key": incoming_api_key,
        "welcome_message": _customer_service_clean_text(
            raw.get("welcome_message") or default["welcome_message"],
            1200,
        ),
        "system_prompt": _customer_service_clean_text(
            raw.get("system_prompt") or default["system_prompt"],
            8000,
        ),
        "capabilities": _sanitize_customer_service_list(
            raw.get("capabilities") or default["capabilities"],
            12,
            80,
        ),
        "knowledge_base": {
            "internal": {
                "enabled": _bool_setting(internal_raw.get("enabled"), True),
                "text": _customer_service_clean_text(
                    internal_raw.get("text") or default_kb["internal"]["text"],
                    12000,
                ),
            },
            "text": {
                "enabled": _bool_setting(text_raw.get("enabled"), True),
                "content": _customer_service_clean_text(text_raw.get("content"), 20000),
            },
            "uploaded_files": _sanitize_customer_service_kb_items(raw_kb.get("uploaded_files"), 16),
            "rag_files": _sanitize_customer_service_kb_items(raw_kb.get("rag_files"), 16),
            "graph": _sanitize_customer_service_graph(raw_kb.get("graph")),
            "external": {
                "enabled": _bool_setting(external_raw.get("enabled"), False),
                "endpoint": _customer_service_clean_text(external_raw.get("endpoint"), 500),
                "method": external_method,
                "api_key": external_api_key,
            },
        },
        "faqs": _sanitize_customer_service_faqs(raw.get("faqs") or default["faqs"]),
        "recommended_questions": _sanitize_customer_service_list(
            raw.get("recommended_questions") or default["recommended_questions"],
            16,
            160,
        ),
    }
    if masked:
        safe = json.loads(json.dumps(config, ensure_ascii=False))
        if safe.get("api_key"):
            safe["api_key"] = _mask_secret(safe["api_key"])
        external = (safe.get("knowledge_base") or {}).get("external") or {}
        if external.get("api_key"):
            external["api_key"] = _mask_secret(external["api_key"])
        return safe
    return config


def _customer_service_ai_settings(db: Session, masked: bool = True) -> dict:
    raw = _get_system_setting_json(
        db,
        CUSTOMER_SERVICE_AI_SETTINGS_KEY,
        _default_customer_service_ai_settings(),
    )
    return _sanitize_customer_service_ai_settings(raw, masked=masked)


def _save_customer_service_ai_settings(db: Session, payload: dict) -> dict:
    existing = _customer_service_ai_settings(db, masked=False)
    config = _sanitize_customer_service_ai_settings(payload, existing=existing)
    _save_system_setting_json(db, CUSTOMER_SERVICE_AI_SETTINGS_KEY, config)
    return _sanitize_customer_service_ai_settings(config, masked=True)


def _customer_service_effective_llm_config(db: Session, config: dict) -> dict:
    provider = _normalize_llm_provider(config.get("provider"))
    model = _customer_service_clean_text(config.get("model") or DEFAULT_LLM_MODEL, 160)
    api_key = _customer_service_clean_text(config.get("api_key"), 2000)
    base_url = _customer_service_clean_text(config.get("api_url"), 500)
    if config.get("use_system_ai", True):
        try:
            from llm_factory import get_llm_config

            shared = get_llm_config(db, user_id=None, allow_shared_fallback=True)
            if not api_key and not base_url:
                provider = _normalize_llm_provider(shared.get("provider"), provider)
            api_key = api_key or _customer_service_clean_text(shared.get("api_key"), 2000)
            model = model or _customer_service_clean_text(shared.get("model"), 160)
            base_url = base_url or _customer_service_clean_text(shared.get("base_url"), 500)
        except Exception:
            pass
    return {
        "provider": provider,
        "model": model or DEFAULT_LLM_MODEL,
        "api_key": api_key,
        "base_url": base_url or _default_llm_base_url(provider),
    }


def _customer_service_is_ready(db: Session, config: dict) -> bool:
    if not config.get("enabled"):
        return False
    if not _customer_service_clean_text(config.get("display_title"), 80):
        return False
    llm_cfg = _customer_service_effective_llm_config(db, config)
    return bool(llm_cfg.get("api_key") and llm_cfg.get("model"))


def _customer_service_public_settings(db: Session) -> dict:
    config = _customer_service_ai_settings(db, masked=True)
    raw_config = _customer_service_ai_settings(db, masked=False)
    if not _customer_service_is_ready(db, raw_config):
        return {"enabled": False}
    return {
        "enabled": True,
        "display_title": config.get("display_title"),
        "welcome_message": config.get("welcome_message"),
        "capabilities": config.get("capabilities") or [],
        "faqs": [item for item in config.get("faqs") or [] if item.get("enabled")],
        "recommended_questions": config.get("recommended_questions") or [],
    }


def _customer_service_external_context(config: dict, question: str) -> str:
    external = ((config.get("knowledge_base") or {}).get("external") or {})
    if not external.get("enabled"):
        return ""
    endpoint = _customer_service_clean_text(external.get("endpoint"), 500)
    if not endpoint or not _assistant_is_public_http_url(endpoint):
        return ""
    headers = {"Accept": "application/json, text/plain;q=0.9, */*;q=0.8"}
    api_key = _customer_service_clean_text(external.get("api_key"), 2000)
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    try:
        method = _customer_service_clean_text(external.get("method") or "GET", 10).upper()
        if method == "POST":
            response = requests.post(
                endpoint,
                json={"query": question[:500]},
                headers=headers,
                timeout=(4, 8),
            )
        else:
            response = requests.get(
                endpoint,
                params={"q": question[:500]},
                headers=headers,
                timeout=(4, 8),
            )
        if response.status_code >= 400:
            return ""
        content_type = response.headers.get("content-type") or ""
        if "json" in content_type:
            return json.dumps(response.json(), ensure_ascii=False, default=str)[:6000]
        return response.text[:6000]
    except Exception:
        return ""


def _customer_service_knowledge_context(config: dict, question: str) -> str:
    kb = config.get("knowledge_base") if isinstance(config.get("knowledge_base"), dict) else {}
    parts: list[str] = []
    internal = kb.get("internal") if isinstance(kb.get("internal"), dict) else {}
    if internal.get("enabled") and internal.get("text"):
        parts.append("[内部知识库]\n" + _customer_service_clean_text(internal.get("text"), 12000))
    text_kb = kb.get("text") if isinstance(kb.get("text"), dict) else {}
    if text_kb.get("enabled") and text_kb.get("content"):
        parts.append("[文本知识库]\n" + _customer_service_clean_text(text_kb.get("content"), 16000))
    for label, key in (("上传知识库", "uploaded_files"), ("RAG导入文件", "rag_files")):
        items = kb.get(key) if isinstance(kb.get(key), list) else []
        for item in items:
            if not isinstance(item, dict) or not item.get("enabled"):
                continue
            content = _customer_service_clean_text(item.get("content"), 6000)
            if content:
                parts.append(f"[{label}:{item.get('name') or '未命名'}]\n{content}")
    graph = kb.get("graph") if isinstance(kb.get("graph"), dict) else {}
    if graph.get("enabled"):
        graph_text = json.dumps(
            {
                "nodes": graph.get("nodes") or [],
                "edges": graph.get("edges") or [],
                "notes": graph.get("notes") or "",
            },
            ensure_ascii=False,
            default=str,
        )
        if graph_text.strip():
            parts.append("[图知识库]\n" + graph_text[:8000])
    external_context = _customer_service_external_context(config, question)
    if external_context:
        parts.append("[外部知识库]\n" + external_context)
    return "\n\n".join(parts)[:36000]


def _customer_service_fallback_answer(config: dict, question: str) -> str:
    normalized_question = question.lower()
    for item in config.get("faqs") or []:
        if not item.get("enabled"):
            continue
        q = str(item.get("question") or "").strip()
        if q and (q.lower() in normalized_question or normalized_question in q.lower()):
            return str(item.get("answer") or "").strip()
    title = config.get("display_title") or "AI客服"
    return (
        f"我是{title}。可以帮你了解产品能力、会员权益、AI投研流程和使用路径。"
        "如果你的问题需要人工处理，请在客服窗口提交工单并留下联系方式。"
    )


def _assistant_is_public_http_url(url_value: str) -> bool:
    parsed = urlparse(str(url_value or "").strip())
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return False
    hostname = parsed.hostname or ""
    if not hostname:
        return False
    try:
        ip_obj = ipaddress.ip_address(hostname)
        return not (
            ip_obj.is_private
            or ip_obj.is_loopback
            or ip_obj.is_link_local
            or ip_obj.is_multicast
            or ip_obj.is_reserved
        )
    except ValueError:
        pass
    try:
        infos = socket.getaddrinfo(hostname, None, proto=socket.IPPROTO_TCP)
        for info in infos:
            ip_obj = ipaddress.ip_address(info[4][0])
            if (
                ip_obj.is_private
                or ip_obj.is_loopback
                or ip_obj.is_link_local
                or ip_obj.is_multicast
                or ip_obj.is_reserved
            ):
                return False
    except Exception:
        return False
    return True


def _assistant_evidence_strength(item: dict) -> str:
    text = " ".join(
        str(item.get(key) or "")
        for key in ("source", "source_type", "url", "domain", "title", "category")
    ).lower()
    strong_markers = (
        "cninfo.com.cn",
        "sse.com.cn",
        "szse.cn",
        "bse.cn",
        "hkexnews.hk",
        "sec.gov",
        "公告",
        "annual",
        "filing",
        "financial_analysis",
        "business_composition",
        "announcement",
        "regulator",
        "patent",
        "tender",
    )
    medium_markers = (
        "research_report",
        "研报",
        "news",
        "eastmoney",
        "东方财富",
        "ths",
        "同花顺",
        "caixin",
        "财新",
        "media",
        "industry",
    )
    weak_markers = ("weibo", "x.com", "twitter", "reddit", "stocktwits", "雪球", "论坛", "rumor")
    if any(marker in text for marker in strong_markers):
        return "strong"
    if any(marker in text for marker in weak_markers):
        return "weak"
    if any(marker in text for marker in medium_markers):
        return "medium"
    return "needs_checking"


def _assistant_clean_search_result(item: dict, provider: str) -> Optional[dict]:
    title = html.unescape(str(item.get("title") or item.get("name") or "").strip())
    url_value = str(item.get("url") or item.get("link") or "").strip()
    summary = html.unescape(
        re.sub(r"<[^>]+>", "", str(item.get("summary") or item.get("snippet") or item.get("content") or "").strip())
    )
    if not title or not url_value or not _assistant_is_public_http_url(url_value):
        return None
    domain = urlparse(url_value).netloc.replace("www.", "")
    return {
        "title": title[:240],
        "summary": summary[:800],
        "url": url_value[:1000],
        "domain": domain[:120],
        "provider": provider,
        "source_type": "web_search",
        "strength": _assistant_evidence_strength({"url": url_value, "source_type": "web_search"}),
    }


def _assistant_web_search(query: str, settings_value: dict) -> tuple[list[dict], str]:
    web_cfg = settings_value.get("web_search") or {}
    limits = settings_value.get("limits") or {}
    if not _bool_setting(web_cfg.get("enabled"), False):
        return [], "web_search.disabled"
    provider = str(web_cfg.get("provider") or "searxng").strip().lower()
    api_key = str(web_cfg.get("api_key") or "").strip()
    endpoint = str(web_cfg.get("endpoint") or "").strip()
    timeout_seconds = _int_setting(limits.get("search_timeout_seconds"), 10, 3, 30)
    result_limit = _int_setting(limits.get("search_results"), 5, 1, 10)
    if not endpoint:
        return [], f"{provider}: endpoint 未配置"
    if not _assistant_is_public_http_url(endpoint):
        return [], f"{provider}: endpoint 非公网地址，已拦截"
    if provider in {"bing", "tavily", "serpapi"} and not api_key:
        return [], f"{provider}: api_key 未配置"

    cache_key = "assistant:web_search:" + hashlib.sha256(
        json.dumps(
            {
                "provider": provider,
                "endpoint": endpoint,
                "query": query,
                "limit": result_limit,
            },
            ensure_ascii=False,
            sort_keys=True,
        ).encode("utf-8")
    ).hexdigest()
    cached = cache_get(cache_key)
    if cached:
        try:
            payload = json.loads(cached)
            if isinstance(payload.get("items"), list):
                return payload["items"], f"{provider}.cache"
        except Exception:
            pass

    items: list[dict] = []
    try:
        if provider == "tavily":
            response = requests.post(
                endpoint,
                json={
                    "api_key": api_key,
                    "query": query,
                    "search_depth": "basic",
                    "max_results": result_limit,
                    "include_answer": False,
                    "include_raw_content": False,
                },
                timeout=timeout_seconds,
            )
            response.raise_for_status()
            raw_items = response.json().get("results") or []
            items = [
                item
                for raw in raw_items
                if (item := _assistant_clean_search_result(raw, provider)) is not None
            ]
        elif provider == "bing":
            response = requests.get(
                endpoint,
                headers={"Ocp-Apim-Subscription-Key": api_key},
                params={
                    "q": query,
                    "count": result_limit,
                    "mkt": web_cfg.get("language") or "zh-CN",
                    "safeSearch": "Strict" if web_cfg.get("safe_search") else "Moderate",
                },
                timeout=timeout_seconds,
            )
            response.raise_for_status()
            raw_items = (response.json().get("webPages") or {}).get("value") or []
            items = [
                item
                for raw in raw_items
                if (item := _assistant_clean_search_result(raw, provider)) is not None
            ]
        elif provider == "serpapi":
            response = requests.get(
                endpoint,
                params={
                    "engine": "google",
                    "q": query,
                    "api_key": api_key,
                    "num": result_limit,
                    "hl": "zh-cn" if "zh" in str(web_cfg.get("language") or "") else "en",
                },
                timeout=timeout_seconds,
            )
            response.raise_for_status()
            raw_items = response.json().get("organic_results") or []
            normalized = []
            for raw in raw_items:
                normalized.append(
                    {
                        "title": raw.get("title"),
                        "url": raw.get("link"),
                        "summary": raw.get("snippet"),
                    }
                )
            items = [
                item
                for raw in normalized
                if (item := _assistant_clean_search_result(raw, provider)) is not None
            ]
        elif provider == "duckduckgo":
            response = requests.get(
                endpoint,
                params={"q": query},
                headers={"User-Agent": "Mozilla/5.0 QuartsysResearchBot/1.0"},
                timeout=timeout_seconds,
            )
            response.raise_for_status()
            matches = re.findall(
                r'<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>(.*?)</a>[\s\S]{0,500}?<a[^>]+class="result__snippet"[^>]*>(.*?)</a>',
                response.text,
                flags=re.I,
            )
            for url_value, title, summary in matches[:result_limit]:
                cleaned = _assistant_clean_search_result(
                    {
                        "title": re.sub(r"<[^>]+>", "", title),
                        "url": html.unescape(url_value),
                        "summary": re.sub(r"<[^>]+>", "", summary),
                    },
                    provider,
                )
                if cleaned:
                    items.append(cleaned)
        else:
            search_endpoint = endpoint.rstrip("/")
            if not search_endpoint.endswith("/search"):
                search_endpoint = search_endpoint + "/search"
            response = requests.get(
                search_endpoint,
                params={
                    "q": query,
                    "format": "json",
                    "language": web_cfg.get("language") or "zh-CN",
                    "safesearch": 1 if web_cfg.get("safe_search") else 0,
                },
                timeout=timeout_seconds,
            )
            response.raise_for_status()
            raw_items = response.json().get("results") or []
            items = [
                item
                for raw in raw_items[: result_limit * 2]
                if (item := _assistant_clean_search_result(raw, provider)) is not None
            ][:result_limit]
    except Exception as err:
        return [], f"{provider}: {err}"

    cache_set(cache_key, json.dumps({"items": items}, ensure_ascii=False), ex=1800)
    return items[:result_limit], provider


def _assistant_read_web_page(url_value: str, settings_value: dict) -> Optional[dict]:
    reader_cfg = settings_value.get("reader") or {}
    if not _bool_setting(reader_cfg.get("enabled"), False):
        return None
    if not _assistant_is_public_http_url(url_value):
        return None
    provider = str(reader_cfg.get("provider") or "direct").strip().lower()
    endpoint = str(reader_cfg.get("endpoint") or "").strip()
    api_key = str(reader_cfg.get("api_key") or "").strip()
    max_chars = _int_setting(reader_cfg.get("max_chars"), 3000, 500, 12000)
    cache_key = "assistant:web_reader:" + hashlib.sha256(
        f"{provider}:{endpoint}:{url_value}:{max_chars}".encode("utf-8")
    ).hexdigest()
    cached = cache_get(cache_key)
    if cached:
        try:
            parsed = json.loads(cached)
            return parsed if isinstance(parsed, dict) else None
        except Exception:
            pass
    try:
        headers = {
            "User-Agent": "Mozilla/5.0 QuartsysResearchBot/1.0",
            "Accept": "application/json, text/markdown, text/plain, text/html;q=0.9, */*;q=0.8",
        }
        if api_key:
            headers["Authorization"] = f"Bearer {api_key}"
        response = None
        text_value = ""
        title = ""
        if provider == "jina":
            reader_url = (
                f"https://r.jina.ai/{url_value}"
                if not endpoint or "r.jina.ai" in endpoint
                else endpoint.replace("{url}", quote(url_value, safe=""))
                if "{url}" in endpoint
                else endpoint.rstrip("/") + "/" + quote(url_value, safe="")
            )
            response = requests.get(reader_url, headers=headers, timeout=(4, 20), allow_redirects=True)
            response.raise_for_status()
            text_value = response.text
            title = str(response.headers.get("x-title") or "").strip()
        elif provider == "firecrawl":
            firecrawl_endpoint = endpoint or "https://api.firecrawl.dev/v1/scrape"
            if not _assistant_is_public_http_url(firecrawl_endpoint):
                return None
            response = requests.post(
                firecrawl_endpoint,
                headers={**headers, "Content-Type": "application/json"},
                json={"url": url_value, "formats": ["markdown"], "onlyMainContent": True},
                timeout=(4, 30),
            )
            response.raise_for_status()
            body = response.json() if "json" in response.headers.get("content-type", "").lower() else {}
            data = body.get("data") if isinstance(body, dict) else {}
            data = data if isinstance(data, dict) else {}
            text_value = str(data.get("markdown") or data.get("content") or body.get("markdown") or "")
            title = str(data.get("title") or "").strip()
        elif provider == "custom" and endpoint:
            if not _assistant_is_public_http_url(endpoint):
                return None
            method = str(reader_cfg.get("method") or "POST").upper()
            if method == "GET":
                response = requests.get(endpoint, params={"url": url_value}, headers=headers, timeout=(4, 20))
            else:
                response = requests.post(
                    endpoint,
                    headers={**headers, "Content-Type": "application/json"},
                    json={"url": url_value},
                    timeout=(4, 20),
                )
            response.raise_for_status()
            if "json" in response.headers.get("content-type", "").lower():
                body = response.json()
                text_value = str(body.get("content") or body.get("markdown") or body.get("text") or body.get("data") or "") if isinstance(body, dict) else str(body)
                title = str(body.get("title") or "") if isinstance(body, dict) else ""
            else:
                text_value = response.text
        else:
            response = requests.get(
                url_value,
                headers=headers,
                timeout=(4, 20),
                allow_redirects=True,
            )
            response.raise_for_status()
            if not _assistant_is_public_http_url(response.url):
                return None
            content_type = response.headers.get("content-type", "").lower()
            if not any(marker in content_type for marker in ("text/html", "text/plain", "application/xhtml")):
                return None
            text_value = response.text[:200000]
        title_match = re.search(r"<title[^>]*>(.*?)</title>", text_value, flags=re.I | re.S)
        title = title or (html.unescape(re.sub(r"\s+", " ", title_match.group(1)).strip()) if title_match else "")
        text_value = re.sub(r"(?is)<(script|style|noscript|svg|canvas).*?</\1>", " ", text_value)
        text_value = re.sub(r"(?s)<[^>]+>", " ", text_value)
        text_value = html.unescape(re.sub(r"\s+", " ", text_value)).strip()
        if not text_value:
            return None
        result = {
            "url": url_value,
            "domain": urlparse(url_value).netloc.replace("www.", ""),
            "title": title[:240],
            "excerpt": text_value[:max_chars],
            "source_type": "web_page",
            "reader": provider,
            "strength": _assistant_evidence_strength({"url": url_value, "title": title}),
        }
        cache_set(cache_key, json.dumps(result, ensure_ascii=False), ex=1800)
        return result
    except Exception:
        return None


def _assistant_section_rows(section: dict, limit: int = 5) -> list[dict]:
    rows = section.get("rows") if isinstance(section, dict) else []
    if not isinstance(rows, list):
        return []
    result: list[dict] = []
    for raw in rows[:limit]:
        if isinstance(raw, dict):
            result.append({str(k): _json_safe_value(v) for k, v in raw.items()})
    return result


def _assistant_f10_context(targets: list[dict], db: Session, settings_value: dict) -> dict:
    enabled = (settings_value.get("enabled_tools") or {}).get("f10", True)
    if not enabled:
        return {"enabled": False, "items": [], "evidence": [], "source": "disabled"}
    limits = settings_value.get("limits") or {}
    timeout_seconds = _int_setting(limits.get("f10_timeout_seconds"), 12, 4, 30)
    items: list[dict] = []
    evidence: list[dict] = []
    for target in targets:
        code = str(target.get("code") or "").strip()
        if not code:
            continue
        payload, error = _call_with_timeout(
            lambda c=code: get_stock_f10(c, refresh=False, db=db),
            timeout_seconds=timeout_seconds,
        )
        if error or not isinstance(payload, dict):
            items.append({"code": code, "status": "error", "error": error or "empty"})
            continue
        sections = payload.get("sections") or {}
        summary = {
            "code": code,
            "name": payload.get("name") or target.get("name") or "",
            "updated_at": payload.get("updated_at") or "",
            "overview": payload.get("overview") or {},
            "announcements": _assistant_section_rows(sections.get("announcements") or {}, 6),
            "research_reports": _assistant_section_rows(sections.get("research_reports") or {}, 5),
            "financial_analysis": _assistant_section_rows(sections.get("financial_analysis") or {}, 6),
            "business_composition": _assistant_section_rows(sections.get("business_composition") or {}, 8),
            "shareholders": _assistant_section_rows(sections.get("shareholders") or {}, 5),
            "sources": {
                key: (section.get("source") if isinstance(section, dict) else "")
                for key, section in sections.items()
                if key in {"announcements", "research_reports", "financial_analysis", "business_composition", "shareholders"}
            },
        }
        items.append(summary)
        for section_key, title_keys, url_keys in [
            ("announcements", ["公告标题", "标题"], ["网址", "链接", "url"]),
            ("research_reports", ["报告名称", "标题"], ["报告PDF链接", "链接", "url"]),
            ("financial_analysis", ["报告期"], []),
            ("business_composition", ["主营构成"], []),
        ]:
            source = summary.get("sources", {}).get(section_key) or f"f10.{section_key}"
            for row in summary.get(section_key) or []:
                title = ""
                for key in title_keys:
                    if row.get(key):
                        title = str(row.get(key))
                        break
                url_value = ""
                for key in url_keys:
                    if row.get(key):
                        url_value = str(row.get(key))
                        break
                evidence_item = {
                    "stock": f"{code} {summary.get('name')}",
                    "title": title[:240] or section_key,
                    "date": str(row.get("公告日期") or row.get("日期") or row.get("报告期") or ""),
                    "source": source,
                    "source_type": section_key,
                    "url": url_value[:1000],
                }
                evidence_item["strength"] = _assistant_evidence_strength(evidence_item)
                evidence.append(evidence_item)
    return {"enabled": True, "items": items, "evidence": evidence[:40], "source": "stock.f10"}


def _assistant_news_context(
    targets: list[dict],
    settings_value: dict,
    market: str = "CN",
) -> dict:
    enabled = (settings_value.get("enabled_tools") or {}).get("news", True)
    if not enabled:
        return {"enabled": False, "items": [], "evidence": [], "source": "disabled"}
    limits = settings_value.get("limits") or {}
    news_limit = _int_setting(limits.get("news_limit"), 8, 3, 20)
    focus_stocks = [
        {"code": item.get("code"), "name": item.get("name") or item.get("code"), "reason": "投研标的"}
        for item in targets
        if item.get("code")
    ]
    market_code = _normalize_market_code(market)
    items: list[dict] = []
    sources: dict[str, str] = {}
    if focus_stocks and market_code in {"CN", "HK"}:
        stock_news, source = _fetch_focus_news(focus_stocks, limit=news_limit)
        items.extend(stock_news)
        sources["target_news"] = source
    if len(items) < max(3, news_limit // 2):
        if market_code in {"CN", "HK"}:
            domestic, domestic_source = _fetch_domestic_news(limit=news_limit)
            items.extend(domestic[:news_limit])
            sources["domestic_cn_hk"] = domestic_source
        else:
            international, international_source = _fetch_international_news(limit=news_limit)
            items.extend(international[:news_limit])
            sources["international_us"] = international_source
    items = _dedupe_news(items, news_limit)
    evidence: list[dict] = []
    for item in items:
        evidence_item = {
            "title": item.get("title") or "",
            "summary": item.get("summary") or "",
            "date": item.get("time") or "",
            "source": item.get("source") or "news",
            "source_type": "news",
            "url": item.get("url") or "",
            "category": item.get("category") or "",
        }
        evidence_item["strength"] = _assistant_evidence_strength(evidence_item)
        evidence.append(evidence_item)
    return {
        "enabled": True,
        "items": items,
        "evidence": evidence,
        "sources": sources,
        "evidence_scope": "domestic_cn_hk" if market_code in {"CN", "HK"} else "international_us",
    }


def _assistant_search_query(
    message: str,
    targets: list[dict],
    market: str = "CN",
) -> str:
    if targets:
        first = targets[0]
        market_code = _normalize_market_code(first.get("market") or market)
        terms = [
            str(first.get("code") or ""),
            str(first.get("name") or ""),
            str(first.get("industry") or ""),
            (
                "公告 财报 研报 产业链 客户 订单 风险"
                if market_code in {"CN", "HK"}
                else "earnings filing investor relations industry news risk"
            ),
        ]
        return " ".join(term for term in terms if term).strip()
    market_label = {"CN": "A股", "HK": "港股", "US": "美股"}[
        _normalize_market_code(market)
    ]
    return f"{message} {market_label} 投研 产业链 证据 公告 财报 风险".strip()


def _assistant_web_context(
    message: str,
    targets: list[dict],
    settings_value: dict,
    market: str = "CN",
) -> dict:
    enabled_tools = settings_value.get("enabled_tools") or {}
    web_cfg = settings_value.get("web_search") or {}
    if not enabled_tools.get("web_search") or not web_cfg.get("enabled"):
        return {"enabled": False, "items": [], "evidence": [], "source": "web_search.disabled"}
    query = _assistant_search_query(message, targets, market)
    items, source = _assistant_web_search(query, settings_value)
    enriched: list[dict] = []
    for item in items[:3]:
        page = _assistant_read_web_page(item.get("url") or "", settings_value)
        if page:
            next_item = dict(item)
            next_item["page_excerpt"] = page.get("excerpt")
            next_item["page_title"] = page.get("title")
            next_item["strength"] = page.get("strength") or item.get("strength")
            enriched.append(next_item)
        else:
            enriched.append(item)
    if len(items) > len(enriched):
        enriched.extend(items[len(enriched):])
    evidence = []
    for item in enriched:
        evidence_item = {
            "title": item.get("title") or "",
            "summary": item.get("summary") or item.get("page_excerpt") or "",
            "source": item.get("provider") or source,
            "source_type": "web_search",
            "url": item.get("url") or "",
            "domain": item.get("domain") or "",
            "strength": item.get("strength") or _assistant_evidence_strength(item),
        }
        evidence.append(evidence_item)
    return {
        "enabled": True,
        "query": query,
        "items": enriched,
        "evidence": evidence,
        "source": source,
    }


def _normalize_llm_provider(value: Optional[str], fallback: str = "openai") -> str:
    normalized = str(value or "").strip().lower()
    if normalized in LLM_PROVIDER_ALIASES:
        return LLM_PROVIDER_ALIASES[normalized]
    if fallback == "":
        return ""
    fallback_normalized = str(fallback or "openai").strip().lower()
    return LLM_PROVIDER_ALIASES.get(fallback_normalized, "openai")


def _default_llm_base_url(provider: str) -> str:
    provider = _normalize_llm_provider(provider)
    if provider == "anthropic":
        return "https://api.anthropic.com"
    if provider == "google":
        return "https://generativelanguage.googleapis.com/v1beta"
    return "https://api.openai.com/v1"


def _module_config_model(value: Any, fallback: str) -> str:
    if isinstance(value, dict):
        candidate = value.get("model")
    else:
        candidate = value
    model = str(candidate or "").strip()
    return model or (fallback or DEFAULT_LLM_MODEL).strip() or DEFAULT_LLM_MODEL


def _module_config_provider(value: Any, fallback: str) -> str:
    if isinstance(value, dict):
        return _normalize_llm_provider(value.get("provider"), fallback)
    return _normalize_llm_provider(fallback)


def _parse_module_model_configs(raw: Optional[str]) -> dict[str, dict[str, str]]:
    if not raw:
        return {}
    try:
        parsed = json.loads(raw)
    except Exception:
        return {}
    if not isinstance(parsed, dict):
        return {}
    result: dict[str, dict[str, str]] = {}
    for key, value in parsed.items():
        module_key = str(key)
        if module_key not in AI_MODULE_MODEL_KEYS:
            continue
        if isinstance(value, dict):
            model = str(value.get("model") or "").strip()
            provider = _normalize_llm_provider(value.get("provider"), "")
        else:
            model = str(value or "").strip()
            provider = ""
        if model:
            result[module_key] = {"model": model, "provider": provider or ""}
    return result


def _parse_module_models(raw: Optional[str]) -> dict[str, str]:
    return {
        key: value["model"]
        for key, value in _parse_module_model_configs(raw).items()
        if value.get("model")
    }


def _sanitize_module_models(
    module_models: Optional[Dict[str, Any]], default_model: str
) -> dict[str, str]:
    fallback = (default_model or DEFAULT_LLM_MODEL).strip()
    result: dict[str, str] = {}
    for key in AI_MODULE_MODEL_KEYS:
        raw_value = module_models.get(key) if isinstance(module_models, dict) else None
        result[key] = _module_config_model(raw_value, fallback)
    return result


def _sanitize_module_model_configs(
    module_models: Optional[Dict[str, Any]],
    default_model: str,
    default_provider: str,
) -> dict[str, dict[str, str]]:
    fallback_model = (default_model or DEFAULT_LLM_MODEL).strip() or DEFAULT_LLM_MODEL
    fallback_provider = _normalize_llm_provider(default_provider)
    result: dict[str, dict[str, str]] = {}
    for key in AI_MODULE_MODEL_KEYS:
        raw_value = module_models.get(key) if isinstance(module_models, dict) else None
        result[key] = {
            "provider": _module_config_provider(raw_value, fallback_provider),
            "model": _module_config_model(raw_value, fallback_model),
        }
    return result


def _legacy_module_models(configs: dict[str, dict[str, str]]) -> dict[str, str]:
    return {
        key: str(value.get("model") or DEFAULT_LLM_MODEL).strip() or DEFAULT_LLM_MODEL
        for key, value in configs.items()
        if key in AI_MODULE_MODEL_KEYS
    }


def _llm_config_for_module(
    db: Session,
    user_id: int,
    module_key: str,
    model_override: Optional[str] = None,
    allow_shared_fallback: bool = True,
) -> dict:
    from llm_factory import get_llm_config

    cfg = get_llm_config(
        db,
        user_id=user_id,
        allow_shared_fallback=allow_shared_fallback,
    )
    provider = _normalize_llm_provider(cfg.get("provider"))
    model = str(cfg.get("model") or DEFAULT_LLM_MODEL).strip() or DEFAULT_LLM_MODEL
    row = db.query(LLMConfig).filter(LLMConfig.user_id == user_id).first()
    if row is None and allow_shared_fallback:
        try:
            row = db.query(LLMConfig).filter(LLMConfig.user_id.is_(None)).first()
        except AttributeError:
            row = db.query(LLMConfig).first()
    module_configs = _sanitize_module_model_configs(
        _parse_module_model_configs(getattr(row, "module_models_json", None) if row else None),
        model,
        provider,
    )
    module_config = module_configs.get(module_key) or {}
    selected_provider = _normalize_llm_provider(module_config.get("provider"), provider)
    selected_model = (
        str(model_override or "").strip()
        or str(module_config.get("model") or "").strip()
        or model
    )
    selected_tier = ""
    selected_multiplier = 1.0
    user = db.query(UserModel).filter(UserModel.id == user_id).first() if user_id else None
    options = _sanitize_llm_model_options(
        _get_system_setting_json(db, LLM_MODEL_OPTIONS_KEY, _default_llm_model_options())
    )
    tier_key = _llm_model_tier_key(model_override)
    if not tier_key and normalize_user_role(getattr(user, "role", None)) != "admin":
        module_tiers = _sanitize_module_model_tiers(options.get("module_model_tiers"), "smart")
        tier_key = module_tiers.get(module_key) or "smart"
    if tier_key:
        allowed = _allowed_llm_model_tiers(options, getattr(user, "role", None))
        if tier_key not in allowed:
            tier_key = "smart"
        tier_cfg = (options.get("model_tiers") or {}).get(tier_key) or {}
        selected_provider = _normalize_llm_provider(tier_cfg.get("provider"), provider)
        selected_model = str(tier_cfg.get("model") or model).strip() or model
        selected_tier = tier_key
        selected_multiplier = _llm_tier_multiplier(tier_cfg.get("multiplier"), 1.0)
    return {
        **cfg,
        "provider": selected_provider,
        "model": selected_model,
        "base_url": cfg.get("base_url") or _default_llm_base_url(selected_provider),
        "_model_tier": selected_tier,
        "_model_tier_multiplier": selected_multiplier,
        "_usage_user_id": user_id,
        "_usage_module": module_key,
        "_usage_credits": LLM_USAGE_DEFAULT_CREDITS.get(module_key, 0),
    }


def _extract_model_ids(payload) -> list[str]:
    if isinstance(payload, dict):
        raw_models = payload.get("data") or payload.get("models") or payload.get("items")
    else:
        raw_models = payload
    if not isinstance(raw_models, list):
        return []

    models: list[str] = []
    seen: set[str] = set()
    for item in raw_models:
        model_id = None
        if isinstance(item, str):
            model_id = item
        elif isinstance(item, dict):
            model_id = item.get("id") or item.get("name") or item.get("model")
        if not model_id:
            continue
        model_id = str(model_id).strip()
        if model_id and model_id not in seen:
            seen.add(model_id)
            models.append(model_id)
    return models


def _extract_llm_json_object(text: str) -> Optional[dict]:
    try:
        parsed = json.loads(text)
        return parsed if isinstance(parsed, dict) else None
    except Exception:
        pass
    match = re.search(r"\{.*\}", text or "", re.S)
    if not match:
        return None
    try:
        parsed = json.loads(match.group(0))
        return parsed if isinstance(parsed, dict) else None
    except Exception:
        return None


def _direct_llm_supported(cfg: dict) -> bool:
    return _normalize_llm_provider(cfg.get("provider")) in {
        "openai",
        "custom",
        "anthropic",
        "google",
    }


def _normalize_ai_insights_result(raw_text: str) -> dict:
    from crews.ai_insights_crew import AI_INSIGHT_DIMENSIONS

    payload = _extract_llm_json_object(raw_text) or {}
    dimensions_raw = payload.get("dimensions") or payload.get("scores") or {}
    analysis_raw = payload.get("analysis_list") or payload.get("analysis") or []
    if not isinstance(dimensions_raw, dict):
        dimensions_raw = {}
    if not isinstance(analysis_raw, list):
        analysis_raw = []

    analysis_by_dim: dict[str, dict] = {}
    for item in analysis_raw:
        if not isinstance(item, dict):
            continue
        dim = str(item.get("dimension") or item.get("name") or "").strip()
        if dim:
            analysis_by_dim[dim] = item

    dimensions: dict[str, int] = {}
    analysis_list: list[dict] = []
    for dim in AI_INSIGHT_DIMENSIONS:
        item = analysis_by_dim.get(dim, {})
        raw_score = dimensions_raw.get(dim, item.get("score", 50))
        try:
            score = int(float(raw_score))
        except (TypeError, ValueError):
            score = 50
        score = max(0, min(100, score))
        summary = str(item.get("summary") or item.get("text") or "").strip()
        if not summary:
            summary = f"{dim}维度评分 {score}/100。"
        dimensions[dim] = score
        analysis_list.append({"dimension": dim, "score": score, "summary": summary[:300]})

    if not dimensions or not payload:
        raise ValueError("AI洞察模型未返回可解析的维度 JSON")
    overall = sum(dimensions.values()) // len(dimensions)
    summary = str(payload.get("summary") or "").strip()
    if not summary:
        summary = f"综合评分 {overall}/100，市场整体{'偏强' if overall >= 60 else '偏弱'}"
    return {
        "status": "done",
        "dimensions": dimensions,
        "summary": summary[:500],
        "analysis_list": analysis_list,
    }


def _build_ai_insights_market_context(db: Session, market_code: str = "CN") -> dict:
    normalized_market = _normalize_market_code(market_code)
    if normalized_market == "CN":
        market = _market_snapshot_current(db, live_tencent=_is_cn_stock_market_open())
        date_value = market.get("date")
        trade_date = date_value.isoformat() if hasattr(date_value, "isoformat") else str(date_value or "")
        top_sectors = list(market.get("sector_flows") or [])[:8]
        stock_count = market.get("count", 0)
        up_count = market.get("up_count", 0)
        down_count = market.get("down_count", 0)
        flat_count = market.get("flat_count", 0)
        avg_change = market.get("avg_change", 0.0)
        up_ratio = market.get("up_ratio", 0.5)
        down_ratio = market.get("down_ratio", 0.5)
        amount_yi = market.get("amount_yi", 0.0)
        source = market.get("source", "local_market")
        source_kind = market.get("source_kind", "local_cache")
    else:
        temperature = _database_market_temperature_payload(db, normalized_market)
        trade_date = str(temperature.get("data_date") or "")
        stock_count = int(temperature.get("total_count") or 0)
        up_count = int(temperature.get("rise_count") or 0)
        down_count = int(temperature.get("fall_count") or 0)
        flat_count = int(temperature.get("flat_count") or 0)
        avg_change = float(temperature.get("avg_change") or 0.0)
        up_ratio = up_count / stock_count if stock_count else 0.5
        down_ratio = down_count / stock_count if stock_count else 0.5
        date_value = None
        try:
            date_value = datetime.strptime(trade_date, "%Y-%m-%d").date() if trade_date else None
        except Exception:
            date_value = None
        amount_query = (
            db.query(func.sum(DailyPrice.amount))
            .join(Stock, Stock.code == DailyPrice.stock_code)
            .filter(_stock_market_condition(normalized_market))
        )
        if date_value:
            amount_query = amount_query.filter(DailyPrice.date == date_value)
        amount_yi = float(amount_query.scalar() or 0) / 100_000_000
        top_groups = get_top_gainers(
            date=trade_date or None,
            group_by="industry",
            market=normalized_market,
            db=db,
        )
        top_sectors = [
            {"name": item.get("industry") or item.get("name"), "value": item.get("avg_change") or 0}
            for item in top_groups[:8]
        ]
        source = temperature.get("source") or f"database.daily_prices.{normalized_market.lower()}"
        source_kind = "database"
    pe_rows = (
        db.query(Stock.pe_ratio)
        .filter(
            Stock.pe_ratio.isnot(None),
            Stock.pe_ratio > 0,
            _stock_market_condition(normalized_market),
        )
        .limit(6000)
        .all()
    )
    pe_values = sorted(
        float(row[0]) for row in pe_rows if data_sources.safe_float(row[0]) is not None
    )
    median_pe = pe_values[len(pe_values) // 2] if pe_values else None
    return {
        "market": normalized_market,
        "trade_date": trade_date,
        "stock_count": stock_count,
        "up_count": up_count,
        "down_count": down_count,
        "flat_count": flat_count,
        "avg_change": avg_change,
        "up_ratio": up_ratio,
        "down_ratio": down_ratio,
        "amount_yi": amount_yi,
        "top_sector_flows": top_sectors,
        "median_pe": round(median_pe, 2) if median_pe is not None else None,
        "source": source,
        "source_kind": source_kind,
        "source_label": (
            "在线实时行情与公开市场数据"
            if "tencent" in str(source).lower()
            else "在线数据服务最新交易日快照"
        ),
    }


def _build_ai_insights_local_result(
    context: dict,
    reason: str = "",
    failure_class: str = "",
) -> dict:
    from crews.ai_insights_crew import AI_INSIGHT_DIMENSIONS

    count = int(context.get("stock_count") or 0)
    avg_change = float(context.get("avg_change") or 0.0)
    up_ratio = float(context.get("up_ratio") or 0.5)
    down_ratio = float(context.get("down_ratio") or 0.5)
    amount_yi = float(context.get("amount_yi") or 0.0)
    median_pe = context.get("median_pe")
    sectors = list(context.get("top_sector_flows") or [])
    positive_sector_count = sum(1 for item in sectors if float(item.get("value") or 0) > 0)
    negative_sector_count = sum(1 for item in sectors if float(item.get("value") or 0) < 0)
    trend_score = _risk_clamp(50.0 + avg_change * 8.0 + (up_ratio - down_ratio) * 28.0)
    momentum_score = _risk_clamp(48.0 + avg_change * 7.0 + positive_sector_count * 2.5 - negative_sector_count * 1.8)
    if isinstance(median_pe, (int, float)) and median_pe > 0:
        valuation_score = _risk_clamp(70.0 - min(32.0, abs(float(median_pe) - 24.0) * 1.2))
        valuation_text = f"全市场正PE中位数约 {float(median_pe):.1f} 倍"
    else:
        valuation_score = 52.0
        valuation_text = "估值字段样本不足"
    sentiment_score = _risk_clamp(50.0 + (up_ratio - 0.5) * 52.0 + avg_change * 5.0)
    risk_control_score = _risk_clamp(68.0 - max(0.0, down_ratio - 0.45) * 55.0 - max(0.0, -avg_change) * 8.0)
    scores = {
        "趋势": int(round(trend_score)),
        "动量": int(round(momentum_score)),
        "估值": int(round(valuation_score)),
        "情绪": int(round(sentiment_score)),
        "风险": int(round(risk_control_score)),
    }
    top_sector_text = "、".join(
        f"{item.get('name')} {float(item.get('value') or 0):+.2f}亿"
        for item in sectors[:3]
    ) or "暂无显著行业资金变化"
    summaries = {
        "趋势": f"{context.get('trade_date') or '最新交易日'} 在线数据服务覆盖 {count} 只股票，平均涨跌幅 {avg_change:+.2f}%，上涨占比 {up_ratio * 100:.1f}%。",
        "动量": f"在线市场数据中的行业资金变化靠前：{top_sector_text}；成交额合计约 {amount_yi:.1f} 亿。",
        "估值": f"{valuation_text}，当前估值分仅作为横截面参考。",
        "情绪": f"上涨 {context.get('up_count', 0)} 只、下跌 {context.get('down_count', 0)} 只，市场情绪按最新行情宽度计算。",
        "风险": f"下跌占比 {down_ratio * 100:.1f}%，风险评分基于在线市场宽度、均值涨跌幅和行业资金变化。",
    }
    analysis_list = [
        {"dimension": dim, "score": scores[dim], "summary": summaries[dim]}
        for dim in AI_INSIGHT_DIMENSIONS
    ]
    overall = int(round(sum(scores.values()) / len(scores)))
    reason_text = str(reason or "").lower()
    if reason:
        if "country" in reason_text and "not supported" in reason_text:
            suffix = "；模型服务当前区域路由不可用，已使用结构化市场数据完成本次分析"
        elif "timeout" in reason_text or "超时" in reason_text:
            suffix = "；模型响应超时，已使用结构化市场数据完成本次分析"
        elif "访问密钥" in reason or "api key" in reason_text:
            suffix = "；模型访问配置未就绪，已使用结构化市场数据完成本次分析"
        else:
            suffix = "；模型服务本次未返回有效结果，已使用结构化市场数据完成分析"
    else:
        suffix = ""
    return {
        "status": "done",
        "degraded": bool(reason),
        "refund_required": bool(reason),
        "failure_class": (
            str(failure_class or "ai_insights_fallback") if reason else ""
        ),
        "dimensions": scores,
        "summary": (
            f"综合评分 {overall}/100，基于在线数据服务最新交易日 {context.get('trade_date') or '-'} "
            f"的 {count} 只股票行情、行业资金变化和估值字段生成{suffix}。"
            "仅供研究参考，不构成投资建议。"
        ),
        "analysis_list": analysis_list,
        "data_context": context,
    }


def _ai_insights_result_lacks_market_data(result: dict) -> bool:
    text = " ".join(
        [
            str(result.get("summary") or ""),
            " ".join(str(item.get("summary") or "") for item in result.get("analysis_list") or [] if isinstance(item, dict)),
        ]
    )
    return any(marker in text for marker in ("未接入", "未提供实时", "缺少实时", "无法获取", "数据不足"))


def _run_ai_insights_direct(cfg: dict, market_context: Optional[dict] = None) -> dict:
    from crews.ai_insights_crew import AI_INSIGHT_DIMENSIONS

    context = market_context or {}
    market_label = {"CN": "A股", "HK": "港股", "US": "美股"}.get(
        str(context.get("market") or "CN"), "目标市场"
    )
    system_prompt = (
        f"你是{market_label}量化投研系统的AI洞察分析器。只返回JSON对象，不要输出Markdown。"
        "字段必须包含 dimensions、summary、analysis_list。"
        f"dimensions 的键必须是：{','.join(AI_INSIGHT_DIMENSIONS)}，值为0到100整数。"
        "analysis_list 每项包含 dimension、score、summary。"
        "必须基于用户提供的数据库市场上下文分析，不要回答未接入数据。"
        "只能输出市场状态、研究线索、数据局限和风险提示。不得输出推荐买入、建议卖出、"
        "建议仓位、目标价、止盈止损、保证收益或任何交易指令。"
        "summary 末尾必须说明：仅供研究参考，不构成投资建议。"
    )
    user_prompt = (
        "请基于以下数据库市场上下文生成趋势、动量、估值、情绪、风险五个维度评分。"
        "上下文来自系统数据库，不是模拟数据："
        f"{json.dumps(context, ensure_ascii=False, default=str)}"
    )
    raw = _assistant_call_json_llm(
        cfg,
        [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
        temperature=0.2,
        read_timeout=_assistant_timeout_seconds(
            "AI_INSIGHTS_LLM_READ_TIMEOUT_SECONDS", 60.0, 10.0, 180.0
        ),
    )
    result = _normalize_ai_insights_result(raw)
    if _ai_insights_result_lacks_market_data(result):
        return _build_ai_insights_local_result(
            context,
            "模型未使用数据库上下文",
            "invalid_llm_output",
        )
    result["data_context"] = context
    return result


def _structured_or_text_to_plain(raw_text: str) -> str:
    payload = _extract_llm_json_object(raw_text)
    if isinstance(payload, dict) and isinstance(payload.get("blocks"), list):
        parts: list[str] = []
        for block in payload["blocks"]:
            if not isinstance(block, dict):
                continue
            if block.get("text"):
                parts.append(str(block.get("text")))
            elif block.get("latex"):
                parts.append(str(block.get("latex")))
            elif block.get("content"):
                parts.append(str(block.get("content")))
            elif isinstance(block.get("rows"), list):
                for row in block["rows"][:3]:
                    if isinstance(row, list):
                        parts.append(" / ".join(str(cell) for cell in row))
        return "\n".join(parts).strip()
    return str(raw_text or "").strip()


def _run_risk_assessment_direct(
    cfg: dict,
    fallback_assessment: str,
    market: str = "CN",
) -> str:
    market_code = _normalize_market_code(market)
    market_name = {"CN": "A股", "HK": "港股", "US": "美股"}[market_code]
    raw = _assistant_call_json_llm(
        cfg,
        [
            {
                "role": "system",
                "content": (
                    f"你是{market_name}量化风控分析师。返回100字以内中文风险评估短文，只保留风险结论、"
                    "两项以内的主要驱动和一条可执行的风险管理建议；不要逐项复述原始数据、数据源或公式，"
                    "不要输出JSON，不要输出Markdown表格。"
                ),
            },
            {
                "role": "user",
                "content": f"请基于以下系统性风险摘要给出操作层面的风险说明：{fallback_assessment}",
            },
        ],
        temperature=0.2,
        read_timeout=_assistant_timeout_seconds(
            "RISK_LLM_READ_TIMEOUT_SECONDS", 60.0, 10.0, 180.0
        ),
    )
    text = _structured_or_text_to_plain(raw)
    if not text:
        raise ValueError("风险评估模型返回内容为空")
    return text[:800]


SMART_RESEARCH_ANALYST_MAP = {
    "technical": {"label": "技术分析师", "agent": "market", "dimension": "技术"},
    "sentiment": {"label": "情绪分析师", "agent": "social", "dimension": "情绪"},
    "news": {"label": "新闻分析师", "agent": "news", "dimension": "新闻"},
    "fundamental": {
        "label": "基本面分析师",
        "agent": "fundamentals",
        "dimension": "基本面",
    },
}
SMART_RESEARCH_DEFAULT_ANALYSTS = [
    "fundamental",
    "sentiment",
    "news",
    "technical",
]
SMART_RESEARCH_MAX_SYMBOLS = max(
    1,
    min(15, int(os.getenv("SMART_RESEARCH_MAX_SYMBOLS") or 15)),
)
SMART_RESEARCH_MAX_PARALLEL = max(
    1,
    min(15, int(os.getenv("SMART_RESEARCH_MAX_PARALLEL") or 15)),
)
SMART_RESEARCH_TRADINGAGENTS_ESTIMATE_SECONDS = int(
    os.getenv("SMART_RESEARCH_TRADINGAGENTS_ESTIMATE_SECONDS") or 600
)
SMART_RESEARCH_LOCAL_ESTIMATE_SECONDS = int(
    os.getenv("SMART_RESEARCH_LOCAL_ESTIMATE_SECONDS") or 20
)
SMART_RESEARCH_PROGRESS_HEARTBEAT_SECONDS = float(
    os.getenv("SMART_RESEARCH_PROGRESS_HEARTBEAT_SECONDS") or 5
)


def _smart_research_depth_key(max_debate_rounds: int, max_risk_rounds: int) -> str:
    """Return the named UI depth for the effective TradingAgents round counts."""
    debate_rounds = max(1, min(3, int(max_debate_rounds or 1)))
    risk_rounds = max(1, min(3, int(max_risk_rounds or 1)))
    if debate_rounds == 1 and risk_rounds == 1:
        return "standard"
    if debate_rounds == 2 and risk_rounds == 1:
        return "deep"
    if debate_rounds == 2 and risk_rounds == 2:
        return "intensive"
    return "custom"


def _smart_research_per_symbol_estimate_seconds(
    use_trading_agents: bool,
    max_debate_rounds: int,
    max_risk_rounds: int,
) -> int:
    """Estimate one symbol's duration from the actual additional debate rounds."""
    base_seconds = (
        SMART_RESEARCH_TRADINGAGENTS_ESTIMATE_SECONDS
        if use_trading_agents
        else SMART_RESEARCH_LOCAL_ESTIMATE_SECONDS
    )
    if not use_trading_agents:
        return base_seconds
    debate_rounds = max(1, min(3, int(max_debate_rounds or 1)))
    risk_rounds = max(1, min(3, int(max_risk_rounds or 1)))
    extra_rounds = max(0, debate_rounds - 1) + max(0, risk_rounds - 1)
    return int(round(base_seconds * _ai_deep_research_multiplier(extra_rounds)))


class SmartResearchRunRequest(BaseModel):
    symbols: List[str]
    market: str = "CN"
    analysis_date: Optional[str] = None
    analysts: Optional[List[str]] = None
    use_trading_agents: bool = True
    max_debate_rounds: int = 1
    max_risk_rounds: int = 1
    model: Optional[str] = None
    language: str = "zh"


def _smart_research_language(value: Optional[str]) -> str:
    return "en" if str(value or "").strip().lower().startswith("en") else "zh"


def _smart_research_request_symbols(raw_values: Optional[List[str]]) -> list[str]:
    raw_symbols = []
    for item in raw_values or []:
        for part in re.split(r"[\s,，;；]+", str(item or "")):
            part = part.strip()
            if part:
                raw_symbols.append(part)
    if not raw_symbols:
        raise HTTPException(status_code=400, detail="请至少输入一个股票代码或名称")
    return raw_symbols


def _resolve_smart_research_request_symbols(
    db: Session,
    payload: SmartResearchRunRequest,
) -> tuple[list[dict], list[str], str]:
    raw_symbols = _smart_research_request_symbols(payload.symbols)
    market_code = _normalize_market_code(payload.market)
    seen_codes: set[str] = set()
    resolved_symbols: list[dict] = []
    errors: list[str] = []
    for raw in raw_symbols:
        try:
            item = _resolve_smart_research_symbol(db, raw, market_code)
            if item["code"] in seen_codes:
                continue
            seen_codes.add(item["code"])
            resolved_symbols.append(item)
        except ValueError as err:
            errors.append(str(err))
    if errors and not resolved_symbols:
        raise HTTPException(status_code=400, detail="；".join(errors))
    if len(resolved_symbols) > SMART_RESEARCH_MAX_SYMBOLS:
        raise HTTPException(
            status_code=400,
            detail=f"单次最多并行研究 {SMART_RESEARCH_MAX_SYMBOLS} 只标的，请拆分批次后重试",
        )
    return resolved_symbols, errors, market_code


def _smart_research_request_analysts(payload: SmartResearchRunRequest) -> list[str]:
    return [
        key
        for key in (payload.analysts or SMART_RESEARCH_DEFAULT_ANALYSTS)
        if key in SMART_RESEARCH_ANALYST_MAP
    ] or SMART_RESEARCH_DEFAULT_ANALYSTS


def _smart_research_request_date(payload: SmartResearchRunRequest) -> str:
    try:
        return (
            datetime.strptime(payload.analysis_date, "%Y-%m-%d").date().isoformat()
            if payload.analysis_date
            else datetime.now().date().isoformat()
        )
    except Exception:
        raise HTTPException(status_code=400, detail="analysis_date 格式应为 YYYY-MM-DD")


def _smart_research_credit_estimate(
    db: Session,
    payload: SmartResearchRunRequest,
    user: UserModel,
    *,
    symbol_count: int,
    analyst_count: int,
) -> dict:
    model_details = _llm_tier_billing_details(db, "smart_research", payload.model, user)
    # TradingAgents supports at most three rounds, so quote and execution stay aligned.
    max_debate_rounds = max(1, min(3, int(payload.max_debate_rounds or 1)))
    max_risk_rounds = max(1, min(3, int(payload.max_risk_rounds or 1)))
    if payload.use_trading_agents:
        context_chars = symbol_count * (2_400 + analyst_count * 850)
        data_sources = max(1, analyst_count + 2)
        deep_units = max(0, max_debate_rounds - 1) + max(0, max_risk_rounds - 1)
    else:
        context_chars = symbol_count * (1_200 + analyst_count * 350)
        data_sources = 1
        deep_units = 0
    estimate = _dynamic_ai_credit_estimate(
        int(model_details["unit_credits"]),
        user=user,
        model_details=model_details,
        context_chars=context_chars,
        data_sources=data_sources,
        deep_units=deep_units,
        quantity=max(1, symbol_count),
    )
    estimate.update(
        {
            "module_key": "smart_research",
            "unit_label": "每只股票",
            "symbol_count": max(0, int(symbol_count or 0)),
            "analyst_count": max(0, int(analyst_count or 0)),
            "use_trading_agents": bool(payload.use_trading_agents),
            "max_debate_rounds": max_debate_rounds,
            "max_risk_rounds": max_risk_rounds,
            "research_depth": _smart_research_depth_key(
                max_debate_rounds,
                max_risk_rounds,
            ),
            "estimated_seconds_per_symbol": _smart_research_per_symbol_estimate_seconds(
                bool(payload.use_trading_agents),
                max_debate_rounds,
                max_risk_rounds,
            ),
        }
    )
    return estimate


def _json_loads_or(value: Optional[str], fallback):
    if not value:
        return fallback
    try:
        parsed = json.loads(value)
        return parsed if parsed is not None else fallback
    except Exception:
        return fallback


def _smart_research_float(value: Any, default: Optional[float] = None) -> Optional[float]:
    parsed = data_sources.safe_float(value)
    return default if parsed is None else float(parsed)


def _smart_research_round(value: Any, digits: int = 2, default: Optional[float] = None):
    parsed = _smart_research_float(value, default)
    if parsed is None or not math.isfinite(parsed):
        return default
    return round(parsed, digits)


def _smart_research_pct(value: Any, digits: int = 2) -> str:
    parsed = _smart_research_float(value)
    if parsed is None:
        return "--"
    return f"{parsed:+.{digits}f}%"


def _smart_research_num(value: Any, digits: int = 2, suffix: str = "") -> str:
    parsed = _smart_research_float(value)
    if parsed is None:
        return "--"
    return f"{parsed:.{digits}f}{suffix}"


def _smart_research_clamp(value: float, min_value: float = 0.0, max_value: float = 100.0) -> float:
    return max(min_value, min(max_value, float(value)))


def _smart_research_symbol_for_tradingagents(code: str) -> str:
    normalized = data_sources.normalize_stock_code(code)
    if data_sources.is_hk_stock_code(normalized):
        digits = normalized[2:]
        yahoo_code = digits.lstrip("0").zfill(4) if digits.strip("0") else digits[-4:]
        return f"{yahoo_code}.HK"
    if data_sources.is_us_stock_code(normalized):
        return normalized[2:].upper().replace(".", "-")
    if re.match(r"^(600|601|603|605|688|689)", normalized):
        return f"{normalized}.SS"
    if re.match(r"^(000|001|002|003|300|301)", normalized):
        return f"{normalized}.SZ"
    if re.match(r"^(4|8|9)", normalized):
        return f"{normalized}.BJ"
    return normalized


def _optional_yfinance_equity_profile(code: str) -> dict:
    """Fetch missing HK/US classification and fundamentals from the public source chain."""
    normalized = data_sources.normalize_stock_code(code)
    market_code = data_sources.equity_market(normalized)
    if market_code not in {"HK", "US"}:
        return {}
    cache_key = f"market:equity-profile:external:v3:{normalized}"
    cached = cache_get(cache_key)
    if cached:
        try:
            return json.loads(cached)
        except Exception:
            pass

    profile, error = _call_with_timeout(
        lambda: data_sources.fetch_equity_profile(normalized),
        9.0,
    )
    if error or not isinstance(profile, dict) or not profile:
        return {}
    payload = dict(profile)
    cache_set(cache_key, json.dumps(payload, ensure_ascii=False), ex=21600)
    return payload


def _optional_eastmoney_a_share_profile(code: str) -> dict:
    """Fill missing A-share ROE from Eastmoney's public financial report API."""
    normalized = data_sources.normalize_stock_code(code)
    if not data_sources.is_a_share_code(normalized):
        return {}
    cache_key = f"market:equity-profile:eastmoney:v1:{normalized}"
    cached = cache_get(cache_key)
    if cached:
        try:
            return json.loads(cached)
        except Exception:
            pass
    secu_code = _em_secu_code(normalized)
    try:
        response = requests.get(
            "https://datacenter-web.eastmoney.com/api/data/v1/get",
            params={
                "reportName": "RPT_F10_FINANCE_MAINFINADATA",
                "columns": "ALL",
                "filter": f'(SECUCODE="{secu_code}")',
                "pageNumber": 1,
                "pageSize": 4,
                "sortTypes": -1,
                "sortColumns": "REPORT_DATE",
                "source": "WEB",
                "client": "WEB",
            },
            headers=EASTMONEY_HEADERS,
            timeout=4.0,
        )
        response.raise_for_status()
        rows = ((response.json().get("result") or {}).get("data") or [])
    except Exception:
        return {}
    roe = None
    report_date = None
    for item in rows:
        roe = data_sources.safe_float(item.get("WEIGHTAVG_ROE") or item.get("ROEJQ"))
        if roe is not None:
            report_date = item.get("REPORT_DATE")
            break
    if roe is None:
        return {}
    payload = {
        "roe": round(float(roe), 2),
        "report_date": str(report_date or "")[:10],
        "source": "eastmoney.RPT_F10_FINANCE_MAINFINADATA",
    }
    cache_set(cache_key, json.dumps(payload, ensure_ascii=False), ex=21600)
    return payload


def _smart_research_equity_candidates(
    raw_symbol: str,
    market_code: str = "CN",
) -> list[str]:
    raw = str(raw_symbol or "").strip()
    if not raw:
        return []
    market = _normalize_market_code(market_code)
    candidates: list[str] = []

    def add(value: str):
        try:
            normalized = data_sources.normalize_stock_code(value)
        except Exception:
            return
        if (
            data_sources.is_supported_equity_code(normalized)
            and data_sources.equity_market(normalized) == market
            and normalized not in candidates
        ):
            candidates.append(normalized)

    upper = raw.upper()
    digits = re.sub(r"\D", "", raw)
    is_hk_query = (
        upper.endswith(".HK")
        or upper.startswith(("HK", "HK."))
        or (re.fullmatch(r"\d{1,5}", raw) is not None and bool(digits))
    )
    if market == "HK" and is_hk_query and digits and len(digits) <= 5:
        add(f"hk{digits.zfill(5)}")
        add(f"{digits.zfill(5)}.HK")

    is_us_query = (
        upper.endswith(".US")
        or upper.startswith(("US", "US."))
        or re.fullmatch(r"[A-Za-z.]{1,10}", raw) is not None
    )
    if market == "US" and is_us_query:
        symbol = re.sub(r"(?i)^US\.?", "", raw).upper()
        if symbol.endswith(".US"):
            symbol = symbol[:-3]
        if symbol:
            add(f"us{symbol}")

    if market == "CN" and len(digits) == 6:
        add(digits)
    add(raw)
    return candidates


def _resolve_smart_research_symbol(
    db: Session,
    raw_symbol: str,
    market_code: str = "CN",
) -> dict:
    raw = str(raw_symbol or "").strip()
    if not raw:
        raise ValueError("股票代码或名称不能为空")

    market = _normalize_market_code(market_code)
    candidates = _smart_research_equity_candidates(raw, market)
    stock_row = None
    if candidates:
        for candidate in candidates:
            stock_row = (
                db.query(Stock)
                .filter(Stock.code == candidate, _stock_data_available_condition())
                .first()
            )
            if stock_row:
                break
    if not stock_row:
        stock_row = (
            db.query(Stock)
            .filter(
                _stock_market_condition(market),
                _stock_data_available_condition(),
                or_(Stock.code.ilike(f"%{raw}%"), Stock.name.ilike(f"%{raw}%")),
            )
            .order_by(Stock.code.asc())
            .first()
        )
    code = stock_row.code if stock_row else (candidates[0] if candidates else "")
    if (
        not code
        or not data_sources.is_supported_equity_code(code)
        or data_sources.equity_market(code) != market
    ):
        raise ValueError(f"未找到有效股票标的：{raw}")
    quote = {}
    try:
        quote = data_sources.fetch_tencent_fundamentals([code]).get(code) or {}
    except Exception as exc:
        print(f"[smart_research] quote fallback failed for {code}: {exc}")
    external_profile = {}
    if market in {"HK", "US"} and (
        not stock_row
        or not stock_row.industry
        or stock_row.pb_ratio is None
        or stock_row.roe is None
    ):
        external_profile = _optional_yfinance_equity_profile(code)
    elif market == "CN" and (not stock_row or stock_row.roe is None):
        external_profile = _optional_eastmoney_a_share_profile(code)

    def first_value(*values):
        for value in values:
            if value not in (None, ""):
                return value
        return None

    board = (
        stock_row.board
        if stock_row and stock_row.board
        else quote.get("board") or data_sources.infer_listing_board(code)
    )
    current_price = _smart_research_round(
        first_value(quote.get("price"), external_profile.get("price")),
        3,
    )
    prev_close = _smart_research_round(
        first_value(quote.get("prev_close"), external_profile.get("prev_close")),
        3,
    )
    current_change_pct = _smart_research_round(quote.get("change_pct"), 3)
    if current_change_pct is None and current_price is not None and prev_close:
        current_change_pct = round((current_price - prev_close) / prev_close * 100, 3)
    quote_date = _parse_tencent_quote_date(quote.get("trade_time"))
    return {
        "input": raw,
        "code": data_sources.normalize_stock_code(code),
        "market": market,
        "name": stock_row.name if stock_row else (quote.get("name") or code),
        "exchange": first_value(
            getattr(stock_row, "exchange", None) if stock_row else None,
            quote.get("exchange"),
            external_profile.get("exchange"),
            data_sources.infer_exchange(code, market=market),
        ),
        "currency": first_value(
            getattr(stock_row, "currency", None) if stock_row else None,
            quote.get("currency"),
            external_profile.get("currency"),
            data_sources.market_currency(market),
        ),
        "currency_symbol": data_sources.market_currency_symbol(market),
        "industry": first_value(
            stock_row.industry if stock_row else None,
            external_profile.get("industry"),
        ) or "",
        "sector": first_value(
            getattr(stock_row, "sector", None) if stock_row else None,
            external_profile.get("sector"),
        ) or "",
        "concepts": _stock_concept_names(
            getattr(stock_row, "concepts_json", None) if stock_row else None
        ),
        "board": board,
        "area": stock_row.area if stock_row else board,
        "pe_ratio": _smart_research_round(
            first_value(
                stock_row.pe_ratio if stock_row else None,
                quote.get("pe_ratio"),
                external_profile.get("pe_ratio"),
            ),
            2,
        ),
        "pb_ratio": _smart_research_round(
            first_value(
                stock_row.pb_ratio if stock_row else None,
                quote.get("pb_ratio"),
                external_profile.get("pb_ratio"),
            ),
            2,
        ),
        "market_cap": _smart_research_round(
            normalize_market_cap_yi(
                first_value(
                    stock_row.market_cap if stock_row else None,
                    quote.get("market_cap"),
                    external_profile.get("market_cap"),
                )
            ),
            2,
        ),
        "circulating_market_cap": _smart_research_round(
            normalize_market_cap_yi(
                first_value(
                    stock_row.circulating_market_cap if stock_row else None,
                    quote.get("circulating_market_cap"),
                    external_profile.get("circulating_market_cap"),
                )
            ),
            2,
        ),
        "roe": _smart_research_round(
            first_value(
                stock_row.roe if stock_row else None,
                external_profile.get("roe"),
            ),
            2,
        ),
        "current_price": current_price,
        "prev_close": prev_close,
        "change_pct": current_change_pct,
        "quote_date": quote_date.isoformat() if quote_date else None,
        "quote_source": "tencent.quote" if quote else external_profile.get("source") or "database",
        "evidence_scope": "domestic_cn_hk" if market in {"CN", "HK"} else "international_us",
    }


def _smart_research_daily_rows(db: Session, code: str, days: int = 260) -> list[DailyPrice]:
    normalized = data_sources.normalize_stock_code(code)
    min_rows = min(60, days)
    row_limit = max(60, min(1200, days))
    rows = (
        db.query(DailyPrice)
        .filter(DailyPrice.stock_code == normalized)
        .order_by(DailyPrice.date.desc())
        .limit(row_limit)
        .all()
    )
    rows = list(reversed(rows))
    if len(rows) >= min_rows:
        return rows

    end_date = datetime.now().date()
    start_date = end_date - timedelta(days=max(120, int(days * 1.8)))
    fallback_rows = []
    try:
        df = data_sources.fetch_daily_price_df(normalized, start_date, end_date)
    except Exception as exc:
        print(f"[smart_research] market daily fallback failed for {normalized}: {exc}")
        df = None
    if df is not None and not df.empty:
        for _, item in df.sort_values("日期").tail(row_limit).iterrows():
            dt = pd.to_datetime(item.get("日期"), errors="coerce")
            if pd.isna(dt):
                continue
            close = _smart_research_float(item.get("收盘"))
            if close is None or close <= 0:
                continue
            fallback_rows.append(
                SimpleNamespace(
                    stock_code=normalized,
                    date=dt.date(),
                    open=_smart_research_float(item.get("开盘"), close),
                    close=close,
                    high=_smart_research_float(item.get("最高"), close),
                    low=_smart_research_float(item.get("最低"), close),
                    volume=_smart_research_float(item.get("成交量"), 0),
                    amount=_smart_research_float(item.get("成交额")),
                )
            )
    if len(fallback_rows) >= min_rows:
        return fallback_rows

    try:
        import yfinance as yf

        yf_symbol = _smart_research_symbol_for_tradingagents(normalized)
        yf_df = yf.download(
            yf_symbol,
            start=start_date.isoformat(),
            end=(end_date + timedelta(days=1)).isoformat(),
            progress=False,
            auto_adjust=False,
            threads=False,
            timeout=10,
        )
    except Exception as exc:
        print(f"[smart_research] yfinance daily fallback failed for {normalized}: {exc}")
        return fallback_rows or rows
    if yf_df is None or yf_df.empty:
        return fallback_rows or rows
    yf_df = yf_df.copy()
    if isinstance(yf_df.columns, pd.MultiIndex):
        yf_df.columns = yf_df.columns.get_level_values(0)
    yf_df = yf_df.reset_index()
    yf_rows = []
    for _, item in yf_df.tail(row_limit).iterrows():
        dt = pd.to_datetime(item.get("Date") or item.get("Datetime"), errors="coerce")
        if pd.isna(dt):
            continue
        close = _smart_research_float(item.get("Close") or item.get("Adj Close"))
        if close is None or close <= 0:
            continue
        volume = _smart_research_float(item.get("Volume"), 0)
        yf_rows.append(
            SimpleNamespace(
                stock_code=normalized,
                date=dt.date(),
                open=_smart_research_float(item.get("Open"), close),
                close=close,
                high=_smart_research_float(item.get("High"), close),
                low=_smart_research_float(item.get("Low"), close),
                volume=volume,
                amount=(close * volume if volume else None),
            )
        )
    if len(yf_rows) >= len(fallback_rows) and yf_rows:
        return yf_rows
    return fallback_rows or rows


def _rolling_average(values: list[float], window: int) -> list[Optional[float]]:
    result: list[Optional[float]] = []
    for idx in range(len(values)):
        if idx + 1 < window:
            result.append(None)
            continue
        chunk = values[idx + 1 - window : idx + 1]
        result.append(sum(chunk) / window if chunk else None)
    return result


def _ema(values: list[float], span: int) -> list[float]:
    if not values:
        return []
    alpha = 2 / (span + 1)
    result = [values[0]]
    for value in values[1:]:
        result.append(value * alpha + result[-1] * (1 - alpha))
    return result


def _stddev(values: list[float]) -> float:
    if len(values) < 2:
        return 0.0
    avg = sum(values) / len(values)
    return math.sqrt(sum((value - avg) ** 2 for value in values) / (len(values) - 1))


def _max_drawdown(values: list[float]) -> float:
    peak = 0.0
    worst = 0.0
    for value in values:
        peak = max(peak, value)
        if peak > 0:
            worst = min(worst, (value - peak) / peak * 100)
    return worst


def _rsi(values: list[float], window: int = 14) -> Optional[float]:
    if len(values) <= window:
        return None
    changes = [values[i] - values[i - 1] for i in range(1, len(values))]
    recent = changes[-window:]
    avg_gain = sum(max(0.0, item) for item in recent) / window
    avg_loss = sum(abs(min(0.0, item)) for item in recent) / window
    if avg_loss == 0:
        return 100.0
    return 100 - 100 / (1 + avg_gain / avg_loss)


def _smart_research_metrics(symbol: dict, rows: list[DailyPrice]) -> dict:
    closes = [float(row.close or 0) for row in rows if row.close and row.close > 0]
    amounts = [
        float(row.amount or 0)
        for row in rows
        if row.amount is not None and float(row.amount or 0) > 0
    ]
    volumes = [
        float(row.volume or 0)
        for row in rows
        if row.volume is not None and float(row.volume or 0) > 0
    ]
    if not closes:
        return {
            "latest_close": None,
            "change_pct": None,
            "momentum_20": None,
            "momentum_60": None,
            "volatility": None,
            "max_drawdown": None,
            "rsi": None,
            "macd": None,
            "ma20": None,
            "ma60": None,
            "avg_amount_yi": None,
        }
    current_price = _smart_research_float(symbol.get("current_price"))
    quote_date = str(symbol.get("quote_date") or "")
    last_row_date = str(rows[-1].date) if rows and getattr(rows[-1], "date", None) else ""
    if current_price and quote_date:
        if last_row_date == quote_date:
            closes[-1] = current_price
        elif not last_row_date or quote_date > last_row_date:
            closes.append(current_price)
    latest = closes[-1]
    prev = closes[-2] if len(closes) >= 2 else (_smart_research_float(symbol.get("prev_close"), latest) or latest)
    quote_change_pct = _smart_research_float(symbol.get("change_pct"))
    change_pct = quote_change_pct if quote_change_pct is not None else ((latest - prev) / prev * 100 if prev else 0.0)
    momentum_20 = (latest / closes[-21] - 1) * 100 if len(closes) >= 21 and closes[-21] else None
    momentum_60 = (latest / closes[-61] - 1) * 100 if len(closes) >= 61 and closes[-61] else None
    returns = [(closes[i] / closes[i - 1] - 1) * 100 for i in range(1, len(closes)) if closes[i - 1]]
    volatility = _stddev(returns[-60:]) * math.sqrt(252) if returns else 0.0
    ma20 = sum(closes[-20:]) / min(20, len(closes))
    ma60 = sum(closes[-60:]) / min(60, len(closes))
    ema12 = _ema(closes, 12)
    ema26 = _ema(closes, 26)
    macd = (ema12[-1] - ema26[-1]) if ema12 and ema26 else 0.0
    avg_amount_yi = (sum(amounts[-20:]) / min(20, len(amounts)) / 100000000) if amounts else None
    avg_volume = sum(volumes[-20:]) / min(20, len(volumes)) if volumes else None
    return {
        "latest_close": round(latest, 3),
        "change_pct": round(change_pct, 3),
        "momentum_20": _smart_research_round(momentum_20, 3),
        "momentum_60": _smart_research_round(momentum_60, 3),
        "volatility": _smart_research_round(volatility, 3),
        "max_drawdown": _smart_research_round(_max_drawdown(closes[-120:]), 3),
        "rsi": _smart_research_round(_rsi(closes), 2),
        "macd": _smart_research_round(macd, 4),
        "ma20": _smart_research_round(ma20, 3),
        "ma60": _smart_research_round(ma60, 3),
        "avg_amount_yi": _smart_research_round(avg_amount_yi, 3),
        "avg_volume": _smart_research_round(avg_volume, 2),
    }


def _smart_research_scores(symbol: dict, metrics: dict) -> dict:
    pe = _smart_research_float(symbol.get("pe_ratio"))
    pb = _smart_research_float(symbol.get("pb_ratio"))
    roe = _smart_research_float(symbol.get("roe"))
    market_cap = _smart_research_float(symbol.get("market_cap"))
    momentum_20 = _smart_research_float(metrics.get("momentum_20"), 0) or 0
    momentum_60 = _smart_research_float(metrics.get("momentum_60"), 0) or 0
    change_pct = _smart_research_float(metrics.get("change_pct"), 0) or 0
    volatility = _smart_research_float(metrics.get("volatility"), 28) or 28
    drawdown = abs(_smart_research_float(metrics.get("max_drawdown"), 0) or 0)
    avg_amount = _smart_research_float(metrics.get("avg_amount_yi"), 0) or 0
    rsi_value = _smart_research_float(metrics.get("rsi"), 50) or 50
    ma20 = _smart_research_float(metrics.get("ma20"))
    ma60 = _smart_research_float(metrics.get("ma60"))
    close = _smart_research_float(metrics.get("latest_close"))

    fundamental = 50.0
    if roe is not None:
        fundamental += min(24, max(-12, roe * 1.2))
    if pe is not None and pe > 0:
        fundamental += 14 - min(28, abs(pe - 25) * 0.75)
    if pb is not None and pb > 0:
        fundamental += 8 - min(16, abs(pb - 2.5) * 3)
    if market_cap is not None:
        fundamental += 4 if market_cap >= 100 else -4

    technical = 50.0 + momentum_20 * 0.75 + momentum_60 * 0.35 + change_pct * 1.2
    if close and ma20:
        technical += 7 if close >= ma20 else -7
    if ma20 and ma60:
        technical += 6 if ma20 >= ma60 else -6
    if rsi_value >= 75:
        technical -= 8
    elif rsi_value <= 30:
        technical -= 4
    elif 45 <= rsi_value <= 68:
        technical += 5

    liquidity_score = 45 + min(28, avg_amount * 4)
    volatility_penalty = max(0, volatility - 32) * 0.7 + max(0, drawdown - 18) * 0.9
    risk_score = 78 - volatility_penalty + min(8, avg_amount)
    sentiment = 50 + change_pct * 4 + max(-10, min(12, momentum_20 * 0.4))
    news = 52 + (4 if symbol.get("industry") else 0) + (3 if symbol.get("board") else 0)
    if change_pct >= 3:
        news += 7
    elif change_pct <= -3:
        news -= 7
    return {
        "基本面": int(round(_smart_research_clamp(fundamental))),
        "情绪": int(round(_smart_research_clamp(sentiment))),
        "新闻": int(round(_smart_research_clamp(news))),
        "技术": int(round(_smart_research_clamp(technical))),
        "风险控制": int(round(_smart_research_clamp(risk_score))),
        "流动性": int(round(_smart_research_clamp(liquidity_score))),
    }


def _smart_research_decision(scores: dict, metrics: dict) -> dict:
    score_values = [
        scores.get("基本面", 50),
        scores.get("情绪", 50),
        scores.get("新闻", 50),
        scores.get("技术", 50),
        scores.get("风险控制", 50),
    ]
    overall = int(round(sum(score_values) / len(score_values)))
    close = _smart_research_float(metrics.get("latest_close"), 0) or 0
    volatility = _smart_research_float(metrics.get("volatility"), 30) or 30
    risk_score = scores.get("风险控制", 50)
    technical_score = scores.get("技术", 50)
    if overall >= 72 and risk_score >= 58 and technical_score >= 62:
        action = "建议买入"
        position = 0.18
    elif overall >= 62 and risk_score >= 50:
        action = "观察/小仓位试探"
        position = 0.08
    elif overall <= 45 or risk_score <= 40:
        action = "回避/减仓"
        position = 0.0
    else:
        action = "继续观察"
        position = 0.0
    stop_loss_pct = max(4.0, min(10.0, volatility / 5))
    take_profit_pct = max(8.0, min(24.0, stop_loss_pct * 2.2))
    return {
        "overall_score": overall,
        "action": action,
        "position_ratio": round(position, 3),
        "entry_price": round(close, 3) if close else None,
        "stop_loss": round(close * (1 - stop_loss_pct / 100), 3) if close else None,
        "take_profit": round(close * (1 + take_profit_pct / 100), 3) if close else None,
        "approved": action in {"建议买入", "观察/小仓位试探"},
        "risk_level": "低" if risk_score >= 70 else ("中" if risk_score >= 50 else "高"),
    }


def _smart_research_position_ratio_from_text(text: str) -> Optional[float]:
    content = str(text or "")
    if not content.strip():
        return None

    explicit_ratio_patterns = [
        r'(?i)"position_ratio"\s*:\s*(0(?:\.\d+)?|1(?:\.0+)?)',
        r"(?i)\bposition_ratio\b\s*[:=]\s*(0(?:\.\d+)?|1(?:\.0+)?)",
    ]
    for pattern in explicit_ratio_patterns:
        match = re.search(pattern, content)
        if match:
            value = _smart_research_float(match.group(1))
            if value is not None:
                return max(0.0, min(1.0, value))

    percent_patterns = [
        r"(?i)(?:建议仓位|仓位建议|建议持仓|目标仓位|配置比例|建议配置|position(?:\s+sizing)?|allocation|weight)[^\n。；;]{0,80}?(\d+(?:\.\d+)?)\s*%[^\n。；;]{0,12}?(?:[-~–—至到]\s*(\d+(?:\.\d+)?)\s*%)?",
        r"(?i)(\d+(?:\.\d+)?)\s*%[^\n。；;]{0,20}?(?:仓位|持仓|配置|position|allocation|weight)",
    ]
    for pattern in percent_patterns:
        for match in re.finditer(pattern, content):
            first = _smart_research_float(match.group(1))
            second = _smart_research_float(match.group(2)) if len(match.groups()) >= 2 else None
            if first is None:
                continue
            pct = (first + second) / 2.0 if second is not None else first
            return max(0.0, min(1.0, pct / 100.0))

    chinese_digit_map = {
        "一": 1,
        "二": 2,
        "两": 2,
        "三": 3,
        "四": 4,
        "五": 5,
        "六": 6,
        "七": 7,
        "八": 8,
        "九": 9,
    }
    if re.search(r"(?:半仓|五成仓|5成仓)", content):
        return 0.5
    match = re.search(r"(?:建议仓位|仓位建议|建议配置|目标仓位|配置比例|仓位)[^\n。；;]{0,40}?([一二两三四五六七八九]|\d(?:\.\d+)?)\s*成", content)
    if match:
        token = match.group(1)
        value = chinese_digit_map.get(token)
        if value is None:
            value = _smart_research_float(token)
        if value is not None:
            return max(0.0, min(1.0, float(value) / 10.0))
    return None


def _smart_research_enrich_decision_from_text(
    decision: Optional[dict],
    *texts: str,
) -> dict:
    updated = dict(decision or {})
    combined = "\n".join(str(text or "") for text in texts if text)
    parsed_position = _smart_research_position_ratio_from_text(combined)
    if parsed_position is not None:
        updated["position_ratio"] = round(parsed_position, 3)
        updated["position_source"] = "tradingagents_report"
    return updated


def _smart_research_charts(rows: list[DailyPrice], scores: dict, metrics: dict) -> dict:
    closes = [float(row.close or 0) for row in rows if row.close and row.close > 0]
    ma20_values = _rolling_average(closes, 20)
    ma60_values = _rolling_average(closes, 60)
    kline = []
    price_series = []
    close_idx = 0
    for row in rows:
        close = _smart_research_float(row.close)
        if close is None or close <= 0:
            continue
        date_text = row.date.isoformat() if row.date else ""
        item = {
            "date": date_text,
            "open": _smart_research_round(row.open, 3, close),
            "close": _smart_research_round(row.close, 3, close),
            "high": _smart_research_round(row.high, 3, close),
            "low": _smart_research_round(row.low, 3, close),
            "volume": _smart_research_round(row.volume, 2, 0),
            "amount": _smart_research_round(row.amount, 2, 0),
        }
        kline.append(item)
        price_series.append(
            {
                "date": date_text,
                "close": item["close"],
                "ma20": _smart_research_round(ma20_values[close_idx], 3) if close_idx < len(ma20_values) else None,
                "ma60": _smart_research_round(ma60_values[close_idx], 3) if close_idx < len(ma60_values) else None,
            }
        )
        close_idx += 1
    return {
        "kline": kline[-260:],
        "price_series": price_series[-260:],
        "radar": [
            {"name": key, "score": int(value)}
            for key, value in scores.items()
            if key in {"基本面", "情绪", "新闻", "技术", "风险控制"}
        ],
        "risk_breakdown": [
            {"name": "年化波动率", "value": _smart_research_round(metrics.get("volatility"), 2, 0)},
            {"name": "最大回撤", "value": abs(_smart_research_round(metrics.get("max_drawdown"), 2, 0) or 0)},
            {"name": "RSI", "value": _smart_research_round(metrics.get("rsi"), 2, 50)},
            {"name": "20日成交额", "value": _smart_research_round(metrics.get("avg_amount_yi"), 2, 0)},
        ],
    }


def _smart_research_mermaid_chart(charts: dict, language: str = "zh") -> str:
    english = _smart_research_language(language) == "en"
    price_series = list(charts.get("price_series") or [])[-16:]
    risk_rows = list(charts.get("risk_breakdown") or [])
    parts = ["## Data Analysis Charts\n" if english else "## 数据分析图表\n"]
    if price_series:
        labels = ", ".join(f'"{str(item.get("date", ""))[5:]}"' for item in price_series)
        closes = ", ".join(str(_smart_research_round(item.get("close"), 2, 0)) for item in price_series)
        parts.append(
            ("### Closing Price Trend\n\n" if english else "### 收盘价走势\n\n")
            +
            "```mermaid\n"
            "xychart-beta\n"
            f"    title \"{'Closing Price Trend' if english else '收盘价走势'}\"\n"
            f"    x-axis [{labels}]\n"
            f"    y-axis \"{'Close' if english else '收盘价'}\"\n"
            f"    line [{closes}]\n"
            "```\n"
        )
    if risk_rows:
        parts.append(
            "### Risk Metrics\n\n| Metric | Value |\n|---|---:|"
            if english
            else "### 风险指标数据\n\n| 指标 | 数值 |\n|---|---:|"
        )
        for item in risk_rows:
            parts.append(f"| {item.get('name')} | {_smart_research_num(item.get('value'), 2)} |")
        parts.append("")
    return "\n".join(parts)


