def _default_dashboard_news_settings() -> dict:
    return {
        "domestic": {
            "enabled": True,
            "limit": 10,
            "provider": DOMESTIC_DASHBOARD_NEWS_PROVIDERS[0],
            "providers": list(DOMESTIC_DASHBOARD_NEWS_PROVIDERS),
        },
        "international": {
            "enabled": True,
            "limit": 10,
            "providers": list(INTERNATIONAL_DASHBOARD_NEWS_PROVIDERS),
        },
        "watchlist": {
            "enabled": True,
            "limit": 10,
            "provider": WATCHLIST_DASHBOARD_NEWS_PROVIDERS[0],
            "providers": list(WATCHLIST_DASHBOARD_NEWS_PROVIDERS),
        },
    }


def _normalize_news_provider_list(raw_value: Any, fallback: list[str], allowed: list[str]) -> list[str]:
    if isinstance(raw_value, str):
        candidates = [item.strip() for item in re.split(r"[,;\s]+", raw_value) if item.strip()]
    elif isinstance(raw_value, list):
        candidates = [str(item).strip() for item in raw_value if str(item).strip()]
    else:
        candidates = list(fallback)
    result: list[str] = []
    allowed_set = set(allowed)
    for provider in candidates:
        if provider in allowed_set and provider not in result:
            result.append(provider)
    return result or list(fallback)


def _normalize_dashboard_news_settings(raw: Optional[dict]) -> dict:
    defaults = _default_dashboard_news_settings()
    value = raw if isinstance(raw, dict) else {}
    result = {}
    for key, default in defaults.items():
        item = value.get(key) if isinstance(value.get(key), dict) else {}
        result[key] = {
            **default,
            "enabled": bool(item.get("enabled", default["enabled"])),
            "limit": max(1, min(int(item.get("limit", default["limit"]) or default["limit"]), 30)),
        }
        if key == "international":
            result[key]["providers"] = _normalize_news_provider_list(
                item.get("providers"),
                default["providers"],
                INTERNATIONAL_DASHBOARD_NEWS_PROVIDERS + OPTIONAL_INTERNATIONAL_DASHBOARD_NEWS_PROVIDERS,
            )
        elif key == "domestic":
            raw_providers = item.get("providers")
            if raw_providers is None and item.get("provider"):
                raw_providers = [item.get("provider")]
            result[key]["providers"] = _normalize_news_provider_list(
                raw_providers,
                default["providers"],
                DOMESTIC_DASHBOARD_NEWS_PROVIDERS,
            )
            result[key]["provider"] = result[key]["providers"][0]
        elif key == "watchlist":
            raw_providers = item.get("providers")
            if raw_providers is None and item.get("provider"):
                raw_providers = [item.get("provider")]
            result[key]["providers"] = _normalize_news_provider_list(
                raw_providers,
                default["providers"],
                WATCHLIST_DASHBOARD_NEWS_PROVIDERS,
            )
            result[key]["provider"] = result[key]["providers"][0]
        else:
            result[key]["provider"] = str(item.get("provider") or default["provider"])
    return result


def _get_dashboard_news_settings(db: Session) -> dict:
    return _normalize_dashboard_news_settings(
        _get_system_setting_json(db, DASHBOARD_NEWS_SETTINGS_KEY, _default_dashboard_news_settings())
    )


@app.get("/api/admin/news-settings", dependencies=[Depends(require_permission("system.manage"))])
def get_admin_news_settings(db: Session = Depends(get_db)):
    return {"settings": _get_dashboard_news_settings(db)}


@app.post("/api/admin/news-settings", dependencies=[Depends(require_permission("system.manage"))])
def save_admin_news_settings(payload: Dict[str, Any] = Body(...), db: Session = Depends(get_db)):
    settings = _normalize_dashboard_news_settings(payload.get("settings") if isinstance(payload.get("settings"), dict) else payload)
    _save_system_setting_json(db, DASHBOARD_NEWS_SETTINGS_KEY, settings)
    cache_delete("news:domestic:v2:10")
    cache_delete("news:domestic:v3:10:eastmoney.web_news_col,akshare.stock_news_main_cx,akshare.stock_news_em")
    cache_delete("news:international:v4:10")
    cache_delete("news:international:v5:10:")
    cache_delete("news:focus:v3:")
    return {"settings": settings}


def _news_cache_get(key: str):
    cached = cache_get(key)
    if not cached:
        return None
    try:
        payload = json.loads(cached)
        items = payload.get("items")
        source = payload.get("source")
        if isinstance(items, list):
            return items, f"{source} · 缓存" if source else "缓存"
    except Exception:
        pass
    return None


def _news_cache_set(key: str, items: list[dict], source: str, ttl: int = 600):
    cache_set(
        key,
        json.dumps({"items": items, "source": source}, ensure_ascii=False, default=str),
        ex=ttl,
    )


def _dedupe_news(items: list[dict], limit: int = 12) -> list[dict]:
    result = []
    seen = set()
    for item in items:
        title = (item.get("title") or "").strip()
        if not title or title in seen:
            continue
        seen.add(title)
        result.append(item)
        if len(result) >= limit:
            break
    return result


def _news_text(item: dict) -> str:
    return f"{item.get('title', '')} {item.get('summary', '')} {item.get('source', '')}"


def _ai_chain_news_score(item: dict) -> int:
    text = _news_text(item)
    return sum(1 for keyword in AI_INDUSTRY_CHAIN_NEWS_KEYWORDS if keyword in text)


def _annotate_news_topics(items: list[dict]) -> list[dict]:
    annotated = []
    for item in items:
        next_item = dict(item)
        if _ai_chain_news_score(next_item) > 0:
            next_item["topic"] = "AI产业链"
        annotated.append(next_item)
    return annotated


def _news_time_epoch(value: Any) -> float:
    if value is None:
        return 0.0
    if isinstance(value, (int, float)):
        number = float(value)
        return number / 1000.0 if number > 100000000000 else number
    text_value = str(value or "").strip()
    if not text_value:
        return 0.0
    if re.fullmatch(r"\d{10,13}", text_value):
        number = float(text_value)
        return number / 1000.0 if number > 100000000000 else number
    for parser in (
        lambda raw: datetime.fromisoformat(raw.replace("Z", "+00:00")),
        parsedate_to_datetime,
    ):
        try:
            parsed = parser(text_value)
            if parsed:
                return parsed.timestamp()
        except Exception:
            pass
    return 0.0


def _sort_news_by_time(items: list[dict]) -> list[dict]:
    indexed = list(enumerate(items))
    indexed.sort(key=lambda pair: (_news_time_epoch(pair[1].get("time")), -pair[0]), reverse=True)
    return [item for _, item in indexed]


def _sort_international_news(items: list[dict]) -> list[dict]:
    indexed = list(enumerate(_annotate_news_topics(items)))

    def sort_key(pair: tuple[int, dict]) -> tuple[float, int, float, int]:
        idx, item = pair
        epoch = _news_time_epoch(item.get("time"))
        recent_bucket = math.floor(epoch / 3600) if epoch else 0
        return recent_bucket, _ai_chain_news_score(item), epoch, -idx

    indexed.sort(key=sort_key, reverse=True)
    return [item for _, item in indexed]


def _format_epoch_news_time(value: Any) -> str:
    epoch = _news_time_epoch(value)
    if not epoch:
        return str(value or "").strip()
    try:
        return datetime.fromtimestamp(epoch).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return str(value or "").strip()


def _eastmoney_news_url(item: dict) -> str:
    raw_url = str(
        item.get("url")
        or item.get("Url")
        or item.get("artUrl")
        or item.get("articleUrl")
        or ""
    ).strip()
    if raw_url:
        return raw_url if raw_url.startswith("http") else f"https:{raw_url}" if raw_url.startswith("//") else raw_url
    code = str(item.get("code") or item.get("infoCode") or item.get("artCode") or "").strip()
    return f"https://finance.eastmoney.com/a/{code}.html" if code else ""


def _fetch_eastmoney_web_news(limit: int = 12, category: str = "domestic") -> list[dict]:
    payload = requests.get(
        "https://np-listapi.eastmoney.com/comm/web/getNewsByColumns",
        params={
            "client": "web",
            "biz": "web_news_col",
            "column": 345,
            "order": 1,
            "needInteractData": 0,
            "page_index": 1,
            "page_size": max(limit * 2, 20),
            "req_trace": 1,
        },
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0 Safari/537.36",
            "Referer": "https://finance.eastmoney.com/",
            "Accept": "application/json,text/plain,*/*",
        },
        timeout=4.0,
    )
    payload.raise_for_status()
    rows = ((payload.json().get("data") or {}).get("list") or [])
    items = []
    for row in rows[: max(limit * 2, 20)]:
        items.append(
            _news_item(
                title=row.get("title") or row.get("summary") or "",
                summary=row.get("summary") if row.get("summary") != row.get("title") else "",
                time_value=row.get("showTime") or row.get("publishTime") or "",
                source=row.get("mediaName") or "东方财富",
                url=_eastmoney_news_url(row),
                category=category,
            )
        )
    return _dedupe_news(items, limit)


def _fetch_akshare_news_em_general(limit: int = 12, category: str = "domestic") -> list[dict]:
    df, error = _call_with_timeout(lambda: ak.stock_news_em(), 4.0)
    if error or df is None or df.empty:
        raise RuntimeError(error or "empty")
    title_col = _pick_df_column(df, ["新闻标题", "标题", "title"])
    time_col = _pick_df_column(df, ["发布时间", "时间"])
    url_col = _pick_df_column(df, ["新闻链接", "链接", "url", "URL", "地址"])
    source_col = _pick_df_column(df, ["文章来源", "来源", "媒体"])
    items = []
    for _, row in df.head(limit * 3).iterrows():
        items.append(
            _news_item(
                title=row.get(title_col, "") if title_col else "",
                time_value=row.get(time_col, "") if time_col else "",
                source=row.get(source_col, "") if source_col else "东方财富",
                url=row.get(url_col, "") if url_col else "",
                category=category,
            )
        )
    return _dedupe_news(items, limit)


def _fetch_domestic_news(limit: int = 12, providers: Optional[list[str]] = None) -> tuple[list[dict], str]:
    selected = providers or DOMESTIC_DASHBOARD_NEWS_PROVIDERS
    provider_key = ",".join(selected)
    cache_key = f"news:domestic:v3:{limit}:{provider_key}"
    cached = _news_cache_get(cache_key)
    if cached is not None:
        return cached

    items: list[dict] = []
    sources: list[str] = []
    errors: list[str] = []
    for provider in selected:
        try:
            if provider == "eastmoney.web_news_col":
                provider_items = _fetch_eastmoney_web_news(limit=limit, category="domestic")
            elif provider == "akshare.stock_news_em":
                provider_items = _fetch_akshare_news_em_general(limit=limit, category="domestic")
            elif provider == "akshare.stock_news_main_cx":
                df, error = _call_with_timeout(lambda: ak.stock_news_main_cx(), 8.0)
                if error or df is None or df.empty:
                    raise RuntimeError(error or "empty")
                provider_items = [
                    _news_item(
                        title=row.get("summary", ""),
                        source=row.get("tag", "财新"),
                        url=row.get("url", ""),
                        category="domestic",
                    )
                    for _, row in df.head(limit * 2).iterrows()
                ]
            else:
                continue
            if provider_items:
                items.extend(provider_items)
                sources.append(provider)
        except Exception as exc:
            errors.append(f"{provider}: {_short_news_error(exc)}")
    items = _dedupe_news(items, limit)
    if items:
        source = " + ".join(sources)
        _news_cache_set(cache_key, items, source, ttl=600)
        return items, source
    return [], "; ".join(errors[:4]) or "empty domestic news"


def _global_news_from_df(df: pd.DataFrame, source: str, limit: int) -> list[dict]:
    title_col = _pick_df_column(df, ["标题", "内容"])
    summary_col = _pick_df_column(df, ["摘要", "内容"])
    time_col = _pick_df_column(df, ["发布时间", "时间"])
    url_col = _pick_df_column(df, ["链接", "url"])
    source_col = _pick_df_column(df, ["来源", "媒体", "source"])
    scan_limit = max(limit * 8, 60)
    items = [
        _news_item(
            title=row.get(title_col, "") if title_col else "",
            summary=(
                row.get(summary_col, "")
                if summary_col and summary_col != title_col
                else ""
            ),
            time_value=row.get(time_col, "") if time_col else "",
            source=row.get(source_col, "") if source_col else source.replace("akshare.", ""),
            url=row.get(url_col, "") if url_col else "",
            category="international",
        )
        for _, row in df.head(scan_limit).iterrows()
    ]
    return _dedupe_news(_sort_international_news(items), limit)


def _fetch_wallstreetcn_global_live(limit: int = 12) -> list[dict]:
    payload = requests.get(
        "https://api-one-wscn.awtmt.com/apiv1/content/lives",
        params={
            "channel": "global-channel",
            "client": "pc",
            "limit": max(limit * 2, 20),
        },
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0 Safari/537.36",
            "Referer": "https://wallstreetcn.com/live/global",
            "Accept": "application/json,text/plain,*/*",
        },
        timeout=4.5,
    )
    payload.raise_for_status()
    rows = ((payload.json().get("data") or {}).get("items") or [])
    items = []
    for row in rows:
        content = row.get("content_text") or row.get("content") or ""
        title = row.get("title") or re.split(r"[。！？\n]", str(content), maxsplit=1)[0]
        items.append(
            _news_item(
                title=title,
                summary=content if title != content else "",
                time_value=_format_epoch_news_time(row.get("display_time") or row.get("created_at") or ""),
                source="华尔街见闻·全球快讯",
                url=row.get("uri") or "",
                category="international",
            )
        )
    return _dedupe_news(_sort_international_news(items), limit)


def _fetch_bbc_chinese_rss(limit: int = 12) -> list[dict]:
    response = requests.get(
        "https://feeds.bbci.co.uk/zhongwen/simp/rss.xml",
        headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0 Safari/537.36"},
        timeout=4.5,
    )
    response.raise_for_status()
    root = ET.fromstring(response.content)
    items = []
    for node in root.findall("./channel/item"):
        title = node.findtext("title") or ""
        summary = node.findtext("description") or ""
        time_value = node.findtext("pubDate") or ""
        url = node.findtext("link") or ""
        items.append(
            _news_item(
                title=title,
                summary=summary,
                time_value=time_value,
                source="BBC中文",
                url=url,
                category="international",
            )
        )
    return _dedupe_news(_sort_international_news(items), limit)


def _economic_calendar_news_from_df(df: pd.DataFrame, source: str, limit: int) -> list[dict]:
    if df is None or df.empty:
        return []
    date_col = _pick_df_column(df, ["日期", "date"])
    time_col = _pick_df_column(df, ["时间", "time"])
    region_col = _pick_df_column(df, ["地区", "region"])
    event_col = _pick_df_column(df, ["事件", "event"])
    actual_col = _pick_df_column(df, ["公布", "actual"])
    expected_col = _pick_df_column(df, ["预期", "expected"])
    previous_col = _pick_df_column(df, ["前值", "previous"])
    items = []
    for _, row in df.head(max(limit * 3, 30)).iterrows():
        event = str(row.get(event_col, "") if event_col else "").strip()
        if not event:
            continue
        date_text = str(row.get(date_col, "") if date_col else "").strip()
        time_text = str(row.get(time_col, "") if time_col else "").strip()
        region = str(row.get(region_col, "") if region_col else "").strip()
        summary_parts = []
        if actual_col:
            summary_parts.append(f"公布 {row.get(actual_col, '--')}")
        if expected_col:
            summary_parts.append(f"预期 {row.get(expected_col, '--')}")
        if previous_col:
            summary_parts.append(f"前值 {row.get(previous_col, '--')}")
        items.append(
            _news_item(
                title=f"{region}{event}" if region and region not in event else event,
                summary=" · ".join(summary_parts),
                time_value=f"{date_text} {time_text}".strip(),
                source=source,
                category="international",
            )
        )
    return _dedupe_news(_sort_international_news(items), limit)


def _looks_global_news(item: dict) -> bool:
    text = _news_text(item)
    return any(keyword in text for keyword in GLOBAL_NEWS_KEYWORDS)


def _fallback_global_news_from_domestic(limit: int) -> tuple[list[dict], str]:
    domestic, domestic_source = _fetch_domestic_news(limit=30)
    items = []
    for item in domestic:
        if not _looks_global_news(item):
            continue
        next_item = dict(item)
        next_item["category"] = "international"
        if not next_item.get("source"):
            next_item["source"] = "国际关键词"
        items.append(next_item)
    return _dedupe_news(items, limit), f"{domestic_source} · 国际关键词兜底"


def _fetch_international_news(limit: int = 12, providers: Optional[list[str]] = None) -> tuple[list[dict], str]:
    provider_key = ",".join(providers or [])
    cache_key = f"news:international:v5:{limit}:{provider_key}"
    cached = _news_cache_get(cache_key)
    if cached is not None:
        return cached

    selected = providers or INTERNATIONAL_DASHBOARD_NEWS_PROVIDERS
    errors: list[str] = []
    items: list[dict] = []
    sources: list[str] = []
    for source in selected:
        try:
            if source == "wallstreetcn.global_live":
                provider_items = _fetch_wallstreetcn_global_live(limit=limit)
            elif source == "rss.bbc_chinese":
                provider_items = _fetch_bbc_chinese_rss(limit=limit)
            elif source == "akshare.stock_info_global_em":
                df, error = _call_with_timeout(lambda: ak.stock_info_global_em(), 6.0)
                if error or df is None or df.empty:
                    raise RuntimeError(error or "empty")
                provider_items = _global_news_from_df(df, source, limit)
            elif source == "akshare.stock_info_global_futu":
                df, error = _call_with_timeout(lambda: ak.stock_info_global_futu(), 4.0)
                if error or df is None or df.empty:
                    raise RuntimeError(error or "empty")
                provider_items = _global_news_from_df(df, source, limit)
            elif source == "akshare.stock_info_global_ths":
                df, error = _call_with_timeout(lambda: ak.stock_info_global_ths(), 4.0)
                if error or df is None or df.empty:
                    raise RuntimeError(error or "empty")
                provider_items = _global_news_from_df(df, source, limit)
            elif source == "akshare.stock_info_global_sina":
                df, error = _call_with_timeout(lambda: ak.stock_info_global_sina(), 4.0)
                if error or df is None or df.empty:
                    raise RuntimeError(error or "empty")
                provider_items = _global_news_from_df(df, source, limit)
            elif source == "akshare.stock_info_global_cls":
                df, error = _call_with_timeout(lambda: ak.stock_info_global_cls(), 4.0)
                if error or df is None or df.empty:
                    raise RuntimeError(error or "empty")
                provider_items = _global_news_from_df(df, source, limit)
            elif source == "akshare.news_economic_baidu":
                df, error = _call_with_timeout(lambda: ak.news_economic_baidu(), 4.0)
                if error or df is None or df.empty:
                    raise RuntimeError(error or "empty")
                provider_items = _economic_calendar_news_from_df(df, "百度经济日历", limit)
            else:
                continue
            if provider_items:
                items.extend(provider_items)
                sources.append(source)
            else:
                errors.append(f"{source}: empty parsed items")
        except Exception as exc:
            errors.append(f"{source}: {_short_news_error(exc)}")

    items = _dedupe_news(_sort_international_news(items), limit)
    if items:
        source_text = " + ".join(sources)
        _news_cache_set(cache_key, items, source_text, ttl=300)
        return items, source_text

    fallback_items, fallback_source = _fallback_global_news_from_domestic(limit)
    if fallback_items:
        _news_cache_set(cache_key, fallback_items, fallback_source, ttl=180)
        return fallback_items, fallback_source
    return [], "; ".join(errors[:4])


def _user_focus_stocks(db: Session, current_user: UserModel, limit: int = 8) -> list[dict]:
    focus: dict[str, dict] = {}
    account = (
        db.query(SimulationAccount)
        .filter(SimulationAccount.user_id == current_user.id)
        .first()
    )
    if account:
        positions = (
            db.query(SimulationPosition)
            .filter(SimulationPosition.account_id == account.id)
            .all()
        )
        for pos in positions:
            code = data_sources.normalize_stock_code(pos.stock_code)
            if code:
                focus[code] = {
                    "code": code,
                    "name": pos.stock_name or code,
                    "reason": "持仓",
                }

    watch_items = (
        db.query(Watchlist)
        .filter(
            (Watchlist.user_id == current_user.id) | (Watchlist.user_id == None),
            Watchlist.code.isnot(None),
            Watchlist.code != WATCHLIST_GROUP_SENTINEL,
        )
        .all()
    )
    for item in watch_items:
        code = data_sources.normalize_stock_code(item.code)
        if not code:
            continue
        current = focus.get(code)
        reason = "持仓/自选" if current else "自选"
        focus[code] = {"code": code, "name": item.name or code, "reason": reason}
    return list(focus.values())[:limit]


def _eastmoney_notice_url(code: str, item: dict) -> str:
    art_code = str(item.get("art_code") or item.get("artCode") or item.get("notice_id") or "").strip()
    return f"https://data.eastmoney.com/notices/detail/{code}/{art_code}.html" if art_code else ""


def _fetch_eastmoney_stock_announcements(stock: dict, limit: int = 4) -> list[dict]:
    code = data_sources.normalize_stock_code(stock.get("code"))
    plain_code = re.sub(r"\D", "", code or "")[:6]
    if not plain_code:
        return []
    payload = requests.get(
        "https://np-anotice-stock.eastmoney.com/api/security/ann",
        params={
            "sr": -1,
            "page_size": limit,
            "page_index": 1,
            "ann_type": "A",
            "client_source": "web",
            "stock_list": plain_code,
        },
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0 Safari/537.36",
            "Referer": "https://data.eastmoney.com/notices/",
            "Accept": "application/json,text/plain,*/*",
        },
        timeout=3.5,
    )
    payload.raise_for_status()
    rows = ((payload.json().get("data") or {}).get("list") or [])
    return [
        _news_item(
            title=item.get("title_ch") or item.get("title") or "",
            time_value=str(item.get("notice_date") or item.get("display_time") or "").split(" ")[0],
            source=f"{stock['reason']} · {stock['name']} · 公告",
            url=_eastmoney_notice_url(plain_code, item),
            category="watchlist",
        )
        for item in rows[:limit]
    ]


def _fetch_eastmoney_stock_reports(stock: dict, limit: int = 4) -> list[dict]:
    code = data_sources.normalize_stock_code(stock.get("code"))
    plain_code = re.sub(r"\D", "", code or "")[:6]
    if not plain_code:
        return []
    end_date = datetime.now().date()
    start_date = end_date - timedelta(days=365)
    payload = requests.get(
        "https://reportapi.eastmoney.com/report/list",
        params={
            "pageSize": limit,
            "pageNo": 1,
            "qType": 0,
            "code": plain_code,
            "beginTime": start_date.isoformat(),
            "endTime": end_date.isoformat(),
        },
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0 Safari/537.36",
            "Referer": "https://data.eastmoney.com/report/",
            "Accept": "application/json,text/plain,*/*",
        },
        timeout=3.5,
    )
    payload.raise_for_status()
    rows = payload.json().get("data") or []
    items = []
    for item in rows[:limit]:
        org = str(item.get("orgSName") or item.get("orgName") or "").strip()
        rating = str(item.get("emRatingName") or item.get("rating") or "").strip()
        summary = " · ".join(part for part in [org, rating] if part)
        items.append(
            _news_item(
                title=item.get("title") or "",
                summary=summary,
                time_value=str(item.get("publishDate") or "").split(" ")[0],
                source=f"{stock['reason']} · {stock['name']} · 研报",
                url=str(item.get("attachUrl") or item.get("encodeUrl") or ""),
                category="watchlist",
            )
        )
    return items


def _fetch_eastmoney_guba_posts(stock: dict, limit: int = 4) -> list[dict]:
    code = data_sources.normalize_stock_code(stock.get("code"))
    plain_code = re.sub(r"\D", "", code or "")[:6]
    if not plain_code:
        return []
    response = requests.get(
        f"https://guba.eastmoney.com/list,{plain_code}.html",
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0 Safari/537.36",
            "Referer": "https://guba.eastmoney.com/",
        },
        timeout=4.5,
    )
    response.raise_for_status()
    response.encoding = "utf-8"
    text_value = response.text or ""
    rows: list[dict] = []
    match = re.search(r"var\s+article_list\s*=\s*(\{.*?\});</script>", text_value, re.S)
    if match:
        try:
            rows = (json.loads(match.group(1)).get("re") or [])
        except Exception:
            rows = []
    if not rows:
        for href, title in re.findall(r'<a[^>]+href="(/news,[^"]+)"[^>]*>(.*?)</a>', text_value, re.S):
            clean_title = re.sub(r"<[^>]+>|\s+", " ", html.unescape(title)).strip()
            if clean_title:
                rows.append({"post_title": clean_title, "post_id": href.split(",")[-1].split(".")[0]})
            if len(rows) >= limit:
                break
    items = []
    for item in rows:
        stockbar_code = str(item.get("stockbar_code") or plain_code).strip()
        if stockbar_code and stockbar_code != plain_code:
            continue
        post_id = str(item.get("post_id") or "").strip()
        items.append(
            _news_item(
                title=item.get("post_title") or "",
                summary=(
                    f"阅读 {item.get('post_click_count', '--')} · 评论 {item.get('post_comment_count', '--')}"
                    if item.get("post_click_count") is not None or item.get("post_comment_count") is not None
                    else ""
                ),
                time_value=item.get("post_last_time") or item.get("post_publish_time") or "",
                source=f"{stock['reason']} · {stock['name']} · 股吧",
                url=f"https://guba.eastmoney.com/news,{plain_code},{post_id}.html" if post_id else "",
                category="watchlist",
            )
        )
        if len(items) >= limit:
            break
    return items


def _fetch_focus_news(
    focus_stocks: list[dict],
    limit: int = 12,
    providers: Optional[list[str]] = None,
) -> tuple[list[dict], str]:
    selected = providers or WATCHLIST_DASHBOARD_NEWS_PROVIDERS
    provider_key = ",".join(selected)
    cache_key = "news:focus:v3:" + ",".join(stock["code"] for stock in focus_stocks) + f":{limit}:{provider_key}"
    cached = _news_cache_get(cache_key)
    if cached is not None:
        return cached

    items: list[dict] = []
    errors: list[str] = []
    for stock in focus_stocks:
        code = stock["code"]
        for provider in selected:
            try:
                if provider == "akshare.stock_news_em":
                    df, error = _call_with_timeout(lambda c=code: ak.stock_news_em(symbol=c), 2.0)
                    if error or df is None or df.empty:
                        raise RuntimeError(error or "empty")
                    url_col = _pick_df_column(df, ["链接", "新闻链接", "url", "URL", "地址"])
                    for _, row in df.head(4).iterrows():
                        items.append(
                            _news_item(
                                title=row.get("新闻标题", ""),
                                time_value=row.get("发布时间", ""),
                                source=f"{stock['reason']} · {stock['name']} · 个股新闻",
                                url=row.get(url_col, "") if url_col else "",
                                category="watchlist",
                            )
                        )
                elif provider == "eastmoney.announcements":
                    items.extend(_fetch_eastmoney_stock_announcements(stock, limit=3))
                elif provider == "eastmoney.research_reports":
                    items.extend(_fetch_eastmoney_stock_reports(stock, limit=3))
                elif provider == "eastmoney.guba":
                    items.extend(_fetch_eastmoney_guba_posts(stock, limit=3))
            except Exception as exc:
                errors.append(f"{code}:{provider}:{_short_news_error(exc)}")
    source = " + ".join(selected)
    if not items and errors:
        source = f"{source}: {'; '.join(errors[:3])}"
    items = _dedupe_news(items, limit)
    _news_cache_set(cache_key, items, source, ttl=300)
    return items, source


@app.get("/api/news/dashboard", dependencies=[Depends(require_permission("dashboard.view"))])
def get_dashboard_news(
    market: str = "CN",
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """行情数据页三类资讯：国内、国际、自选/持仓。"""
    market_code = _normalize_market_code(market)
    settings = _get_dashboard_news_settings(db)
    focus_stocks = [
        item
        for item in _user_focus_stocks(db, current_user, limit=40)
        if data_sources.equity_market(item.get("code") or "") == market_code
    ][:8]
    defaults = {
        "domestic": ([], "akshare.stock_news_main_cx: timeout"),
        "international": ([], "wallstreetcn.global_live + akshare.stock_info_global_*: timeout"),
        "watchlist": ([], "akshare.stock_news_em(symbol=自选/持仓代码): timeout"),
    }
    tasks = {}
    if settings["domestic"]["enabled"]:
        tasks["domestic"] = lambda: _fetch_domestic_news(
            limit=settings["domestic"]["limit"],
            providers=settings["domestic"].get("providers") or [settings["domestic"].get("provider")],
        )
    if settings["international"]["enabled"]:
        tasks["international"] = lambda: _fetch_international_news(
            limit=settings["international"]["limit"],
            providers=settings["international"]["providers"],
        )
    if settings["watchlist"]["enabled"]:
        tasks["watchlist"] = lambda: _fetch_focus_news(
            focus_stocks,
            limit=settings["watchlist"]["limit"],
            providers=settings["watchlist"].get("providers") or [settings["watchlist"].get("provider")],
        )
    executor = concurrent.futures.ThreadPoolExecutor(max_workers=3)
    futures = {key: executor.submit(fn) for key, fn in tasks.items()}
    done, _ = concurrent.futures.wait(futures.values(), timeout=12.0)
    results = dict(defaults)
    for key, future in futures.items():
        if future not in done:
            continue
        try:
            results[key] = future.result(timeout=0)
        except Exception as exc:
            results[key] = ([], str(exc))
    executor.shutdown(wait=False, cancel_futures=True)

    domestic, domestic_source = results["domestic"]
    international, international_source = results["international"]
    watchlist_news, watchlist_source = results["watchlist"]
    return {
        "market": market_code,
        "domestic": domestic,
        "international": international,
        "watchlist": watchlist_news,
        "focus_stocks": focus_stocks,
        "sources": {
            "domestic": domestic_source,
            "international": international_source,
            "watchlist": watchlist_source,
        },
        "settings": settings,
    }


# --- Configurable Financial Agent Analysis API ---

FINANCIAL_AGENT_MAX_SELECTED = 8
FINANCIAL_AGENT_MAX_ROUNDS = 3
FINANCIAL_AGENT_MAX_SESSION_ROUNDS = 50
FINANCIAL_AGENT_MCP_TIMEOUT_SECONDS = 12
FINANCIAL_AGENT_MCP_SETTINGS_KEY = "financial_agent_mcp_settings"
FINANCIAL_AGENT_ROLE_LIMITS: Dict[str, Dict[str, Any]] = {
    "normal": {
        "can_create_agents": False,
        "max_agents": 2,
        "max_initial_rounds": 1,
        "mcp_mode": "none",
    },
    "vip": {
        "can_create_agents": True,
        "max_agents": 4,
        "max_initial_rounds": 2,
        "mcp_mode": "none",
    },
    "svip": {
        "can_create_agents": True,
        "max_agents": 6,
        "max_initial_rounds": 3,
        "mcp_mode": "allowlist",
    },
    "admin": {
        "can_create_agents": True,
        "max_agents": FINANCIAL_AGENT_MAX_SELECTED,
        "max_initial_rounds": FINANCIAL_AGENT_MAX_ROUNDS,
        "mcp_mode": "unrestricted",
    },
}


def _financial_agent_role_limits(role: Optional[str]) -> dict:
    normalized = normalize_user_role(role)
    if COMMUNITY_EDITION:
        return {
            "role": normalized,
            "can_create_agents": True,
            "max_agents": 1,
            "max_initial_rounds": 1,
            "mcp_mode": "none",
            "community_single_analyst": True,
        }
    limits = FINANCIAL_AGENT_ROLE_LIMITS.get(
        normalized, FINANCIAL_AGENT_ROLE_LIMITS["normal"]
    )
    return {"role": normalized, **limits}


def _agent_analysis_credit_cost(
    agent_count: int,
    rounds: int = 1,
    *,
    db: Optional[Session] = None,
    model_or_tier: Optional[str] = None,
    user: Optional[UserModel] = None,
    include_moderator: bool = True,
) -> int:
    analysts = max(0, int(agent_count or 0))
    round_count = max(0, int(rounds or 0))
    per_turn = (
        _llm_tier_credit_cost(db, "agent_analysis_turn", model_or_tier, user)
        if db
        else AI_CREDIT_COSTS["agent_analysis_turn"]
    )
    moderator = (
        _llm_tier_credit_cost(db, "agent_analysis_moderator", model_or_tier, user)
        if db
        else AI_CREDIT_COSTS["agent_analysis_moderator"]
    )
    cost = analysts * round_count * per_turn
    if include_moderator and analysts and round_count:
        cost += moderator
    return cost


def _agent_analysis_data_source_count(profiles: list[FinancialAgentProfile]) -> int:
    sources: set[str] = set()
    for profile in profiles or []:
        for tool in financial_agents.normalize_tool_keys(
            financial_agents.json_loads_or(profile.tools_json, [])
        ):
            if tool:
                sources.add(str(tool))
        for server in financial_agents.normalize_mcp_servers(
            financial_agents.json_loads_or(profile.mcp_servers_json, [])
        ):
            if server.get("enabled", True):
                sources.add(f"mcp:{server.get('name') or server.get('tool') or 'server'}")
    return max(1, len(sources))


def _agent_analysis_dynamic_credit_estimate(
    db: Session,
    user: UserModel,
    *,
    agent_count: int,
    rounds: int,
    model_or_tier: Optional[str],
    context_chars: int,
    data_sources: int,
    include_moderator: bool = True,
) -> dict:
    if COMMUNITY_EDITION:
        include_moderator = False
    analysts = max(0, int(agent_count or 0))
    round_count = max(0, int(rounds or 0))
    turn_model = _llm_tier_billing_details(db, "agent_analysis_turn", model_or_tier, user)
    moderator_model = _llm_tier_billing_details(db, "agent_analysis_moderator", model_or_tier, user)
    base_credits = analysts * round_count * int(turn_model["unit_credits"])
    if include_moderator and analysts and round_count:
        base_credits += int(moderator_model["unit_credits"])
    deep_units = max(0, round_count - 1)
    estimate = _dynamic_ai_credit_estimate(
        base_credits,
        user=user,
        model_details=turn_model,
        context_chars=context_chars,
        data_sources=data_sources,
        deep_units=deep_units,
        quantity=1,
    )
    estimate.update(
        {
            "module_key": "agent_analysis",
            "agent_count": analysts,
            "rounds": round_count,
            "per_agent_round_credits": int(turn_model["unit_credits"]),
            "moderator_summary_credits": int(moderator_model["unit_credits"]) if include_moderator else 0,
            "include_moderator": bool(include_moderator),
        }
    )
    return estimate


def _financial_agent_mcp_settings(db: Session) -> dict:
    raw = _get_system_setting_json(
        db, FINANCIAL_AGENT_MCP_SETTINGS_KEY, {"servers": []}
    )
    return {
        "servers": financial_agents.normalize_mcp_servers(raw.get("servers") or [])[:50]
    }


def _financial_agent_mcp_endpoint_allowed_for_save(endpoint: str) -> bool:
    parsed = urlparse(str(endpoint or "").strip())
    hostname = (parsed.hostname or "").strip().lower()
    if parsed.scheme not in {"http", "https"} or not hostname:
        return False
    if hostname == "localhost" or hostname.endswith((".localhost", ".local", ".lan", ".internal")):
        return False
    try:
        ip_obj = ipaddress.ip_address(hostname)
        return not (
            ip_obj.is_private
            or ip_obj.is_loopback
            or ip_obj.is_link_local
            or ip_obj.is_multicast
            or ip_obj.is_reserved
        )
    except ValueError:
        return "." in hostname


def _save_financial_agent_mcp_settings(db: Session, payload: dict) -> dict:
    servers = financial_agents.normalize_mcp_servers(
        (payload or {}).get("servers") or []
    )[:50]
    if any(
        not _financial_agent_mcp_endpoint_allowed_for_save(item.get("endpoint") or "")
        for item in servers
    ):
        raise HTTPException(status_code=400, detail="MCP 白名单只允许可解析的公网 HTTP/HTTPS 地址")
    settings_value = {"servers": servers}
    _save_system_setting_json(db, FINANCIAL_AGENT_MCP_SETTINGS_KEY, settings_value)
    return settings_value


def _financial_agent_available_models(db: Session, user: Optional[UserModel] = None) -> list[str]:
    options = _sanitize_llm_model_options(
        _get_system_setting_json(db, LLM_MODEL_OPTIONS_KEY, _default_llm_model_options())
    )
    if user is not None and normalize_user_role(user.role) != "admin":
        return list(_allowed_llm_model_tiers(options, user.role).keys())
    models = [str(item).strip() for item in options.get("models") or [] if str(item).strip()]
    module_model = str((options.get("module_models") or {}).get("agent_analysis") or "").strip()
    if module_model and module_model not in models:
        models.append(module_model)
    for tier in _allowed_llm_model_tiers(options, "admin"):
        if tier not in models:
            models.append(tier)
    return models or [DEFAULT_LLM_MODEL]


def _financial_agent_validated_model(
    db: Session, user: UserModel, model_value: Optional[str]
) -> Optional[str]:
    model = str(model_value or "").strip()[:160]
    if not model or normalize_user_role(user.role) == "admin":
        return model or None
    if model not in _financial_agent_available_models(db, user):
        raise HTTPException(
            status_code=400,
            detail="模型不在管理员配置的可用模型列表中",
        )
    return model


def _financial_agent_mcp_for_user(
    db: Session,
    user: UserModel,
    requested_servers: Optional[List[Dict[str, Any]]],
) -> list[dict]:
    normalized = financial_agents.normalize_mcp_servers(requested_servers or [])
    mode = _financial_agent_role_limits(user.role)["mcp_mode"]
    if mode == "unrestricted":
        if any(
            not _financial_agent_mcp_endpoint_allowed_for_save(item.get("endpoint") or "")
            for item in normalized
        ):
            raise HTTPException(status_code=400, detail="MCP 只允许可解析的公网 HTTP/HTTPS 地址")
        return normalized
    if not normalized:
        return []
    if mode == "none":
        raise HTTPException(status_code=403, detail="当前套餐不支持为私有分析师配置 MCP")

    approved = _financial_agent_mcp_settings(db)["servers"]
    approved_map = {
        (str(item.get("endpoint") or "").rstrip("/"), str(item.get("tool") or "")): item
        for item in approved
        if item.get("enabled", True)
    }
    result = []
    for server in normalized:
        key = (
            str(server.get("endpoint") or "").rstrip("/"),
            str(server.get("tool") or ""),
        )
        allowed = approved_map.get(key)
        if not allowed:
            raise HTTPException(status_code=400, detail="所选 MCP 工具不在管理员白名单中")
        result.append(
            {
                **allowed,
                "arguments": server.get("arguments") or allowed.get("arguments") or {},
                "enabled": bool(server.get("enabled", True)),
            }
        )
    return result


