class AgentAnalysisSessionRequest(BaseModel):
    title: Optional[str] = None
    subject_type: str = "stock"
    subject: str
    symbol: Optional[str] = None
    market: str = "CN"
    agent_ids: List[int]
    max_rounds: int = 1
    model: Optional[str] = None


class AgentAnalysisUserMessageRequest(BaseModel):
    content: str
    continue_discussion: bool = True
    target_agent_id: Optional[int] = None


FINANCIAL_AGENT_ICON_MAX_LENGTH = 420_000
FINANCIAL_AGENT_ICON_URL_MAX_LENGTH = 1200
FINANCIAL_AGENT_IMAGE_ICON_RE = re.compile(
    r"^data:image/(?:png|jpe?g|webp|gif);base64,[a-z0-9+/=\s]+$",
    re.I,
)


def _normalize_financial_agent_icon(value: Optional[str]) -> str:
    icon = str(value or "").strip()
    if not icon:
        return "bot"
    if re.match(r"^https?://", icon, re.I):
        return icon[:FINANCIAL_AGENT_ICON_URL_MAX_LENGTH]
    if icon.startswith("data:image/"):
        compact_icon = re.sub(r"\s+", "", icon)
        if (
            len(compact_icon) <= FINANCIAL_AGENT_ICON_MAX_LENGTH
            and FINANCIAL_AGENT_IMAGE_ICON_RE.match(compact_icon)
        ):
            return compact_icon
        raise HTTPException(status_code=400, detail="分析师头像图片过大或格式不支持")
    normalized = re.sub(r"[^a-z0-9_\-]+", "_", icon.lower()).strip("_-")[:80]
    return normalized or "bot"


def _ensure_default_financial_agents(db: Session) -> None:
    existing = {
        row.name
        for row in db.query(FinancialAgentProfile)
        .filter(
            FinancialAgentProfile.owner_user_id.is_(None),
            FinancialAgentProfile.is_builtin.is_(True),
        )
        .all()
    }
    changed = False
    for item in financial_agents.default_financial_agent_profiles():
        if item["name"] in existing:
            continue
        db.add(
            FinancialAgentProfile(
                owner_user_id=None,
                name=item["name"],
                category=item["category"],
                icon=item.get("icon"),
                color=item.get("color"),
                description=item.get("description"),
                system_prompt=item["system_prompt"],
                model=None,
                tools_json=json.dumps(item.get("tools") or [], ensure_ascii=False),
                skills_json=json.dumps(item.get("skills") or [], ensure_ascii=False),
                mcp_servers_json="[]",
                visibility="public",
                is_builtin=True,
                enabled=True,
            )
        )
        changed = True
    if changed:
        db.commit()


def _financial_agent_can_edit(profile: FinancialAgentProfile, user: UserModel) -> bool:
    role = normalize_user_role(user.role)
    if role == "admin":
        return profile.owner_user_id in {None, user.id}
    return (
        _financial_agent_role_limits(role)["can_create_agents"]
        and profile.owner_user_id == user.id
    )


def _serialize_financial_agent(profile: FinancialAgentProfile, user: UserModel) -> dict:
    return {
        "id": profile.id,
        "owner_user_id": profile.owner_user_id,
        "name": profile.name,
        "category": profile.category or "general",
        "icon": profile.icon or "bot",
        "color": profile.color or "#2563eb",
        "description": profile.description or "",
        "system_prompt": profile.system_prompt or "",
        "model": profile.model or "",
        "tools": financial_agents.normalize_tool_keys(
            financial_agents.json_loads_or(profile.tools_json, [])
        ),
        "skills": financial_agents.normalize_skill_keys(
            financial_agents.json_loads_or(profile.skills_json, [])
        ),
        "mcp_servers": financial_agents.normalize_mcp_servers(
            financial_agents.json_loads_or(profile.mcp_servers_json, [])
        ),
        "visibility": profile.visibility or "private",
        "is_builtin": bool(profile.is_builtin),
        "enabled": bool(profile.enabled),
        "can_edit": _financial_agent_can_edit(profile, user),
        "created_at": profile.created_at.isoformat() if profile.created_at else None,
        "updated_at": profile.updated_at.isoformat() if profile.updated_at else None,
    }


def _financial_agent_visible_query(db: Session, user: UserModel):
    query = db.query(FinancialAgentProfile)
    role = normalize_user_role(user.role)
    if role == "admin":
        return query.filter(
            or_(
                FinancialAgentProfile.owner_user_id.is_(None),
                FinancialAgentProfile.owner_user_id == user.id,
            )
        )
    if not _financial_agent_role_limits(role)["can_create_agents"]:
        return query.filter(
            FinancialAgentProfile.owner_user_id.is_(None),
            FinancialAgentProfile.visibility == "public",
        )
    return query.filter(
        or_(
            FinancialAgentProfile.owner_user_id == user.id,
            and_(
                FinancialAgentProfile.owner_user_id.is_(None),
                FinancialAgentProfile.visibility == "public",
            ),
        )
    )


def _apply_financial_agent_payload(
    db: Session,
    row: FinancialAgentProfile,
    payload: FinancialAgentProfileRequest,
    user: UserModel,
) -> None:
    name = str(payload.name or "").strip()[:80]
    system_prompt = str(payload.system_prompt or "").strip()[:16000]
    if not name:
        raise HTTPException(status_code=400, detail="分析师名称不能为空")
    if len(system_prompt) < 20:
        raise HTTPException(status_code=400, detail="系统提示词至少需要 20 个字符")
    category = re.sub(r"[^a-z0-9_\-]+", "_", str(payload.category or "general").lower())[:40]
    visibility = str(payload.visibility or "private").strip().lower()
    if visibility not in {"private", "public"}:
        visibility = "private"
    if normalize_user_role(user.role) != "admin":
        visibility = "private"
    row.name = name
    row.category = category or "general"
    row.icon = _normalize_financial_agent_icon(payload.icon)
    row.color = str(payload.color or "#2563eb").strip()[:20]
    row.description = str(payload.description or "").strip()[:1200]
    row.system_prompt = system_prompt
    row.model = _financial_agent_validated_model(db, user, payload.model)
    row.tools_json = json.dumps(
        [] if COMMUNITY_EDITION else financial_agents.normalize_tool_keys(payload.tools), ensure_ascii=False
    )
    row.skills_json = json.dumps(
        [] if COMMUNITY_EDITION else financial_agents.normalize_skill_keys(payload.skills), ensure_ascii=False
    )
    row.mcp_servers_json = json.dumps(
        [] if COMMUNITY_EDITION else _financial_agent_mcp_for_user(db, user, payload.mcp_servers),
        ensure_ascii=False,
    )
    row.visibility = visibility
    row.enabled = bool(payload.enabled)


def _agent_analysis_capabilities(db: Session, user: UserModel) -> dict:
    limits = _financial_agent_role_limits(user.role)
    approved_mcp = (
        _financial_agent_mcp_settings(db)["servers"]
        if limits["mcp_mode"] in {"allowlist", "unrestricted"}
        else []
    )
    return {
        **limits,
        "max_session_rounds": FINANCIAL_AGENT_MAX_SESSION_ROUNDS,
        "can_configure_mcp_allowlist": limits["role"] == "admin",
        "can_enter_custom_model": limits["role"] == "admin",
        "available_models": _financial_agent_available_models(db, user),
        "approved_mcp_servers": approved_mcp,
        "costs": {
            "per_agent_round": _ai_credit_cost(db, "agent_analysis_turn"),
            "moderator_summary": _ai_credit_cost(db, "agent_analysis_moderator"),
        },
        "credit_summary": _credit_summary(db, user),
    }


@app.get(
    "/api/agent-analysis/capabilities",
    dependencies=[Depends(require_permission("agent_analysis.use"))],
)
def get_agent_analysis_capabilities(
    db: Session = Depends(get_db), current_user: UserModel = Depends(get_current_user)
):
    return _agent_analysis_capabilities(db, current_user)


@app.post(
    "/api/agent-analysis/settings",
    dependencies=[Depends(require_permission("system.manage"))],
)
def save_agent_analysis_settings(
    payload: dict = Body(...),
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    _save_financial_agent_mcp_settings(db, payload)
    return {"status": "ok", **_agent_analysis_capabilities(db, current_user)}


@app.get(
    "/api/agent-analysis/agents",
    dependencies=[Depends(require_permission("agent_analysis.use"))],
)
def list_financial_agents(
    db: Session = Depends(get_db), current_user: UserModel = Depends(get_current_user)
):
    _ensure_default_financial_agents(db)
    rows = (
        _financial_agent_visible_query(db, current_user)
        .order_by(
            FinancialAgentProfile.is_builtin.desc(),
            FinancialAgentProfile.enabled.desc(),
            FinancialAgentProfile.created_at.asc(),
        )
        .all()
    )
    return {"agents": [_serialize_financial_agent(row, current_user) for row in rows]}


@app.post(
    "/api/agent-analysis/agents",
    dependencies=[Depends(require_permission("agent_analysis.use"))],
)
def create_financial_agent(
    payload: FinancialAgentProfileRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    if not _financial_agent_role_limits(current_user.role)["can_create_agents"]:
        raise HTTPException(status_code=403, detail="当前套餐仅可使用管理员提供的分析师模板")
    row = FinancialAgentProfile(
        owner_user_id=current_user.id,
        is_builtin=False,
        visibility="private",
    )
    _apply_financial_agent_payload(db, row, payload, current_user)
    if normalize_user_role(current_user.role) == "admin" and row.visibility == "public":
        row.owner_user_id = None
    db.add(row)
    db.commit()
    db.refresh(row)
    return {"agent": _serialize_financial_agent(row, current_user)}


@app.put(
    "/api/agent-analysis/agents/{agent_id}",
    dependencies=[Depends(require_permission("agent_analysis.use"))],
)
def update_financial_agent(
    agent_id: int,
    payload: FinancialAgentProfileRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    row = db.query(FinancialAgentProfile).filter(FinancialAgentProfile.id == agent_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="分析师不存在")
    if not _financial_agent_can_edit(row, current_user):
        raise HTTPException(status_code=403, detail="无权修改该分析师")
    _apply_financial_agent_payload(db, row, payload, current_user)
    if normalize_user_role(current_user.role) == "admin" and not row.is_builtin:
        row.owner_user_id = None if row.visibility == "public" else current_user.id
    db.commit()
    db.refresh(row)
    return {"agent": _serialize_financial_agent(row, current_user)}


@app.delete(
    "/api/agent-analysis/agents/{agent_id}",
    dependencies=[Depends(require_permission("agent_analysis.use"))],
)
def delete_financial_agent(
    agent_id: int,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    row = db.query(FinancialAgentProfile).filter(FinancialAgentProfile.id == agent_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="分析师不存在")
    if not _financial_agent_can_edit(row, current_user):
        raise HTTPException(status_code=403, detail="无权删除该分析师")
    if row.is_builtin:
        raise HTTPException(status_code=400, detail="内置分析师不能删除，可将其停用")
    db.query(AgentAnalysisMessage).filter(AgentAnalysisMessage.agent_id == row.id).update(
        {AgentAnalysisMessage.agent_id: None}, synchronize_session=False
    )
    db.delete(row)
    db.commit()
    return {"ok": True}


def _parse_mcp_http_response(response: requests.Response) -> dict:
    content_type = str(response.headers.get("content-type") or "").lower()
    if "text/event-stream" in content_type:
        payloads: list[dict] = []
        for line in response.text.splitlines():
            if not line.startswith("data:"):
                continue
            raw = line[5:].strip()
            if not raw or raw == "[DONE]":
                continue
            try:
                item = json.loads(raw)
                if isinstance(item, dict):
                    payloads.append(item)
            except Exception:
                continue
        return payloads[-1] if payloads else {}
    body = response.json()
    return body if isinstance(body, dict) else {"result": body}


def _call_financial_agent_mcp(server: dict, subject: str, symbol: str = "") -> dict:
    endpoint = str(server.get("endpoint") or "").strip()
    tool_name = str(server.get("tool") or "").strip()
    label = str(server.get("name") or "MCP").strip()[:80]
    if not endpoint or not tool_name or not server.get("enabled", True):
        return {"name": label, "tool": tool_name, "status": "disabled"}
    if not _assistant_is_public_http_url(endpoint):
        return {
            "name": label,
            "tool": tool_name,
            "status": "blocked",
            "error": "MCP 地址未通过 SSRF 公网校验",
        }
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
        "User-Agent": "QuartSys-AgentAnalysis/1.0",
    }
    call_args = dict(server.get("arguments") or {})
    call_args.setdefault("query", subject)
    if symbol:
        call_args.setdefault("symbol", symbol)
    try:
        init_response = requests.post(
            endpoint,
            headers=headers,
            json={
                "jsonrpc": "2.0",
                "id": uuid.uuid4().hex,
                "method": "initialize",
                "params": {
                    "protocolVersion": "2025-03-26",
                    "capabilities": {},
                    "clientInfo": {"name": "QuartSys", "version": "1.0"},
                },
            },
            timeout=(4, FINANCIAL_AGENT_MCP_TIMEOUT_SECONDS),
        )
        session_id = init_response.headers.get("Mcp-Session-Id") or init_response.headers.get(
            "mcp-session-id"
        )
        if init_response.status_code < 400 and session_id:
            headers["Mcp-Session-Id"] = session_id
            try:
                requests.post(
                    endpoint,
                    headers=headers,
                    json={
                        "jsonrpc": "2.0",
                        "method": "notifications/initialized",
                        "params": {},
                    },
                    timeout=(4, 6),
                )
            except Exception:
                pass
        response = requests.post(
            endpoint,
            headers=headers,
            json={
                "jsonrpc": "2.0",
                "id": uuid.uuid4().hex,
                "method": "tools/call",
                "params": {"name": tool_name, "arguments": call_args},
            },
            timeout=(4, FINANCIAL_AGENT_MCP_TIMEOUT_SECONDS),
        )
        response.raise_for_status()
        payload = _parse_mcp_http_response(response)
        if payload.get("error"):
            return {
                "name": label,
                "tool": tool_name,
                "status": "error",
                "error": str(payload.get("error"))[:500],
            }
        result = payload.get("result")
        serialized_result = json.dumps(result, ensure_ascii=False, default=str)
        safe_result = (
            json.loads(serialized_result)
            if len(serialized_result) <= 12000
            else {"truncated": True, "content": serialized_result[:12000]}
        )
        return {
            "name": label,
            "tool": tool_name,
            "status": "ok",
            "result": safe_result,
        }
    except Exception as exc:
        return {
            "name": label,
            "tool": tool_name,
            "status": "error",
            "error": _assistant_sanitize_error(exc),
        }


def _financial_agent_mcp_context(profile: FinancialAgentProfile, subject: str, symbol: str) -> list[dict]:
    servers = financial_agents.normalize_mcp_servers(
        financial_agents.json_loads_or(profile.mcp_servers_json, [])
    )
    return [
        _call_financial_agent_mcp(server, subject, symbol)
        for server in servers[:3]
        if server.get("enabled", True)
    ]


def _financial_agent_research_intents(subject: str, context: dict) -> set[str]:
    text = str(subject or "").lower()
    intents = {"general_research"}
    if context.get("targets"):
        intents.add("stock_research")
    if any(token in text for token in ("行业", "板块", "产业链", "赛道", "industry", "sector", "supply chain")):
        intents.add("industry_research")
    if any(token in text for token in ("新闻", "事件", "政策", "冲突", "并购", "event", "news", "policy", "merger")):
        intents.add("event_research")
    if any(token in text for token in ("情绪", "舆情", "讨论", "sentiment", "social")):
        intents.add("sentiment_research")
    if any(token in text for token in ("财报", "估值", "基本面", "roe", "pb", "pe", "financial", "valuation")):
        intents.add("fundamental_research")
    if any(token in text for token in ("技术", "走势", "均线", "macd", "rsi", "technical", "trend")):
        intents.add("technical_research")
    if any(token in text for token in ("组合", "仓位", "资产配置", "portfolio", "allocation")):
        intents.add("portfolio_research")
    return intents


def _route_financial_agent_skills(
    db: Session,
    profile: FinancialAgentProfile,
    subject: str,
    context: dict,
) -> list[dict]:
    keys = financial_agents.normalize_skill_keys(
        financial_agents.json_loads_or(profile.skills_json, [])
    )
    if not keys:
        return []
    available = {
        str(item.get("key")): item
        for item in _assistant_skills_settings(db, enabled_only=True).get("skills", [])
    }
    subject_text = str(subject or "").lower()
    intents = _financial_agent_research_intents(subject, context)
    market_code = _normalize_market_code(context.get("market") or "CN").lower()
    profile_category = str(profile.category or "general").lower()
    scored: list[tuple[int, int, dict]] = []
    for key in keys:
        skill = available.get(key)
        if not skill:
            continue
        if not skill.get("auto_route", True):
            scored.append((1000, int(skill.get("priority") or 50), skill))
            continue
        score = 0
        routing_metadata = any(
            skill.get(field) for field in ("intents", "keywords", "markets", "categories")
        )
        if not routing_metadata:
            score = 1
        score += 5 * sum(1 for keyword in skill.get("keywords") or [] if keyword and keyword in subject_text)
        score += 4 * sum(1 for intent in skill.get("intents") or [] if intent in intents)
        markets = {str(item).lower() for item in skill.get("markets") or []}
        if not markets or market_code in markets or "all" in markets:
            score += 2
        categories = {str(item).lower() for item in skill.get("categories") or []}
        if profile_category in categories or "all" in categories:
            score += 2
        if score > 0:
            scored.append((score, int(skill.get("priority") or 50), skill))
    if not scored:
        fallback = [available[key] for key in keys if key in available]
        fallback.sort(key=lambda item: int(item.get("priority") or 50), reverse=True)
        return fallback[:1]
    scored.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return [item[2] for item in scored[:3]]


def _financial_agent_skill_text(
    db: Session,
    profile: FinancialAgentProfile,
    subject: str,
    context: dict,
) -> tuple[str, list[dict]]:
    routed = _route_financial_agent_skills(db, profile, subject, context)
    pieces = [_assistant_skill_instruction_text(skill) for skill in routed]
    metadata = [
        {
            "key": skill.get("key"),
            "name": skill.get("name"),
            "intents": skill.get("intents") or [],
        }
        for skill in routed
    ]
    return "\n\n".join(pieces)[:36000], metadata


def _filter_agent_research_context(context: dict, tools: list[str]) -> dict:
    enabled = set(tools)
    result = {
        "query": context.get("query"),
        "market": context.get("market"),
        "evidence_scope": context.get("evidence_scope"),
        "targets": context.get("targets") if "database" in enabled else [],
        "market_temperature": context.get("market_temperature") if "database" in enabled else {},
        "top_concepts": context.get("top_concepts") if "database" in enabled else [],
        "limitations": context.get("limitations") or [],
        "research_tools": context.get("research_tools") or {},
    }
    result["f10"] = context.get("f10") if "f10" in enabled else {"items": [], "source": "agent.disabled"}
    result["news"] = context.get("news") if "news" in enabled else {"items": [], "source": "agent.disabled"}
    result["web_search"] = (
        context.get("web_search")
        if "web_search" in enabled
        else {"items": [], "source": "agent.disabled"}
    )
    evidence = []
    for item in context.get("evidence_chain") or []:
        source_type = str(item.get("source_type") or "")
        if source_type == "web_search" and "web_search" not in enabled:
            continue
        if source_type in {"news", "research_report"} and "news" not in enabled:
            continue
        evidence.append(item)
    result["evidence_chain"] = evidence[:30]
    return result


def _agent_analysis_market_blocks(db: Session, context: dict) -> list[dict]:
    targets = context.get("targets") or []
    if not targets:
        return [
            {
                "type": "callout",
                "tone": "warning",
                "content": "未从数据库识别到目标股票，本轮将以事件、新闻和用户上下文为主。",
            }
        ]
    target = targets[0]
    latest = target.get("latest") or {}
    currency_symbol = target.get("currency_symbol") or data_sources.market_currency_symbol(
        target.get("market") or "CN"
    )
    latest_price = latest.get("close")
    latest_change = latest.get("change_pct")
    blocks: list[dict] = [
        {
            "type": "metrics",
            "items": [
                {
                    "label": "最新价",
                    "value": f"{currency_symbol}{float(latest_price):.3f}" if latest_price is not None else "--",
                    "trend": "neutral",
                },
                {
                    "label": "当日涨跌",
                    "value": f"{float(latest_change):+.2f}%" if latest_change is not None else "--",
                    "trend": "up" if (latest_change or 0) >= 0 else "down",
                },
                {"label": "PE", "value": target.get("pe_ratio", "--"), "trend": "neutral"},
                {"label": "PB", "value": target.get("pb_ratio", "--"), "trend": "neutral"},
                {"label": "ROE", "value": f"{target.get('roe', '--')}%", "trend": "neutral"},
            ],
        }
    ]
    code = str(target.get("code") or "")
    if code:
        rows = (
            db.query(DailyPrice)
            .filter(DailyPrice.stock_code == code)
            .order_by(DailyPrice.date.desc())
            .limit(90)
            .all()
        )
        ordered = list(reversed(rows))
        categories = [str(row.date) for row in ordered if row.date]
        closes = [data_sources.safe_float(row.close) for row in ordered]
        if categories and closes:
            ma20 = []
            for index in range(len(closes)):
                values = [value for value in closes[max(0, index - 19) : index + 1] if value is not None]
                ma20.append(round(sum(values) / len(values), 3) if values else None)
            blocks.append(
                {
                    "type": "chart",
                    "chart_type": "line",
                    "title": f"{code} 近90日收盘价与MA20",
                    "categories": categories,
                    "series": [
                        {"name": "收盘价", "data": closes},
                        {"name": "MA20", "data": ma20},
                    ],
                }
            )
    evidence_rows = []
    for item in (context.get("evidence_chain") or [])[:8]:
        evidence_rows.append(
            [
                str(item.get("title") or item.get("category") or "证据"),
                str(item.get("source") or item.get("domain") or ""),
                str(item.get("strength") or "needs_checking"),
            ]
        )
    if evidence_rows:
        blocks.append(
            {
                "type": "table",
                "columns": ["证据", "来源", "强度"],
                "rows": evidence_rows,
            }
        )
    return blocks


def _serialize_agent_analysis_message(row: AgentAnalysisMessage) -> dict:
    return {
        "id": row.id,
        "session_id": row.session_id,
        "agent_id": row.agent_id,
        "sender_type": row.sender_type,
        "sender_name": row.sender_name,
        "round_no": row.round_no or 0,
        "content_markdown": row.content_markdown or "",
        "blocks": financial_agents.json_loads_or(row.blocks_json, []),
        "meta": financial_agents.json_loads_or(row.meta_json, {}),
        "created_at": row.created_at.isoformat() if row.created_at else None,
    }


def _agent_analysis_messages(db: Session, session_id: int) -> list[dict]:
    rows = (
        db.query(AgentAnalysisMessage)
        .filter(AgentAnalysisMessage.session_id == session_id)
        .order_by(AgentAnalysisMessage.id.asc())
        .all()
    )
    return [_serialize_agent_analysis_message(row) for row in rows]


def _agent_analysis_session_query(db: Session, session_id: int, user: UserModel):
    return db.query(AgentAnalysisSession).filter(
        AgentAnalysisSession.id == session_id,
        AgentAnalysisSession.user_id == user.id,
    )


def _serialize_agent_analysis_session(
    db: Session,
    row: AgentAnalysisSession,
    include_messages: bool = False,
) -> dict:
    progress_payload = financial_agents.json_loads_or(row.progress_json, {})
    market_code = _normalize_market_code(
        progress_payload.get("market")
        or (
            data_sources.equity_market(row.symbol)
            if row.symbol and data_sources.is_supported_equity_code(row.symbol)
            else "CN"
        )
    )
    message_count = (
        db.query(func.count(AgentAnalysisMessage.id))
        .filter(AgentAnalysisMessage.session_id == row.id)
        .scalar()
        or 0
    )
    payload = {
        "id": row.id,
        "title": row.title,
        "subject_type": row.subject_type,
        "subject": row.subject,
        "symbol": row.symbol or "",
        "market": market_code,
        "agent_ids": financial_agents.json_loads_or(row.selected_agent_ids_json, []),
        "model": row.model or "",
        "max_rounds": row.max_rounds or 1,
        "current_round": row.current_round or 0,
        "status": row.status or "pending",
        "progress": progress_payload,
        "result": financial_agents.json_loads_or(row.result_json, {}),
        "memory": {
            "enabled": True,
            "summary": row.memory_summary or "",
            "message_count": int(message_count),
            "round_count": int(row.current_round or 0),
            "context_policy": "user_isolated_persistent",
        },
        "report_ready": bool(row.report_markdown),
        "error": row.error or "",
        "created_at": row.created_at.isoformat() if row.created_at else None,
        "updated_at": row.updated_at.isoformat() if row.updated_at else None,
    }
    if include_messages:
        messages = _agent_analysis_messages(db, row.id)
        has_initial_request = any(
            item.get("sender_type") == "user"
            and bool((item.get("meta") or {}).get("initial_request"))
            for item in messages
        )
        if not has_initial_request:
            owner = db.query(UserModel).filter(UserModel.id == row.user_id).first()
            initial_markdown = f"## 研究问题\n\n{row.subject}"
            if row.symbol:
                initial_markdown += f"\n\n**研究标的：** `{row.symbol}`"
            messages.insert(
                0,
                {
                    "id": -int(row.id),
                    "session_id": row.id,
                    "agent_id": None,
                    "sender_type": "user",
                    "sender_name": owner.username if owner else "用户",
                    "round_no": 0,
                    "content_markdown": initial_markdown,
                    "blocks": [{"type": "markdown", "content": initial_markdown}],
                    "meta": {"initial_request": True, "legacy_session": True},
                    "created_at": row.created_at.isoformat() if row.created_at else None,
                },
            )
        payload["messages"] = messages
    return payload


def _set_agent_analysis_progress(db: Session, row: AgentAnalysisSession, **values) -> None:
    progress = financial_agents.json_loads_or(row.progress_json, {})
    progress.update(values)
    progress["updated_at"] = datetime.now().isoformat(timespec="seconds")
    row.progress_json = json.dumps(progress, ensure_ascii=False, default=str)
    row.updated_at = datetime.now()
    db.commit()


def _agent_analysis_profiles_for_round(
    db: Session,
    session_id: int,
    round_no: int,
    profiles: list[FinancialAgentProfile],
) -> list[FinancialAgentProfile]:
    user_message = (
        db.query(AgentAnalysisMessage)
        .filter(
            AgentAnalysisMessage.session_id == session_id,
            AgentAnalysisMessage.sender_type == "user",
            AgentAnalysisMessage.round_no == round_no,
        )
        .order_by(AgentAnalysisMessage.id.desc())
        .first()
    )
    if not user_message:
        return profiles
    meta = financial_agents.json_loads_or(user_message.meta_json, {})
    target_agent_id = meta.get("target_agent_id")
    if target_agent_id in {None, ""}:
        return profiles
    try:
        parsed_target = int(target_agent_id)
    except (TypeError, ValueError):
        return profiles
    return [profile for profile in profiles if profile.id == parsed_target]


def _run_agent_analysis_profile(
    *,
    profile_id: int,
    user_id: int,
    session_id: int,
    round_no: int,
    subject: str,
    symbol: str,
    session_model: Optional[str],
    research_context: dict,
    transcript: list[dict],
) -> dict:
    worker_db = SessionLocal()
    try:
        profile = (
            worker_db.query(FinancialAgentProfile)
            .filter(FinancialAgentProfile.id == profile_id)
            .first()
        )
        user = worker_db.query(UserModel).filter(UserModel.id == user_id).first()
        if not profile or not user or not profile.enabled:
            raise ValueError("分析师当前不可用")
        tools = financial_agents.normalize_tool_keys(
            financial_agents.json_loads_or(profile.tools_json, [])
        )
        agent_context = _filter_agent_research_context(research_context, tools)
        mcp_context = _financial_agent_mcp_context(profile, subject, symbol)
        profile_payload = _serialize_financial_agent(profile, user)
        skill_text, routed_skills = _financial_agent_skill_text(
            worker_db,
            profile,
            subject,
            agent_context,
        )
        system_prompt, user_prompt = financial_agents.build_agent_prompts(
            profile_payload,
            subject,
            agent_context,
            transcript,
            skill_text=skill_text,
            mcp_context=mcp_context,
        )
        cfg = _llm_config_for_module(
            worker_db,
            user_id=user_id,
            module_key="agent_analysis",
            model_override=profile.model or session_model or None,
        )
        cfg["_usage_credits"] = _llm_tier_credit_cost(
            worker_db,
            "agent_analysis_turn",
            profile.model or session_model or None,
            user,
        )
        cfg["_usage_reference_id"] = (
            f"agent_analysis:{session_id}:round:{round_no}:agent:{profile.id}"
        )
        response_payload = None
        fallback_reason = ""
        if cfg.get("api_key") and _direct_llm_supported(cfg):
            try:
                raw = _assistant_call_json_llm(
                    cfg,
                    [
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": user_prompt},
                    ],
                    temperature=0.35,
                    read_timeout=_assistant_timeout_seconds(
                        "AGENT_ANALYSIS_LLM_TIMEOUT_SECONDS",
                        150.0,
                        20.0,
                        360.0,
                    ),
                )
                response_payload = financial_agents.parse_agent_response(raw)
            except Exception as exc:
                fallback_reason = _assistant_sanitize_error(exc)
        else:
            fallback_reason = "当前 AI 分析师模型未配置或协议不可用"
        if not response_payload or not response_payload.get("markdown"):
            response_payload = financial_agents.build_local_agent_response(
                profile_payload,
                agent_context,
                fallback_reason,
            )
        return {
            "profile_id": profile.id,
            "profile_name": profile.name,
            "response": response_payload,
            "model": cfg.get("model"),
            "provider": cfg.get("provider"),
            "tools": tools,
            "skills": routed_skills,
            "mcp": mcp_context,
            "fallback_reason": fallback_reason,
        }
    finally:
        worker_db.close()


def _run_agent_analysis_session(session_id: int, user_id: int) -> None:
    db = SessionLocal()
    rerun_requested = False
    try:
        session = (
            db.query(AgentAnalysisSession)
            .filter(AgentAnalysisSession.id == session_id, AgentAnalysisSession.user_id == user_id)
            .first()
        )
        user = db.query(UserModel).filter(UserModel.id == user_id).first()
        if not session or not user:
            return
        session_progress = financial_agents.json_loads_or(session.progress_json, {})
        session_market = _normalize_market_code(
            session_progress.get("market")
            or (
                data_sources.equity_market(session.symbol)
                if session.symbol and data_sources.is_supported_equity_code(session.symbol)
                else "CN"
            )
        )
        session.status = "running"
        session.error = ""
        _set_agent_analysis_progress(
            db,
            session,
            stage="准备数据库与资讯上下文",
            percent=3,
            market=session_market,
        )

        subject_query = " ".join(
            item for item in [session.subject, session.symbol or ""] if item
        )
        research_context = _assistant_research_context(
            subject_query,
            db,
            current_user=user,
            market_code=session_market,
        )
        research_context["committee_memory"] = {
            "summary": session.memory_summary or "",
            "message_count": (
                db.query(func.count(AgentAnalysisMessage.id))
                .filter(AgentAnalysisMessage.session_id == session.id)
                .scalar()
                or 0
            ),
            "current_round": int(session.current_round or 0),
            "scope": "current_user_current_session_only",
        }
        if not db.query(AgentAnalysisMessage).filter(
            AgentAnalysisMessage.session_id == session.id,
            AgentAnalysisMessage.sender_type == "system",
        ).first():
            tool_status = research_context.get("research_tools") or {}
            system_markdown = (
                "### 研究上下文已准备\n\n"
                f"数据库目标 {len(research_context.get('targets') or [])} 个，"
                f"新闻 {len((research_context.get('news') or {}).get('items') or [])} 条，"
                f"联网结果 {len((research_context.get('web_search') or {}).get('items') or [])} 条。"
            )
            db.add(
                AgentAnalysisMessage(
                    session_id=session.id,
                    sender_type="system",
                    sender_name="研究上下文",
                    round_no=0,
                    content_markdown=system_markdown,
                    blocks_json=json.dumps(
                        _agent_analysis_market_blocks(db, research_context),
                        ensure_ascii=False,
                        default=str,
                    ),
                    meta_json=json.dumps({"research_tools": tool_status}, ensure_ascii=False),
                )
            )
            db.commit()

        selected_ids = [
            int(item)
            for item in financial_agents.json_loads_or(session.selected_agent_ids_json, [])
            if str(item).isdigit()
        ][:FINANCIAL_AGENT_MAX_SELECTED]
        profiles = (
            _financial_agent_visible_query(db, user)
            .filter(
                FinancialAgentProfile.id.in_(selected_ids),
                FinancialAgentProfile.enabled.is_(True),
            )
            .all()
        )
        profile_by_id = {profile.id: profile for profile in profiles}
        profiles = [profile_by_id[item] for item in selected_ids if item in profile_by_id]
        if len(profiles) < (1 if COMMUNITY_EDITION else 2):
            raise ValueError(
                "至少需要一位可用分析师" if COMMUNITY_EDITION else "至少需要两个可用分析师参与讨论"
            )

        while True:
            db.refresh(session)
            start_round = max(1, int(session.current_round or 0) + 1)
            end_round = min(
                int(session.max_rounds or 1),
                FINANCIAL_AGENT_MAX_SESSION_ROUNDS,
            )
            if start_round > end_round:
                break
            for round_no in range(start_round, end_round + 1):
                round_profiles = _agent_analysis_profiles_for_round(
                    db, session.id, round_no, profiles
                )
                if not round_profiles:
                    raise ValueError("本轮指定的分析师当前不可用")
                transcript = _agent_analysis_messages(db, session.id)
                _set_agent_analysis_progress(
                    db,
                    session,
                    stage=f"第 {round_no} 轮 · {len(round_profiles)} 位分析师并行讨论中",
                    percent=10,
                    current_round=round_no,
                    current_agent="parallel",
                    agent_index=0,
                    agent_total=len(round_profiles),
                    parallel=True,
                )
                max_workers = max(1, min(len(round_profiles), FINANCIAL_AGENT_MAX_SELECTED))
                with concurrent.futures.ThreadPoolExecutor(
                    max_workers=max_workers,
                    thread_name_prefix=f"agent-analysis-{session.id}-r{round_no}",
                ) as executor:
                    future_map = {
                        executor.submit(
                            _run_agent_analysis_profile,
                            profile_id=profile.id,
                            user_id=user_id,
                            session_id=session.id,
                            round_no=round_no,
                            subject=session.subject,
                            symbol=session.symbol or "",
                            session_model=session.model,
                            research_context=research_context,
                            transcript=transcript,
                        ): profile
                        for profile in round_profiles
                    }
                    completed_agents = 0
                    round_results: dict[int, dict] = {}
                    for future in concurrent.futures.as_completed(future_map):
                        profile = future_map[future]
                        try:
                            round_results[profile.id] = future.result()
                        except Exception as exc:
                            fallback_reason = _assistant_sanitize_error(exc)
                            profile_payload = _serialize_financial_agent(profile, user)
                            agent_context = _filter_agent_research_context(
                                research_context,
                                financial_agents.normalize_tool_keys(
                                    financial_agents.json_loads_or(profile.tools_json, [])
                                ),
                            )
                            round_results[profile.id] = {
                                "profile_id": profile.id,
                                "profile_name": profile.name,
                                "response": financial_agents.build_local_agent_response(
                                    profile_payload,
                                    agent_context,
                                    fallback_reason,
                                ),
                                "model": profile.model or session.model,
                                "provider": "",
                                "tools": financial_agents.normalize_tool_keys(
                                    financial_agents.json_loads_or(profile.tools_json, [])
                                ),
                                "mcp": [],
                                "fallback_reason": fallback_reason,
                            }
                        completed_agents += 1
                        _set_agent_analysis_progress(
                            db,
                            session,
                            stage=f"第 {round_no} 轮 · 并行讨论 {completed_agents}/{len(round_profiles)}",
                            percent=min(
                                88,
                                10 + int(completed_agents / len(round_profiles) * 74),
                            ),
                            current_round=round_no,
                            current_agent=profile.name,
                            agent_index=completed_agents,
                            agent_total=len(round_profiles),
                            parallel=True,
                        )

                for profile in round_profiles:
                    agent_result = round_results[profile.id]
                    response_payload = agent_result["response"]
                    db.add(
                        AgentAnalysisMessage(
                            session_id=session.id,
                            agent_id=profile.id,
                            sender_type="agent",
                            sender_name=profile.name,
                            round_no=round_no,
                            content_markdown=response_payload.get("markdown") or "",
                            blocks_json=json.dumps(
                                response_payload.get("blocks") or [], ensure_ascii=False, default=str
                            ),
                            meta_json=json.dumps(
                                {
                                    "stance": response_payload.get("stance"),
                                    "confidence": response_payload.get("confidence"),
                                    "evidence": response_payload.get("evidence") or [],
                                    "model": agent_result.get("model"),
                                    "provider": agent_result.get("provider"),
                                    "tools": agent_result.get("tools") or [],
                                    "skills": agent_result.get("skills") or [],
                                    "mcp": agent_result.get("mcp") or [],
                                    "fallback_reason": agent_result.get("fallback_reason") or "",
                                    "parallel_round": True,
                                },
                                ensure_ascii=False,
                                default=str,
                            ),
                        )
                    )
                db.commit()
                session.current_round = round_no
                db.commit()
            db.refresh(session)
            if int(session.current_round or 0) >= int(session.max_rounds or 0):
                break

        _set_agent_analysis_progress(
            db,
            session,
            stage="生成分析摘要" if COMMUNITY_EDITION else "投资委员会汇总结论",
            percent=92,
        )
        transcript = _agent_analysis_messages(db, session.id)
        moderator_system, moderator_user = financial_agents.build_moderator_prompts(
            session.subject, research_context, transcript
        )
        cfg = _llm_config_for_module(
            db,
            user_id=user_id,
            module_key="agent_analysis",
            model_override=session.model or None,
        )
        cfg["_usage_credits"] = _llm_tier_credit_cost(
            db,
            "agent_analysis_moderator",
            session.model or None,
            db.query(UserModel).filter(UserModel.id == user_id).first(),
        )
        cfg["_usage_reference_id"] = f"agent_analysis:{session.id}:moderator"
        final_result = None
        moderator_error = ""
        if not COMMUNITY_EDITION and cfg.get("api_key") and _direct_llm_supported(cfg):
            try:
                raw = _assistant_call_json_llm(
                    cfg,
                    [
                        {"role": "system", "content": moderator_system},
                        {"role": "user", "content": moderator_user},
                    ],
                    temperature=0.2,
                    read_timeout=_assistant_timeout_seconds(
                        "AGENT_ANALYSIS_LLM_TIMEOUT_SECONDS", 150.0, 20.0, 360.0
                    ),
                )
                final_result = financial_agents.parse_moderator_response(raw, transcript)
            except Exception as exc:
                moderator_error = _assistant_sanitize_error(exc)
        if not final_result:
            final_result = financial_agents.build_local_final_result(transcript, moderator_error)
        confidence_chart = financial_agents.confidence_chart_block(transcript)
        if confidence_chart:
            final_result.setdefault("blocks", []).append(confidence_chart)
        db.add(
            AgentAnalysisMessage(
                session_id=session.id,
                sender_type="moderator",
                sender_name="分析摘要" if COMMUNITY_EDITION else "投资委员会主持人",
                round_no=session.current_round or 1,
                content_markdown=final_result.get("markdown") or "",
                blocks_json=json.dumps(final_result.get("blocks") or [], ensure_ascii=False),
                meta_json=json.dumps(
                    {
                        "stance": final_result.get("stance"),
                        "confidence": final_result.get("confidence"),
                        "decision": final_result.get("decision"),
                        "risk_level": final_result.get("risk_level"),
                        "model": cfg.get("model"),
                        "moderator_error": moderator_error,
                    },
                    ensure_ascii=False,
                ),
            )
        )
        report = financial_agents.build_markdown_report(
            {
                "subject": session.subject,
                "subject_type": session.subject_type,
                "symbol": session.symbol,
            },
            transcript,
            final_result,
        )
        session.status = "done"
        session.result_json = json.dumps(final_result, ensure_ascii=False, default=str)
        session.memory_summary = "\n".join(
            item
            for item in [
                f"{'分析结论' if COMMUNITY_EDITION else '委员会决策'}：{final_result.get('decision') or '继续观察'}",
                f"立场：{final_result.get('stance') or 'neutral'}；置信度：{final_result.get('confidence') or 0}/100；风险：{final_result.get('risk_level') or '中'}",
                "关键结论：" + "；".join(final_result.get("key_points") or []),
                "主要分歧：" + "；".join(final_result.get("disagreements") or []),
                "后续观察：" + "；".join(final_result.get("watch_items") or []),
            ]
            if item and not item.endswith("：")
        )[:12000]
        session.report_markdown = report
        session.error = ""
        session.progress_json = json.dumps(
            {
                "stage": "讨论完成",
                "percent": 100,
                "current_round": session.current_round,
                "market": session_market,
                "updated_at": datetime.now().isoformat(timespec="seconds"),
            },
            ensure_ascii=False,
        )
        session.updated_at = datetime.now()
        db.commit()
        db.refresh(session)
        if int(session.max_rounds or 0) > int(session.current_round or 0):
            session.status = "pending"
            session.progress_json = json.dumps(
                {
                    "stage": "检测到新的用户追问，继续下一轮讨论",
                    "percent": 0,
                    "current_round": session.current_round,
                    "market": session_market,
                },
                ensure_ascii=False,
            )
            db.commit()
            rerun_requested = True
    except Exception as exc:
        session = db.query(AgentAnalysisSession).filter(AgentAnalysisSession.id == session_id).first()
        if session:
            session.status = "failed"
            session.error = _assistant_sanitize_error(exc)
            session.progress_json = json.dumps(
                {
                    "stage": "讨论失败",
                    "percent": 100,
                    "market": _normalize_market_code(
                        financial_agents.json_loads_or(
                            session.progress_json, {}
                        ).get("market")
                        or "CN"
                    ),
                    "error": session.error,
                    "updated_at": datetime.now().isoformat(timespec="seconds"),
                },
                ensure_ascii=False,
            )
            db.commit()
    finally:
        db.close()
    if rerun_requested:
        _run_agent_analysis_session(session_id, user_id)


@app.get(
    "/api/agent-analysis/sessions",
    dependencies=[Depends(require_permission("agent_analysis.use"))],
)
def list_agent_analysis_sessions(
    db: Session = Depends(get_db), current_user: UserModel = Depends(get_current_user)
):
    query = db.query(AgentAnalysisSession).filter(
        AgentAnalysisSession.user_id == current_user.id
    )
    rows = query.order_by(AgentAnalysisSession.updated_at.desc(), AgentAnalysisSession.id.desc()).limit(80).all()
    return {"sessions": [_serialize_agent_analysis_session(db, row) for row in rows]}


@app.post(
    "/api/agent-analysis/quote",
    dependencies=[Depends(require_permission("agent_analysis.use"))],
)
def quote_agent_analysis_session(
    payload: AgentAnalysisSessionRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    limits = _financial_agent_role_limits(current_user.role)
    subject = str(payload.subject or "").strip()[:4000]
    agent_ids = []
    for value in payload.agent_ids or []:
        try:
            parsed = int(value)
        except (TypeError, ValueError):
            continue
        if parsed not in agent_ids:
            agent_ids.append(parsed)
    if len(agent_ids) > int(limits["max_agents"]):
        raise HTTPException(
            status_code=400,
            detail=f"当前套餐单次最多选择 {limits['max_agents']} 个分析师",
        )
    selected_profiles = []
    if agent_ids:
        selected_profiles = (
            _financial_agent_visible_query(db, current_user)
            .filter(
                FinancialAgentProfile.id.in_(agent_ids),
                FinancialAgentProfile.enabled.is_(True),
            )
            .all()
        )
        if len(selected_profiles) != len(agent_ids):
            raise HTTPException(status_code=400, detail="选择的分析师包含不可用或无权访问的项目")
    max_rounds = max(1, int(payload.max_rounds or 1))
    if max_rounds > int(limits["max_initial_rounds"]):
        raise HTTPException(
            status_code=400,
            detail=f"当前套餐首次讨论最多 {limits['max_initial_rounds']} 轮",
        )
    selected_model = _financial_agent_validated_model(db, current_user, payload.model)
    context_chars = len(subject) + len(str(payload.symbol or "")) * 20 + len(agent_ids) * 900
    billing_estimate = _agent_analysis_dynamic_credit_estimate(
        db,
        current_user,
        agent_count=len(agent_ids),
        rounds=max_rounds if len(agent_ids) >= 2 else 0,
        model_or_tier=selected_model,
        context_chars=context_chars,
        data_sources=_agent_analysis_data_source_count(selected_profiles),
    )
    min_agents = 1 if COMMUNITY_EDITION else 2
    eligible = bool(subject and len(agent_ids) >= min_agents)
    reason = ""
    if not subject:
        reason = "请先填写讨论主题"
    elif len(agent_ids) < min_agents:
        reason = "至少选择一位分析师" if COMMUNITY_EDITION else "至少选择两个分析师"
    return {
        "eligible": eligible,
        "reason": reason,
        "billing_estimate": billing_estimate,
        "limits": limits,
        "credit_summary": _credit_summary(db, current_user),
    }


@app.post(
    "/api/agent-analysis/sessions",
    dependencies=[Depends(require_permission("agent_analysis.use"))],
)
def create_agent_analysis_session(
    background_tasks: BackgroundTasks,
    payload: AgentAnalysisSessionRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    limits = _financial_agent_role_limits(current_user.role)
    subject = str(payload.subject or "").strip()[:4000]
    if not subject:
        raise HTTPException(status_code=400, detail="讨论主题不能为空")
    agent_ids = []
    for value in payload.agent_ids or []:
        try:
            parsed = int(value)
        except (TypeError, ValueError):
            continue
        if parsed not in agent_ids:
            agent_ids.append(parsed)
    if len(agent_ids) < (1 if COMMUNITY_EDITION else 2):
        raise HTTPException(
            status_code=400,
            detail="至少选择一位分析师" if COMMUNITY_EDITION else "至少选择两个分析师",
        )
    if len(agent_ids) > int(limits["max_agents"]):
        raise HTTPException(
            status_code=400,
            detail=f"当前套餐单次最多选择 {limits['max_agents']} 个分析师",
        )
    selected_profiles = (
        _financial_agent_visible_query(db, current_user)
        .filter(
            FinancialAgentProfile.id.in_(agent_ids),
            FinancialAgentProfile.enabled.is_(True),
        )
        .all()
    )
    if len(selected_profiles) != len(agent_ids):
        raise HTTPException(status_code=400, detail="选择的分析师包含不可用或无权访问的项目")
    subject_type = str(payload.subject_type or "stock").strip().lower()
    if subject_type not in {"stock", "event", "sentiment", "portfolio", "industry"}:
        subject_type = "stock"
    max_rounds = max(1, int(payload.max_rounds or 1))
    if max_rounds > int(limits["max_initial_rounds"]):
        raise HTTPException(
            status_code=400,
            detail=f"当前套餐首次讨论最多 {limits['max_initial_rounds']} 轮",
        )
    selected_model = _financial_agent_validated_model(db, current_user, payload.model)
    market_code = _normalize_market_code(payload.market)
    raw_symbol = str(payload.symbol or "").strip()
    normalized_symbol = data_sources.normalize_stock_code(raw_symbol) if raw_symbol else ""
    if normalized_symbol and data_sources.is_supported_equity_code(normalized_symbol):
        if data_sources.equity_market(normalized_symbol) != market_code:
            raise HTTPException(status_code=400, detail="研究标的与当前选择的市场不一致")
        raw_symbol = normalized_symbol
    row = AgentAnalysisSession(
        user_id=current_user.id,
        title=str(payload.title or subject[:48]).strip()[:120] or "AI 分析",
        subject_type=subject_type,
        subject=subject,
        symbol=raw_symbol[:40] or None,
        selected_agent_ids_json=json.dumps(agent_ids, ensure_ascii=False),
        model=selected_model,
        max_rounds=max_rounds,
        current_round=0,
        status="pending",
        progress_json=json.dumps(
            {
                "stage": "等待后台任务启动",
                "percent": 0,
                "current_round": 0,
                "market": market_code,
            },
            ensure_ascii=False,
        ),
    )
    db.add(row)
    db.flush()
    user_markdown = f"## 研究问题\n\n{subject}"
    if row.symbol:
        user_markdown += f"\n\n**研究标的：** `{row.symbol}`"
    db.add(
        AgentAnalysisMessage(
            session_id=row.id,
            sender_type="user",
            sender_name=current_user.username,
            round_no=0,
            content_markdown=user_markdown,
            blocks_json=json.dumps(
                [{"type": "markdown", "content": user_markdown}], ensure_ascii=False
            ),
            meta_json=json.dumps(
                {
                    "initial_request": True,
                    "subject_type": subject_type,
                    "symbol": row.symbol or "",
                    "market": market_code,
                },
                ensure_ascii=False,
            ),
        )
    )
    context_chars = len(subject) + len(raw_symbol) * 20 + len(agent_ids) * 900
    credit_estimate = _agent_analysis_dynamic_credit_estimate(
        db=db,
        user=current_user,
        agent_count=len(agent_ids),
        rounds=max_rounds,
        model_or_tier=selected_model,
        context_chars=context_chars,
        data_sources=_agent_analysis_data_source_count(selected_profiles),
    )
    credit_summary = _consume_user_credits(
        db,
        current_user,
        "agent_analysis",
        int(credit_estimate.get("estimated_credits") or 0),
        reference_id=f"agent-analysis:{row.id}:initial",
        meta={
            "session_id": row.id,
            "agent_count": len(agent_ids),
            "rounds": max_rounds,
            "moderator_summary": True,
            "billing_estimate": credit_estimate,
        },
    )
    db.commit()
    db.refresh(row)
    background_tasks.add_task(_run_agent_analysis_session, row.id, current_user.id)
    return {
        "session": _serialize_agent_analysis_session(db, row, include_messages=True),
        "credit_summary": credit_summary,
        "billing_estimate": credit_estimate,
    }


