LLM_MODEL_OPTIONS_KEY = "llm_model_options"


def _default_llm_model_options() -> dict:
    module_model_configs = _sanitize_module_model_configs({}, DEFAULT_LLM_MODEL, "openai")
    module_models = _legacy_module_models(module_model_configs)
    module_model_tiers = _sanitize_module_model_tiers({}, "smart")
    return {
        "default_model": DEFAULT_LLM_MODEL,
        "models": [DEFAULT_LLM_MODEL],
        "module_models": module_models,
        "module_model_tiers": module_model_tiers,
        "model_tiers": _default_llm_model_tiers(DEFAULT_LLM_MODEL, "openai"),
        "notes": "系统管理员维护模型等级、真实模型映射和额度倍率。",
    }


def _sanitize_llm_model_options(value: Optional[dict]) -> dict:
    raw = value if isinstance(value, dict) else {}
    models: list[str] = []
    seen: set[str] = set()

    def add_model(item: Any):
        model = str(item or "").strip()
        if not model or model in seen:
            return
        seen.add(model)
        models.append(model)

    for item in raw.get("models") or []:
        add_model(item)
    default_model = str(raw.get("default_model") or "").strip()
    add_model(default_model)
    if not models:
        add_model(DEFAULT_LLM_MODEL)
    default_model = default_model if default_model in seen else models[0]
    module_models = _sanitize_module_models(
        raw.get("module_models") if isinstance(raw.get("module_models"), dict) else {},
        default_model,
    )
    model_tiers = _sanitize_llm_model_tiers(raw.get("model_tiers"), default_model, "openai")
    module_model_tiers = _sanitize_module_model_tiers(
        raw.get("module_model_tiers") if isinstance(raw.get("module_model_tiers"), dict) else {},
        "smart",
    )
    return {
        "default_model": default_model,
        "models": models,
        "module_models": module_models,
        "module_model_tiers": module_model_tiers,
        "model_tiers": model_tiers,
        "tier_options": [
            {
                "value": key,
                "label": model_tiers[key]["label"],
                "label_en": model_tiers[key]["label_en"],
                "multiplier": model_tiers[key]["multiplier"],
                "min_role": model_tiers[key]["min_role"],
                "enabled": model_tiers[key]["enabled"],
            }
            for key in LLM_MODEL_TIERS
        ],
        "notes": str(raw.get("notes") or "系统管理员维护模型等级、真实模型映射和额度倍率。"),
    }


def _shared_llm_config_row(db: Session) -> Optional[LLMConfig]:
    return db.query(LLMConfig).filter(LLMConfig.user_id.is_(None)).first()


def _ensure_shared_llm_config_row(db: Session) -> LLMConfig:
    cfg = _shared_llm_config_row(db)
    if not cfg:
        cfg = LLMConfig(user_id=None)
        db.add(cfg)
    return cfg


