def _token_usage_query(
    db: Session,
    *,
    days: int,
    user_id: Optional[int] = None,
    module_key: Optional[str] = None,
    model: Optional[str] = None,
):
    since = _utcnow() - timedelta(days=max(1, days) - 1)
    since = since.replace(hour=0, minute=0, second=0, microsecond=0)
    query = db.query(LLMUsageRecord).filter(LLMUsageRecord.created_at >= since)
    if user_id:
        query = query.filter(LLMUsageRecord.user_id == int(user_id))
    if module_key:
        query = query.filter(LLMUsageRecord.module_key == str(module_key).strip())
    if model:
        query = query.filter(LLMUsageRecord.model == str(model).strip())
    return query, since


def _token_cost_group_payload(row: Any, keys: tuple[str, ...]) -> dict:
    payload = {key: getattr(row, key) for key in keys}
    for field in (
        "request_count",
        "input_tokens",
        "output_tokens",
        "cache_read_tokens",
        "cache_write_tokens",
        "total_tokens",
        "credits_charged",
        "total_cost_micros",
    ):
        payload[field] = int(getattr(row, field, 0) or 0)
    payload["cost_usd"] = round(payload["total_cost_micros"] / 1_000_000.0, 8)
    return payload


def _csv_cell(value: Any) -> Any:
    if value is None:
        return ""
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, (dict, list, tuple)):
        return json.dumps(value, ensure_ascii=False, default=str)
    return value


def _csv_section_rows(rows: list[dict], headers: list[str]) -> list[list[Any]]:
    return [[_csv_cell(row.get(header)) for header in headers] for row in rows]


def _csv_response(
    filename_prefix: str,
    sections: list[tuple[str, list[str], list[list[Any]]]],
) -> Response:
    buffer = StringIO()
    buffer.write("\ufeff")
    writer = csv.writer(buffer)
    for section_index, (section_name, headers, rows) in enumerate(sections):
        if section_index:
            writer.writerow([])
        writer.writerow([section_name])
        writer.writerow(headers)
        for row in rows:
            writer.writerow([_csv_cell(value) for value in row])
    filename = f"{filename_prefix}-{datetime.now().strftime('%Y%m%d-%H%M%S')}.csv"
    return Response(
        content=buffer.getvalue(),
        media_type="text/csv; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


def _llm_usage_csv_rows(rows: list[Any]) -> list[list[Any]]:
    result: list[list[Any]] = []
    for row, username, role in rows:
        result.append(
            [
                row.id,
                row.created_at,
                row.user_id,
                username,
                normalize_user_role(role),
                row.module_key,
                LLM_USAGE_MODULE_LABELS.get(row.module_key, row.module_key),
                row.provider,
                row.model,
                row.request_id,
                row.status,
                row.usage_source,
                row.latency_ms,
                int(row.input_tokens or 0),
                int(row.output_tokens or 0),
                int(row.cache_read_tokens or 0),
                int(row.cache_write_tokens or 0),
                int(row.total_tokens or 0),
                int(row.credits_charged or 0),
                round(int(row.input_cost_micros or 0) / 1_000_000.0, 8),
                round(int(row.output_cost_micros or 0) / 1_000_000.0, 8),
                round(int(row.cache_read_cost_micros or 0) / 1_000_000.0, 8),
                round(int(row.cache_write_cost_micros or 0) / 1_000_000.0, 8),
                round(int(row.total_cost_micros or 0) / 1_000_000.0, 8),
                int(row.total_cost_micros or 0),
            ]
        )
    return result


LLM_USAGE_CSV_HEADERS = [
    "id",
    "created_at",
    "user_id",
    "username",
    "role",
    "module_key",
    "module_label",
    "provider",
    "model",
    "request_id",
    "status",
    "usage_source",
    "latency_ms",
    "input_tokens",
    "output_tokens",
    "cache_read_tokens",
    "cache_write_tokens",
    "total_tokens",
    "credits_charged",
    "input_cost_usd",
    "output_cost_usd",
    "cache_read_cost_usd",
    "cache_write_cost_usd",
    "total_cost_usd",
    "total_cost_micros",
]


@app.get(
    "/api/admin/token-cost/dashboard",
    dependencies=[Depends(require_permission("system.manage"))],
)
def get_admin_token_cost_dashboard(
    days: int = 30,
    user_id: Optional[int] = None,
    module_key: Optional[str] = None,
    model: Optional[str] = None,
    page: int = 1,
    page_size: int = 10,
    limit: Optional[int] = None,
    db: Session = Depends(get_db),
):
    safe_days = max(1, min(int(days or 30), 365))
    safe_page = max(1, int(page or 1))
    _ = limit  # Backward-compatible query parameter; recent rows use explicit pagination.
    safe_page_size = max(1, min(int(page_size or 10), 50))
    query, since = _token_usage_query(
        db,
        days=safe_days,
        user_id=user_id,
        module_key=module_key,
        model=model,
    )
    summary = query.with_entities(
        func.count(LLMUsageRecord.id).label("request_count"),
        func.coalesce(func.sum(LLMUsageRecord.input_tokens), 0).label("input_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.output_tokens), 0).label("output_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_read_tokens), 0).label("cache_read_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_write_tokens), 0).label("cache_write_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.total_tokens), 0).label("total_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.credits_charged), 0).label("credits_charged"),
        func.coalesce(func.sum(LLMUsageRecord.input_cost_micros), 0).label("input_cost_micros"),
        func.coalesce(func.sum(LLMUsageRecord.output_cost_micros), 0).label("output_cost_micros"),
        func.coalesce(func.sum(LLMUsageRecord.cache_read_cost_micros), 0).label("cache_read_cost_micros"),
        func.coalesce(func.sum(LLMUsageRecord.cache_write_cost_micros), 0).label("cache_write_cost_micros"),
        func.coalesce(func.sum(LLMUsageRecord.total_cost_micros), 0).label("total_cost_micros"),
    ).one()
    summary_payload = {
        key: int(getattr(summary, key, 0) or 0)
        for key in (
            "request_count",
            "input_tokens",
            "output_tokens",
            "cache_read_tokens",
            "cache_write_tokens",
            "total_tokens",
            "credits_charged",
            "input_cost_micros",
            "output_cost_micros",
            "cache_read_cost_micros",
            "cache_write_cost_micros",
            "total_cost_micros",
        )
    }
    summary_payload["cost_usd"] = round(
        summary_payload["total_cost_micros"] / 1_000_000.0,
        8,
    )
    prompt_total = summary_payload["input_tokens"] + summary_payload["cache_read_tokens"]
    summary_payload["cache_hit_ratio"] = round(
        summary_payload["cache_read_tokens"] / prompt_total,
        6,
    ) if prompt_total else 0.0

    date_key = func.date(LLMUsageRecord.created_at).label("date")
    trend_rows = query.with_entities(
        date_key,
        func.count(LLMUsageRecord.id).label("request_count"),
        func.coalesce(func.sum(LLMUsageRecord.input_tokens), 0).label("input_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.output_tokens), 0).label("output_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_read_tokens), 0).label("cache_read_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_write_tokens), 0).label("cache_write_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.total_tokens), 0).label("total_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.credits_charged), 0).label("credits_charged"),
        func.coalesce(func.sum(LLMUsageRecord.total_cost_micros), 0).label("total_cost_micros"),
    ).group_by(date_key).order_by(date_key.asc()).all()
    trend = []
    for row in trend_rows:
        item = _token_cost_group_payload(row, ("date",))
        item["date"] = str(item["date"])
        trend.append(item)

    module_rows = query.with_entities(
        LLMUsageRecord.module_key.label("module_key"),
        func.count(LLMUsageRecord.id).label("request_count"),
        func.coalesce(func.sum(LLMUsageRecord.input_tokens), 0).label("input_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.output_tokens), 0).label("output_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_read_tokens), 0).label("cache_read_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_write_tokens), 0).label("cache_write_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.total_tokens), 0).label("total_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.credits_charged), 0).label("credits_charged"),
        func.coalesce(func.sum(LLMUsageRecord.total_cost_micros), 0).label("total_cost_micros"),
    ).group_by(LLMUsageRecord.module_key).order_by(desc("total_cost_micros")).all()
    by_module = []
    for row in module_rows:
        item = _token_cost_group_payload(row, ("module_key",))
        item["module_label"] = LLM_USAGE_MODULE_LABELS.get(item["module_key"], item["module_key"])
        by_module.append(item)

    user_rows = query.join(UserModel, UserModel.id == LLMUsageRecord.user_id).with_entities(
        LLMUsageRecord.user_id.label("user_id"),
        UserModel.username.label("username"),
        UserModel.role.label("role"),
        func.count(LLMUsageRecord.id).label("request_count"),
        func.coalesce(func.sum(LLMUsageRecord.input_tokens), 0).label("input_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.output_tokens), 0).label("output_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_read_tokens), 0).label("cache_read_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_write_tokens), 0).label("cache_write_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.total_tokens), 0).label("total_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.credits_charged), 0).label("credits_charged"),
        func.coalesce(func.sum(LLMUsageRecord.total_cost_micros), 0).label("total_cost_micros"),
    ).group_by(LLMUsageRecord.user_id, UserModel.username, UserModel.role).order_by(desc("total_cost_micros")).all()
    by_user = [_token_cost_group_payload(row, ("user_id", "username", "role")) for row in user_rows]

    model_rows = query.with_entities(
        LLMUsageRecord.provider.label("provider"),
        LLMUsageRecord.model.label("model"),
        func.count(LLMUsageRecord.id).label("request_count"),
        func.coalesce(func.sum(LLMUsageRecord.input_tokens), 0).label("input_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.output_tokens), 0).label("output_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_read_tokens), 0).label("cache_read_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.cache_write_tokens), 0).label("cache_write_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.total_tokens), 0).label("total_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.credits_charged), 0).label("credits_charged"),
        func.coalesce(func.sum(LLMUsageRecord.total_cost_micros), 0).label("total_cost_micros"),
    ).group_by(LLMUsageRecord.provider, LLMUsageRecord.model).order_by(desc("total_cost_micros")).all()
    by_model = [_token_cost_group_payload(row, ("provider", "model")) for row in model_rows]

    recent_total = query.with_entities(func.count(LLMUsageRecord.id)).scalar() or 0
    recent_pages = max(1, math.ceil(int(recent_total) / safe_page_size))
    safe_page = min(safe_page, recent_pages)
    recent_rows = query.join(UserModel, UserModel.id == LLMUsageRecord.user_id).with_entities(
        LLMUsageRecord,
        UserModel.username,
    ).order_by(LLMUsageRecord.created_at.desc()).offset(
        (safe_page - 1) * safe_page_size
    ).limit(safe_page_size).all()
    recent = [_serialize_llm_usage_record(row, username) for row, username in recent_rows]

    user_options = (
        db.query(UserModel.id, UserModel.username, UserModel.role)
        .order_by(UserModel.username.asc())
        .all()
    )
    module_options = list(LLM_USAGE_MODULE_LABELS)
    for row in (
        db.query(LLMUsageRecord.module_key)
        .distinct()
        .order_by(LLMUsageRecord.module_key.asc())
        .all()
    ):
        key = str(row[0] or "").strip()
        if key and key not in module_options:
            module_options.append(key)

    model_option_pairs: list[tuple[str, str]] = []

    def add_model_option(provider_value: Any, model_value: Any) -> None:
        provider_name = _pricing_provider(provider_value)
        model_name = str(model_value or "").strip()
        pair = (provider_name, model_name)
        if model_name and model_name != "*" and pair not in model_option_pairs:
            model_option_pairs.append(pair)

    for item in _configured_llm_pricing_models(db):
        add_model_option(item.get("provider"), item.get("model"))
    for item in _llm_pricing_settings(db).get("models") or []:
        add_model_option(item.get("provider"), item.get("model"))
    for row in (
        db.query(LLMUsageRecord.provider, LLMUsageRecord.model)
        .distinct()
        .order_by(LLMUsageRecord.provider.asc(), LLMUsageRecord.model.asc())
        .all()
    ):
        add_model_option(row[0], row[1])
    model_options = [
        {"provider": provider_name, "model": model_name}
        for provider_name, model_name in sorted(model_option_pairs)
    ]
    return {
        "range": {"days": safe_days, "since": since.isoformat()},
        "filters": {
            "user_id": user_id,
            "module_key": module_key or "",
            "model": model or "",
        },
        "summary": summary_payload,
        "trend": trend,
        "by_module": by_module,
        "by_user": by_user,
        "by_model": by_model,
        "recent": recent,
        "recent_pagination": {
            "page": safe_page,
            "page_size": safe_page_size,
            "total": int(recent_total),
            "pages": recent_pages,
        },
        "options": {
            "users": [
                {"id": row.id, "username": row.username, "role": normalize_user_role(row.role)}
                for row in user_options
            ],
            "modules": [
                {"key": key, "label": LLM_USAGE_MODULE_LABELS.get(key, key)}
                for key in module_options
            ],
            "models": model_options,
        },
        "pricing": _llm_pricing_settings(db),
    }


@app.get(
    "/api/admin/token-cost/export",
    dependencies=[Depends(require_permission("system.manage"))],
)
def export_admin_token_cost_csv(
    days: int = 30,
    user_id: Optional[int] = None,
    module_key: Optional[str] = None,
    model: Optional[str] = None,
    limit: int = 50000,
    db: Session = Depends(get_db),
):
    safe_days = max(1, min(int(days or 30), 365))
    safe_limit = max(1, min(int(limit or 50000), 100000))
    query, since = _token_usage_query(
        db,
        days=safe_days,
        user_id=user_id,
        module_key=module_key,
        model=model,
    )
    summary = query.with_entities(
        func.count(LLMUsageRecord.id).label("request_count"),
        func.coalesce(func.sum(LLMUsageRecord.total_tokens), 0).label("total_tokens"),
        func.coalesce(func.sum(LLMUsageRecord.credits_charged), 0).label("credits_charged"),
        func.coalesce(func.sum(LLMUsageRecord.total_cost_micros), 0).label("total_cost_micros"),
    ).one()
    usage_rows = (
        query.join(UserModel, UserModel.id == LLMUsageRecord.user_id)
        .with_entities(LLMUsageRecord, UserModel.username, UserModel.role)
        .order_by(LLMUsageRecord.created_at.desc(), LLMUsageRecord.id.desc())
        .limit(safe_limit)
        .all()
    )
    sections = [
        (
            "summary",
            ["metric", "value"],
            [
                ["range_days", safe_days],
                ["since", since],
                ["user_id", user_id or ""],
                ["module_key", module_key or ""],
                ["model", model or ""],
                ["export_limit", safe_limit],
                ["request_count", int(summary.request_count or 0)],
                ["total_tokens", int(summary.total_tokens or 0)],
                ["credits_charged", int(summary.credits_charged or 0)],
                ["total_cost_usd", round(int(summary.total_cost_micros or 0) / 1_000_000.0, 8)],
                ["total_cost_micros", int(summary.total_cost_micros or 0)],
            ],
        ),
        (
            "token_usage_records",
            LLM_USAGE_CSV_HEADERS,
            _llm_usage_csv_rows(usage_rows),
        ),
    ]
    return _csv_response("quartsys-token-cost", sections)


def _revenue_since(days: int) -> tuple[int, datetime]:
    safe_days = max(1, min(int(days or 30), 365))
    since = _utcnow() - timedelta(days=safe_days - 1)
    return safe_days, since.replace(hour=0, minute=0, second=0, microsecond=0)


def _paid_order_filter(model: Any, since: datetime):
    return and_(
        model.status == "paid",
        or_(
            model.paid_at >= since,
            and_(model.paid_at.is_(None), model.created_at >= since),
        ),
    )


def _cny_from_cents(value: Any) -> float:
    return round(int(value or 0) / 100.0, 2)


def _money(value: Any, digits: int = 2) -> float:
    return round(float(value or 0), digits)


def _date_key(value: Any) -> str:
    if isinstance(value, datetime):
        return (_as_naive_utc(value) or value).date().isoformat()
    text_value = str(value or "")[:10]
    return text_value if text_value else _utcnow().date().isoformat()


def _revenue_trend_seed(since: datetime, days: int) -> dict[str, dict]:
    return {
        (since + timedelta(days=index)).date().isoformat(): {
            "date": (since + timedelta(days=index)).date().isoformat(),
            "subscription_revenue_cny": 0.0,
            "recharge_revenue_cny": 0.0,
            "ad_estimated_revenue_cny": 0.0,
            "ai_cost_cny": 0.0,
            "net_estimated_revenue_cny": 0.0,
            "paid_orders": 0,
            "recharge_orders": 0,
            "ad_impressions": 0,
            "rewarded_ad_completions": 0,
        }
        for index in range(days)
    }


@app.get(
    "/api/admin/revenue/dashboard",
    dependencies=[Depends(require_permission("system.manage"))],
)
def get_admin_revenue_dashboard(
    days: int = 30,
    user_id: Optional[int] = None,
    usd_cny: float = 7.2,
    homepage_ecpm_cny: float = 20.0,
    rewarded_ecpm_cny: float = 60.0,
    db: Session = Depends(get_db),
):
    safe_days, since = _revenue_since(days)
    safe_usd_cny = _bounded_float(usd_cny, 7.2, 0.01, 99.0)
    safe_homepage_ecpm = _bounded_float(homepage_ecpm_cny, 20.0, 0.0, 10000.0)
    safe_rewarded_ecpm = _bounded_float(rewarded_ecpm_cny, 60.0, 0.0, 10000.0)

    subscription_query = db.query(SubscriptionOrder).filter(
        _paid_order_filter(SubscriptionOrder, since)
    )
    recharge_query = db.query(CreditRechargeOrder).filter(
        _paid_order_filter(CreditRechargeOrder, since)
    )
    reward_query = db.query(AdRewardSession).filter(
        AdRewardSession.status == "granted",
        AdRewardSession.granted_at >= since,
    )
    ad_query = db.query(AdEvent).filter(AdEvent.created_at >= since)
    usage_query = db.query(LLMUsageRecord).filter(LLMUsageRecord.created_at >= since)
    if user_id:
        subscription_query = subscription_query.filter(SubscriptionOrder.user_id == int(user_id))
        recharge_query = recharge_query.filter(CreditRechargeOrder.user_id == int(user_id))
        reward_query = reward_query.filter(AdRewardSession.user_id == int(user_id))
        ad_query = ad_query.filter(AdEvent.user_id == int(user_id))
        usage_query = usage_query.filter(LLMUsageRecord.user_id == int(user_id))

    subscription_summary = subscription_query.with_entities(
        func.count(SubscriptionOrder.id).label("order_count"),
        func.coalesce(func.sum(SubscriptionOrder.amount_cents), 0).label("amount_cents"),
        func.count(func.distinct(SubscriptionOrder.user_id)).label("user_count"),
    ).one()
    recharge_summary = recharge_query.with_entities(
        func.count(CreditRechargeOrder.id).label("order_count"),
        func.coalesce(func.sum(CreditRechargeOrder.amount_cents), 0).label("amount_cents"),
        func.coalesce(func.sum(CreditRechargeOrder.credits), 0).label("credits"),
        func.count(func.distinct(CreditRechargeOrder.user_id)).label("user_count"),
    ).one()
    ad_impressions = int(
        ad_query.filter(AdEvent.event_type == "impression")
        .with_entities(func.count(AdEvent.id))
        .scalar()
        or 0
    )
    ad_clicks = int(
        ad_query.filter(AdEvent.event_type == "click")
        .with_entities(func.count(AdEvent.id))
        .scalar()
        or 0
    )
    rewarded_summary = reward_query.with_entities(
        func.count(AdRewardSession.id).label("completion_count"),
        func.coalesce(func.sum(AdRewardSession.reward_credits), 0).label("reward_credits"),
        func.count(func.distinct(AdRewardSession.user_id)).label("user_count"),
    ).one()
    usage_summary = usage_query.with_entities(
        func.count(LLMUsageRecord.id).label("request_count"),
        func.coalesce(func.sum(LLMUsageRecord.total_cost_micros), 0).label("total_cost_micros"),
        func.coalesce(func.sum(LLMUsageRecord.credits_charged), 0).label("credits_charged"),
    ).one()

    subscription_cny = _cny_from_cents(subscription_summary.amount_cents)
    recharge_cny = _cny_from_cents(recharge_summary.amount_cents)
    homepage_ad_cny = _money(ad_impressions / 1000.0 * safe_homepage_ecpm, 4)
    rewarded_ad_cny = _money(
        int(rewarded_summary.completion_count or 0) / 1000.0 * safe_rewarded_ecpm,
        4,
    )
    estimated_ad_cny = _money(homepage_ad_cny + rewarded_ad_cny, 4)
    paid_revenue_cny = _money(subscription_cny + recharge_cny)
    gross_revenue_cny = _money(paid_revenue_cny + estimated_ad_cny, 4)
    ai_cost_usd = _money(int(usage_summary.total_cost_micros or 0) / 1_000_000.0, 8)
    ai_cost_cny = _money(ai_cost_usd * safe_usd_cny, 4)
    net_estimated_cny = _money(gross_revenue_cny - ai_cost_cny, 4)

    user_count_query = db.query(UserModel)
    new_user_query = db.query(UserModel).filter(UserModel.created_at >= since)
    active_paid_query = db.query(UserModel).filter(UserModel.role.in_(["vip", "svip"]))
    free_user_query = db.query(UserModel).filter(or_(UserModel.role.is_(None), UserModel.role.in_(["normal", "user"])))
    if user_id:
        user_count_query = user_count_query.filter(UserModel.id == int(user_id))
        new_user_query = new_user_query.filter(UserModel.id == int(user_id))
        active_paid_query = active_paid_query.filter(UserModel.id == int(user_id))
        free_user_query = free_user_query.filter(UserModel.id == int(user_id))
    registered_users = int(user_count_query.with_entities(func.count(UserModel.id)).scalar() or 0)
    new_users = int(new_user_query.with_entities(func.count(UserModel.id)).scalar() or 0)
    active_paid_users = int(active_paid_query.with_entities(func.count(UserModel.id)).scalar() or 0)
    free_users = int(free_user_query.with_entities(func.count(UserModel.id)).scalar() or 0)
    period_paid_users = int(subscription_summary.user_count or 0)
    conversion_rate = round(active_paid_users / registered_users, 6) if registered_users else 0.0
    period_conversion_rate = round(period_paid_users / new_users, 6) if new_users else 0.0
    arppu_cny = _money(subscription_cny / period_paid_users) if period_paid_users else 0.0
    ad_ctr = round(ad_clicks / ad_impressions, 6) if ad_impressions else 0.0
    margin_ratio = round(net_estimated_cny / gross_revenue_cny, 6) if gross_revenue_cny else 0.0

    trend_map = _revenue_trend_seed(since, safe_days)
    sub_date = func.date(SubscriptionOrder.paid_at).label("date")
    for row in (
        subscription_query.filter(SubscriptionOrder.paid_at.isnot(None))
        .with_entities(
            sub_date,
            func.count(SubscriptionOrder.id).label("order_count"),
            func.coalesce(func.sum(SubscriptionOrder.amount_cents), 0).label("amount_cents"),
        )
        .group_by(sub_date)
        .all()
    ):
        item = trend_map.get(_date_key(row.date))
        if item:
            item["subscription_revenue_cny"] = _cny_from_cents(row.amount_cents)
            item["paid_orders"] = int(row.order_count or 0)

    recharge_date = func.date(CreditRechargeOrder.paid_at).label("date")
    for row in (
        recharge_query.filter(CreditRechargeOrder.paid_at.isnot(None))
        .with_entities(
            recharge_date,
            func.count(CreditRechargeOrder.id).label("order_count"),
            func.coalesce(func.sum(CreditRechargeOrder.amount_cents), 0).label("amount_cents"),
        )
        .group_by(recharge_date)
        .all()
    ):
        item = trend_map.get(_date_key(row.date))
        if item:
            item["recharge_revenue_cny"] = _cny_from_cents(row.amount_cents)
            item["recharge_orders"] = int(row.order_count or 0)

    ad_date = func.date(AdEvent.created_at).label("date")
    for row in (
        ad_query.filter(AdEvent.event_type == "impression")
        .with_entities(ad_date, func.count(AdEvent.id).label("impressions"))
        .group_by(ad_date)
        .all()
    ):
        item = trend_map.get(_date_key(row.date))
        if item:
            item["ad_impressions"] = int(row.impressions or 0)

    reward_date = func.date(AdRewardSession.granted_at).label("date")
    for row in (
        reward_query.filter(AdRewardSession.granted_at.isnot(None))
        .with_entities(reward_date, func.count(AdRewardSession.id).label("completions"))
        .group_by(reward_date)
        .all()
    ):
        item = trend_map.get(_date_key(row.date))
        if item:
            item["rewarded_ad_completions"] = int(row.completions or 0)

    usage_date = func.date(LLMUsageRecord.created_at).label("date")
    for row in (
        usage_query.with_entities(
            usage_date,
            func.coalesce(func.sum(LLMUsageRecord.total_cost_micros), 0).label("cost_micros"),
        )
        .group_by(usage_date)
        .all()
    ):
        item = trend_map.get(_date_key(row.date))
        if item:
            item["ai_cost_cny"] = _money(int(row.cost_micros or 0) / 1_000_000.0 * safe_usd_cny, 4)

    for item in trend_map.values():
        item["ad_estimated_revenue_cny"] = _money(
            item["ad_impressions"] / 1000.0 * safe_homepage_ecpm
            + item["rewarded_ad_completions"] / 1000.0 * safe_rewarded_ecpm,
            4,
        )
        item["net_estimated_revenue_cny"] = _money(
            item["subscription_revenue_cny"]
            + item["recharge_revenue_cny"]
            + item["ad_estimated_revenue_cny"]
            - item["ai_cost_cny"],
            4,
        )

    by_plan = []
    for row in (
        subscription_query.join(SubscriptionPlan, SubscriptionPlan.id == SubscriptionOrder.plan_id)
        .with_entities(
            SubscriptionPlan.id.label("plan_id"),
            SubscriptionPlan.key.label("plan_key"),
            SubscriptionPlan.name.label("plan_name"),
            SubscriptionPlan.role.label("role"),
            func.count(SubscriptionOrder.id).label("order_count"),
            func.count(func.distinct(SubscriptionOrder.user_id)).label("user_count"),
            func.coalesce(func.sum(SubscriptionOrder.amount_cents), 0).label("amount_cents"),
        )
        .group_by(SubscriptionPlan.id, SubscriptionPlan.key, SubscriptionPlan.name, SubscriptionPlan.role)
        .order_by(desc("amount_cents"))
        .all()
    ):
        by_plan.append(
            {
                "plan_id": row.plan_id,
                "plan_key": row.plan_key,
                "plan_name": row.plan_name,
                "role": normalize_user_role(row.role),
                "order_count": int(row.order_count or 0),
                "user_count": int(row.user_count or 0),
                "revenue_cny": _cny_from_cents(row.amount_cents),
            }
        )

    provider_map: dict[str, dict] = {}
    for row in (
        subscription_query.with_entities(
            SubscriptionOrder.provider.label("provider"),
            func.count(SubscriptionOrder.id).label("order_count"),
            func.coalesce(func.sum(SubscriptionOrder.amount_cents), 0).label("amount_cents"),
        )
        .group_by(SubscriptionOrder.provider)
        .all()
    ):
        key = str(row.provider or "unknown")
        provider_map.setdefault(
            key,
            {
                "provider": key,
                "subscription_orders": 0,
                "recharge_orders": 0,
                "subscription_revenue_cny": 0.0,
                "recharge_revenue_cny": 0.0,
                "total_revenue_cny": 0.0,
            },
        )
        provider_map[key]["subscription_orders"] = int(row.order_count or 0)
        provider_map[key]["subscription_revenue_cny"] = _cny_from_cents(row.amount_cents)
    for row in (
        recharge_query.with_entities(
            CreditRechargeOrder.provider.label("provider"),
            func.count(CreditRechargeOrder.id).label("order_count"),
            func.coalesce(func.sum(CreditRechargeOrder.amount_cents), 0).label("amount_cents"),
        )
        .group_by(CreditRechargeOrder.provider)
        .all()
    ):
        key = str(row.provider or "unknown")
        provider_map.setdefault(
            key,
            {
                "provider": key,
                "subscription_orders": 0,
                "recharge_orders": 0,
                "subscription_revenue_cny": 0.0,
                "recharge_revenue_cny": 0.0,
                "total_revenue_cny": 0.0,
            },
        )
        provider_map[key]["recharge_orders"] = int(row.order_count or 0)
        provider_map[key]["recharge_revenue_cny"] = _cny_from_cents(row.amount_cents)
    for item in provider_map.values():
        item["total_revenue_cny"] = _money(item["subscription_revenue_cny"] + item["recharge_revenue_cny"])
    by_payment_provider = sorted(
        provider_map.values(),
        key=lambda item: item["total_revenue_cny"],
        reverse=True,
    )

    ad_map: dict[str, dict] = {}
    for row in (
        ad_query.with_entities(
            AdEvent.placement_key.label("placement_key"),
            AdEvent.platform.label("platform"),
            AdEvent.event_type.label("event_type"),
            func.count(AdEvent.id).label("event_count"),
        )
        .group_by(AdEvent.placement_key, AdEvent.platform, AdEvent.event_type)
        .all()
    ):
        key = f"{row.placement_key or 'unknown'}:{row.platform or 'direct'}"
        item = ad_map.setdefault(
            key,
            {
                "placement_key": row.placement_key or "unknown",
                "platform": row.platform or "direct",
                "impressions": 0,
                "clicks": 0,
                "completions": 0,
                "reward_credits": 0,
                "estimated_revenue_cny": 0.0,
                "ctr": 0.0,
            },
        )
        if row.event_type == "click":
            item["clicks"] = int(row.event_count or 0)
        else:
            item["impressions"] = int(row.event_count or 0)
    for row in (
        reward_query.with_entities(
            AdRewardSession.provider.label("provider"),
            func.count(AdRewardSession.id).label("completion_count"),
            func.coalesce(func.sum(AdRewardSession.reward_credits), 0).label("reward_credits"),
        )
        .group_by(AdRewardSession.provider)
        .all()
    ):
        key = f"rewarded_ad:{row.provider or 'unknown'}"
        ad_map[key] = {
            "placement_key": "rewarded_ad",
            "platform": row.provider or "unknown",
            "impressions": 0,
            "clicks": 0,
            "completions": int(row.completion_count or 0),
            "reward_credits": int(row.reward_credits or 0),
            "estimated_revenue_cny": _money(int(row.completion_count or 0) / 1000.0 * safe_rewarded_ecpm, 4),
            "ctr": 0.0,
        }
    for item in ad_map.values():
        if item["placement_key"] != "rewarded_ad":
            item["estimated_revenue_cny"] = _money(item["impressions"] / 1000.0 * safe_homepage_ecpm, 4)
            item["ctr"] = round(item["clicks"] / item["impressions"], 6) if item["impressions"] else 0.0
    by_ad_placement = sorted(
        ad_map.values(),
        key=lambda item: item["estimated_revenue_cny"],
        reverse=True,
    )

    recent_payments = []
    subscription_recent = (
        subscription_query.join(UserModel, UserModel.id == SubscriptionOrder.user_id)
        .join(SubscriptionPlan, SubscriptionPlan.id == SubscriptionOrder.plan_id)
        .with_entities(SubscriptionOrder, UserModel.username, SubscriptionPlan.name, SubscriptionPlan.key)
        .order_by(SubscriptionOrder.paid_at.desc(), SubscriptionOrder.id.desc())
        .limit(20)
        .all()
    )
    for order, username, plan_name, plan_key in subscription_recent:
        recent_payments.append(
            {
                "id": order.id,
                "type": "subscription",
                "trade_no": order.trade_no,
                "username": username,
                "label": plan_name or plan_key or "subscription",
                "provider": order.provider,
                "amount_cny": _cny_from_cents(order.amount_cents),
                "paid_at": (order.paid_at or order.created_at).isoformat() if (order.paid_at or order.created_at) else None,
            }
        )
    recharge_recent = (
        recharge_query.join(UserModel, UserModel.id == CreditRechargeOrder.user_id)
        .with_entities(CreditRechargeOrder, UserModel.username)
        .order_by(CreditRechargeOrder.paid_at.desc(), CreditRechargeOrder.id.desc())
        .limit(20)
        .all()
    )
    for order, username in recharge_recent:
        recent_payments.append(
            {
                "id": order.id,
                "type": "credit_recharge",
                "trade_no": order.trade_no,
                "username": username,
                "label": f"{int(order.credits or 0)} credits",
                "provider": order.provider,
                "amount_cny": _cny_from_cents(order.amount_cents),
                "paid_at": (order.paid_at or order.created_at).isoformat() if (order.paid_at or order.created_at) else None,
            }
        )
    recent_payments.sort(key=lambda item: item.get("paid_at") or "", reverse=True)

    user_options = (
        db.query(UserModel.id, UserModel.username, UserModel.role)
        .order_by(UserModel.username.asc())
        .all()
    )
    return {
        "range": {"days": safe_days, "since": since.isoformat()},
        "filters": {"user_id": user_id},
        "assumptions": {
            "usd_cny": safe_usd_cny,
            "homepage_ecpm_cny": safe_homepage_ecpm,
            "rewarded_ecpm_cny": safe_rewarded_ecpm,
        },
        "summary": {
            "gross_revenue_cny": gross_revenue_cny,
            "paid_revenue_cny": paid_revenue_cny,
            "subscription_revenue_cny": subscription_cny,
            "recharge_revenue_cny": recharge_cny,
            "estimated_ad_revenue_cny": estimated_ad_cny,
            "estimated_homepage_ad_revenue_cny": homepage_ad_cny,
            "estimated_rewarded_ad_revenue_cny": rewarded_ad_cny,
            "ai_cost_usd": ai_cost_usd,
            "ai_cost_cny": ai_cost_cny,
            "net_estimated_revenue_cny": net_estimated_cny,
            "margin_ratio": margin_ratio,
            "subscription_order_count": int(subscription_summary.order_count or 0),
            "recharge_order_count": int(recharge_summary.order_count or 0),
            "recharge_credits": int(recharge_summary.credits or 0),
            "period_paid_users": period_paid_users,
            "recharge_users": int(recharge_summary.user_count or 0),
            "registered_users": registered_users,
            "new_users": new_users,
            "active_paid_users": active_paid_users,
            "free_users": free_users,
            "conversion_rate": conversion_rate,
            "period_conversion_rate": period_conversion_rate,
            "arppu_cny": arppu_cny,
            "ad_impressions": ad_impressions,
            "ad_clicks": ad_clicks,
            "ad_ctr": ad_ctr,
            "rewarded_ad_completions": int(rewarded_summary.completion_count or 0),
            "rewarded_ad_users": int(rewarded_summary.user_count or 0),
            "rewarded_ad_credits": int(rewarded_summary.reward_credits or 0),
            "llm_request_count": int(usage_summary.request_count or 0),
            "llm_credits_charged": int(usage_summary.credits_charged or 0),
        },
        "trend": list(trend_map.values()),
        "by_plan": by_plan,
        "by_payment_provider": by_payment_provider,
        "by_ad_placement": by_ad_placement,
        "recent_payments": recent_payments[:20],
        "options": {
            "users": [
                {"id": row.id, "username": row.username, "role": normalize_user_role(row.role)}
                for row in user_options
            ],
        },
    }


@app.get(
    "/api/admin/revenue/export",
    dependencies=[Depends(require_permission("system.manage"))],
)
def export_admin_revenue_csv(
    days: int = 30,
    user_id: Optional[int] = None,
    usd_cny: float = 7.2,
    homepage_ecpm_cny: float = 20.0,
    rewarded_ecpm_cny: float = 60.0,
    limit: int = 50000,
    db: Session = Depends(get_db),
):
    safe_days, since = _revenue_since(days)
    safe_limit = max(1, min(int(limit or 50000), 100000))
    dashboard = get_admin_revenue_dashboard(
        days=safe_days,
        user_id=user_id,
        usd_cny=usd_cny,
        homepage_ecpm_cny=homepage_ecpm_cny,
        rewarded_ecpm_cny=rewarded_ecpm_cny,
        db=db,
    )
    assumptions = dashboard.get("assumptions") or {}

    subscription_query = db.query(SubscriptionOrder).filter(
        _paid_order_filter(SubscriptionOrder, since)
    )
    recharge_query = db.query(CreditRechargeOrder).filter(
        _paid_order_filter(CreditRechargeOrder, since)
    )
    reward_query = db.query(AdRewardSession).filter(
        AdRewardSession.status == "granted",
        AdRewardSession.granted_at >= since,
    )
    ad_query = db.query(AdEvent).filter(AdEvent.created_at >= since)
    usage_query = db.query(LLMUsageRecord).filter(LLMUsageRecord.created_at >= since)
    if user_id:
        subscription_query = subscription_query.filter(SubscriptionOrder.user_id == int(user_id))
        recharge_query = recharge_query.filter(CreditRechargeOrder.user_id == int(user_id))
        reward_query = reward_query.filter(AdRewardSession.user_id == int(user_id))
        ad_query = ad_query.filter(AdEvent.user_id == int(user_id))
        usage_query = usage_query.filter(LLMUsageRecord.user_id == int(user_id))

    summary_rows = [
        ["range_days", safe_days],
        ["since", since],
        ["user_id", user_id or ""],
        ["usd_cny", assumptions.get("usd_cny")],
        ["homepage_ecpm_cny", assumptions.get("homepage_ecpm_cny")],
        ["rewarded_ecpm_cny", assumptions.get("rewarded_ecpm_cny")],
    ]
    summary_rows.extend(
        [[key, value] for key, value in (dashboard.get("summary") or {}).items()]
    )

    trend_headers = [
        "date",
        "subscription_revenue_cny",
        "recharge_revenue_cny",
        "ad_estimated_revenue_cny",
        "ai_cost_cny",
        "net_estimated_revenue_cny",
        "paid_orders",
        "recharge_orders",
        "ad_impressions",
        "rewarded_ad_completions",
    ]
    plan_headers = [
        "plan_id",
        "plan_key",
        "plan_name",
        "role",
        "order_count",
        "user_count",
        "revenue_cny",
    ]
    provider_headers = [
        "provider",
        "subscription_orders",
        "recharge_orders",
        "subscription_revenue_cny",
        "recharge_revenue_cny",
        "total_revenue_cny",
    ]
    ad_headers = [
        "placement_key",
        "platform",
        "impressions",
        "clicks",
        "completions",
        "reward_credits",
        "estimated_revenue_cny",
        "ctr",
    ]

    subscription_rows = []
    for order, username, plan_name, plan_key in (
        subscription_query.join(UserModel, UserModel.id == SubscriptionOrder.user_id)
        .join(SubscriptionPlan, SubscriptionPlan.id == SubscriptionOrder.plan_id)
        .with_entities(
            SubscriptionOrder,
            UserModel.username,
            SubscriptionPlan.name,
            SubscriptionPlan.key,
        )
        .order_by(SubscriptionOrder.paid_at.desc(), SubscriptionOrder.id.desc())
        .limit(safe_limit)
        .all()
    ):
        subscription_rows.append(
            [
                order.id,
                order.trade_no,
                order.user_id,
                username,
                plan_key,
                plan_name,
                order.provider,
                _cny_from_cents(order.amount_cents),
                order.currency,
                order.status,
                order.provider_trade_no,
                order.created_at,
                order.paid_at,
            ]
        )

    recharge_rows = []
    for order, username in (
        recharge_query.join(UserModel, UserModel.id == CreditRechargeOrder.user_id)
        .with_entities(CreditRechargeOrder, UserModel.username)
        .order_by(CreditRechargeOrder.paid_at.desc(), CreditRechargeOrder.id.desc())
        .limit(safe_limit)
        .all()
    ):
        recharge_rows.append(
            [
                order.id,
                order.trade_no,
                order.user_id,
                username,
                order.provider,
                _cny_from_cents(order.amount_cents),
                order.credits,
                order.currency,
                order.status,
                order.provider_trade_no,
                order.created_at,
                order.paid_at,
            ]
        )

    ad_event_rows = []
    for row, username in (
        ad_query.outerjoin(UserModel, UserModel.id == AdEvent.user_id)
        .with_entities(AdEvent, UserModel.username)
        .order_by(AdEvent.created_at.desc(), AdEvent.id.desc())
        .limit(safe_limit)
        .all()
    ):
        ad_event_rows.append(
            [
                row.id,
                row.created_at,
                row.placement_key,
                row.event_type,
                row.ad_name,
                row.platform,
                row.sponsor_index,
                row.href,
                row.user_id,
                username,
                row.session_key,
            ]
        )

    reward_rows = []
    for row, username in (
        reward_query.join(UserModel, UserModel.id == AdRewardSession.user_id)
        .with_entities(AdRewardSession, UserModel.username)
        .order_by(AdRewardSession.granted_at.desc(), AdRewardSession.id.desc())
        .limit(safe_limit)
        .all()
    ):
        reward_rows.append(
            [
                row.id,
                row.session_token,
                row.user_id,
                username,
                row.provider,
                row.reward_credits,
                row.status,
                row.provider_event_id,
                row.created_at,
                row.granted_at,
                row.expires_at,
            ]
        )

    usage_rows = (
        usage_query.join(UserModel, UserModel.id == LLMUsageRecord.user_id)
        .with_entities(LLMUsageRecord, UserModel.username, UserModel.role)
        .order_by(LLMUsageRecord.created_at.desc(), LLMUsageRecord.id.desc())
        .limit(safe_limit)
        .all()
    )

    sections = [
        ("summary", ["metric", "value"], summary_rows),
        ("daily_trend", trend_headers, _csv_section_rows(dashboard.get("trend") or [], trend_headers)),
        ("plan_revenue", plan_headers, _csv_section_rows(dashboard.get("by_plan") or [], plan_headers)),
        (
            "payment_provider_revenue",
            provider_headers,
            _csv_section_rows(dashboard.get("by_payment_provider") or [], provider_headers),
        ),
        ("ad_placement_revenue", ad_headers, _csv_section_rows(dashboard.get("by_ad_placement") or [], ad_headers)),
        (
            "subscription_orders",
            [
                "id",
                "trade_no",
                "user_id",
                "username",
                "plan_key",
                "plan_name",
                "provider",
                "amount_cny",
                "currency",
                "status",
                "provider_trade_no",
                "created_at",
                "paid_at",
            ],
            subscription_rows,
        ),
        (
            "credit_recharge_orders",
            [
                "id",
                "trade_no",
                "user_id",
                "username",
                "provider",
                "amount_cny",
                "credits",
                "currency",
                "status",
                "provider_trade_no",
                "created_at",
                "paid_at",
            ],
            recharge_rows,
        ),
        (
            "ad_events",
            [
                "id",
                "created_at",
                "placement_key",
                "event_type",
                "ad_name",
                "platform",
                "sponsor_index",
                "href",
                "user_id",
                "username",
                "session_key",
            ],
            ad_event_rows,
        ),
        (
            "rewarded_ad_sessions",
            [
                "id",
                "session_token",
                "user_id",
                "username",
                "provider",
                "reward_credits",
                "status",
                "provider_event_id",
                "created_at",
                "granted_at",
                "expires_at",
            ],
            reward_rows,
        ),
        ("llm_usage_records", LLM_USAGE_CSV_HEADERS, _llm_usage_csv_rows(usage_rows)),
    ]
    return _csv_response("quartsys-revenue", sections)


ANALYTICS_CORE_MODULES = {
    "stock_search",
    "market_data",
    "stock_detail",
    "screener",
    "factor_filter",
    "strategy",
    "backtest",
    "smart_research",
    "agent_analysis",
    "risk_monitor",
    "watchlist",
    "paper_trade",
    "ai_insights",
}


def _analytics_rate(part: Any, total: Any) -> float:
    total_value = int(total or 0)
    if total_value <= 0:
        return 0.0
    return round(int(part or 0) / total_value, 6)


def _analytics_avg(value: Any) -> float:
    return round(float(value or 0), 3)


def _analytics_trend_seed(since: datetime, days: int) -> dict[str, dict]:
    return {
        (since + timedelta(days=index)).date().isoformat(): {
            "date": (since + timedelta(days=index)).date().isoformat(),
            "pv": 0,
            "uv": 0,
            "dau": 0,
            "new_users": 0,
            "avg_visit_seconds": 0.0,
        }
        for index in range(days)
    }


def _analytics_distribution(rows: list[Any], key_name: str = "key") -> list[dict]:
    total = sum(int(getattr(row, "views", 0) or getattr(row, "count", 0) or 0) for row in rows)
    result = []
    for row in rows:
        count_value = int(getattr(row, "views", 0) or getattr(row, "count", 0) or 0)
        result.append(
            {
                key_name: str(getattr(row, key_name, None) or "unknown"),
                "views": count_value,
                "visitors": int(getattr(row, "visitors", 0) or 0),
                "ratio": round(count_value / total, 6) if total else 0.0,
            }
        )
    return result


def _analytics_funnel_step(
    key: str,
    label: str,
    count_value: int,
    first_count: int,
    previous_count: int,
) -> dict:
    return {
        "key": key,
        "label": label,
        "count": int(count_value or 0),
        "conversion_rate": _analytics_rate(count_value, previous_count),
        "overall_rate": _analytics_rate(count_value, first_count),
    }


@app.get(
    "/api/admin/analytics/dashboard",
    dependencies=[Depends(require_permission("system.manage"))],
)
def get_admin_analytics_dashboard(
    days: int = 30,
    db: Session = Depends(get_db),
):
    safe_days, since = _revenue_since(days)
    today_start = _utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    page_query = db.query(AnalyticsPageView).filter(AnalyticsPageView.created_at >= since)
    session_query = db.query(AnalyticsSession).filter(AnalyticsSession.last_seen_at >= since)
    module_query = db.query(AnalyticsModuleUsage).filter(AnalyticsModuleUsage.created_at >= since)
    api_query = db.query(AnalyticsApiLog).filter(AnalyticsApiLog.created_at >= since)
    today_page_query = db.query(AnalyticsPageView).filter(AnalyticsPageView.created_at >= today_start)
    today_session_query = db.query(AnalyticsSession).filter(AnalyticsSession.last_seen_at >= today_start)

    today_pv = int(today_page_query.with_entities(func.count(AnalyticsPageView.id)).scalar() or 0)
    today_uv = int(
        today_page_query.with_entities(func.count(func.distinct(AnalyticsPageView.visitor_key))).scalar()
        or 0
    )
    today_dau = int(
        today_session_query.filter(AnalyticsSession.user_id.isnot(None))
        .with_entities(func.count(func.distinct(AnalyticsSession.user_id)))
        .scalar()
        or 0
    )
    today_new_users = int(
        db.query(UserModel).filter(UserModel.created_at >= today_start).with_entities(func.count(UserModel.id)).scalar()
        or 0
    )
    today_session_total = int(today_session_query.with_entities(func.count(AnalyticsSession.id)).scalar() or 0)
    today_bounces = int(
        today_session_query.filter(AnalyticsSession.page_count <= 1)
        .with_entities(func.count(AnalyticsSession.id))
        .scalar()
        or 0
    )
    today_avg_visit = _analytics_avg(
        today_session_query.with_entities(func.avg(AnalyticsSession.duration_seconds)).scalar()
    )
    api_total = int(api_query.with_entities(func.count(AnalyticsApiLog.id)).scalar() or 0)
    api_errors = int(
        api_query.filter(or_(AnalyticsApiLog.status_code >= 400, AnalyticsApiLog.success.is_(False)))
        .with_entities(func.count(AnalyticsApiLog.id))
        .scalar()
        or 0
    )
    api_avg_ms = _analytics_avg(api_query.with_entities(func.avg(AnalyticsApiLog.duration_ms)).scalar())

    trend_map = _analytics_trend_seed(since, safe_days)
    page_date = func.date(AnalyticsPageView.created_at).label("date")
    for row in (
        page_query.with_entities(
            page_date,
            func.count(AnalyticsPageView.id).label("pv"),
            func.count(func.distinct(AnalyticsPageView.visitor_key)).label("uv"),
            func.count(func.distinct(AnalyticsPageView.user_id)).label("dau"),
        )
        .group_by(page_date)
        .all()
    ):
        item = trend_map.get(_date_key(row.date))
        if item:
            item["pv"] = int(row.pv or 0)
            item["uv"] = int(row.uv or 0)
            item["dau"] = int(row.dau or 0)

    user_date = func.date(UserModel.created_at).label("date")
    for row in (
        db.query(UserModel)
        .filter(UserModel.created_at >= since)
        .with_entities(user_date, func.count(UserModel.id).label("new_users"))
        .group_by(user_date)
        .all()
    ):
        item = trend_map.get(_date_key(row.date))
        if item:
            item["new_users"] = int(row.new_users or 0)

    session_date = func.date(AnalyticsSession.last_seen_at).label("date")
    for row in (
        session_query.with_entities(
            session_date,
            func.avg(AnalyticsSession.duration_seconds).label("avg_visit_seconds"),
        )
        .group_by(session_date)
        .all()
    ):
        item = trend_map.get(_date_key(row.date))
        if item:
            item["avg_visit_seconds"] = _analytics_avg(row.avg_visit_seconds)

    page_rank = []
    for row in (
        page_query.with_entities(
            AnalyticsPageView.path.label("path"),
            func.max(AnalyticsPageView.title).label("title"),
            func.count(AnalyticsPageView.id).label("views"),
            func.count(func.distinct(AnalyticsPageView.visitor_key)).label("visitors"),
            func.avg(AnalyticsPageView.duration_seconds).label("avg_duration_seconds"),
            func.sum(case((AnalyticsPageView.is_exit.is_(True), 1), else_=0)).label("exits"),
            func.sum(case((AnalyticsPageView.is_entry.is_(True), 1), else_=0)).label("entries"),
        )
        .group_by(AnalyticsPageView.path)
        .order_by(desc("views"))
        .limit(20)
        .all()
    ):
        views = int(row.views or 0)
        exits = int(row.exits or 0)
        entries = int(row.entries or 0)
        page_rank.append(
            {
                "path": row.path or "/",
                "title": row.title or "",
                "views": views,
                "visitors": int(row.visitors or 0),
                "avg_duration_seconds": _analytics_avg(row.avg_duration_seconds),
                "exit_rate": _analytics_rate(exits, views),
                "bounce_rate": _analytics_rate(exits, entries),
            }
        )

    feature_rank = []
    for row in (
        module_query.with_entities(
            AnalyticsModuleUsage.module_key.label("module_key"),
            func.max(AnalyticsModuleUsage.module_label).label("module_label"),
            AnalyticsModuleUsage.action.label("action"),
            func.count(AnalyticsModuleUsage.id).label("count"),
            func.count(func.distinct(AnalyticsModuleUsage.visitor_key)).label("visitors"),
            func.sum(case((AnalyticsModuleUsage.success.is_(True), 1), else_=0)).label("success_count"),
            func.avg(AnalyticsModuleUsage.duration_ms).label("avg_duration_ms"),
        )
        .group_by(AnalyticsModuleUsage.module_key, AnalyticsModuleUsage.action)
        .order_by(desc("count"))
        .limit(20)
        .all()
    ):
        count_value = int(row.count or 0)
        success_count = int(row.success_count or 0)
        feature_rank.append(
            {
                "module_key": row.module_key or "unknown",
                "module_label": row.module_label or row.module_key or "unknown",
                "action": row.action or "",
                "count": count_value,
                "visitors": int(row.visitors or 0),
                "success_rate": _analytics_rate(success_count, count_value),
                "avg_duration_ms": _analytics_avg(row.avg_duration_ms),
            }
        )

    visit_site = int(page_query.with_entities(func.count(func.distinct(AnalyticsPageView.visitor_key))).scalar() or 0)
    auth_page = int(
        page_query.filter(or_(AnalyticsPageView.path.like("%/login%"), AnalyticsPageView.path.like("%/register%")))
        .with_entities(func.count(func.distinct(AnalyticsPageView.visitor_key)))
        .scalar()
        or 0
    )
    registered = int(
        db.query(UserModel)
        .filter(UserModel.created_at >= since)
        .with_entities(func.count(UserModel.id))
        .scalar()
        or 0
    )
    first_login = int(
        module_query.filter(AnalyticsModuleUsage.module_key == "auth", AnalyticsModuleUsage.action.like("login%"))
        .with_entities(func.count(func.distinct(AnalyticsModuleUsage.visitor_key)))
        .scalar()
        or 0
    )
    first_search = int(
        module_query.filter(AnalyticsModuleUsage.module_key == "stock_search")
        .with_entities(func.count(func.distinct(AnalyticsModuleUsage.visitor_key)))
        .scalar()
        or 0
    )
    core_feature = int(
        module_query.filter(AnalyticsModuleUsage.module_key.in_(sorted(ANALYTICS_CORE_MODULES)))
        .with_entities(func.count(func.distinct(AnalyticsModuleUsage.visitor_key)))
        .scalar()
        or 0
    )
    subscription_click = int(
        module_query.filter(
            or_(
                AnalyticsModuleUsage.module_key == "subscription",
                AnalyticsModuleUsage.action == "subscription_click",
            )
        )
        .with_entities(func.count(func.distinct(AnalyticsModuleUsage.visitor_key)))
        .scalar()
        or 0
    )
    payment_started = int(
        module_query.filter(
            or_(
                AnalyticsModuleUsage.module_key == "payment",
                AnalyticsModuleUsage.action == "payment_started",
            )
        )
        .with_entities(func.count(func.distinct(AnalyticsModuleUsage.visitor_key)))
        .scalar()
        or 0
    )
    funnel_counts = [
        ("visit_site", "访问网站", visit_site),
        ("auth_page", "进入登录 / 注册页", auth_page),
        ("registered", "完成注册", registered),
        ("first_login", "完成首次登录", first_login),
        ("first_search", "完成首次股票搜索", first_search),
        ("core_feature", "使用核心功能", core_feature),
        ("subscription_click", "点击订阅入口", subscription_click),
        ("payment_started", "发起支付", payment_started),
    ]
    funnel = []
    previous = funnel_counts[0][2] if funnel_counts else 0
    for key, label, count_value in funnel_counts:
        funnel.append(_analytics_funnel_step(key, label, count_value, visit_site, previous))
        previous = count_value

    device_rows = (
        page_query.with_entities(
            AnalyticsPageView.device_type.label("device_type"),
            func.count(AnalyticsPageView.id).label("views"),
            func.count(func.distinct(AnalyticsPageView.visitor_key)).label("visitors"),
        )
        .group_by(AnalyticsPageView.device_type)
        .order_by(desc("views"))
        .all()
    )
    source_rows = (
        session_query.with_entities(
            AnalyticsSession.source_type.label("source_type"),
            func.count(AnalyticsSession.id).label("views"),
            func.count(func.distinct(AnalyticsSession.visitor_key)).label("visitors"),
        )
        .group_by(AnalyticsSession.source_type)
        .order_by(desc("views"))
        .all()
    )
    browser_rows = (
        page_query.with_entities(
            AnalyticsPageView.browser.label("browser"),
            func.count(AnalyticsPageView.id).label("views"),
            func.count(func.distinct(AnalyticsPageView.visitor_key)).label("visitors"),
        )
        .group_by(AnalyticsPageView.browser)
        .order_by(desc("views"))
        .limit(8)
        .all()
    )
    os_rows = (
        page_query.with_entities(
            AnalyticsPageView.os.label("os"),
            func.count(AnalyticsPageView.id).label("views"),
            func.count(func.distinct(AnalyticsPageView.visitor_key)).label("visitors"),
        )
        .group_by(AnalyticsPageView.os)
        .order_by(desc("views"))
        .limit(8)
        .all()
    )

    api_slow_top = []
    for row in (
        api_query.with_entities(
            AnalyticsApiLog.method.label("method"),
            AnalyticsApiLog.path.label("path"),
            func.count(AnalyticsApiLog.id).label("count"),
            func.avg(AnalyticsApiLog.duration_ms).label("avg_duration_ms"),
            func.max(AnalyticsApiLog.duration_ms).label("max_duration_ms"),
            func.sum(case((or_(AnalyticsApiLog.status_code >= 400, AnalyticsApiLog.success.is_(False)), 1), else_=0)).label("error_count"),
        )
        .group_by(AnalyticsApiLog.method, AnalyticsApiLog.path)
        .order_by(desc("avg_duration_ms"))
        .limit(10)
        .all()
    ):
        count_value = int(row.count or 0)
        error_count = int(row.error_count or 0)
        api_slow_top.append(
            {
                "method": row.method,
                "path": row.path,
                "count": count_value,
                "avg_duration_ms": _analytics_avg(row.avg_duration_ms),
                "max_duration_ms": _analytics_avg(row.max_duration_ms),
                "error_count": error_count,
                "error_rate": _analytics_rate(error_count, count_value),
            }
        )

    api_error_top = []
    for row in (
        api_query.filter(or_(AnalyticsApiLog.status_code >= 400, AnalyticsApiLog.success.is_(False)))
        .with_entities(
            AnalyticsApiLog.status_code.label("status_code"),
            AnalyticsApiLog.method.label("method"),
            AnalyticsApiLog.path.label("path"),
            func.count(AnalyticsApiLog.id).label("count"),
            func.avg(AnalyticsApiLog.duration_ms).label("avg_duration_ms"),
        )
        .group_by(AnalyticsApiLog.status_code, AnalyticsApiLog.method, AnalyticsApiLog.path)
        .order_by(desc("count"))
        .limit(10)
        .all()
    ):
        api_error_top.append(
            {
                "status_code": int(row.status_code or 0),
                "method": row.method,
                "path": row.path,
                "count": int(row.count or 0),
                "avg_duration_ms": _analytics_avg(row.avg_duration_ms),
            }
        )

    module_heatmap = []
    module_date = func.date(AnalyticsModuleUsage.created_at).label("date")
    for row in (
        module_query.with_entities(
            module_date,
            AnalyticsModuleUsage.module_key.label("module_key"),
            func.max(AnalyticsModuleUsage.module_label).label("module_label"),
            func.count(AnalyticsModuleUsage.id).label("count"),
        )
        .group_by(module_date, AnalyticsModuleUsage.module_key)
        .order_by(module_date.asc(), desc("count"))
        .all()
    ):
        module_heatmap.append(
            {
                "date": _date_key(row.date),
                "module_key": row.module_key or "unknown",
                "module_label": row.module_label or row.module_key or "unknown",
                "count": int(row.count or 0),
            }
        )

    high_frequency_users = []
    for row in (
        page_query.filter(AnalyticsPageView.user_id.isnot(None))
        .join(UserModel, UserModel.id == AnalyticsPageView.user_id)
        .with_entities(
            AnalyticsPageView.user_id.label("user_id"),
            UserModel.username.label("username"),
            UserModel.role.label("role"),
            func.count(AnalyticsPageView.id).label("page_views"),
            func.count(func.distinct(AnalyticsPageView.session_key)).label("sessions"),
            func.max(AnalyticsPageView.created_at).label("last_seen_at"),
        )
        .group_by(AnalyticsPageView.user_id, UserModel.username, UserModel.role)
        .order_by(desc("page_views"))
        .limit(10)
        .all()
    ):
        high_frequency_users.append(
            {
                "user_id": row.user_id,
                "username": row.username,
                "role": normalize_user_role(row.role),
                "page_views": int(row.page_views or 0),
                "sessions": int(row.sessions or 0),
                "last_seen_at": row.last_seen_at.isoformat() if row.last_seen_at else None,
            }
        )

    last_seen_rows = (
        db.query(
            UserModel.id,
            UserModel.username,
            UserModel.role,
            UserModel.created_at,
            func.max(AnalyticsPageView.created_at).label("last_seen_at"),
        )
        .outerjoin(AnalyticsPageView, UserModel.id == AnalyticsPageView.user_id)
        .filter(UserModel.role != "admin")
        .group_by(UserModel.id, UserModel.username, UserModel.role, UserModel.created_at)
        .order_by(func.max(AnalyticsPageView.created_at).asc())
        .limit(50)
        .all()
    )
    silent_users = []
    stale_before = _utcnow() - timedelta(days=30)
    for row in last_seen_rows:
        last_seen_at = _as_naive_utc(row.last_seen_at)
        if last_seen_at is None or last_seen_at < stale_before:
            silent_users.append(
                {
                    "user_id": row.id,
                    "username": row.username,
                    "role": normalize_user_role(row.role),
                    "last_seen_at": last_seen_at.isoformat() if last_seen_at else None,
                    "created_at": row.created_at.isoformat() if row.created_at else None,
                }
            )
        if len(silent_users) >= 10:
            break

    return {
        "range": {"days": safe_days, "since": since.isoformat()},
        "summary": {
            "today_pv": today_pv,
            "today_uv": today_uv,
            "today_dau": today_dau,
            "today_new_users": today_new_users,
            "avg_visit_seconds": today_avg_visit,
            "bounce_rate": _analytics_rate(today_bounces, today_session_total),
            "api_error_rate": _analytics_rate(api_errors, api_total),
            "api_avg_duration_ms": api_avg_ms,
            "api_request_count": api_total,
            "api_error_count": api_errors,
        },
        "traffic_trend": list(trend_map.values()),
        "page_rank": page_rank,
        "feature_rank": feature_rank,
        "funnel": funnel,
        "device_distribution": _analytics_distribution(device_rows, "device_type"),
        "source_distribution": _analytics_distribution(source_rows, "source_type"),
        "browser_distribution": _analytics_distribution(browser_rows, "browser"),
        "os_distribution": _analytics_distribution(os_rows, "os"),
        "api_slow_top": api_slow_top,
        "api_error_top": api_error_top,
        "module_heatmap": module_heatmap,
        "high_frequency_users": high_frequency_users,
        "silent_users": silent_users,
    }


@app.get(
    "/api/admin/analytics/export",
    dependencies=[Depends(require_permission("system.manage"))],
)
def export_admin_analytics_csv(
    days: int = 30,
    limit: int = 50000,
    db: Session = Depends(get_db),
):
    safe_days, since = _revenue_since(days)
    safe_limit = max(1, min(int(limit or 50000), 100000))
    dashboard = get_admin_analytics_dashboard(days=safe_days, db=db)
    summary_rows = [["range_days", safe_days], ["since", since], ["export_limit", safe_limit]]
    summary_rows.extend([[key, value] for key, value in (dashboard.get("summary") or {}).items()])

    traffic_headers = ["date", "pv", "uv", "dau", "new_users", "avg_visit_seconds"]
    page_rank_headers = [
        "path",
        "title",
        "views",
        "visitors",
        "avg_duration_seconds",
        "exit_rate",
        "bounce_rate",
    ]
    feature_headers = [
        "module_key",
        "module_label",
        "action",
        "count",
        "visitors",
        "success_rate",
        "avg_duration_ms",
    ]
    funnel_headers = ["key", "label", "count", "conversion_rate", "overall_rate"]

    daily_rows = []
    for row in (
        db.query(AnalyticsDailyStats)
        .filter(AnalyticsDailyStats.stat_date >= since.date())
        .order_by(AnalyticsDailyStats.stat_date.asc())
        .limit(safe_limit)
        .all()
    ):
        daily_rows.append(
            [
                row.stat_date,
                row.pv,
                row.uv,
                row.dau,
                row.new_users,
                row.avg_visit_seconds,
                row.bounce_rate,
                row.created_at,
                row.updated_at,
            ]
        )

    session_rows = []
    for row, username in (
        db.query(AnalyticsSession)
        .filter(AnalyticsSession.last_seen_at >= since)
        .outerjoin(UserModel, UserModel.id == AnalyticsSession.user_id)
        .with_entities(AnalyticsSession, UserModel.username)
        .order_by(AnalyticsSession.last_seen_at.desc(), AnalyticsSession.id.desc())
        .limit(safe_limit)
        .all()
    ):
        session_rows.append(
            [
                row.id,
                row.session_key,
                row.visitor_key,
                row.user_id,
                username,
                row.started_at,
                row.last_seen_at,
                row.duration_seconds,
                row.page_count,
                row.is_returning,
                row.source_type,
                row.source,
                row.device_type,
                row.browser,
                row.os,
                row.region,
                row.created_at,
            ]
        )

    page_view_rows = []
    for row, username in (
        db.query(AnalyticsPageView)
        .filter(AnalyticsPageView.created_at >= since)
        .outerjoin(UserModel, UserModel.id == AnalyticsPageView.user_id)
        .with_entities(AnalyticsPageView, UserModel.username)
        .order_by(AnalyticsPageView.created_at.desc(), AnalyticsPageView.id.desc())
        .limit(safe_limit)
        .all()
    ):
        page_view_rows.append(
            [
                row.id,
                row.created_at,
                row.session_key,
                row.visitor_key,
                row.user_id,
                username,
                row.path,
                row.title,
                row.referrer,
                row.source_type,
                row.source,
                row.device_type,
                row.browser,
                row.os,
                row.region,
                row.duration_seconds,
                row.is_entry,
                row.is_exit,
            ]
        )

    module_rows = []
    for row, username in (
        db.query(AnalyticsModuleUsage)
        .filter(AnalyticsModuleUsage.created_at >= since)
        .outerjoin(UserModel, UserModel.id == AnalyticsModuleUsage.user_id)
        .with_entities(AnalyticsModuleUsage, UserModel.username)
        .order_by(AnalyticsModuleUsage.created_at.desc(), AnalyticsModuleUsage.id.desc())
        .limit(safe_limit)
        .all()
    ):
        module_rows.append(
            [
                row.id,
                row.created_at,
                row.module_key,
                row.module_label,
                row.action,
                row.path,
                row.success,
                row.result_count,
                row.duration_ms,
                row.session_key,
                row.visitor_key,
                row.user_id,
                username,
            ]
        )

    api_rows = []
    for row, username in (
        db.query(AnalyticsApiLog)
        .filter(AnalyticsApiLog.created_at >= since)
        .outerjoin(UserModel, UserModel.id == AnalyticsApiLog.user_id)
        .with_entities(AnalyticsApiLog, UserModel.username)
        .order_by(AnalyticsApiLog.created_at.desc(), AnalyticsApiLog.id.desc())
        .limit(safe_limit)
        .all()
    ):
        api_rows.append(
            [
                row.id,
                row.created_at,
                row.method,
                row.path,
                row.status_code,
                row.success,
                row.duration_ms,
                row.user_id,
                username,
                row.session_key,
                row.visitor_key,
            ]
        )

    sections = [
        ("summary", ["metric", "value"], summary_rows),
        (
            "traffic_trend",
            traffic_headers,
            _csv_section_rows(dashboard.get("traffic_trend") or [], traffic_headers),
        ),
        (
            "page_rank",
            page_rank_headers,
            _csv_section_rows(dashboard.get("page_rank") or [], page_rank_headers),
        ),
        (
            "feature_rank",
            feature_headers,
            _csv_section_rows(dashboard.get("feature_rank") or [], feature_headers),
        ),
        (
            "user_funnel",
            funnel_headers,
            _csv_section_rows(dashboard.get("funnel") or [], funnel_headers),
        ),
        (
            "daily_stats_records",
            [
                "stat_date",
                "pv",
                "uv",
                "dau",
                "new_users",
                "avg_visit_seconds",
                "bounce_rate",
                "created_at",
                "updated_at",
            ],
            daily_rows,
        ),
        (
            "analytics_sessions",
            [
                "id",
                "session_key",
                "visitor_key",
                "user_id",
                "username",
                "started_at",
                "last_seen_at",
                "duration_seconds",
                "page_count",
                "is_returning",
                "source_type",
                "source",
                "device_type",
                "browser",
                "os",
                "region",
                "created_at",
            ],
            session_rows,
        ),
        (
            "analytics_page_views",
            [
                "id",
                "created_at",
                "session_key",
                "visitor_key",
                "user_id",
                "username",
                "path",
                "title",
                "referrer",
                "source_type",
                "source",
                "device_type",
                "browser",
                "os",
                "region",
                "duration_seconds",
                "is_entry",
                "is_exit",
            ],
            page_view_rows,
        ),
        (
            "analytics_module_usage",
            [
                "id",
                "created_at",
                "module_key",
                "module_label",
                "action",
                "path",
                "success",
                "result_count",
                "duration_ms",
                "session_key",
                "visitor_key",
                "user_id",
                "username",
            ],
            module_rows,
        ),
        (
            "analytics_api_logs",
            [
                "id",
                "created_at",
                "method",
                "path",
                "status_code",
                "success",
                "duration_ms",
                "user_id",
                "username",
                "session_key",
                "visitor_key",
            ],
            api_rows,
        ),
    ]
    return _csv_response("quartsys-analytics", sections)


@app.get("/api/assistant/skills", dependencies=[Depends(require_permission("assistant.use"))])
def get_assistant_skills_api(db: Session = Depends(get_db)):
    settings_value = _assistant_skills_settings(db, enabled_only=True)
    return {"skills": [_assistant_public_skill(item) for item in settings_value["skills"]]}


@app.get("/api/admin/assistant/skills", dependencies=[Depends(require_permission("system.manage"))])
def get_admin_assistant_skills_api(db: Session = Depends(get_db)):
    return _assistant_skills_settings(db, enabled_only=False)


@app.post("/api/admin/assistant/skills", dependencies=[Depends(require_permission("system.manage"))])
def save_admin_assistant_skills_api(
    payload: AssistantSkillsSettingsSchema,
    db: Session = Depends(get_db),
):
    saved = _save_assistant_skills_settings(db, payload.model_dump())
