@app.post("/api/public/customer-service-ai/chat")
def chat_public_customer_service_ai_api(
    payload: CustomerServiceChatRequest,
    db: Session = Depends(get_db),
):
    message = _customer_service_clean_text(payload.message, 1200)
    if not message:
        raise HTTPException(status_code=400, detail="消息内容不能为空")
    config = _customer_service_ai_settings(db, masked=False)
    if not _customer_service_is_ready(db, config):
        raise HTTPException(status_code=404, detail="AI客服未启用")

    llm_cfg = _customer_service_effective_llm_config(db, config)
    knowledge = _customer_service_knowledge_context(config, message)
    system = _customer_service_clean_text(config.get("system_prompt"), 8000)
    if knowledge:
        system += "\n\n[客服知识库]\n" + knowledge
    system += (
        "\n\n[回答要求]\n"
        "优先回答产品能力、客户咨询、快速引导和工单提交相关问题。"
        "涉及投资判断时必须提示仅供研究参考，不构成投资建议。"
        "如果用户需要人工处理，请引导其提交工单并留下联系方式。"
    )
    history = _assistant_sanitize_history(payload.history, max_rounds=6)
    messages = [
        {"role": "system", "content": system},
        *history,
        {"role": "user", "content": message},
    ]
    try:
        raw = _assistant_call_json_llm(
            llm_cfg,
            messages,
            temperature=0.3,
            read_timeout=_assistant_timeout_seconds(
                "CUSTOMER_SERVICE_LLM_READ_TIMEOUT_SECONDS",
                45.0,
                8.0,
                120.0,
            ),
        )
        answer = _structured_or_text_to_plain(raw) or str(raw or "").strip()
        if not answer:
            answer = _customer_service_fallback_answer(config, message)
        return {"answer": answer[:5000], "fallback": False}
    except Exception as exc:
        return {
            "answer": _customer_service_fallback_answer(config, message),
            "fallback": True,
            "reason": _assistant_sanitize_error(exc),
        }


