def _serialize_support_ticket(
    row: SupportTicket,
    *,
    owner: Optional[UserModel] = None,
    include_admin_details: bool = False,
) -> dict:
    payload = {
        "id": row.id,
        "user_id": row.user_id,
        "category": row.category or "product",
        "subject": row.subject or "",
        "message": row.message or "",
        "status": row.status or "open",
        "priority": row.priority or "normal",
        "admin_reply": row.admin_reply or "",
        "resolved_by": row.resolved_by,
        "resolved_at": row.resolved_at.isoformat() if row.resolved_at else None,
        "email_status": row.email_status or "not_sent",
        "created_at": row.created_at.isoformat() if row.created_at else None,
        "updated_at": row.updated_at.isoformat() if row.updated_at else None,
    }
    if owner is not None:
        payload["user"] = {
            "id": owner.id,
            "username": owner.username or "",
            "email": owner.email or "",
        }
    if include_admin_details:
        payload["email_error"] = row.email_error or ""
    return payload


def _support_ticket_resolution_email_html(
    row: SupportTicket,
    owner: UserModel,
) -> str:
    username = html.escape(str(owner.username or "用户"))
    subject = html.escape(str(row.subject or ""))
    reply = html.escape(str(row.admin_reply or "")).replace("\n", "<br />")
    return (
        f"<p>{username}，您好：</p>"
        f"<p>您提交的工单 <strong>#{row.id} {subject}</strong> 已处理完成。</p>"
        f"<div style=\"margin:16px 0;padding:14px 16px;border-left:3px solid #2563eb;"
        f"background:#f7f4ed;line-height:1.8\">{reply}</div>"
        "<p>您可以登录AIQuartSmart Community Edition量化分析系统，在“设置中心 - 支持与帮助”中查看完整记录。</p>"
    )


def _send_support_ticket_resolution_email(ticket_id: int):
    db = SessionLocal()
    row: Optional[SupportTicket] = None
    try:
        row = db.query(SupportTicket).filter(SupportTicket.id == ticket_id).first()
        if not row or row.email_status != "queued":
            return
        owner = db.query(UserModel).filter(UserModel.id == row.user_id).first()
        if not owner or not owner.email:
            row.email_status = "skipped"
            row.email_error = None
            db.commit()
            return
        _send_smtp_email(
            _auth_security_settings(db, masked=False),
            owner.email,
            f"工单 #{row.id} 已处理 - {row.subject}",
            _support_ticket_resolution_email_html(row, owner),
        )
        row.email_status = "sent"
        row.email_error = None
        db.commit()
    except Exception as exc:
        db.rollback()
        if row is None:
            row = db.query(SupportTicket).filter(SupportTicket.id == ticket_id).first()
        if row is not None:
            detail = exc.detail if isinstance(exc, HTTPException) else str(exc)
            row.email_status = "failed"
            row.email_error = str(detail or "邮件发送失败")[:1000]
            db.commit()
    finally:
        db.close()


