@app.get(
    "/api/admin/support/tickets",
    dependencies=[Depends(require_permission("system.manage"))],
)
def list_admin_support_tickets_api(
    search: str = "",
    status: str = "",
    category: str = "",
    page: int = 1,
    page_size: int = 20,
    db: Session = Depends(get_db),
):
    safe_page = max(1, int(page or 1))
    safe_page_size = max(1, min(100, int(page_size or 20)))
    normalized_status = str(status or "").strip().lower()
    normalized_category = str(category or "").strip().lower()
    query = db.query(SupportTicket, UserModel).join(
        UserModel,
        UserModel.id == SupportTicket.user_id,
    )
    if normalized_status and normalized_status != "all":
        if normalized_status not in SUPPORT_TICKET_STATUSES:
            raise HTTPException(status_code=400, detail="不支持的工单状态")
        query = query.filter(SupportTicket.status == normalized_status)
    if normalized_category and normalized_category != "all":
        if normalized_category not in SUPPORT_TICKET_CATEGORIES:
            raise HTTPException(status_code=400, detail="不支持的工单分类")
        query = query.filter(SupportTicket.category == normalized_category)
    search_text = str(search or "").strip()[:120]
    if search_text:
        pattern = f"%{search_text}%"
        query = query.filter(
            or_(
                SupportTicket.subject.ilike(pattern),
                SupportTicket.message.ilike(pattern),
                SupportTicket.admin_reply.ilike(pattern),
                UserModel.username.ilike(pattern),
                UserModel.email.ilike(pattern),
            )
        )
    total = query.count()
    status_order = case(
        (SupportTicket.status == "open", 0),
        (SupportTicket.status == "in_progress", 1),
        (SupportTicket.status == "resolved", 2),
        else_=3,
    )
    priority_order = case(
        (SupportTicket.priority == "urgent", 0),
        (SupportTicket.priority == "high", 1),
        (SupportTicket.priority == "normal", 2),
        else_=3,
    )
    rows = (
        query.order_by(status_order, priority_order, SupportTicket.created_at.desc())
        .offset((safe_page - 1) * safe_page_size)
        .limit(safe_page_size)
        .all()
    )
    return {
        "tickets": [
            _serialize_support_ticket(
                ticket,
                owner=owner,
                include_admin_details=True,
            )
            for ticket, owner in rows
        ],
        "total": total,
        "page": safe_page,
        "page_size": safe_page_size,
        "pages": max(1, math.ceil(total / safe_page_size)),
    }


@app.patch(
    "/api/admin/support/tickets/{ticket_id}",
    dependencies=[Depends(require_permission("system.manage"))],
)
def update_admin_support_ticket_api(
    ticket_id: int,
    payload: SupportTicketAdminUpdateRequest,
    background_tasks: BackgroundTasks,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    row = db.query(SupportTicket).filter(SupportTicket.id == ticket_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="工单不存在")
    previous_status = row.status or "open"
    if payload.priority is not None:
        row.priority = payload.priority
    if payload.admin_reply is not None:
        row.admin_reply = payload.admin_reply or None
    if payload.status is not None:
        row.status = payload.status

    next_status = row.status or "open"
    transitioned_to_terminal = (
        previous_status not in SUPPORT_TICKET_TERMINAL_STATUSES
        and next_status in SUPPORT_TICKET_TERMINAL_STATUSES
    )
    if transitioned_to_terminal:
        if not str(row.admin_reply or "").strip():
            raise HTTPException(status_code=400, detail="处理完成前请填写管理员回复")
        row.resolved_by = current_user.id
        row.resolved_at = datetime.now(timezone.utc)
        owner = db.query(UserModel).filter(UserModel.id == row.user_id).first()
        smtp_enabled = bool(
            (_auth_security_settings(db, masked=False).get("smtp") or {}).get("enabled")
        )
        row.email_status = "queued" if owner and owner.email and smtp_enabled else "skipped"
        row.email_error = None
        db.add(
            Notification(
                user_id=row.user_id,
                type="support_ticket",
                title=f"工单 #{row.id} 已处理",
                content=f"{row.subject}\n{row.admin_reply}",
            )
        )
    elif next_status not in SUPPORT_TICKET_TERMINAL_STATUSES:
        row.resolved_by = None
        row.resolved_at = None
        if previous_status in SUPPORT_TICKET_TERMINAL_STATUSES:
            row.email_status = "not_sent"
            row.email_error = None

    db.commit()
    db.refresh(row)
    owner = db.query(UserModel).filter(UserModel.id == row.user_id).first()
    if transitioned_to_terminal and row.email_status == "queued":
        background_tasks.add_task(_send_support_ticket_resolution_email, row.id)
    return {
        "status": "ok",
        "ticket": _serialize_support_ticket(
            row,
            owner=owner,
            include_admin_details=True,
        ),
    }


@app.get("/api/llm-config", dependencies=[Depends(require_permission("settings.view"))])
def get_llm_config_api(
    db: Session = Depends(get_db), current_user: UserModel = Depends(get_current_user)
):
    from llm_factory import get_llm_config

    is_admin = normalize_user_role(current_user.role) == "admin"
    cfg = _shared_llm_config_row(db)
    effective = get_llm_config(
        db, user_id=None if is_admin else current_user.id, allow_shared_fallback=True
    )
    key = effective.get("api_key")
    masked = (
        (key[:4] + "****" + key[-4:])
        if key and len(key) > 8
        else ("****" if key else None)
    )
    key_source = None
    if cfg and cfg.api_key:
        key_source = "database"
    default_model = effective.get("model") or DEFAULT_LLM_MODEL
    default_provider = _normalize_llm_provider(
        (cfg.provider if cfg else effective.get("provider")) or "openai"
    )
    module_model_configs = _sanitize_module_model_configs(
        _parse_module_model_configs(getattr(cfg, "module_models_json", None) if cfg else None),
        default_model,
        default_provider,
    )
    model_options = _sanitize_llm_model_options(
        _get_system_setting_json(db, LLM_MODEL_OPTIONS_KEY, _default_llm_model_options())
    )
    if not is_admin:
        public_options = _public_llm_model_options(model_options, current_user)
        return {
            "provider": "",
            "model": public_options.get("default_model") or "smart",
            "module_models": public_options.get("module_models") or {},
            "module_model_configs": {},
            "api_key": None,
            "api_key_configured": bool(key),
            "api_key_source": "system" if key else None,
            "base_url": "",
            "scope": "tier_selection",
            "models": public_options["models"],
            "model_options": public_options,
        }
    return {
        "provider": default_provider,
        "model": default_model,
        "module_models": _legacy_module_models(module_model_configs),
        "module_model_configs": module_model_configs,
        "api_key": masked,
        "api_key_configured": bool(key),
        "api_key_source": key_source,
        "base_url": effective.get("base_url") or "",
        "scope": "system",
        "models": model_options["models"],
        "model_options": model_options,
    }


@app.post("/api/llm-config", dependencies=[Depends(require_permission("system.manage"))])
def save_llm_config_api(
    data: LLMConfigSchema,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    cfg = _ensure_shared_llm_config_row(db)
    incoming_api_key = (data.api_key or "").strip()
    has_existing_key = bool(cfg.api_key)
    if not incoming_api_key and not has_existing_key:
        raise HTTPException(status_code=400, detail="API 密钥不能为空，请填写后再保存")
    if _is_masked_api_key(incoming_api_key) and not has_existing_key:
        raise HTTPException(status_code=400, detail="当前只有脱敏密钥，未找到已保存的真实 API Key，请重新填写完整密钥")

    cfg.provider = _normalize_llm_provider(data.provider)
    cfg.model = data.model
    if data.module_models is not None:
        cfg.module_models_json = json.dumps(
            _sanitize_module_model_configs(
                data.module_models,
                data.model,
                cfg.provider,
            ),
            ensure_ascii=False,
        )
    # Fernet 加密存储 API Key
    if incoming_api_key and not _is_masked_api_key(incoming_api_key):
        try:
            from cryptography.fernet import Fernet

            fernet_key = os.getenv("FERNET_KEY", "").encode()
            if len(fernet_key) == 44:
                f = Fernet(fernet_key)
                cfg.api_key = "fernet:" + f.encrypt(incoming_api_key.encode()).decode()
            else:
                cfg.api_key = incoming_api_key
        except Exception:
            cfg.api_key = incoming_api_key
    cfg.base_url = data.base_url
    db.commit()
    return {"status": "ok", "api_key_configured": bool(cfg.api_key)}


@app.post("/api/llm-config/models", dependencies=[Depends(require_permission("system.manage"))])
def list_llm_models_api(
    data: LLMConfigSchema,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """Fetch available models from the selected provider when the provider exposes a model list.

    If the frontend only has a masked API key, use the stored backend key.
    """
    try:
        from llm_factory import get_llm_config

        saved = get_llm_config(
            db, user_id=None, allow_shared_fallback=True
        )
    except Exception:
        saved = {}

    provider = _normalize_llm_provider(data.provider or saved.get("provider"))
    base_url = (
        data.base_url
        or saved.get("base_url")
        or _default_llm_base_url(provider)
    ).rstrip("/")
    api_key = (data.api_key or "").strip()
    if not api_key or _is_masked_api_key(api_key):
        api_key = (saved.get("api_key") or "").strip()

    if not base_url:
        raise HTTPException(status_code=400, detail="base_url 不能为空")
    if not api_key:
        raise HTTPException(status_code=400, detail="访问密钥不能为空")

    models_url = f"{base_url}/models"
    try:
        headers = {"Accept": "application/json"}
        params = None
        if provider == "anthropic":
            headers.update(
                {
                    "x-api-key": api_key,
                    "anthropic-version": "2023-06-01",
                }
            )
        elif provider == "google":
            headers["x-goog-api-key"] = api_key
            params = {"key": api_key}
        else:
            headers["Authorization"] = f"Bearer {api_key}"
        response = requests.get(models_url, headers=headers, params=params, timeout=15)
        if response.status_code in {401, 403}:
            raise HTTPException(
                status_code=400,
                detail="模型列表拉取失败：API Key 无效或没有权限",
            )
        response.raise_for_status()
        models = _extract_model_ids(response.json())
    except HTTPException:
        raise
    except Exception as err:
        raise HTTPException(status_code=400, detail=f"模型列表拉取失败: {err}")

    return {"status": "ok", "source": models_url, "models": models}


def _llm_test_config(
    data: LLMConfigSchema,
    db: Session,
    current_user: UserModel,
) -> dict:
    from llm_factory import get_llm_config

    saved = get_llm_config(db, user_id=None, allow_shared_fallback=True)
    provider = _normalize_llm_provider(data.provider or saved.get("provider"))
    model = str(data.model or saved.get("model") or DEFAULT_LLM_MODEL).strip() or DEFAULT_LLM_MODEL
    base_url = str(
        data.base_url or saved.get("base_url") or _default_llm_base_url(provider)
    ).rstrip("/")
    api_key = (data.api_key or "").strip()
    if not api_key or _is_masked_api_key(api_key):
        api_key = (saved.get("api_key") or "").strip()
    if not api_key:
        raise HTTPException(status_code=400, detail="访问密钥不能为空")
    return {
        "provider": provider,
        "model": model,
        "base_url": base_url,
        "api_key": api_key,
    }


def _raise_llm_ping_error(response: requests.Response) -> None:
    if response.status_code < 400:
        return
    try:
        body = response.json()
    except Exception:
        body = response.text
    detail = body
    if isinstance(body, dict):
        detail = (
            body.get("error", {}).get("message")
            if isinstance(body.get("error"), dict)
            else body.get("message") or body.get("detail") or body
        )
    if response.status_code in {401, 403}:
        raise HTTPException(status_code=400, detail=f"LLM 上游鉴权失败：{detail}")
    raise HTTPException(
        status_code=400,
        detail=f"LLM 上游请求失败({response.status_code})：{str(detail)[:300]}",
    )


def _ping_llm_upstream(cfg: dict) -> dict:
    provider = _normalize_llm_provider(cfg.get("provider"))
    model = str(cfg.get("model") or DEFAULT_LLM_MODEL).strip() or DEFAULT_LLM_MODEL
    api_key = str(cfg.get("api_key") or "").strip()
    base_url = str(cfg.get("base_url") or _default_llm_base_url(provider)).rstrip("/")
    started = time.time()
    timeout = (6, 24)
    if provider in {"openai", "custom"}:
        response = requests.post(
            f"{base_url}/chat/completions",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            json={
                "model": model,
                "messages": [{"role": "user", "content": "ping"}],
                "temperature": 0,
                "max_tokens": 8,
            },
            timeout=timeout,
        )
    elif provider == "anthropic":
        response = requests.post(
            f"{base_url}/v1/messages",
            headers={
                "x-api-key": api_key,
                "anthropic-version": "2023-06-01",
                "Content-Type": "application/json",
            },
            json={
                "model": model,
                "max_tokens": 8,
                "messages": [{"role": "user", "content": "ping"}],
            },
            timeout=timeout,
        )
    elif provider == "google":
        clean_model = model
        if clean_model.startswith("models/"):
            clean_model = clean_model.split("/", 1)[1]
        response = requests.post(
            f"{base_url}/models/{quote(clean_model, safe='')}:generateContent",
            headers={
                "x-goog-api-key": api_key,
                "Content-Type": "application/json",
            },
            params={"key": api_key},
            json={
                "contents": [{"parts": [{"text": "ping"}]}],
                "generationConfig": {"maxOutputTokens": 8, "temperature": 0},
            },
            timeout=timeout,
        )
    else:
        raise HTTPException(status_code=400, detail=f"不支持的 provider: {provider}")

    _raise_llm_ping_error(response)
    latency_ms = int((time.time() - started) * 1000)
    return {
        "status": "ok",
        "provider": provider,
        "model": model,
        "latency_ms": latency_ms,
        "message": f"上游连通：{LLM_PROVIDER_LABELS.get(provider, provider)} / {model}，响应 {latency_ms}ms",
    }


@app.post("/api/llm-config/test", dependencies=[Depends(require_permission("system.manage"))])
def test_llm_config_api(
    data: LLMConfigSchema,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """真实请求上游模型服务，确认协议、地址、Key 和模型名可用。"""
    cfg = _llm_test_config(data, db, current_user)
    try:
        return _ping_llm_upstream(cfg)
    except HTTPException:
        raise
    except Exception as err:
        raise HTTPException(status_code=400, detail=f"LLM 上游连通测试失败：{err}")


