def _subscription_order_meta(order: SubscriptionOrder) -> dict:
    payload = _json_loads_dict(order.provider_payload, {})
    meta = payload.get("order_meta") if isinstance(payload.get("order_meta"), dict) else {}
    return meta


def _rewarded_ads_status(db: Session, current_user: UserModel) -> dict:
    settings_value = _billing_settings(db)
    config = settings_value.get("rewarded_ads") or {}
    role = normalize_user_role(current_user.role)
    providers = []
    google = config.get("google") or {}
    if config.get("enabled") and google.get("enabled") and google.get("ad_unit_path"):
        providers.append(
            {
                "key": "google",
                "label": "Google Rewarded Ads",
                "launch_mode": "google_gpt",
            }
        )
    if config.get("enabled"):
        for provider_key in REWARD_AD_EXTERNAL_PROVIDER_ORDER:
            provider_config = config.get(provider_key) or {}
            if _reward_external_provider_ready(provider_config):
                providers.append(
                    {
                        "key": provider_key,
                        "label": REWARD_AD_EXTERNAL_PROVIDER_LABELS.get(
                            provider_key, provider_key
                        ),
                        "launch_mode": "external_callback",
                    }
                )
    active = None if role == "admin" else _ensure_user_subscription(db, current_user)
    is_free = bool(role == "normal" and active and normalize_user_role(active.role) == "normal")
    today_start = datetime.combine(_utcnow().date(), datetime.min.time())
    completed_today = (
        db.query(func.count(AdRewardSession.id))
        .filter(
            AdRewardSession.user_id == current_user.id,
            AdRewardSession.status == "granted",
            AdRewardSession.granted_at >= today_start,
        )
        .scalar()
        or 0
    )
    return {
        "available": bool(config.get("enabled") and providers and is_free),
        "configured": bool(config.get("enabled") and providers),
        "free_only": True,
        "reward_credits": int(config.get("reward_credits") or 0),
        "daily_limit": int(config.get("daily_limit") or 0),
        "completed_today": int(completed_today),
        "remaining_today": max(0, int(config.get("daily_limit") or 0) - int(completed_today)),
        "cooldown_seconds": int(config.get("cooldown_seconds") or 0),
        "providers": providers,
        "reason": "" if is_free else "奖励广告仅向免费用户开放",
    }


def _public_billing_status(db: Session) -> dict:
    settings_value = _billing_settings(db)
    return {
        "credits_per_cny": int(settings_value.get("credits_per_cny") or 100),
        "recharge_min_cents": int(settings_value.get("recharge_min_cents") or 100),
        "recharge_max_cents": int(settings_value.get("recharge_max_cents") or 100000),
        "recharge_presets_cents": settings_value.get("recharge_presets_cents") or [],
        "credit_recharge": {
            "enabled": bool((settings_value.get("credit_recharge") or {}).get("enabled")),
        },
        "enterprise_plan": {
            "enabled": bool((settings_value.get("enterprise_plan") or {}).get("enabled")),
        },
    }


def _subscription_self_payload(db: Session, current_user: UserModel) -> dict:
    active = None if normalize_user_role(current_user.role) == "admin" else _ensure_user_subscription(db, current_user)
    rows = (
        db.query(UserSubscription)
        .filter(UserSubscription.user_id == current_user.id)
        .order_by(UserSubscription.created_at.desc())
        .limit(20)
        .all()
    )
    enabled_plans = (
        db.query(SubscriptionPlan)
        .filter(SubscriptionPlan.enabled == 1)
        .order_by(SubscriptionPlan.sort_order.asc(), SubscriptionPlan.id.asc())
        .all()
    )
    return {
        "role": normalize_user_role(current_user.role),
        "active_subscription": _serialize_subscription(active),
        "subscriptions": [_serialize_subscription(row) for row in rows],
        "credit_summary": _credit_summary(db, current_user),
        "assistant_quota": _assistant_conversation_quota(db, current_user),
        "payment_channels": _payment_channel_status(db),
        "costs": _billing_settings(db).get("module_credit_costs") or dict(AI_CREDIT_COSTS),
        "plan_quotes": {
            str(plan.id): _subscription_checkout_quote(db, current_user, plan)
            for plan in enabled_plans
        },
        "billing": _public_billing_status(db),
        "rewarded_ads": _rewarded_ads_status(db, current_user),
    }


def _find_subscription_plan(db: Session, payload: SubscriptionPayRequest) -> SubscriptionPlan:
    query = db.query(SubscriptionPlan)
    plan = None
    if payload.plan_id:
        plan = query.filter(SubscriptionPlan.id == payload.plan_id).first()
    if not plan and payload.plan_key:
        plan = query.filter(SubscriptionPlan.key == payload.plan_key).first()
    if not plan:
        raise HTTPException(status_code=404, detail="订阅套餐不存在")
    if not plan.enabled:
        raise HTTPException(status_code=400, detail="订阅套餐未启用")
    return plan


def _create_subscription_order(
    db: Session, current_user: UserModel, plan: SubscriptionPlan, provider: str
) -> SubscriptionOrder:
    quote_value = _subscription_checkout_quote(db, current_user, plan)
    if not quote_value.get("eligible"):
        raise HTTPException(status_code=400, detail=quote_value.get("reason") or "当前套餐不可购买")
    db.query(SubscriptionOrder).filter(
        SubscriptionOrder.user_id == current_user.id,
        SubscriptionOrder.status == "pending",
    ).update({SubscriptionOrder.status: "cancelled"}, synchronize_session=False)
    trade_no = f"SUB{current_user.id}{int(time.time() * 1000)}{uuid.uuid4().hex[:6].upper()}"
    order = SubscriptionOrder(
        trade_no=trade_no,
        user_id=current_user.id,
        plan_id=plan.id,
        provider=provider,
        amount_cents=int(quote_value.get("amount_cents") or 0),
        currency=plan.currency or "CNY",
        status="pending",
        provider_payload=json.dumps({"order_meta": quote_value}, ensure_ascii=False),
    )
    db.add(order)
    db.commit()
    db.refresh(order)
    return order


def _serialize_order(order: SubscriptionOrder) -> dict:
    return {
        "id": order.id,
        "trade_no": order.trade_no,
        "plan_id": order.plan_id,
        "provider": order.provider,
        "amount_cents": int(order.amount_cents or 0),
        "currency": order.currency or "CNY",
        "status": order.status,
        "order_type": "subscription",
        "quote": _subscription_order_meta(order),
        "created_at": order.created_at.isoformat() if order.created_at else None,
        "paid_at": order.paid_at.isoformat() if order.paid_at else None,
    }


def _credit_recharge_quote(db: Session, amount_cents: int) -> dict:
    billing = _billing_settings(db)
    if not (billing.get("credit_recharge") or {}).get("enabled"):
        raise HTTPException(status_code=400, detail="AI 使用额度购买暂未开放")
    minimum = int(billing.get("recharge_min_cents") or 100)
    maximum = int(billing.get("recharge_max_cents") or 100000)
    amount = int(amount_cents or 0)
    if amount < minimum or amount > maximum:
        raise HTTPException(
            status_code=400,
            detail=f"充值金额需在 ￥{minimum / 100:.2f} 至 ￥{maximum / 100:.2f} 之间",
        )
    rate = int(billing.get("credits_per_cny") or 100)
    credits = int(amount * rate // 100)
    if credits <= 0:
        raise HTTPException(status_code=400, detail="购买的 AI 使用额度必须大于 0")
    return {
        "amount_cents": amount,
        "currency": "CNY",
        "credits": credits,
        "credits_per_cny": rate,
    }


def _create_credit_recharge_order(
    db: Session,
    current_user: UserModel,
    *,
    amount_cents: int,
    provider: str,
) -> CreditRechargeOrder:
    if normalize_user_role(current_user.role) == "admin":
        raise HTTPException(status_code=400, detail="系统管理员 AI 使用额度无限，无需购买")
    quote_value = _credit_recharge_quote(db, amount_cents)
    db.query(CreditRechargeOrder).filter(
        CreditRechargeOrder.user_id == current_user.id,
        CreditRechargeOrder.status == "pending",
    ).update({CreditRechargeOrder.status: "cancelled"}, synchronize_session=False)
    order = CreditRechargeOrder(
        trade_no=f"CRD{current_user.id}{int(time.time() * 1000)}{uuid.uuid4().hex[:6].upper()}",
        user_id=current_user.id,
        provider=provider,
        amount_cents=quote_value["amount_cents"],
        credits=quote_value["credits"],
        currency="CNY",
        status="pending",
        provider_payload=json.dumps({"quote": quote_value}, ensure_ascii=False),
    )
    db.add(order)
    db.commit()
    db.refresh(order)
    return order


def _serialize_credit_recharge_order(order: CreditRechargeOrder) -> dict:
    return {
        "id": order.id,
        "trade_no": order.trade_no,
        "order_type": "credit_recharge",
        "provider": order.provider,
        "amount_cents": int(order.amount_cents or 0),
        "credits": int(order.credits or 0),
        "currency": order.currency or "CNY",
        "status": order.status,
        "created_at": order.created_at.isoformat() if order.created_at else None,
        "paid_at": order.paid_at.isoformat() if order.paid_at else None,
    }


def _complete_credit_recharge_order(
    db: Session,
    *,
    trade_no: str,
    provider: str,
    provider_payload: Optional[dict] = None,
    provider_trade_no: Optional[str] = None,
) -> dict:
    order = (
        db.query(CreditRechargeOrder)
        .filter(CreditRechargeOrder.trade_no == trade_no)
        .with_for_update()
        .first()
    )
    if not order:
        raise ValueError("credit recharge order not found")
    if order.provider != provider:
        raise ValueError("provider mismatch")
    if order.status == "paid":
        return {"order": order, "completed": False}
    if order.status not in {"pending", "created"}:
        raise ValueError("order status invalid")
    user = db.query(UserModel).filter(UserModel.id == order.user_id).first()
    if not user:
        raise ValueError("user missing")
    order.status = "paid"
    order.provider_trade_no = provider_trade_no or order.provider_trade_no
    order.provider_payload = json.dumps(provider_payload or {}, ensure_ascii=False)
    order.paid_at = _utcnow()
    summary = _grant_user_credits(
        db,
        user,
        action="credit_recharge",
        credits=int(order.credits or 0),
        reference_id=f"recharge:{order.trade_no}",
        meta={
            "amount_cents": int(order.amount_cents or 0),
            "provider": provider,
        },
    )
    db.refresh(order)
    return {"order": order, "credit_summary": summary, "completed": True}


def _complete_ad_reward_session(
    db: Session,
    *,
    session_token: str,
    provider: str,
    provider_event_id: Optional[str] = None,
    meta: Optional[dict] = None,
) -> dict:
    row = (
        db.query(AdRewardSession)
        .filter(AdRewardSession.session_token == session_token)
        .with_for_update()
        .first()
    )
    if not row or row.provider != provider:
        raise HTTPException(status_code=404, detail="广告奖励会话不存在")
    if row.status == "granted":
        user = db.query(UserModel).filter(UserModel.id == row.user_id).first()
        return {
            "status": "ok",
            "completed": False,
            "credits_awarded": int(row.reward_credits or 0),
            "credit_summary": _credit_summary(db, user) if user else None,
        }
    if row.status != "pending" or row.expires_at <= _utcnow():
        row.status = "expired"
        db.commit()
        raise HTTPException(status_code=400, detail="广告奖励会话已失效")
    config = _billing_settings(db).get("rewarded_ads") or {}
    today_start = datetime.combine(_utcnow().date(), datetime.min.time())
    completed_today = (
        db.query(func.count(AdRewardSession.id))
        .filter(
            AdRewardSession.user_id == row.user_id,
            AdRewardSession.status == "granted",
            AdRewardSession.granted_at >= today_start,
        )
        .scalar()
        or 0
    )
    if int(completed_today) >= int(config.get("daily_limit") or 0):
        raise HTTPException(status_code=429, detail="今日广告奖励次数已用完")
    user = db.query(UserModel).filter(UserModel.id == row.user_id).first()
    if not user:
        raise HTTPException(status_code=404, detail="用户不存在")
    row.status = "granted"
    row.provider_event_id = (provider_event_id or f"client:{row.session_token}")[:255]
    row.meta_json = json.dumps(meta or {}, ensure_ascii=False)
    row.granted_at = _utcnow()
    summary = _grant_user_credits(
        db,
        user,
        action="rewarded_ad",
        credits=int(row.reward_credits or 0),
        reference_id=f"rewarded-ad:{row.session_token}",
        meta={"provider": provider, "provider_event_id": row.provider_event_id},
    )
    db.refresh(row)
    return {
        "status": "ok",
        "completed": True,
        "credits_awarded": int(row.reward_credits or 0),
        "credit_summary": summary,
    }


