    plan.name = payload.name.strip()
    plan.description = (payload.description or "").strip()
    plan.role = normalize_user_role(payload.role)
    plan.price_cents = max(0, int(payload.price_cents or 0))
    plan.currency = (payload.currency or "CNY").strip().upper()[:8]
    plan.interval = (payload.interval or "month").strip()[:16]
    plan.credits = max(0, int(payload.credits or 0))
    plan.enabled = 1 if payload.enabled else 0
    plan.sort_order = int(payload.sort_order or 100)
    plan.features_json = json.dumps(payload.features or [], ensure_ascii=False)
