@app.post("/api/admin/redeem-codes", dependencies=[Depends(require_permission("system.manage"))])
def admin_create_redeem_code(
    payload: RedeemCodeUpdateSchema,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    plan = _plan_for_redeem_payload(db, payload)
    code = _normalize_redeem_code(payload.code) if payload.code else _generate_redeem_code(db)
    if not code:
        raise HTTPException(status_code=400, detail="兑换码不能为空")
    if db.query(RedeemCode.id).filter(RedeemCode.code == code).first():
        raise HTTPException(status_code=409, detail="兑换码已存在")
    row = RedeemCode(code=code, created_by_user_id=current_user.id)
    db.add(row)
    _apply_redeem_code_payload(row, payload, plan)
    db.commit()
    db.refresh(row)
    return {"code": _serialize_redeem_code(row)}


@app.put("/api/admin/redeem-codes/{code_id}", dependencies=[Depends(require_permission("system.manage"))])
def admin_update_redeem_code(
    code_id: int,
    payload: RedeemCodeUpdateSchema,
    db: Session = Depends(get_db),
):
    row = db.query(RedeemCode).filter(RedeemCode.id == code_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="兑换码不存在")
    plan = _plan_for_redeem_payload(db, payload)
    next_code = _normalize_redeem_code(payload.code) if payload.code else row.code
    if not next_code:
        raise HTTPException(status_code=400, detail="兑换码不能为空")
    duplicate = (
        db.query(RedeemCode.id)
        .filter(RedeemCode.code == next_code, RedeemCode.id != row.id)
        .first()
    )
    if duplicate:
        raise HTTPException(status_code=409, detail="兑换码已存在")
    if int(payload.max_uses or 1) < int(row.used_count or 0):
        raise HTTPException(status_code=400, detail="总可用次数不能小于已使用次数")
    row.code = next_code
    _apply_redeem_code_payload(row, payload, plan)
    db.commit()
    db.refresh(row)
    return {"code": _serialize_redeem_code(row)}


@app.delete("/api/admin/redeem-codes/{code_id}", dependencies=[Depends(require_permission("system.manage"))])
def admin_disable_redeem_code(code_id: int, db: Session = Depends(get_db)):
    row = db.query(RedeemCode).filter(RedeemCode.id == code_id).first()
    if not row:
        raise HTTPException(status_code=404, detail="兑换码不存在")
    row.enabled = 0
