@app.post("/api/subscription/epay/pay")
def subscription_epay_pay(
    payload: SubscriptionPayRequest,
    request: Request,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    plan = _find_subscription_plan(db, payload)
    if int(plan.price_cents or 0) <= 0:
        raise HTTPException(status_code=400, detail="免费套餐无需支付")
    settings_value = _payment_settings(db, masked=False).get("epay", {})
    if not settings_value.get("enabled") or not settings_value.get("gateway_url"):
        raise HTTPException(status_code=400, detail="暂时未设置支付方式")
    order = _create_subscription_order(db, current_user, plan, "epay")
    if int(order.amount_cents or 0) <= 0:
        completed = _complete_subscription_order(
            db,
            trade_no=order.trade_no,
            provider="epay",
            provider_payload={"zero_amount_upgrade": True},
            provider_trade_no="zero-amount",
        )
        return {
            "message": "completed",
            "data": {},
            "url": "",
            "order": _serialize_order(order),
            "subscription": _serialize_subscription(completed.get("subscription")),
        }
    base_url = _payment_callback_base_url(request, settings_value)
    notify_url = settings_value.get("notify_url") or f"{base_url}/api/subscription/epay/notify"
    return_url = _payment_return_url(request, settings_value)
    params = {
        "pid": settings_value.get("merchant_id", ""),
        "type": _epay_payment_method(payload.payment_method, settings_value),
        "out_trade_no": order.trade_no,
        "notify_url": notify_url,
        "return_url": return_url,
        "name": f"SUB:{plan.name}{'·升级补差价' if _subscription_order_meta(order).get('is_upgrade') else ''}",
        "money": f"{(order.amount_cents or 0) / 100:.2f}",
        "sitename": "StockSys",
    }
    params["sign"] = _epay_sign(params, settings_value.get("secret_key", ""))
    params["sign_type"] = "MD5"
    return {
        "message": "success",
        "data": params,
        "url": settings_value["gateway_url"],
        "order": _serialize_order(order),
        "local_callback_unreachable": _payment_local_callback_notice(request, settings_value),
    }


