async def _epay_params_from_request(request: Request) -> dict:
    params = dict(request.query_params)
    if request.method.upper() == "POST":
        try:
            form = await request.form()
            params.update({key: str(value) for key, value in form.items()})
        except Exception:
            pass
    return params


async def _handle_epay_callback(request: Request, db: Session) -> bool:
    params = await _epay_params_from_request(request)
    settings_value = _payment_settings(db, masked=False).get("epay", {})
    if not params or not _verify_epay_payload(params, settings_value.get("secret_key", "")):
        return False
    trade_status = str(params.get("trade_status") or params.get("status") or "").upper()
    if trade_status and trade_status not in {"TRADE_SUCCESS", "SUCCESS"}:
        return False
    trade_no = str(params.get("out_trade_no") or params.get("trade_no") or "")
    order = db.query(SubscriptionOrder).filter(SubscriptionOrder.trade_no == trade_no).first()
    recharge_order = None
    if not order:
        recharge_order = (
            db.query(CreditRechargeOrder)
            .filter(CreditRechargeOrder.trade_no == trade_no)
            .first()
        )
    billing_order = order or recharge_order
    if not billing_order or billing_order.provider != "epay":
        return False
    try:
        paid_cents = int(round(float(params.get("money") or "0") * 100))
    except Exception:
        paid_cents = 0
    if paid_cents and paid_cents != int(billing_order.amount_cents or 0):
        return False
    try:
        if order:
            _complete_subscription_order(
                db,
                trade_no=trade_no,
                provider="epay",
                provider_payload=params,
                provider_trade_no=str(params.get("trade_no") or ""),
            )
        else:
            _complete_credit_recharge_order(
                db,
                trade_no=trade_no,
                provider="epay",
                provider_payload=params,
                provider_trade_no=str(params.get("trade_no") or ""),
            )
        return True
    except Exception as err:
        print(f"[payment] epay callback failed trade_no={trade_no}: {err}")
        return False


@app.api_route("/api/subscription/epay/notify", methods=["GET", "POST"])
async def subscription_epay_notify(request: Request, db: Session = Depends(get_db)):
    ok = await _handle_epay_callback(request, db)
    return Response("success" if ok else "fail", media_type="text/plain")


@app.api_route("/api/subscription/epay/return", methods=["GET", "POST"])
async def subscription_epay_return(request: Request, db: Session = Depends(get_db)):
    ok = await _handle_epay_callback(request, db)
    return Response("success" if ok else "pending", media_type="text/plain")


@app.post("/api/subscription/stripe/pay")
def subscription_stripe_pay(
    payload: SubscriptionPayRequest,
    request: Request,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    plan = _find_subscription_plan(db, payload)
    if int(plan.price_cents or 0) <= 0:
        raise HTTPException(status_code=400, detail="免费套餐无需支付")
    settings_value = _payment_settings(db, masked=False).get("stripe", {})
    if not settings_value.get("enabled") or not settings_value.get("secret_key"):
        raise HTTPException(status_code=400, detail="暂时未设置支付方式")
    if not settings_value.get("webhook_secret"):
        raise HTTPException(status_code=400, detail="Stripe Webhook Secret 未配置")
    order = _create_subscription_order(db, current_user, plan, "stripe")
    if int(order.amount_cents or 0) <= 0:
        completed = _complete_subscription_order(
            db,
            trade_no=order.trade_no,
            provider="stripe",
            provider_payload={"zero_amount_upgrade": True},
            provider_trade_no="zero-amount",
        )
        return {
            "message": "completed",
            "data": {"pay_link": ""},
            "order": _serialize_order(order),
            "subscription": _serialize_subscription(completed.get("subscription")),
        }
    fallback_return = payload.return_url or f"{str(request.base_url).rstrip('/')}/settings?tab=subscription"
    success_url = _stripe_success_cancel_url(
        settings_value.get("success_url") or fallback_return,
        order.trade_no,
        "success",
    )
    cancel_url = _stripe_success_cancel_url(
        settings_value.get("cancel_url") or fallback_return,
        order.trade_no,
        "cancel",
    )
    try:
        pay_link = _create_stripe_checkout_session(
            secret_key=settings_value.get("secret_key", ""),
            trade_no=order.trade_no,
            success_url=success_url,
            cancel_url=cancel_url,
            email=current_user.email,
            amount_cents=int(order.amount_cents or 0),
            currency=order.currency or "CNY",
            product_name=f"{plan.name}{' · 升级补差价' if _subscription_order_meta(order).get('is_upgrade') else ''}",
        )
    except HTTPException:
        order.status = "failed"
        db.commit()
        raise
    return {
        "message": "success",
        "data": {"pay_link": pay_link},
        "order": _serialize_order(order),
    }


