class AlphaRecommendRequest(BaseModel):
    strategy_name: str = "default"
    limit: int = 10
    market: str = "CN"


ALPHA_RECOMMEND_CACHE_TTL_SECONDS = 300
ALPHA_RECOMMEND_STALE_TTL_SECONDS = 3600


def _alpha_recommend_cache_key(
    settings_value: dict,
    scheme: dict,
    market_code: str,
    role: str,
    effective_limit: int,
) -> str:
    settings_fingerprint = hashlib.sha256(
        json.dumps(
            {
                "scheme": scheme,
                "display_fields": settings_value.get("display_fields") or [],
                "prefer_curated_cache": bool(
                    settings_value.get("prefer_curated_cache")
                ),
            },
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        ).encode("utf-8")
    ).hexdigest()[:16]
    strategy_key = str(scheme.get("key") or "default").strip().lower()
    return (
        "alpha:recommend:v1:"
        f"{market_code}:{role}:{strategy_key}:{effective_limit}:{settings_fingerprint}"
    )


def _alpha_clamp(value: float, low: float = 0.0, high: float = 100.0) -> float:
    return max(low, min(high, float(value)))


def _alpha_stars(score: float) -> int:
    if score >= 85:
        return 5
    if score >= 70:
        return 4
    if score >= 55:
        return 3
    if score >= 40:
        return 2
    return 1


def _alpha_pct_change(row) -> float:
    cached = data_sources.safe_float(getattr(row, "change_pct", None))
    if cached is not None:
        return cached
    open_price = data_sources.safe_float(getattr(row, "open", None)) or 0.0
    close_price = data_sources.safe_float(getattr(row, "close", None)) or 0.0
    return (close_price - open_price) / open_price * 100.0 if open_price else 0.0


def _alpha_scheme_for_key(settings_value: dict, strategy_name: str) -> dict:
    schemes = [
        item
        for item in (settings_value.get("schemes") or [])
        if item.get("enabled", True)
    ]
    if not schemes:
        raise HTTPException(status_code=409, detail="AI 观察池方案尚未启用")
    requested = str(strategy_name or "").strip().lower()
    return next(
        (item for item in schemes if str(item.get("key") or "").lower() == requested),
        schemes[0],
    )


def _alpha_row_score(row, scheme: dict) -> tuple[float, str, str, dict]:
    close = data_sources.safe_float(getattr(row, "close", None)) or 0.0
    ma60 = data_sources.safe_float(getattr(row, "ma60", None))
    pe_ratio = data_sources.safe_float(getattr(row, "pe_ratio", None))
    pb_ratio = data_sources.safe_float(getattr(row, "pb_ratio", None))
    roe = data_sources.safe_float(getattr(row, "roe", None))
    amount_yi = _flow_amount_to_yi(getattr(row, "amount", None), "amount")
    turnover = data_sources.safe_float(getattr(row, "turnover_rate", None)) or 0.0
    change_pct = _alpha_pct_change(row)
    ma_gap = ((close - ma60) / ma60 * 100.0) if close and ma60 else None

    change_score = _alpha_clamp(50.0 + change_pct * 8.0)
    liquidity_score = _alpha_clamp(amount_yi / 20.0 * 100.0) if amount_yi > 0 else 45.0
    turnover_score = _alpha_clamp(turnover * 10.0)
    pe_score = _alpha_clamp(100.0 - abs(pe_ratio - 25.0) * 2.0) if pe_ratio and pe_ratio > 0 else 50.0
    pb_score = _alpha_clamp(100.0 - abs(pb_ratio - 3.0) * 9.0) if pb_ratio and pb_ratio > 0 else 50.0
    valuation_score = pe_score * 0.65 + pb_score * 0.35
    quality_score = _alpha_clamp(45.0 + roe * 2.2) if roe is not None else 50.0
    pe_text = f"{pe_ratio:.1f}" if pe_ratio and pe_ratio > 0 else "暂无"
    pb_text = f"{pb_ratio:.1f}" if pb_ratio and pb_ratio > 0 else "暂无"
    roe_text = f"{roe:.1f}%" if roe is not None else "暂无"
    ma_gap_text = f"{ma_gap:+.2f}%" if ma_gap is not None else "暂无"
    amount_text = f"{amount_yi:.2f} 亿" if amount_yi > 0 else "暂无"
    ma_balance_score = _alpha_clamp(100.0 - abs(ma_gap) * 5.0) if ma_gap is not None else 50.0

    kind = str(scheme.get("kind") or "balanced").lower()
    if kind == "momentum":
        ma_score = _alpha_clamp(100.0 - abs((ma_gap if ma_gap is not None else 0.0) - 4.0) * 8.0)
    elif kind == "reversal":
        ma_score = _alpha_clamp(100.0 - abs((ma_gap if ma_gap is not None else 0.0) + 8.0) * 6.0)
        change_score = _alpha_clamp(50.0 + change_pct * 12.0)
    else:
        ma_score = ma_balance_score

    component_scores = {
        "change": round(change_score, 2),
        "liquidity": round(liquidity_score, 2),
        "valuation": round(valuation_score, 2),
        "turnover": round(turnover_score, 2),
        "ma": round(ma_score, 2),
        "quality": round(quality_score, 2),
    }
    weights = scheme.get("weights") or {}
    score = sum(
        component_scores[key] * float(weights.get(key) or 0.0)
        for key in component_scores
    )
    label_zh = str(scheme.get("label_zh") or "AI 观察池")
    label_en = str(scheme.get("label_en") or "AI Watchlist Pool")
    logic = (
        f"{label_zh}观察样本：涨跌幅 {change_pct:+.2f}%，成交额 {amount_text}，"
        f"PE {pe_text}、PB {pb_text}、ROE {roe_text}，MA60偏离 {ma_gap_text}。"
        f"{str(scheme.get('description_zh') or '').strip()} 该结果仅表示模型筛选信号，不构成买卖建议。"
    )
    logic_en = (
        f"{label_en} candidate: change {change_pct:+.2f}%, turnover {amount_text}, "
        f"PE {pe_text}, PB {pb_text}, ROE {roe_text}, MA60 gap {ma_gap_text}. "
        f"{str(scheme.get('description_en') or '').strip()} This only represents a model screening signal and is not investment advice."
    )
    breakdown = {
        key: {
            "score": component_scores[key],
            "weight": round(float(weights.get(key) or 0.0), 4),
            "contribution": round(component_scores[key] * float(weights.get(key) or 0.0), 2),
        }
        for key in component_scores
    }
    return round(_alpha_clamp(score), 2), logic, logic_en, breakdown


def _alpha_access_limit(user: UserModel) -> int:
    role = normalize_user_role(getattr(user, "role", None))
    return {
        "admin": 12,
        "normal": 0,
        "vip": 3,
        "svip": 6,
    }.get(role, 0)


def _build_alpha_recommendation_payload(
    db: Session,
    *,
    settings_value: dict,
    scheme: dict,
    market_code: str,
    strategy_key: str,
    access_limit: int,
    effective_limit: int,
) -> dict:
    # 从数据库取最新观察样本（若有）
    rows = []
    if market_code == "CN" and settings_value.get("prefer_curated_cache"):
        rows = (
            db.query(AlphaRecommendation)
            .filter(AlphaRecommendation.strategy_name == strategy_key)
            .order_by(AlphaRecommendation.created_at.desc())
            .limit(effective_limit)
            .all()
        )

    # 若无缓存，基于最新日线和策略因子即时打分生成观察样本
    if not rows:
        sq = latest_daily_subquery(db)
        stocks = (
            db.query(
                Stock.code,
                Stock.name,
                Stock.pe_ratio,
                Stock.pb_ratio,
                Stock.roe,
                Stock.market_cap,
                DailyPrice.close,
                DailyPrice.open,
                DailyPrice.amount,
                DailyPrice.change_pct,
                DailyPrice.turnover_rate,
                DailyPrice.ma60,
            )
            .join(sq, sq.c.stock_code == Stock.code)
            .join(
                DailyPrice,
                and_(
                    DailyPrice.stock_code == sq.c.stock_code,
                    DailyPrice.date == sq.c.latest_date,
                ),
            )
            .filter(
                DailyPrice.close > 0,
                _stock_market_condition(market_code),
            )
            .limit(6000)
            .all()
        )
        if not stocks:
            return {
                "strategy_name": strategy_key,
                "market": market_code,
                "items": [],
                "status": "empty",
                "access_limit": access_limit,
                "error": None,
            }
        scored = []
        for s in stocks:
            close = float(s.close or 0)
            if close <= 0:
                continue
            score, logic, logic_en, breakdown = _alpha_row_score(s, scheme)
            scored.append((score, logic, logic_en, breakdown, s))
        scored = sorted(scored, key=lambda item: item[0], reverse=True)[:effective_limit]
        result = []
        for i, (score, logic, logic_en, breakdown, s) in enumerate(scored):
            close = float(s.close or 0)
            stop_loss = close * (1.0 - float(scheme.get("stop_loss_pct") or 5.0) / 100.0)
            target_price = close * (1.0 + float(scheme.get("target_pct") or 12.0) / 100.0)
            result.append(
                {
                    "rank": i + 1,
                    "stock_code": s.code,
                    "stock_name": s.name,
                    "stars": _alpha_stars(score),
                    "score": round(score, 1),
                    "signal_source": "latest_daily_price",
                    "ai_logic": logic,
                    "ai_logic_en": logic_en,
                    "score_breakdown": breakdown,
                    "buy_price": round(close, 2),
                    "stop_loss": round(stop_loss, 2),
                    "target_price": round(target_price, 2),
                    "currency": data_sources.market_currency(market_code),
                    "currency_symbol": data_sources.market_currency_symbol(market_code),
                    "locked": False,
                }
            )
        return {
            "strategy_name": strategy_key,
            "market": market_code,
            "items": result,
            "status": "ok",
            "source": "computed_latest_daily_factor_score",
            "access_limit": access_limit,
            "scheme": scheme,
            "display_fields": settings_value.get("display_fields") or [],
            "error": None,
        }

    result = []
    for i, r in enumerate(rows):
        result.append(
            {
                "rank": i + 1,
                "stock_code": r.stock_code,
                "stock_name": r.stock_name,
                "stars": r.stars,
                "score": None,
                "signal_source": "alpha_recommendations",
                "ai_logic": r.ai_logic or "",
                "ai_logic_en": r.ai_logic or "",
                "score_breakdown": {},
                "buy_price": r.buy_price,
                "stop_loss": r.stop_loss,
                "target_price": r.target_price,
                "currency": data_sources.market_currency(market_code),
                "currency_symbol": data_sources.market_currency_symbol(market_code),
                "locked": False,
            }
        )
    return {
        "strategy_name": strategy_key,
        "market": market_code,
        "items": result,
        "status": "ok",
        "source": "alpha_recommendations",
        "access_limit": access_limit,
        "scheme": scheme,
        "display_fields": settings_value.get("display_fields") or [],
        "error": None,
    }


@app.post("/api/alpha/recommend", dependencies=[Depends(require_permission("ai.insights"))])
def alpha_recommend(
    payload: AlphaRecommendRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """基于策略生成 AI 观察样本；按用户套餐限制返回数量。"""
    market_code = _normalize_market_code(payload.market)
    settings_value = _ai_recommendation_settings(db)
    if not settings_value.get("enabled", True):
        return {
            "strategy_name": payload.strategy_name,
            "market": market_code,
            "items": [],
            "status": "disabled",
            "source": "admin_configuration",
            "access_limit": 0,
            "settings": settings_value,
            "error": None,
        }
    scheme = _alpha_scheme_for_key(settings_value, payload.strategy_name)
    strategy_key = str(scheme.get("key") or "default")
    access_limit = _alpha_access_limit(current_user)
    if access_limit <= 0:
        return {
            "strategy_name": strategy_key,
            "market": market_code,
            "items": [],
            "status": "locked",
            "source": "subscription_limit",
            "access_limit": 0,
            "error": None,
        }
    effective_limit = max(1, min(int(payload.limit or access_limit), access_limit))
    role = normalize_user_role(current_user.role)
    cache_key = _alpha_recommend_cache_key(
        settings_value,
        scheme,
        market_code,
        role,
        effective_limit,
    )
    return _coalesced_cached_json(
        cache_key,
        lambda: _build_alpha_recommendation_payload(
            db,
            settings_value=settings_value,
            scheme=scheme,
            market_code=market_code,
            strategy_key=strategy_key,
            access_limit=access_limit,
            effective_limit=effective_limit,
        ),
        ttl=ALPHA_RECOMMEND_CACHE_TTL_SECONDS,
        stale_ttl=ALPHA_RECOMMEND_STALE_TTL_SECONDS,
        expected_type=dict,
        lock_timeout=45,
        wait_timeout=1.5,
        busy_message="智能观察池正在刷新，请稍后重试",
    )


# --- Position Advice API ---
class PositionAdviceRunRequest(BaseModel):
    model: Optional[str] = None
    market: str = "CN"


def _build_position_advice_data_result(db: Session, market: str) -> dict:
    market_code = _normalize_market_code(market)
    temperature = _database_market_temperature_payload(db, market_code)
    heatmap = temperature.get("heatmap_data") or {}
    ranked = sorted(
        (
            (str(name), float(value))
            for name, value in heatmap.items()
            if name and data_sources.safe_float(value) is not None
        ),
        key=lambda item: item[1],
        reverse=True,
    )
    defaults = {
        "CN": (["科技成长", "高端制造", "消费复苏"], ["银行", "公用事业", "高股息"]),
        "HK": (["互联网平台", "创新药", "可选消费"], ["电信运营", "公用事业", "高股息央企"]),
        "US": (["半导体", "云计算软件", "工业自动化"], ["医疗保健", "公用事业", "必选消费"]),
    }[market_code]
    attack = [name for name, value in ranked if value > 0][:3] or list(defaults[0])
    defensive_candidates = sorted(ranked, key=lambda item: (abs(item[1]), item[1]))
    defense = [name for name, _value in defensive_candidates[:3]] or list(defaults[1])
    total = int(temperature.get("total_count") or 0)
    up_count = int(temperature.get("rise_count") or 0)
    up_ratio = up_count / total if total else 0.5
    avg_change = float(temperature.get("avg_change") or 0.0)
    position_ratio = max(
        0.25,
        min(0.85, 0.38 + up_ratio * 0.42 + max(-0.12, min(0.12, avg_change * 0.04))),
    )
    strongest = "、".join(f"{name} {value:+.2f}%" for name, value in ranked[:3]) or "暂无显著强势板块"
    weakest = "、".join(f"{name} {value:+.2f}%" for name, value in ranked[-3:]) or "暂无显著弱势板块"
    market_label = {"CN": "A股", "HK": "港股", "US": "美股"}[market_code]
    context = {
        "market": market_code,
        "data_date": temperature.get("data_date"),
        "source": temperature.get("source"),
        "rise_count": up_count,
        "fall_count": int(temperature.get("fall_count") or 0),
        "total_count": total,
        "up_ratio": round(up_ratio, 4),
        "avg_change": avg_change,
        "sector_changes": ranked[:30],
    }
    return {
        "position_ratio": round(position_ratio, 3),
        "attack": attack,
        "defense": defense,
        "neutral": (
            f"{market_label}{temperature.get('data_date') or '最新交易日'}上涨占比 {up_ratio * 100:.1f}%，"
            f"平均涨跌幅 {avg_change:+.2f}%。市场信号强度 {position_ratio * 100:.0f}%，"
            "用于观察市场宽度和板块扩散强弱，不构成仓位或交易建议。"
        ),
        "attack_reason": f"强势板块主要为：{strongest}。进攻方向需继续确认成交额和趋势延续。",
        "defense_reason": f"相对弱势或低波动板块为：{weakest}。防御方向用于降低组合波动，不代表绝对收益。",
        "analysis_source": "structured_market_context",
        "market_context": context,
    }


def _run_position_advice_direct(cfg: dict, fallback: dict) -> dict:
    raw = _assistant_call_json_llm(
        cfg,
        [
            {
                "role": "system",
                "content": (
                    "你是量化战术配置分析师。只返回JSON，字段为 position_ratio、attack、defense、"
                    "neutral、attack_reason、defense_reason。position_ratio为0到1的市场信号强度，"
                    "attack和defense各2到4项。必须严格使用提供的市场数据，不得虚构资金流或新闻。"
                    "不得输出买入、卖出、荐股、目标价或建议仓位等投资建议。"
                ),
            },
            {
                "role": "user",
                "content": json.dumps(fallback.get("market_context") or {}, ensure_ascii=False, default=str),
            },
        ],
        temperature=0.2,
        read_timeout=_assistant_timeout_seconds(
            "POSITION_ADVICE_LLM_TIMEOUT_SECONDS",
            90.0,
            10.0,
            180.0,
        ),
    )
    payload = _extract_llm_json_object(raw) or {}
    ratio = data_sources.safe_float(payload.get("position_ratio"))
    attack = [str(item).strip() for item in (payload.get("attack") or []) if str(item).strip()][:4]
    defense = [str(item).strip() for item in (payload.get("defense") or []) if str(item).strip()][:4]
    return {
        **fallback,
        "position_ratio": max(0.0, min(1.0, ratio)) if ratio is not None else fallback["position_ratio"],
        "attack": attack or fallback["attack"],
        "defense": defense or fallback["defense"],
        "neutral": str(payload.get("neutral") or fallback["neutral"])[:800],
        "attack_reason": str(payload.get("attack_reason") or fallback["attack_reason"])[:800],
        "defense_reason": str(payload.get("defense_reason") or fallback["defense_reason"])[:800],
        "analysis_source": "llm+structured_market_context",
    }


@app.get("/api/position-advice", dependencies=[Depends(require_permission("ai.insights"))])
def get_position_advice(market: str = "CN", db: Session = Depends(get_db)):
    """获取最新市场信号观察（缓存在DB，不实时调用LLM）"""
    market_code = _normalize_market_code(market)
    row = (
        db.query(PositionAdvice)
        .filter(PositionAdvice.market == market_code)
        .order_by(PositionAdvice.created_at.desc())
        .first()
    )
    if not row:
        fallback = _build_position_advice_data_result(db, market_code)
        return {
            **fallback,
            "market": market_code,
            "neutral": "尚未触发 AI 刷新；当前先展示基于最新市场宽度和板块表现生成的市场观察。",
            "status": "empty",
        }
    legacy_text = str(row.neutral_assessment or "")
    legacy_markers = (
        "本地战术模板",
        "country, region, or territory not supported",
        "区域路由不可用",
    )
    if row.status == "failed" or any(marker in legacy_text.lower() for marker in legacy_markers):
        fallback = _build_position_advice_data_result(db, market_code)
        return {
            **fallback,
            "id": row.id,
            "market": market_code,
            "status": "done",
            "analysis_source": "structured_market_context_fallback",
            "created_at": row.created_at.isoformat() if row.created_at else None,
        }
    return {
        "id": row.id,
        "market": row.market or market_code,
        "position_ratio": row.position_ratio,
        "attack": json.loads(row.attack_industries or "[]"),
        "defense": json.loads(row.defense_industries or "[]"),
        "neutral": row.neutral_assessment or "",
        "attack_reason": row.attack_reason or "",
        "defense_reason": row.defense_reason or "",
        "analysis_source": row.analysis_source or "",
        "market_context": _json_loads_or(row.market_context_json, {}),
        "status": row.status,
        "created_at": row.created_at.isoformat() if row.created_at else None,
    }


@app.post("/api/position-advice/run", dependencies=[Depends(require_permission("ai.insights"))])
def run_position_advice(
    background_tasks: BackgroundTasks,
    payload: Optional[PositionAdviceRunRequest] = Body(default=None),
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """触发战术分析，异步执行"""
    market_code = _normalize_market_code(payload.market if payload else "CN")
    row = PositionAdvice(status="running", market=market_code)
    db.add(row)
    db.commit()
    db.refresh(row)
    advice_id = row.id
    try:
        credit_summary = _consume_user_credits(
            db,
            current_user,
            "position_advice_refresh",
            _llm_tier_credit_cost(
                db,
                "position_advice_refresh",
                (payload.model if payload else "") or "",
                current_user,
            ),
            reference_id=f"position_advice:{advice_id}",
        )
    except HTTPException:
        db.delete(row)
        db.commit()
        raise
    user_id = current_user.id
    model_override = (payload.model if payload else "") or ""

    def _run():
        _db = SessionLocal()
        try:
            fallback = _build_position_advice_data_result(_db, market_code)
            result = fallback
            usage_cfg = _llm_config_for_module(
                _db,
                user_id=user_id,
                module_key="ai_insights",
                model_override=model_override.strip() or None,
                allow_shared_fallback=True,
            )
            usage_cfg["_usage_reference_id"] = f"position_advice:{advice_id}"
            usage_cfg["_usage_module"] = "position_advice"
            usage_cfg["_usage_credits"] = _llm_tier_credit_cost(
                _db,
                "position_advice_refresh",
                model_override,
                _db.query(UserModel).filter(UserModel.id == user_id).first(),
            )
            if usage_cfg.get("api_key") and _direct_llm_supported(usage_cfg):
                try:
                    result = _run_position_advice_direct(usage_cfg, fallback)
                except Exception as exc:
                    result = {
                        **fallback,
                        "analysis_source": "structured_market_context_fallback",
                        "fallback_reason": (
                            "模型服务当前区域路由不可用"
                            if "country" in str(exc).lower() and "not supported" in str(exc).lower()
                            else "模型服务本次未及时返回有效结果"
                        ),
                    }
            t = _db.query(PositionAdvice).filter(PositionAdvice.id == advice_id).first()
            if t:
                t.position_ratio = result["position_ratio"]
                t.attack_industries = json.dumps(result["attack"], ensure_ascii=False)
                t.defense_industries = json.dumps(result["defense"], ensure_ascii=False)
                t.neutral_assessment = result["neutral"]
                t.attack_reason = result.get("attack_reason") or ""
                t.defense_reason = result.get("defense_reason") or ""
                t.analysis_source = result.get("analysis_source") or "structured_market_context"
                t.market_context_json = json.dumps(
                    result.get("market_context") or {},
                    ensure_ascii=False,
                    default=str,
                )
                t.status = "done"
                _db.commit()
        except Exception as e:
            t = _db.query(PositionAdvice).filter(PositionAdvice.id == advice_id).first()
            if t:
                t.status = "failed"
                t.neutral_assessment = "战术建议生成失败，请稍后重试。"
                _db.commit()
        finally:
            _db.close()

    background_tasks.add_task(_run)
    return {"advice_id": advice_id, "credit_summary": credit_summary}


# --- Strategy API ---
class StrategyGenerateRequest(BaseModel):
    prompt: str
    market: str = "CN"
    buy_condition: str = "RSI Crossover"
    sell_condition: Optional[str] = None
    profit_target: float = 12.5
    stop_loss: float = 4.0
    holding_period: Optional[int] = None
    model: Optional[str] = None
    factor_ids: List[int] = []
    factor_specs: List[Dict[str, object]] = []


class StrategySaveRequest(BaseModel):
    name: str
    code: str
    params_json: Optional[str] = None
    factor_ids: List[int] = []


class StrategyPoolPreviewRequest(BaseModel):
    factor_ids: List[int] = []
    factor_specs: List[Dict[str, object]] = []
    market: str = "CN"
    limit: int = 12
    universe_limit: int = 150
    date: Optional[str] = None


def _parse_strategy_factor_ids(row: Strategy) -> List[int]:
    raw = getattr(row, "factor_ids_json", None)
    if not raw:
        return []
    try:
        values = json.loads(raw)
    except Exception:
        return []
    ids: List[int] = []
    for value in values if isinstance(values, list) else []:
        try:
            factor_id = int(value)
        except Exception:
            continue
        if factor_id not in ids:
            ids.append(factor_id)
    return ids


def _load_strategy_factor_rows(db: Session, factor_ids: List[int]):
    if not factor_ids:
        return []
    rows = (
        db.query(CustomFactorModel)
        .filter(CustomFactorModel.id.in_(factor_ids))
        .all()
    )
    order = {factor_id: idx for idx, factor_id in enumerate(factor_ids)}
    return sorted(rows, key=lambda factor: order.get(factor.id, len(order)))


def _merge_strategy_factor_specs(
    factor_rows: List[CustomFactorModel],
    override_specs: Optional[List[Dict[str, object]]] = None,
) -> List[Dict[str, object]]:
    overrides: Dict[int, Dict[str, object]] = {}
    for raw in override_specs or []:
        if not isinstance(raw, dict):
            continue
        try:
            factor_id = int(raw.get("id") or raw.get("factor_id") or 0)
        except Exception:
            continue
        if factor_id:
            overrides[factor_id] = raw

    specs: List[Dict[str, object]] = []
    for factor in factor_rows:
        spec = custom_factor_model_to_spec(factor)
        override = overrides.get(factor.id)
        if override:
            if isinstance(override.get("params"), dict):
                spec["params"] = {
                    str(key): value
                    for key, value in override["params"].items()
                    if isinstance(value, (int, float))
                }
            for source_key, target_key in (
                ("filter_min", "filter_min"),
                ("filter_max", "filter_max"),
                ("output_type", "output_type"),
            ):
                if source_key in override:
                    spec[target_key] = override.get(source_key)
        if spec.get("expression"):
            specs.append(spec)
    return specs


def _serialize_strategy_factor_refs(db: Session, row: Strategy) -> dict:
    factor_ids = _parse_strategy_factor_ids(row)
    factors = _load_strategy_factor_rows(db, factor_ids)
    valid_ids = [factor.id for factor in factors]
    return {
        "factor_ids": valid_ids,
        "factors": [
            {
                "id": factor.id,
                "name": factor.name,
                "display_name": factor.display_name or factor.name,
                "category": factor.category,
                "expression": factor.expression,
            }
            for factor in factors
        ],
    }


def _strategy_factor_context(payload: StrategyGenerateRequest, db: Session) -> str:
    factors = []
    if payload.factor_ids:
        factors = (
            db.query(CustomFactorModel)
            .filter(CustomFactorModel.id.in_(payload.factor_ids))
            .all()
        )
    order = {factor_id: idx for idx, factor_id in enumerate(payload.factor_ids or [])}
    factors = sorted(factors, key=lambda factor: order.get(factor.id, len(order)))
    specs = _merge_strategy_factor_specs(factors, payload.factor_specs)
    spec_by_id = {spec.get("id"): spec for spec in specs}
    return "\n".join(
        [
            (
                f"- {f.display_name or f.name} ({f.name}): {f.expression}; "
                f"参数: {json.dumps((spec_by_id.get(f.id) or {}).get('params') or {}, ensure_ascii=False)}; "
                f"过滤: min={(spec_by_id.get(f.id) or {}).get('filter_min')}, "
                f"max={(spec_by_id.get(f.id) or {}).get('filter_max')}"
            )
            for f in factors
        ]
    ) or "无"


def _strategy_prompts(payload: StrategyGenerateRequest, factor_context: str) -> tuple[str, str]:
    market_code = _normalize_market_code(payload.market)
    market_label = {"CN": "A股", "HK": "港股", "US": "美股"}[market_code]
    holding_context = (
        f"持有周期:{payload.holding_period}天"
        if payload.holding_period
        else "持有周期:未设置，由策略代码根据买卖条件自动决定"
    )
    system_prompt = (
        f"你是{market_label}量化策略工程师。生成完整、可运行、便于调试的Python策略代码。"
        "必须包含参数定义、买入/卖出判断、止盈止损、仓位控制、日志输出和一个可直接调用的on_bar或on_tick入口。"
        "系统执行顺序是：先用用户选择的因子筛出候选股票池，再在该股票池内运行策略代码。"
        "因子只负责股票池过滤，策略代码负责买入、卖出、仓位和风控，不要在代码里随机选择股票。"
        "若未设置持有周期，不要强制按固定周期平仓。"
        "只输出Python代码，不要输出Markdown代码块，不要解释。"
    )
    user_prompt = (
        f"研究市场:{market_label}（{market_code}）\n"
        f"用户需求:{payload.prompt}\n"
        f"买入条件:{payload.buy_condition}\n"
        f"卖出条件:{payload.sell_condition or '由代码结合止盈止损自动生成'}\n"
        f"止盈:{payload.profit_target}% 止损:{payload.stop_loss}% {holding_context}\n"
        f"候选股票池因子:\n{factor_context}\n"
        "请输出一个Python策略类。该类的on_bar输入是一只已经通过候选股票池过滤的股票日线，"
        "代码只需要判断BUY/SELL/HOLD、仓位建议和风控理由，便于在控制台中调试。"
    )
    return system_prompt, user_prompt


def _local_strategy_template(payload: StrategyGenerateRequest) -> str:
    prompt_text = (payload.prompt or "").lower()
    is_turtle = "海龟" in payload.prompt or "turtle" in prompt_text
    if is_turtle:
        return f'''# Turtle Trading Strategy
# 20日唐奇安通道突破买入，10日通道跌破卖出，ATR 风控和仓位管理。

class TurtleTradingStrategy:
    def __init__(
        self,
        entry_window=20,
        exit_window=10,
        atr_window=20,
        risk_per_trade=0.01,
        stop_loss_pct={payload.stop_loss / 100:.4f},
        take_profit_pct={payload.profit_target / 100:.4f},
        account_equity=1_000_000,
    ):
        self.entry_window = entry_window
        self.exit_window = exit_window
        self.atr_window = atr_window
        self.risk_per_trade = risk_per_trade
        self.stop_loss_pct = stop_loss_pct
        self.take_profit_pct = take_profit_pct
        self.account_equity = account_equity

        self.bars = []
        self.position = 0
        self.entry_price = None
        self.stop_price = None
        self.take_profit_price = None
        self.logs = []

    def _atr(self):
        if len(self.bars) < self.atr_window + 1:
            return None
        trs = []
        recent = self.bars[-self.atr_window:]
        previous = self.bars[-self.atr_window - 1]
        prev_close = previous["close"]
        for bar in recent:
            tr = max(
                bar["high"] - bar["low"],
                abs(bar["high"] - prev_close),
                abs(bar["low"] - prev_close),
            )
            trs.append(tr)
            prev_close = bar["close"]
        return sum(trs) / len(trs)

    def _highest_high(self, window):
        if len(self.bars) <= window:
            return None
        return max(bar["high"] for bar in self.bars[-window - 1:-1])

    def _lowest_low(self, window):
        if len(self.bars) <= window:
            return None
        return min(bar["low"] for bar in self.bars[-window - 1:-1])

    def _position_size(self, close, atr):
        risk_cash = self.account_equity * self.risk_per_trade
        unit_risk = max(2 * atr, close * self.stop_loss_pct, 0.01)
        return max(int(risk_cash / unit_risk), 100)

    def on_bar(self, date, open_price, high, low, close, volume):
        bar = {{
            "date": date,
            "open": float(open_price),
            "high": float(high),
            "low": float(low),
            "close": float(close),
            "volume": float(volume),
        }}
        self.bars.append(bar)

        atr = self._atr()
        entry_breakout = self._highest_high(self.entry_window)
        exit_breakdown = self._lowest_low(self.exit_window)

        if atr is None or entry_breakout is None or exit_breakdown is None:
            return {{"action": "HOLD", "reason": "warming_up", "date": date}}

        if self.position <= 0 and close > entry_breakout:
            shares = self._position_size(close, atr)
            self.position = shares
            self.entry_price = close
            self.stop_price = close - 2 * atr
            self.take_profit_price = close * (1 + self.take_profit_pct)
            event = {{
                "action": "BUY",
                "date": date,
                "price": close,
                "shares": shares,
                "atr": round(atr, 4),
                "stop_price": round(self.stop_price, 4),
                "take_profit_price": round(self.take_profit_price, 4),
                "reason": "20_day_breakout",
            }}
            self.logs.append(event)
            return event

        if self.position > 0:
            stop_hit = close <= self.stop_price
            take_profit_hit = close >= self.take_profit_price
            channel_exit = close < exit_breakdown
            if stop_hit or take_profit_hit or channel_exit:
                reason = (
                    "stop_loss"
                    if stop_hit
                    else "take_profit"
                    if take_profit_hit
                    else "10_day_channel_exit"
                )
                event = {{
                    "action": "SELL",
                    "date": date,
                    "price": close,
                    "shares": self.position,
                    "pnl_pct": round((close / self.entry_price - 1) * 100, 2),
                    "reason": reason,
                }}
                self.position = 0
                self.entry_price = None
                self.stop_price = None
                self.take_profit_price = None
                self.logs.append(event)
                return event

        return {{
            "action": "HOLD",
            "date": date,
            "price": close,
            "position": self.position,
            "entry_breakout": round(entry_breakout, 4),
            "exit_breakdown": round(exit_breakdown, 4),
        }}
'''
    return f'''# Generated Strategy Template

class GeneratedStrategy:
    def __init__(self, stop_loss_pct={payload.stop_loss / 100:.4f}, take_profit_pct={payload.profit_target / 100:.4f}):
        self.stop_loss_pct = stop_loss_pct
        self.take_profit_pct = take_profit_pct
        self.position = 0
        self.entry_price = None
        self.prices = []
        self.logs = []

    def on_tick(self, price, timestamp=None):
        price = float(price)
        self.prices.append(price)
        if len(self.prices) < 20:
            return {{"action": "HOLD", "reason": "warming_up"}}

        ma_short = sum(self.prices[-5:]) / 5
        ma_long = sum(self.prices[-20:]) / 20

        if self.position <= 0 and ma_short > ma_long:
            self.position = 1
            self.entry_price = price
            event = {{"action": "BUY", "price": price, "timestamp": timestamp, "reason": "ma_cross"}}
            self.logs.append(event)
            return event

        if self.position > 0:
            pnl = price / self.entry_price - 1
            if pnl <= -self.stop_loss_pct or pnl >= self.take_profit_pct or ma_short < ma_long:
                reason = "stop_loss" if pnl <= -self.stop_loss_pct else "take_profit" if pnl >= self.take_profit_pct else "ma_exit"
                self.position = 0
                event = {{"action": "SELL", "price": price, "timestamp": timestamp, "pnl_pct": round(pnl * 100, 2), "reason": reason}}
                self.logs.append(event)
                return event

        return {{"action": "HOLD", "price": price, "position": self.position}}
'''


def _sse_payload(payload: dict) -> str:
    return f"data: {json.dumps(payload, ensure_ascii=False)}\n\n"


def _iter_text_chunks(text: str, chunk_size: int = 120):
    for idx in range(0, len(text), chunk_size):
        yield text[idx : idx + chunk_size]


def _strategy_query_for_user(db: Session, user: UserModel):
    query = db.query(Strategy)
    if normalize_user_role(user.role) == "admin":
        return query
    return query.filter(Strategy.user_id == user.id)


def _strategy_for_user(db: Session, strategy_id: int, user: UserModel) -> Optional[Strategy]:
    query = db.query(Strategy).filter(Strategy.id == strategy_id)
    if normalize_user_role(user.role) != "admin":
        query = query.filter(Strategy.user_id == user.id)
    return query.first()


@app.get("/api/strategy/list", dependencies=[Depends(require_permission("strategy.manage"))])
def list_strategies(
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    rows = _strategy_query_for_user(db, current_user).order_by(Strategy.updated_at.desc()).all()
    result = []
    for r in rows:
        factor_refs = _serialize_strategy_factor_refs(db, r)
        result.append(
            {
                "id": r.id,
                "user_id": getattr(r, "user_id", None),
                "name": r.name,
                "updated_at": r.updated_at.isoformat() if r.updated_at else None,
                "factor_ids": factor_refs["factor_ids"],
                "factors": factor_refs["factors"],
            }
        )
    return result


@app.post("/api/strategy/stock-pool/preview", dependencies=[Depends(require_permission("strategy.manage"))])
def preview_strategy_stock_pool(
    payload: StrategyPoolPreviewRequest,
    db: Session = Depends(get_db),
):
    """快速预览：先用因子筛股票池，再交给策略代码处理交易逻辑。"""
    market_code = _normalize_market_code(payload.market)
    factor_ids = []
    for value in payload.factor_ids or []:
        try:
            factor_id = int(value)
        except Exception:
            continue
        if factor_id not in factor_ids:
            factor_ids.append(factor_id)

    if not factor_ids:
        return {
            "total": 0,
            "market": market_code,
            "date": payload.date,
            "universe_count": 0,
            "rows": [],
            "source": "strategy.factor_pool_preview",
            "message": "未选择因子",
        }

    factor_rows = _load_strategy_factor_rows(db, factor_ids)
    factor_specs = _merge_strategy_factor_specs(factor_rows, payload.factor_specs)
    if not factor_specs:
        return {
            "total": 0,
            "market": market_code,
            "date": payload.date,
            "universe_count": 0,
            "rows": [],
            "source": "strategy.factor_pool_preview",
            "message": "所选因子缺少可执行表达式",
        }

    target_date = None
    if payload.date:
        try:
            target_date = datetime.strptime(payload.date, "%Y-%m-%d").date()
        except Exception:
            raise HTTPException(status_code=400, detail="date 必须是 YYYY-MM-DD")

    if target_date:
        latest_sq = (
            db.query(
                DailyPrice.stock_code.label("stock_code"),
                func.max(DailyPrice.date).label("latest_date"),
            )
            .filter(DailyPrice.date <= target_date)
            .group_by(DailyPrice.stock_code)
            .subquery()
        )
    else:
        latest_sq = latest_daily_subquery(db)

    universe_limit = max(50, min(int(payload.universe_limit or 500), 2000))
    rows = (
        db.query(
            Stock.code.label("code"),
            Stock.name.label("name"),
            Stock.industry.label("industry"),
            Stock.board.label("board"),
            Stock.area.label("area"),
            Stock.pe_ratio.label("pe_ratio"),
            Stock.pb_ratio.label("pb_ratio"),
            Stock.market_cap.label("market_cap"),
            Stock.circulating_market_cap.label("circulating_market_cap"),
            Stock.roe.label("roe"),
            DailyPrice.open.label("open"),
            DailyPrice.close.label("close"),
            DailyPrice.high.label("high"),
            DailyPrice.low.label("low"),
            DailyPrice.volume.label("volume"),
            DailyPrice.amount.label("amount"),
            DailyPrice.change_pct.label("change_pct_cached"),
            DailyPrice.turnover_rate.label("turnover_rate"),
            DailyPrice.ma60.label("ma60"),
            DailyPrice.date.label("date"),
        )
        .join(latest_sq, latest_sq.c.stock_code == Stock.code)
        .join(
            DailyPrice,
            and_(
                DailyPrice.stock_code == latest_sq.c.stock_code,
                DailyPrice.date == latest_sq.c.latest_date,
            ),
        )
        .filter(_stock_market_condition(market_code))
        .filter(DailyPrice.close.isnot(None))
        .order_by(desc(func.coalesce(DailyPrice.amount, 0)), desc(func.coalesce(Stock.market_cap, 0)))
        .limit(universe_limit)
        .all()
    )

    if not rows:
        return {
            "total": 0,
            "market": market_code,
            "date": target_date.isoformat() if target_date else None,
            "universe_count": 0,
            "rows": [],
            "source": "strategy.factor_pool_preview",
            "message": "数据库暂无可用行情",
        }

    history_cache = load_screening_histories(
        db,
        list({r.code for r in rows}),
        target_date,
        220,
    )
    prev_close_map = build_prev_close_map_from_history(history_cache, rows)
    result_rows = []

    for r in rows:
        hist_df = history_cache.get(r.code, pd.DataFrame())
        if hist_df.empty:
            continue
        factor_df = prepare_factor_dataframe(hist_df)
        if factor_df.empty or not all(
            factor_spec_passes(factor_df, spec) for spec in factor_specs
        ):
            continue

        close_price = float(r.close or 0)
        prev_close = prev_close_map.get(r.code, 0)
        cached_change = data_sources.safe_float(getattr(r, "change_pct_cached", None))
        change_pct = (
            cached_change
            if cached_change is not None
            else ((close_price - prev_close) / prev_close * 100.0 if prev_close else 0.0)
        )
        amount = float(r.amount or 0)
        volume = float(r.volume or 0)
        liquidity_score = min(60.0, amount / 100000000.0 * 6.0)
        change_score = max(-30.0, min(30.0, change_pct)) * 1.2
        ma60 = float(r.ma60) if r.ma60 is not None else latest_moving_average_from_history(hist_df, 60)
        ma_score = 0.0
        if ma60 and ma60 > 0:
            ma_score = max(-20.0, min(20.0, (close_price - ma60) / ma60 * 100.0))
        score = liquidity_score + change_score + ma_score + len(factor_specs) * 5.0

        market_cap_yi = normalize_market_cap_yi(r.market_cap)
        circulating_market_cap_yi = normalize_market_cap_yi(r.circulating_market_cap)
        result_rows.append(
            {
                "code": r.code,
                "name": r.name,
                "industry": r.industry,
                "board": r.board or data_sources.infer_listing_board(r.code),
                "area": r.area,
                "price": round(close_price, 2),
                "open": round(float(r.open or 0), 2),
                "high": round(float(r.high or 0), 2),
                "low": round(float(r.low or 0), 2),
                "volume": int(volume),
                "amount": round(amount, 2),
                "turnover_rate": round(float(r.turnover_rate or 0), 2),
                "market_cap": round(market_cap_yi, 2) if market_cap_yi is not None else None,
                "circulating_market_cap": (
                    round(circulating_market_cap_yi, 2)
                    if circulating_market_cap_yi is not None
                    else None
                ),
                "ma60": round(ma60, 2) if ma60 else None,
                "change_pct": round(float(change_pct or 0), 2),
                "pe_ratio": round(float(r.pe_ratio), 2) if r.pe_ratio is not None else None,
                "pb_ratio": round(float(r.pb_ratio), 2) if r.pb_ratio is not None else None,
                "roe_pct": round(float(r.roe), 2) if r.roe is not None else None,
                "score": round(score, 2),
                "date": r.date.isoformat() if r.date else None,
            }
        )

    result_rows.sort(
        key=lambda item: (
            item.get("score") if item.get("score") is not None else 0,
            item.get("amount") if item.get("amount") is not None else 0,
        ),
        reverse=True,
    )
    total = len(result_rows)
    limit = max(1, min(int(payload.limit or 12), 500))
    if total > 1:
        scores = [float(item.get("score") or 0) for item in result_rows]
        score_min, score_max = min(scores), max(scores)
        score_range = score_max - score_min or 1.0
        for item in result_rows:
            item["score_pct"] = round((float(item.get("score") or 0) - score_min) / score_range * 100, 1)
    else:
        for item in result_rows:
            item["score_pct"] = 50.0

    preview_date = max((r.date for r in rows if r.date), default=None) or target_date

    return {
        "total": total,
        "market": market_code,
        "limit": limit,
        "date": preview_date.isoformat() if preview_date else None,
        "universe_count": len(rows),
        "factor_count": len(factor_specs),
        "rows": result_rows[:limit],
        "source": "strategy.factor_pool_preview",
    }


@app.post("/api/strategy/generate/stream", dependencies=[Depends(require_permission("strategy.manage"))])
def generate_strategy_stream(
    payload: StrategyGenerateRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """流式生成策略代码，前端可逐块写入 Python 策略代码编辑器。"""
    usage_reference_id = f"strategy_stream:{uuid.uuid4().hex}"
    credit_summary = _consume_user_credits(
        db,
        current_user,
        "strategy_generation",
        _llm_tier_credit_cost(db, "strategy_generation", payload.model, current_user),
        reference_id=usage_reference_id,
        meta={"mode": "stream"},
    )
    factor_context = _strategy_factor_context(payload, db)
    system_prompt, user_prompt = _strategy_prompts(payload, factor_context)
    fallback_code = _local_strategy_template(payload)
    try:
        cfg = _llm_config_for_module(
            db,
            user_id=current_user.id,
            module_key="strategy",
            model_override=(payload.model or "").strip() or None,
        )
        cfg["_usage_reference_id"] = usage_reference_id
        cfg["_usage_credits"] = _llm_tier_credit_cost(
            db,
            "strategy_generation",
            payload.model,
            current_user,
        )
    except Exception:
        cfg = {}

    def generate():
        yield _sse_payload(
            {
                "type": "status",
                "message": "开始生成策略代码...",
                "credit_summary": credit_summary,
            }
        )
        provider = _normalize_llm_provider(cfg.get("provider"))
        api_key = cfg.get("api_key")
        if provider in {"anthropic", "google"} and api_key:
            try:
                yield _sse_payload(
                    {
                        "type": "status",
                        "message": "当前协议使用非流式生成，完成后写入 Python 策略代码...",
                        "source": "llm",
                    }
                )
                code = _assistant_call_json_llm(
                    cfg,
                    [
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": user_prompt},
                    ],
                    temperature=0.2,
                    read_timeout=150,
                ).strip()
                if "```python" in code:
                    code = code.split("```python", 1)[1].split("```", 1)[0].strip()
                elif "```" in code:
                    code = code.split("```", 1)[1].split("```", 1)[0].strip()
                if not code:
                    raise RuntimeError("LLM响应为空")
                for delta in _iter_text_chunks(code):
                    yield _sse_payload({"type": "delta", "delta": delta})
                yield _sse_payload({"type": "done", "source": "llm"})
                return
            except Exception as exc:
                yield _sse_payload(
                    {
                        "type": "status",
                        "message": f"AI生成失败，使用本地策略模板: {str(exc)[:160]}",
                        "source": "template",
                    }
                )
                for delta in _iter_text_chunks(fallback_code):
                    yield _sse_payload({"type": "delta", "delta": delta})
                yield _sse_payload({"type": "done", "source": "template"})
                return
        if provider not in {"openai", "custom"} or not api_key:
            yield _sse_payload(
                {
                    "type": "status",
                    "message": "助手配置未完成或当前模型来源不支持流式输出，使用本地策略模板。",
                    "source": "template",
                }
            )
            for delta in _iter_text_chunks(fallback_code):
                yield _sse_payload({"type": "delta", "delta": delta})
            yield _sse_payload({"type": "done", "source": "template"})
            return

        try:
            import openai

            base_url = cfg.get("base_url") or "https://api.openai.com/v1"
            yield _sse_payload({"type": "status", "message": "正在调用LLM流式生成..."})
            client = openai.OpenAI(api_key=api_key, base_url=base_url, timeout=12.0)
            messages = [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ]
            create_kwargs = {
                "model": cfg.get("model", DEFAULT_LLM_MODEL),
                "messages": messages,
                "stream": True,
                "temperature": 0.2,
            }
            if "api.openai.com" in base_url:
                create_kwargs["stream_options"] = {"include_usage": True}
            started = time.time()
            stream = client.chat.completions.create(**create_kwargs)
            emitted = False
            generated_parts: list[str] = []
            raw_usage = None
            for chunk in stream:
                chunk_usage = getattr(chunk, "usage", None)
                if chunk_usage is not None:
                    raw_usage = chunk_usage
                choices = getattr(chunk, "choices", None) or []
                if not choices:
                    continue
                choice = choices[0]
                delta_obj = getattr(choice, "delta", None)
                delta = getattr(delta_obj, "content", None) or ""
                if delta:
                    emitted = True
                    generated_parts.append(delta)
                    yield _sse_payload({"type": "delta", "delta": delta})
            if not emitted:
                yield _sse_payload(
                    {
                        "type": "status",
                        "message": "LLM流式响应为空，使用本地策略模板。",
                        "source": "template",
                    }
                )
                for delta in _iter_text_chunks(fallback_code):
                    yield _sse_payload({"type": "delta", "delta": delta})
                yield _sse_payload({"type": "done", "source": "template"})
                return
            _record_llm_call_usage(
                cfg,
                messages=messages,
                output_text="".join(generated_parts),
                raw_usage=raw_usage,
                latency_ms=int((time.time() - started) * 1000),
                meta={"stream": True},
            )
            yield _sse_payload({"type": "done", "source": "llm"})
        except Exception as e:
            yield _sse_payload(
                {
                    "type": "status",
                    "message": f"AI生成失败，使用本地策略模板: {str(e)[:160]}",
                    "source": "template",
                }
            )
            for delta in _iter_text_chunks(fallback_code):
                yield _sse_payload({"type": "delta", "delta": delta})
            yield _sse_payload({"type": "done", "source": "template"})

    return StreamingResponse(generate(), media_type="text/event-stream")


@app.post("/api/strategy/generate", dependencies=[Depends(require_permission("strategy.manage"))])
def generate_strategy(
    payload: StrategyGenerateRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """基于参数生成策略代码（调用LLM或返回模板）"""
    usage_reference_id = f"strategy_generate:{uuid.uuid4().hex}"
    credit_summary = _consume_user_credits(
        db,
        current_user,
        "strategy_generation",
        _llm_tier_credit_cost(db, "strategy_generation", payload.model, current_user),
        reference_id=usage_reference_id,
        meta={"mode": "json"},
    )
    try:
        from crewai import Agent, Crew, Task
        from llm_factory import build_crewai_llm

        factor_context = _strategy_factor_context(payload, db)
        system_prompt, user_prompt = _strategy_prompts(payload, factor_context)
        market_code = _normalize_market_code(payload.market)
        market_label = {"CN": "A股", "HK": "港股", "US": "美股"}[market_code]
        usage_cfg = _llm_config_for_module(
            db,
            user_id=current_user.id,
            module_key="strategy",
            model_override=(payload.model or "").strip() or None,
            allow_shared_fallback=False,
        )
        llm = build_crewai_llm(
            db,
            user_id=current_user.id,
            allow_shared_fallback=False,
            resolved_config=usage_cfg,
        )
        agent = Agent(
            role=f"{market_label}量化策略工程师",
            goal="生成可执行的Python量化策略代码",
            backstory=system_prompt,
            llm=llm,
            verbose=False,
        )
        task = Task(
            description=f"{system_prompt}\n{user_prompt}",
            expected_output="Python策略代码",
            agent=agent,
        )
        crew = Crew(agents=[agent], tasks=[task], verbose=False)
        crew_result = crew.kickoff()
        code = str(task.output.raw if hasattr(task, "output") else "")
        # 提取代码块
        if "```python" in code:
            code = code.split("```python")[1].split("```")[0].strip()
        elif "```" in code:
            code = code.split("```")[1].split("```")[0].strip()
        crew_usage = usage_metering.extract_token_usage(
            [crew_result, getattr(crew, "usage_metrics", None)],
            provider=str(usage_cfg.get("provider") or ""),
        )
        if not crew_usage.get("total_tokens"):
            crew_usage = usage_metering.normalize_token_usage(
                provider=str(usage_cfg.get("provider") or ""),
                input_text=task.description,
                output_text=code,
            )
        _persist_llm_usage(
            db,
            user_id=current_user.id,
            module_key="strategy",
            provider=str(usage_cfg.get("provider") or "openai"),
            model=str(usage_cfg.get("model") or payload.model or "unknown"),
            usage=crew_usage,
            request_id=usage_reference_id,
            credits_charged=_llm_tier_credit_cost(
                db,
                "strategy_generation",
                payload.model,
                current_user,
            ),
            meta={"engine": "crewai", "stream": False},
            output_text=code,
            data_source="strategy_prompt",
        )
    except Exception as e:
        return {
            "code": "",
            "status": "failed",
            "credit_summary": credit_summary,
            "error": error_payload(
                "STRATEGY_GENERATION_FAILED",
                "策略生成失败",
                {"reason": str(e)[:200]},
            ),
        }
    if not code.strip():
        return {
            "code": "",
            "status": "empty",
            "credit_summary": credit_summary,
            "error": None,
        }
    return {"code": code, "status": "ok", "error": None, "credit_summary": credit_summary}


