@app.post("/api/strategy/save", dependencies=[Depends(require_permission("strategy.manage"))])
def save_strategy(
    payload: StrategySaveRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    name = (payload.name or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="策略名称不能为空")
    factor_rows = _load_strategy_factor_rows(db, payload.factor_ids)
    factor_ids = [factor.id for factor in factor_rows]
    row = db.query(Strategy).filter(Strategy.name == name).first()
    if row:
        if normalize_user_role(current_user.role) != "admin" and row.user_id != current_user.id:
            raise HTTPException(status_code=409, detail="策略名称已被占用，请更换名称")
        row.code = payload.code
        row.params_json = payload.params_json
        row.factor_ids_json = json.dumps(factor_ids, ensure_ascii=False)
        if row.user_id is None:
            row.user_id = current_user.id
    else:
        row = Strategy(
            user_id=current_user.id,
            name=name,
            code=payload.code,
            params_json=payload.params_json,
            factor_ids_json=json.dumps(factor_ids, ensure_ascii=False),
        )
        db.add(row)
    db.commit()
    db.refresh(row)
    factor_refs = _serialize_strategy_factor_refs(db, row)
    return {"id": row.id, "name": row.name, **factor_refs}


