def _sanitize_risk_keyword_list(value: Any, fallback: list[str]) -> list[str]:
    items = value if isinstance(value, list) else fallback
    result: list[str] = []
    seen: set[str] = set()
    for item in items:
        keyword = str(item or "").strip()
        if not keyword or keyword.lower() in seen:
            continue
        seen.add(keyword.lower())
        result.append(keyword[:80])
        if len(result) >= 120:
            break
    return result


def _sanitize_risk_event_rules(value: Any) -> dict:
    raw = value if isinstance(value, dict) else {}
    defaults = _default_risk_event_rules()
    result: dict[str, dict] = {}
    for rule_key in ("geopolitical", "policy"):
        default = defaults[rule_key]
        incoming = raw.get(rule_key) if isinstance(raw.get(rule_key), dict) else {}
        market_keywords_raw = incoming.get("market_keywords")
        if not isinstance(market_keywords_raw, dict):
            market_keywords_raw = {}
        try:
            base_score = float(incoming.get("base_score", default["base_score"]))
            hit_score = float(incoming.get("hit_score", default["hit_score"]))
            severe_score = float(incoming.get("severe_score", default["severe_score"]))
            max_hits = int(incoming.get("max_hits", default["max_hits"]))
            max_severe_hits = int(incoming.get("max_severe_hits", default["max_severe_hits"]))
        except (TypeError, ValueError):
            base_score = float(default["base_score"])
            hit_score = float(default["hit_score"])
            severe_score = float(default["severe_score"])
            max_hits = int(default["max_hits"])
            max_severe_hits = int(default["max_severe_hits"])
        result[rule_key] = {
            "keywords": _sanitize_risk_keyword_list(incoming.get("keywords"), default["keywords"]),
            "severe_keywords": _sanitize_risk_keyword_list(
                incoming.get("severe_keywords"), default["severe_keywords"]
            ),
            "market_keywords": {
                market_code: _sanitize_risk_keyword_list(
                    market_keywords_raw.get(market_code),
                    default["market_keywords"].get(market_code, []),
                )
                for market_code in ("CN", "HK", "US")
            },
            "base_score": max(0.0, min(100.0, base_score)),
            "hit_score": max(0.0, min(30.0, hit_score)),
            "severe_score": max(0.0, min(40.0, severe_score)),
            "max_hits": max(1, min(40, max_hits)),
            "max_severe_hits": max(1, min(20, max_severe_hits)),
        }
    return result


def _risk_event_rules(db: Optional[Session] = None) -> dict:
    if db is not None:
        return _sanitize_risk_event_rules(
            _get_system_setting_json(db, RISK_EVENT_RULES_SETTINGS_KEY, _default_risk_event_rules())
        )
    session = SessionLocal()
    try:
        return _risk_event_rules(session)
    finally:
        session.close()


def _default_risk_monitor_config() -> dict:
    return {
        "watched_sectors": DEFAULT_RISK_SECTORS[:3],
        "market_watched_sectors": {
            "CN": DEFAULT_RISK_SECTORS[:3],
            "HK": [],
            "US": [],
        },
        "max_sectors": 12,
        "risk_dimensions": [
            "市场宽度",
            "北向资金",
            "南向资金",
            "板块资金流",
            "指数波动率",
            "宏观金融数据",
            "地缘政治事件",
            "政策事件",
        ],
        "fund_flow_focus": ["北向资金", "南向资金", "板块资金流"],
        "notes": "watched_sectors 控制风险监控页默认关注板块，最多50个。",
    }


def _normalize_risk_sector_list(value: Any) -> list[str]:
    if isinstance(value, str):
        items = [value]
    elif isinstance(value, list):
        items = value
    else:
        items = []
    result: list[str] = []
    seen: set[str] = set()
    for item in items:
        name = str(item or "").strip()
        if not name or name in seen:
            continue
        seen.add(name)
        result.append(name)
        if len(result) >= 50:
            break
    return result or DEFAULT_RISK_SECTORS[:3]


def _sanitize_risk_monitor_config(raw: Any) -> dict:
    base = _default_risk_monitor_config()
    if not isinstance(raw, dict):
        return base
    config = {**base, **raw}
    config["watched_sectors"] = _normalize_risk_sector_list(
        raw.get("watched_sectors") or raw.get("sectors")
    )
    try:
        max_sectors = int(config.get("max_sectors") or 12)
    except (TypeError, ValueError):
        max_sectors = 12
    config["max_sectors"] = max(1, min(max_sectors, 50))
    config["watched_sectors"] = config["watched_sectors"][: config["max_sectors"]]
    raw_market_sectors = raw.get("market_watched_sectors")
    if not isinstance(raw_market_sectors, dict):
        raw_market_sectors = {}
    config["market_watched_sectors"] = {
        market_code: (
            _normalize_risk_sector_list(raw_market_sectors.get(market_code))[
                : config["max_sectors"]
            ]
            if raw_market_sectors.get(market_code)
            else (
                config["watched_sectors"]
                if market_code == "CN"
                else []
            )
        )
        for market_code in ("CN", "HK", "US")
    }
    for key in ("risk_dimensions", "fund_flow_focus"):
        if not isinstance(config.get(key), list):
            config[key] = base[key]
        else:
            config[key] = [str(item).strip() for item in config[key] if str(item).strip()]
    return config


def _risk_watched_sectors_for_market(
    config: dict,
    market: str,
    db: Optional[Session] = None,
) -> list[str]:
    market_code = _normalize_market_code(market)
    market_map = config.get("market_watched_sectors") or {}
    selected = market_map.get(market_code) if isinstance(market_map, dict) else None
    if isinstance(selected, list) and selected:
        return _normalize_risk_sector_list(selected)
    if market_code != "CN" and db is not None:
        options = _risk_sector_options(db, market_code)
        names = [str(item.get("name") or "").strip() for item in options[:3]]
        names = [name for name in names if name]
        if names:
            return names
    return _normalize_risk_sector_list(
        config.get("watched_sectors") or DEFAULT_RISK_SECTORS[:3]
    )


def _get_user_risk_monitor_config(db: Session, current_user: UserModel) -> dict:
    row = (
        db.query(UserSetting)
        .filter(
            UserSetting.user_id == current_user.id,
            UserSetting.key == USER_SETTING_RISK_MONITOR_KEY,
        )
        .first()
    )
    if not row or not row.value_json:
        return _default_risk_monitor_config()
    try:
        return _sanitize_risk_monitor_config(json.loads(row.value_json))
    except Exception:
        return _default_risk_monitor_config()


def _save_user_risk_monitor_config(
    db: Session, current_user: UserModel, config: dict
) -> dict:
    sanitized = _sanitize_risk_monitor_config(config)
    row = (
        db.query(UserSetting)
        .filter(
            UserSetting.user_id == current_user.id,
            UserSetting.key == USER_SETTING_RISK_MONITOR_KEY,
        )
        .first()
    )
    if not row:
        row = UserSetting(
            user_id=current_user.id,
            key=USER_SETTING_RISK_MONITOR_KEY,
        )
        db.add(row)
    row.value_json = json.dumps(sanitized, ensure_ascii=False, indent=2)
    db.commit()
    return sanitized


def _risk_sector_options(db: Session, market: str = "CN") -> list[dict]:
    market_code = _normalize_market_code(market)
    options: list[dict] = []
    seen: set[tuple[str, str]] = set()

    def add_option(name: str, option_type: str, source: str, count: int = 0):
        clean_name = str(name or "").strip()
        if not clean_name:
            return
        key = (clean_name, option_type)
        if key in seen:
            return
        seen.add(key)
        options.append(
            {
                "name": clean_name,
                "type": option_type,
                "source": source,
                "count": int(count or 0),
            }
        )

    if market_code == "CN":
        for row in (
            db.query(ConceptBoard.name, ConceptBoard.stock_count)
            .filter(ConceptBoard.name.isnot(None), func.trim(ConceptBoard.name) != "")
            .order_by(desc(ConceptBoard.stock_count), ConceptBoard.name.asc())
            .all()
        ):
            add_option(row.name, "concept", "concept_boards", row.stock_count)

    industry_count = func.count(Stock.code).label("count")
    for row in (
        db.query(Stock.industry, func.count(Stock.code).label("count"))
        .filter(
            Stock.industry.isnot(None),
            func.trim(Stock.industry) != "",
            _stock_market_condition(market_code),
        )
        .group_by(Stock.industry)
        .order_by(desc(industry_count), Stock.industry.asc())
        .all()
    ):
        add_option(row.industry, "industry", "stocks.industry", row.count)

    board_count = func.count(Stock.code).label("count")
    for row in (
        db.query(Stock.board, func.count(Stock.code).label("count"))
        .filter(
            Stock.board.isnot(None),
            func.trim(Stock.board) != "",
            _stock_market_condition(market_code),
        )
        .group_by(Stock.board)
        .order_by(desc(board_count), Stock.board.asc())
        .all()
    ):
        add_option(row.board, "board", "stocks.board", row.count)

    if not options:
        for name in DEFAULT_RISK_SECTORS:
            add_option(name, "default", "default", 0)

    return options

