_risk_refreshing_keys: set[str] = set()
_risk_refresh_lock = threading.Lock()


def _schedule_risk_refresh(key: str, fn) -> None:
    with _risk_refresh_lock:
        if key in _risk_refreshing_keys:
            return
        _risk_refreshing_keys.add(key)

    def run_refresh():
        try:
            fn()
        except Exception:
            pass
        finally:
            with _risk_refresh_lock:
                _risk_refreshing_keys.discard(key)

    thread = threading.Thread(
        target=run_refresh,
        name=f"risk-refresh-{abs(hash(key))}",
        daemon=True,
    )
    thread.start()


def _risk_clamp(value: float, low: float = 0.0, high: float = 100.0) -> float:
    return max(low, min(high, value))


def _risk_label(value: float) -> str:
    if value < 30:
        return "低风险"
    if value < 60:
        return "中风险"
    if value < 80:
        return "较高风险"
    return "高风险"


def _risk_source_label(source_kind: str) -> str:
    return RISK_SOURCE_LABELS.get(source_kind, RISK_SOURCE_LABELS["unavailable"])


def _risk_source_rank(source_kind: str) -> int:
    return {"real": 0, "local_cache": 1, "unavailable": 2, "fallback": 3}.get(source_kind, 3)


def _risk_overall_source_kind(components: list[dict]) -> str:
    kinds = {item.get("source_kind") or item.get("source") for item in components}
    if not kinds:
        return "unavailable"
    if "local_cache" in kinds:
        return "local_cache"
    if "unavailable" in kinds:
        return "unavailable"
    if "fallback" in kinds:
        return "unavailable"
    return "real"


def _risk_component(
    key: str,
    name: str,
    score: Optional[float],
    weight: float,
    value: str,
    source_kind: str,
    status: str = "ok",
    detail: str = "",
    provider: str = "",
    updated_at: Optional[str] = None,
    error: Optional[str] = None,
    source_url: str = "",
    evidence: Optional[list[dict]] = None,
) -> dict:
    normalized_source = source_kind if source_kind in RISK_SOURCE_LABELS else "unavailable"
    normalized_score = None
    if score is not None:
        try:
            normalized_score = round(_risk_clamp(float(score)), 2)
        except Exception:
            normalized_score = None
    return {
        "key": key,
        "name": name,
        "score": normalized_score,
        "weight": round(float(weight), 4),
        "value": value,
        "source": normalized_source,
        "source_kind": normalized_source,
        "source_label": _risk_source_label(normalized_source),
        "status": status,
        "updated_at": updated_at or datetime.now().isoformat(timespec="seconds"),
        "provider": provider,
        "source_url": source_url,
        "evidence": evidence or [],
        "detail": detail,
        "error": error,
    }


def _flow_amount_to_yi(value, column_name: str = "") -> float:
    parsed = data_sources.safe_float(value)
    if parsed is None:
        return 0.0
    name = column_name or ""
    if "万元" in name:
        return round(parsed / 10000.0, 4)
    if "元" in name and "万元" not in name and abs(parsed) > 10000:
        return round(parsed / 100000000.0, 4)
    if abs(parsed) > 1000000:
        return round(parsed / 100000000.0, 4)
    if abs(parsed) > 10000:
        return round(parsed / 10000.0, 4)
    return round(parsed, 4)


def _pick_df_column(df: pd.DataFrame | None, candidates: list[str]) -> Optional[str]:
    if df is None or df.empty:
        return None
    columns = [str(c) for c in df.columns]
    for candidate in candidates:
        for col in columns:
            if candidate == col or candidate in col:
                return col
    return None


def _call_with_timeout(fn, timeout_seconds: float = 2.5):
    executor = concurrent.futures.ThreadPoolExecutor(max_workers=1)
    future = executor.submit(fn)
    try:
        return future.result(timeout=timeout_seconds), None
    except concurrent.futures.TimeoutError:
        return None, "timeout"
    except Exception as exc:
        return None, str(exc)
    finally:
        executor.shutdown(wait=False, cancel_futures=True)


def _request_json(
    url: str,
    *,
    params: Optional[dict] = None,
    headers: Optional[dict] = None,
    timeout: float = 3.5,
) -> dict:
    response = requests.get(
        url,
        params=params,
        headers=headers or EASTMONEY_HEADERS,
        timeout=timeout,
    )
    response.raise_for_status()
    return response.json()


def _timestamp_to_date(value) -> Optional[str]:
    parsed = data_sources.safe_float(value)
    if parsed is None or parsed <= 0:
        return None
    try:
        return datetime.fromtimestamp(parsed).date().isoformat()
    except Exception:
        return None


def _market_snapshot_date(snapshot: Optional[dict]):
    value = (snapshot or {}).get("date")
    if value is None:
        return None
    if hasattr(value, "date") and callable(getattr(value, "date")):
        try:
            return value.date()
        except Exception:
            pass
    if hasattr(value, "isoformat") and not isinstance(value, str):
        return value
    text_value = str(value).strip()
    if not text_value:
        return None
    try:
        return datetime.strptime(text_value[:10], "%Y-%m-%d").date()
    except Exception:
        return None


def _flow_yi_from_wan(value) -> float:
    parsed = data_sources.safe_float(value)
    return round((parsed or 0.0) / 10000.0, 4)


def _parse_risk_sectors(sectors: Optional[str]) -> list[str]:
    if not sectors:
        return DEFAULT_RISK_SECTORS[:3]
    parsed = [item.strip() for item in sectors.split(",") if item.strip()]
    return parsed[:50] or DEFAULT_RISK_SECTORS[:3]


