def _build_systemic_risk_context(
    db: Session,
    watched: Optional[list[str]] = None,
    use_cache: bool = True,
    market: str = "CN",
) -> dict:
    market_code = _normalize_market_code(market)
    market_weights = SYSTEMIC_RISK_WEIGHTS_BY_MARKET[market_code]
    watched_sectors = watched or DEFAULT_RISK_SECTORS[:3]
    cache_key = f"risk:systemic:v9:{market_code}:full-market"
    if use_cache:
        cached = cache_get(cache_key)
        if cached:
            try:
                return json.loads(cached)
            except Exception:
                pass
    component_fallbacks = {
        "index_volatility": _risk_component(
            "index_volatility",
            "指数波动率",
            None,
            market_weights["index_volatility"],
            "无",
            "unavailable",
            "unavailable",
            "指数行情源未在页面等待窗口内返回。",
            "index.timeout",
            error="timeout",
        ),
        "macro_finance": _risk_component(
            "macro_finance",
            "宏观金融数据",
            None,
            market_weights["macro_finance"],
            "无",
            "unavailable",
            "unavailable",
            "宏观金融数据源未在页面等待窗口内返回。",
            "macro.timeout",
            error="timeout",
        ),
        "geopolitical_events": _risk_component(
            "geopolitical_events",
            "地缘政治事件",
            None,
            market_weights["geopolitical_events"],
            "无",
            "unavailable",
            "unavailable",
            "地缘政治新闻源未在页面等待窗口内返回。",
            "news.timeout",
            error="timeout",
        ),
        "policy_events": _risk_component(
            "policy_events",
            "政策事件",
            None,
            market_weights["policy_events"],
            "无",
            "unavailable",
            "unavailable",
            "政策新闻源未在页面等待窗口内返回。",
            "news.timeout",
            error="timeout",
        ),
    }
    executor = concurrent.futures.ThreadPoolExecutor(max_workers=5)
    futures = {
        executor.submit(
            _risk_fund_flow_payload_isolated,
            watched_sectors,
            market_code,
        ): "fund_flow",
        executor.submit(
            _index_volatility_component_isolated,
            market_code,
        ): "index_volatility",
        executor.submit(_macro_finance_component, market_code): "macro_finance",
        executor.submit(_geopolitical_event_component, market_code): "geopolitical_events",
        executor.submit(_policy_event_component, market_code): "policy_events",
    }
    market_snapshot = _market_snapshot_current(
        db,
        live_tencent=False,
        market=market_code,
    )
    async_results = {}
    try:
        done, pending = concurrent.futures.wait(futures, timeout=4.0)
        for future in done:
            key = futures[future]
            try:
                async_results[key] = future.result(timeout=0)
            except Exception as exc:
                if key in component_fallbacks:
                    fallback = dict(component_fallbacks[key])
                    fallback["error"] = str(exc)
                    async_results[key] = fallback
        for future in pending:
            future.cancel()
            key = futures[future]
            if key in component_fallbacks:
                async_results[key] = component_fallbacks[key]
    finally:
        executor.shutdown(wait=False, cancel_futures=True)
    fund_flow = async_results.get("fund_flow") or _build_local_fund_flow(
        db,
        watched_sectors,
        market=market_code,
    )
    components = [
        _market_breadth_component(market_snapshot),
        _sector_flow_component(fund_flow),
        async_results.get("index_volatility", component_fallbacks["index_volatility"]),
    ]
    if market_weights.get("northbound", 0) > 0:
        components.insert(
            1,
            _flow_component(
                "northbound",
                "北向资金",
                fund_flow.get("northbound") or _fallback_cross_border_flow("北向资金"),
                market_weights["northbound"],
            ),
        )
    if market_weights.get("southbound", 0) > 0:
        insert_at = 2 if market_weights.get("northbound", 0) > 0 else 1
        components.insert(
            insert_at,
            _flow_component(
                "southbound",
                "南向资金",
                fund_flow.get("southbound") or _fallback_cross_border_flow("南向资金"),
                market_weights["southbound"],
            ),
        )
    components.extend(
        [
            async_results.get("macro_finance", component_fallbacks["macro_finance"]),
            async_results.get(
                "geopolitical_events",
                component_fallbacks["geopolitical_events"],
            ),
            async_results.get("policy_events", component_fallbacks["policy_events"]),
        ]
    )
    for component in components:
        component["weight"] = round(float(market_weights.get(component.get("key"), 0.0)), 4)
    scored_components = [
        item
        for item in components
        if item.get("score") is not None
        and item.get("source_kind") not in {"unavailable", "fallback"}
    ]
    total_weight = sum(float(item.get("weight") or 0.0) for item in scored_components)
    score = (
        sum(float(item["score"]) * float(item["weight"]) for item in scored_components) / total_weight
        if total_weight > 0
        else None
    )
    source_kind = _risk_overall_source_kind(components)
    source_counts = {
        kind: sum(1 for item in components if item.get("source_kind") == kind)
        for kind in RISK_SOURCE_LABELS
    }
    fallback_count = source_counts["fallback"]
    unavailable_count = source_counts["unavailable"]
    degraded_count = fallback_count + unavailable_count
    if not scored_components:
        status = "unavailable"
    elif degraded_count == 0:
        status = "ok"
    else:
        status = "partial"
    source_label = " / ".join(
        _risk_source_label(kind)
        for kind in ("real", "local_cache", "unavailable", "fallback")
        if source_counts[kind]
    ) or _risk_source_label(source_kind)
    payload = {
        "market": market_code,
        "score": round(_risk_clamp(score), 2) if score is not None else None,
        "label": _risk_label(score) if score is not None else "无数据",
        "status": status,
        "source": source_kind,
        "source_kind": source_kind,
        "source_label": source_label,
        "updated_at": datetime.now().isoformat(timespec="seconds"),
        "formula": "系统性风险 = 市场宽度 + 市场适用的跨境资金 + 全市场板块资金流 + 指数波动率 + 市场宏观金融数据 + 地缘政治事件 + 政策事件",
        "weights": market_weights,
        "components": components,
        "fund_flow": fund_flow,
        "market_snapshot": market_snapshot,
        "sector_scope": "full_market",
        "watched_sectors": watched_sectors,
        "data_quality": {
            "real": source_counts["real"],
            "local_cache": source_counts["local_cache"],
            "unavailable": unavailable_count,
            "fallback": fallback_count,
        },
    }
    cache_set(cache_key, json.dumps(payload, ensure_ascii=False, default=str), ex=180)
    return payload


def _build_risk_events(
    db: Session,
    current_user: UserModel,
    market: str = "CN",
) -> list[dict]:
    watched = _risk_watched_sectors_for_market(
        _get_user_risk_monitor_config(db, current_user),
        market,
        db,
    )
    context = _build_systemic_risk_context(db, watched, market=market)
    components = context["components"]
    now = datetime.now().strftime("%H:%M")
    events = []
    scored_components = [
        item for item in components if item.get("score") is not None
    ]
    for component in sorted(
        scored_components,
        key=lambda item: float(item.get("score") or 0.0),
        reverse=True,
    ):
        score = float(component.get("score") or 0.0)
        source_label = component.get("source_label") or _risk_source_label("fallback")
        if (
            score < 55
            and component.get("source_kind") != "fallback"
            and not component.get("evidence")
        ):
            continue
        events.append(
            {
                "time": now,
                "title": f"{component['name']}风险{_risk_label(score)}",
                "desc": f"{component.get('value') or ''}；{component.get('detail') or ''}",
                "level": "error" if score >= 75 else ("warning" if score >= 55 else "info"),
                "tags": [component["name"], source_label],
                "source_url": component.get("source_url") or "",
                "evidence": component.get("evidence") or [],
            }
        )

    if not events:
        if not scored_components:
            events.append(
                {
                    "time": now,
                    "title": "暂无系统性风险数据",
                    "desc": "市场宽度、资金流、波动率、宏观和政策事件暂未形成可计算样本。",
                    "level": "info",
                    "tags": ["无数据"],
                }
            )
            return events
        events.append(
            {
                "time": now,
                "title": "风险巡检正常",
                "desc": "未发现高优先级系统性风险事件，继续监控市场宽度、资金流、波动率、宏观和政策事件。",
                "level": "info",
                "tags": ["巡检", "正常"],
            }
        )
    return events[:8]


def _build_risk_assessment(
    db: Session,
    current_user: UserModel,
    context: Optional[dict] = None,
    market: str = "CN",
) -> str:
    context = context or _build_systemic_risk_context(
        db,
        DEFAULT_RISK_SECTORS[:3],
        market=market,
    )
    score = context["score"]
    components = context["components"]
    scored_components = [
        item for item in components if item.get("score") is not None
    ]
    if score is None or not scored_components:
        return (
            "当前可用数据尚不足以形成稳定的系统性风险结论。"
            "建议暂时保持分散配置，等待市场宽度、资金流、指数波动率与事件数据完成同步。"
        )
    top_risks = sorted(
        scored_components,
        key=lambda item: float(item.get("score") or 0.0),
        reverse=True,
    )[:3]
    top_text = "、".join(
        f"{item['name']}（风险贡献 {item['score']:.0f}）" for item in top_risks
    )
    advice = (
        "当前应降低高波动和资金持续流出板块的暴露，保留流动性并等待风险指标回落。"
        if score >= 60
        else "当前可维持分散配置，重点跟踪市场宽度、跨境成交变化、板块资金和指数波动是否同步转弱。"
    )
    return (
        f"市场整体处于{_risk_label(score)}区间，综合风险评分为 {score:.1f}/100。"
        f"当前需要重点关注 {top_text}。{advice}"
    )


