def _risk_ai_assessment_payload(
    db: Session,
    current_user: UserModel,
    use_llm: bool = False,
    model: Optional[str] = None,
    market: str = "CN",
    *,
    charge_credits: bool = True,
    usage_reference_id_override: Optional[str] = None,
    charged_credits_override: Optional[int] = None,
) -> dict:
    """AI 策略风险评估（无可用 LLM 时返回本地结构化评估）"""
    credit_summary = None
    usage_reference_id = None
    usage_credits = int(
        charged_credits_override
        if charged_credits_override is not None
        else _llm_tier_credit_cost(db, "risk_ai_assessment", model, current_user)
    )
    if use_llm:
        usage_reference_id = usage_reference_id_override or (
            f"risk_ai_assessment:{uuid.uuid4().hex}"
        )
        if charge_credits:
            credit_summary = _consume_user_credits(
                db,
                current_user,
                "risk_ai_assessment",
                usage_credits,
                reference_id=usage_reference_id,
            )
        else:
            credit_summary = _credit_summary(db, current_user)
    market_code = _normalize_market_code(market)
    watched = _risk_watched_sectors_for_market(
        _get_user_risk_monitor_config(db, current_user),
        market_code,
        db,
    )
    systemic_context = _build_systemic_risk_context(
        db,
        watched,
        market=market_code,
    )
    fallback_assessment = _build_risk_assessment(
        db,
        current_user,
        systemic_context,
        market=market_code,
    )
    try:
        llm_cfg = _llm_config_for_module(
            db,
            user_id=current_user.id,
            module_key="risk",
            model_override=(model or "").strip() or None,
        )
        if usage_reference_id:
            llm_cfg["_usage_reference_id"] = usage_reference_id
            llm_cfg["_usage_credits"] = usage_credits
        if use_llm and llm_cfg.get("api_key"):
            def run_llm_assessment():
                if _direct_llm_supported(llm_cfg):
                    cfg = {**llm_cfg}
                    return _run_risk_assessment_direct(
                        cfg,
                        fallback_assessment,
                        market=market_code,
                    )

                from llm_factory import build_crewai_llm
                from crewai import Agent, Crew, Task

                thread_db = SessionLocal()
                try:
                    llm = build_crewai_llm(
                        thread_db,
                        user_id=current_user.id,
                        allow_shared_fallback=False,
                        resolved_config=llm_cfg,
                    )
                    agent = Agent(
                        role="风险分析师",
                        goal="评估当前持仓风险",
                        backstory="专业量化风控专家",
                        llm=llm,
                        verbose=False,
                    )
                    task = Task(
                        description=(
                            "简要评估当前市场风险，给出100字以内的风险评估报告。"
                            f"本地风控摘要：{fallback_assessment}"
                        ),
                        expected_output="风险评估报告",
                        agent=agent,
                    )
                    crew = Crew(agents=[agent], tasks=[task], verbose=False)
                    crew_result = crew.kickoff()
                    result_text = str(crew_result)
                    usage = usage_metering.extract_token_usage(
                        [crew_result, getattr(crew, "usage_metrics", None)],
                        provider=str(llm_cfg.get("provider") or ""),
                    )
                    if not usage.get("total_tokens"):
                        usage = usage_metering.normalize_token_usage(
                            provider=str(llm_cfg.get("provider") or ""),
                            input_text=task.description,
                            output_text=result_text,
                        )
                    _persist_llm_usage(
                        thread_db,
                        user_id=current_user.id,
                        module_key="risk",
                        provider=str(llm_cfg.get("provider") or "openai"),
                        model=str(llm_cfg.get("model") or "unknown"),
                        usage=usage,
                        request_id=usage_reference_id,
                        credits_charged=usage_credits,
                        meta={"engine": "crewai"},
                        output_text=result_text,
                        data_source="systemic_risk_context",
                    )
                    return result_text
                finally:
                    thread_db.close()

            risk_llm_timeout = _assistant_timeout_seconds(
                "RISK_LLM_TIMEOUT_SECONDS", 60.0, 6.0, 180.0
            )
            result, llm_error = _call_with_timeout(
                run_llm_assessment, risk_llm_timeout
            )
            if not result:
                return {
                    "assessment": fallback_assessment,
                    "source": systemic_context["source"],
                    "source_kind": systemic_context["source_kind"],
                    "source_label": systemic_context["source_label"],
                    "status": "unavailable" if systemic_context.get("score") is None else "partial",
                    "components": systemic_context["components"],
                    "score": systemic_context["score"],
                    "label": systemic_context["label"],
                    "credit_summary": credit_summary,
                    "degraded": True,
                    "refund_required": bool(use_llm),
                    "failure_class": "llm_timeout",
                    "error": error_payload(
                        "RISK_AI_ASSESSMENT_TIMEOUT",
                        "AI 风险评估超时，已返回本地评估",
                        llm_error,
                    ),
                }
            return {
                "assessment": result,
                "source": "llm",
                "source_kind": systemic_context["source_kind"],
                "source_label": systemic_context["source_label"],
                "status": "ok",
                "components": systemic_context["components"],
                "score": systemic_context["score"],
                "label": systemic_context["label"],
                "credit_summary": credit_summary,
                "degraded": False,
                "refund_required": False,
                "failure_class": "",
                "error": None,
            }
        return {
            "assessment": fallback_assessment,
            "source": systemic_context["source"],
            "source_kind": systemic_context["source_kind"],
            "source_label": systemic_context["source_label"],
            "status": systemic_context.get("status") or ("unavailable" if systemic_context.get("score") is None else "ok"),
            "components": systemic_context["components"],
            "score": systemic_context["score"],
            "label": systemic_context["label"],
            "credit_summary": credit_summary,
            "degraded": bool(use_llm),
            "refund_required": bool(use_llm),
            "failure_class": "llm_not_configured" if use_llm else "",
            "error": (
                error_payload(
                    "RISK_AI_CONFIG_UNAVAILABLE",
                    "AI 风险评估模型配置未就绪，已返回本地评估",
                )
                if use_llm
                else None
            ),
        }
    except Exception as e:
        return {
            "assessment": fallback_assessment,
            "source": systemic_context["source"],
            "source_kind": systemic_context["source_kind"],
            "source_label": systemic_context["source_label"],
            "status": "unavailable" if systemic_context.get("score") is None else "partial",
            "components": systemic_context["components"],
            "score": systemic_context["score"],
            "label": systemic_context["label"],
            "credit_summary": credit_summary,
            "degraded": True,
            "refund_required": bool(use_llm),
            "failure_class": "risk_llm_error",
            "error": error_payload(
                "RISK_AI_ASSESSMENT_FAILED", "AI 风险评估暂不可用", str(e)
            ),
        }


def _risk_assessment_cache_key(user_id: int, market: str) -> str:
    return f"risk:assessment:v2:{int(user_id)}:{_normalize_market_code(market)}"


def _serialize_risk_assessment_task(task: RiskAssessmentTask) -> dict:
    result = _json_loads_or(task.result_json, {})
    return {
        "task_id": task.id,
        "market": task.market or "CN",
        "status": task.status,
        "result": result if isinstance(result, dict) else {},
        "error": task.error or "",
        "queue_status": task.queue_status or "inline",
        "attempt_count": int(task.attempt_count or 0),
        "failure_class": task.failure_class or "",
        "charged_credits": int(task.charged_credits or 0),
        "refunded_credits": int(task.refunded_credits or 0),
        "created_at": task.created_at.isoformat() if task.created_at else None,
        "updated_at": task.updated_at.isoformat() if task.updated_at else None,
    }


def _run_risk_assessment_task(task_id: int, user_id: int) -> dict:
    db = SessionLocal()
    try:
        task = (
            db.query(RiskAssessmentTask)
            .filter(
                RiskAssessmentTask.id == task_id,
                RiskAssessmentTask.user_id == user_id,
            )
            .first()
        )
        user = db.query(UserModel).filter(UserModel.id == user_id).first()
        if not task or not user:
            return {"status": "missing", "task_id": task_id}
        if task.status in {"done", "cancelled"}:
            return {"status": task.status, "task_id": task_id}
        task.status = "running"
        if task.queue_status != "inline":
            task.queue_status = "running"
        task.started_at = task.started_at or datetime.now(timezone.utc)
        task.heartbeat_at = datetime.now(timezone.utc)
        db.commit()

        market_code = _normalize_market_code(task.market)
        queue_managed = task.queue_status != "inline"
        watched = _risk_watched_sectors_for_market(
            _get_user_risk_monitor_config(db, user),
            market_code,
            db,
        )
        _risk_fund_flow_payload(
            db,
            watched,
            use_cache=False,
            allow_slow_fallback=False,
            market=market_code,
        )
        cache_delete(f"risk:systemic:v9:{market_code}:full-market")
        result = _risk_ai_assessment_payload(
            db,
            user,
            use_llm=bool(task.use_llm),
            model=(task.model or "").strip() or None,
            market=market_code,
            # The API charges before enqueueing. The worker must never charge
            # again when a task is retried or delivered inline in development.
            charge_credits=False,
            usage_reference_id_override=(
                f"risk_ai_assessment:{task.id}"
            ),
            charged_credits_override=int(task.charged_credits or 0),
        )
        refund_required = bool(result.get("refund_required"))
        failure_class = str(result.get("failure_class") or "")
        task.status = "done"
        if task.queue_status != "inline":
            task.queue_status = "completed"
        task.result_json = json.dumps(result, ensure_ascii=False, default=str)
        task.error = ""
        task.failure_class = failure_class or None
        task.heartbeat_at = datetime.now(timezone.utc)
        task.finished_at = datetime.now(timezone.utc)
        db.add(
            Notification(
                user_id=user_id,
                type="risk_assessment",
                title="风险评估已完成",
                content=f"{market_code} 市场风险评估任务 #{task.id} 已完成，可进入风险监控页面查看。",
            )
        )
        db.commit()
        cache_set(
            _risk_assessment_cache_key(user_id, market_code),
            json.dumps(result, ensure_ascii=False, default=str),
            ex=21600,
        )
        try:
            _deliver_robot_webhooks(
                db,
                user,
                "风险评估已完成",
                f"{market_code} 市场风险评估任务 #{task.id} 已完成。",
                "risk_assessment",
            )
        except Exception:
            pass
        if refund_required and not queue_managed:
            _refund_risk_assessment_task(
                int(task_id),
                failure_class or "risk_assessment_fallback",
            )
        return {
            "status": "done",
            "task_id": task_id,
            "refund_required": refund_required,
            "failure_class": failure_class,
        }
    except Exception as exc:
        db.rollback()
        task = (
            db.query(RiskAssessmentTask)
            .filter(
                RiskAssessmentTask.id == task_id,
                RiskAssessmentTask.user_id == user_id,
            )
            .first()
        )
        if task:
            inline_failure = task.queue_status == "inline"
            task.status = "failed"
            if task.queue_status != "inline":
                task.queue_status = "failed"
            task.error = _assistant_sanitize_error(exc)
            task.failure_class = "risk_assessment_error"
            task.finished_at = datetime.now(timezone.utc)
            db.commit()
            if inline_failure:
                _refund_risk_assessment_task(
                    int(task_id),
                    "risk_assessment_error",
                )
        return {
            "status": "failed",
            "task_id": task_id,
            "system_failure": True,
            "failure_class": "risk_assessment_error",
        }
    finally:
        db.close()


@app.get("/api/risk/ai-assessment", dependencies=[Depends(require_permission("risk.view"))])
def get_risk_ai_assessment(
    market: str = "CN",
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """只读风险评估。GET 不触发 LLM，也不扣减积分。"""
    market_code = _normalize_market_code(market)
    cached = cache_get(_risk_assessment_cache_key(current_user.id, market_code))
    if cached:
        try:
            payload = json.loads(cached)
            if isinstance(payload, dict):
                payload["cached"] = True
                return payload
        except Exception:
            pass
    latest_task = (
        db.query(RiskAssessmentTask)
        .filter(
            RiskAssessmentTask.user_id == current_user.id,
            RiskAssessmentTask.market == market_code,
            RiskAssessmentTask.status == "done",
        )
        .order_by(RiskAssessmentTask.updated_at.desc())
        .first()
    )
    if latest_task and latest_task.result_json:
        payload = _json_loads_or(latest_task.result_json, {})
        if isinstance(payload, dict) and payload:
            cache_set(
                _risk_assessment_cache_key(current_user.id, market_code),
                json.dumps(payload, ensure_ascii=False, default=str),
                ex=21600,
            )
            payload["cached"] = True
            return payload
    return _risk_ai_assessment_payload(
        db,
        current_user,
        use_llm=False,
        model=None,
        market=market_code,
    )


@app.post("/api/risk/ai-assessment/run", dependencies=[Depends(require_permission("risk.view"))])
def run_risk_ai_assessment(
    payload: RiskAiAssessmentRunRequest,
    background_tasks: BackgroundTasks = None,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """Create one user-owned background refresh; polling does not consume credits."""
    market_code = _normalize_market_code(payload.market)
    use_durable_queue = bool(queue_enabled())
    if use_durable_queue and not broker_ready():
        raise HTTPException(
            status_code=503,
            detail={
                "code": "TASK_QUEUE_UNAVAILABLE",
                "message": "后台任务队列暂不可用，请稍后重试",
            },
        )
    _lock_long_task_admission(db) if use_durable_queue else None
    active = (
        db.query(RiskAssessmentTask)
        .filter(
            RiskAssessmentTask.user_id == current_user.id,
            RiskAssessmentTask.market == market_code,
            RiskAssessmentTask.status.in_(["pending", "running"]),
        )
        .order_by(RiskAssessmentTask.created_at.desc())
        .first()
    )
    if active:
        response = _serialize_risk_assessment_task(active)
        # A repeated refresh request reuses the existing task. Keep the same
        # credit contract as a newly accepted request so the client can render
        # its current balance without treating the request as a new charge.
        response["credit_summary"] = _credit_summary(db, current_user)
        return response
    if use_durable_queue:
        queue_depth = _long_task_queue_depth(db)
        if queue_depth >= QUEUE_MAX_PENDING:
            raise HTTPException(
                status_code=429,
                detail={
                    "code": "TASK_QUEUE_FULL",
                    "message": "后台任务队列已满，请等待已有任务完成",
                    "queue_depth": queue_depth,
                    "queue_limit": QUEUE_MAX_PENDING,
                },
            )
    task = RiskAssessmentTask(
        user_id=current_user.id,
        market=market_code,
        status="pending",
        model=(payload.model or "").strip() or None,
        use_llm=bool(payload.use_llm),
        queue_status="queued" if use_durable_queue else "inline",
        queue_priority=queue_priority_for_role(current_user.role),
    )
    db.add(task)
    db.commit()
    db.refresh(task)
    try:
        estimated_credits = (
            _llm_tier_credit_cost(
                db, "risk_ai_assessment", payload.model, current_user
            )
            if payload.use_llm
            else 0
        )
        credit_summary = _consume_user_credits(
            db,
            current_user,
            "risk_ai_assessment",
            estimated_credits,
            reference_id=f"risk_ai_assessment:{task.id}",
        )
        task.charged_credits = (
            int(estimated_credits or 0)
            if (credit_summary.get("last_charge") or {}).get("charged")
            else 0
        )
        db.commit()
    except HTTPException:
        db.delete(task)
        db.commit()
        raise

    task_payload = {
        "task_id": task.id,
        "user_id": current_user.id,
    }
    db_task_payload = {
        **task_payload,
        "model": (payload.model or "").strip() or None,
    }
    task.queue_payload_json = json.dumps(
        db_task_payload,
        ensure_ascii=False,
        default=str,
    )
    db.commit()
    if use_durable_queue:
        try:
            task.queue_task_id = enqueue_named_task(
                "quantsys.risk_assessment",
                task_payload,
                queue="long_tasks",
                priority=_celery_priority_for_user(current_user),
            )
            db.commit()
        except Exception as exc:
            db.rollback()
            failed_task_id = int(task.id)
            task = db.query(RiskAssessmentTask).filter(RiskAssessmentTask.id == failed_task_id).first()
            if task:
                task.status = "failed"
                task.queue_status = "failed"
                task.failure_class = "queue_submit_error"
                task.error = "后台任务提交失败，请稍后重试"
                task.finished_at = datetime.now(timezone.utc)
                db.commit()
            _refund_risk_assessment_task(failed_task_id, "queue_submit_error")
            raise HTTPException(
                status_code=503,
                detail={
                    "code": "TASK_QUEUE_SUBMIT_FAILED",
                    "message": "后台任务提交失败，请稍后重试",
                },
            ) from exc
    else:
        if background_tasks is None:
            background_tasks = BackgroundTasks()
        background_tasks.add_task(_run_risk_assessment_task, task.id, current_user.id)
    response = _serialize_risk_assessment_task(task)
    response.update(
        {
            "credit_summary": credit_summary,
            "queue_depth": _long_task_queue_depth(db) if use_durable_queue else None,
            "queue_limit": QUEUE_MAX_PENDING if use_durable_queue else None,
            "global_concurrency": (
                effective_global_concurrency() if use_durable_queue else None
            ),
            "configured_global_concurrency": (
                QUEUE_GLOBAL_CONCURRENCY if use_durable_queue else None
            ),
        }
    )
    return response


