@app.get("/api/logs", dependencies=[Depends(require_permission("system.manage"))])
def get_logs(limit: int = 50):
    """返回操作日志（从后端日志文件读取最近N行）"""
    import os

    log_file = os.path.join(os.path.dirname(__file__), "backend.out.log")
    lines = []
    try:
        with open(log_file, encoding="utf-8", errors="ignore") as f:
            lines = f.readlines()[-limit:]
    except Exception:
        pass
    return [{"line": i + 1, "content": l.rstrip()} for i, l in enumerate(lines)]


@app.get("/api/logs/export", dependencies=[Depends(require_permission("system.manage"))])
def export_logs(limit: Optional[int] = None, db: Session = Depends(get_db)):
    """导出后端日志，仅系统管理员可用。"""
    settings_value = _auth_security_settings(db)
    logging_cfg = settings_value.get("logging") or {}
    if not logging_cfg.get("export_enabled", True):
        raise HTTPException(status_code=403, detail="日志导出未启用")
    max_lines = int(logging_cfg.get("max_export_lines") or 5000)
    effective_limit = max(100, min(max_lines, int(limit or max_lines)))
    log_file = os.path.join(os.path.dirname(__file__), "backend.out.log")
    lines: list[str] = []
    try:
        with open(log_file, encoding="utf-8", errors="ignore") as f:
            lines = f.readlines()[-effective_limit:]
    except Exception as err:
        lines = [f"日志读取失败：{err}\n"]
    content = "".join(lines)
    filename = f"quartsys-backend-{datetime.now().strftime('%Y%m%d-%H%M%S')}.log"
    return Response(
        content=content,
        media_type="text/plain; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


