def _default_robot_webhook_config() -> dict:
    return {
        "feishu": {"enabled": False, "webhook_url": "", "secret": ""},
        "wecom": {"enabled": False, "webhook_url": ""},
        "telegram": {"enabled": False, "bot_token": "", "chat_id": "", "webhook_url": ""},
        "scope": {
            "risk_events": True,
            "ai_insights": True,
            "strategy_signals": True,
            "trade_events": True,
            "system_status": True,
            "subscription": False,
        },
        "templates": {
            "risk_events": "【风险提醒】{title}\n{content}",
            "ai_insights": "【AI洞察】{title}\n{content}",
            "strategy_signals": "【策略信号】{title}\n{content}",
            "trade_events": "【交易提醒】{title}\n{content}",
            "system_status": "【系统通知】{title}\n{content}",
            "subscription": "【订阅通知】{title}\n{content}",
        },
    }


ROBOT_WEBHOOK_PROVIDERS = ("feishu", "wecom", "telegram")
NOTIFICATION_SCOPE_OPTIONS = {
    "risk_events": "风险事件",
    "ai_insights": "AI洞察",
    "strategy_signals": "策略信号",
    "trade_events": "交易提醒",
    "system_status": "系统通知",
    "subscription": "订阅与额度",
}


def _user_can_manage_notification_templates(user: UserModel) -> bool:
    return normalize_user_role(getattr(user, "role", None)) in {"admin", "svip"}


def _normalize_robot_webhook_config(
    raw: Optional[dict],
    *,
    existing: Optional[dict] = None,
    preserve_masked: bool = True,
    allow_templates: bool = True,
) -> dict:
    base = _default_robot_webhook_config()
    raw = raw if isinstance(raw, dict) else {}
    existing = existing if isinstance(existing, dict) else {}
    result: dict = {}
    for provider in ROBOT_WEBHOOK_PROVIDERS:
        defaults = base[provider]
        current = existing.get(provider) if isinstance(existing.get(provider), dict) else {}
        incoming = raw.get(provider) if isinstance(raw.get(provider), dict) else {}
        provider_config = {**defaults, **current}
        for key, value in incoming.items():
            if preserve_masked and isinstance(value, str) and "****" in value:
                continue
            provider_config[key] = value
        provider_config["enabled"] = bool(provider_config.get("enabled"))
        for key in list(provider_config.keys()):
            if key != "enabled":
                provider_config[key] = str(provider_config.get(key) or "").strip()
        result[provider] = provider_config

    scope_config = {
        **base["scope"],
        **(existing.get("scope") if isinstance(existing.get("scope"), dict) else {}),
        **(raw.get("scope") if isinstance(raw.get("scope"), dict) else {}),
    }
    result["scope"] = {
        key: bool(scope_config.get(key))
        for key in NOTIFICATION_SCOPE_OPTIONS.keys()
    }

    existing_templates = existing.get("templates") if isinstance(existing.get("templates"), dict) else {}
    incoming_templates = raw.get("templates") if isinstance(raw.get("templates"), dict) else {}
    templates = {**base["templates"], **existing_templates}
    if allow_templates:
        templates.update(incoming_templates)
    result["templates"] = {
        key: str(templates.get(key) or base["templates"][key]).strip()[:1000]
        for key in NOTIFICATION_SCOPE_OPTIONS.keys()
    }
    return result


def _mask_robot_webhook_config(config: dict) -> dict:
    masked = json.loads(json.dumps(_normalize_robot_webhook_config(config)))
    for provider in ("feishu", "wecom"):
        if masked.get(provider, {}).get("webhook_url"):
            masked[provider]["webhook_url"] = _mask_url(masked[provider]["webhook_url"])
    if masked.get("feishu", {}).get("secret"):
        masked["feishu"]["secret"] = _mask_secret(masked["feishu"]["secret"])
    if masked.get("telegram", {}).get("bot_token"):
        masked["telegram"]["bot_token"] = _mask_secret(masked["telegram"]["bot_token"])
    if masked.get("telegram", {}).get("webhook_url"):
        masked["telegram"]["webhook_url"] = _mask_url(masked["telegram"]["webhook_url"])
    return masked


def _get_user_robot_webhook_config(
    db: Session, current_user: UserModel, *, masked: bool = False
) -> dict:
    row = (
        db.query(UserSetting)
        .filter(
            UserSetting.user_id == current_user.id,
            UserSetting.key == NOTIFICATION_WEBHOOKS_KEY,
        )
        .first()
    )
    config = _normalize_robot_webhook_config(_json_loads_dict(row.value_json if row else None))
    return _mask_robot_webhook_config(config) if masked else config


def _save_user_robot_webhook_config(
    db: Session, current_user: UserModel, raw_config: dict
) -> dict:
    existing = _get_user_robot_webhook_config(db, current_user, masked=False)
    config = _normalize_robot_webhook_config(
        raw_config,
        existing=existing,
        allow_templates=_user_can_manage_notification_templates(current_user),
    )
    row = (
        db.query(UserSetting)
        .filter(
            UserSetting.user_id == current_user.id,
            UserSetting.key == NOTIFICATION_WEBHOOKS_KEY,
        )
        .first()
    )
    if not row:
        row = UserSetting(user_id=current_user.id, key=NOTIFICATION_WEBHOOKS_KEY)
        db.add(row)
    row.value_json = json.dumps(config, ensure_ascii=False, indent=2)
    db.commit()
    return config


def _feishu_signed_payload(config: dict, text: str) -> dict:
    payload = {"msg_type": "text", "content": {"text": text}}
    secret = config.get("secret")
    if not secret:
        return payload
    timestamp = str(int(time.time()))
    string_to_sign = f"{timestamp}\n{secret}"
    digest = hmac.new(
        string_to_sign.encode("utf-8"), b"", digestmod=hashlib.sha256
    ).digest()
    payload["timestamp"] = timestamp
    payload["sign"] = base64.b64encode(digest).decode("utf-8")
    return payload


ROBOT_WEBHOOK_ALLOWED_HOSTS = {
    "feishu": ("open.feishu.cn", "open.larksuite.com"),
    "wecom": ("qyapi.weixin.qq.com",),
    "telegram": ("api.telegram.org",),
}


def _validate_robot_webhook_url(provider: str, url: str) -> tuple[bool, str]:
    parsed = urlparse(str(url or "").strip())
    if parsed.scheme != "https" or not parsed.hostname:
        return False, "webhook_url must be https"
    hostname = parsed.hostname.lower()
    allowed = ROBOT_WEBHOOK_ALLOWED_HOSTS.get(provider, ())
    if not any(hostname == host or hostname.endswith(f".{host}") for host in allowed):
        return False, "webhook host is not allowed"
    return True, ""


def _send_robot_webhook(provider: str, provider_config: dict, title: str, content: str) -> dict:
    text = f"{title}\n{content}".strip()
    try:
        if provider == "feishu":
            webhook_url = provider_config.get("webhook_url")
            if not webhook_url:
                return {"provider": provider, "ok": False, "error": "webhook_url missing"}
            valid, error = _validate_robot_webhook_url(provider, webhook_url)
            if not valid:
                return {"provider": provider, "ok": False, "error": error}
            response = requests.post(
                webhook_url,
                json=_feishu_signed_payload(provider_config, text),
                timeout=4,
            )
        elif provider == "wecom":
            webhook_url = provider_config.get("webhook_url")
            if not webhook_url:
                return {"provider": provider, "ok": False, "error": "webhook_url missing"}
            valid, error = _validate_robot_webhook_url(provider, webhook_url)
            if not valid:
                return {"provider": provider, "ok": False, "error": error}
            response = requests.post(
                webhook_url,
                json={"msgtype": "text", "text": {"content": text}},
                timeout=4,
            )
        elif provider == "telegram":
            if provider_config.get("webhook_url"):
                valid, error = _validate_robot_webhook_url(provider, provider_config["webhook_url"])
                if not valid:
                    return {"provider": provider, "ok": False, "error": error}
                response = requests.post(
                    provider_config["webhook_url"],
                    json={"text": text, "chat_id": provider_config.get("chat_id")},
                    timeout=4,
                )
            else:
                token = provider_config.get("bot_token")
                chat_id = provider_config.get("chat_id")
                if not token or not chat_id:
                    return {"provider": provider, "ok": False, "error": "bot_token/chat_id missing"}
                response = requests.post(
                    f"https://api.telegram.org/bot{token}/sendMessage",
                    json={"chat_id": chat_id, "text": text},
                    timeout=4,
                )
        else:
            return {"provider": provider, "ok": False, "error": "unsupported provider"}
        ok = 200 <= response.status_code < 300
        return {
            "provider": provider,
            "ok": ok,
            "status_code": response.status_code,
            "error": "" if ok else f"HTTP {response.status_code}",
        }
    except Exception as err:
        return {"provider": provider, "ok": False, "error": str(err)[:120]}


def _notification_scope_key(notification_type: str) -> str:
    value = str(notification_type or "system").strip().lower()
    if any(token in value for token in ("risk", "风控", "风险")):
        return "risk_events"
    if any(token in value for token in ("ai", "insight", "洞察")):
        return "ai_insights"
    if any(token in value for token in ("strategy", "signal", "策略", "信号")):
        return "strategy_signals"
    if any(token in value for token in ("trade", "order", "交易", "订单", "成交")):
        return "trade_events"
    if any(token in value for token in ("subscription", "billing", "credit", "订阅", "积分")):
        return "subscription"
    return "system_status"


def _render_notification_template(config: dict, notification_type: str, title: str, content: str) -> tuple[str, str]:
    scope_key = _notification_scope_key(notification_type)
    template = str((config.get("templates") or {}).get(scope_key) or "{title}\n{content}")
    values = {
        "title": title,
        "content": content,
        "type": notification_type or "system",
        "scope": NOTIFICATION_SCOPE_OPTIONS.get(scope_key, scope_key),
    }
    try:
        rendered = template.format(**values)
    except Exception:
        rendered = f"{title}\n{content}".strip()
    return title, rendered


def _deliver_robot_webhooks(
    db: Session,
    current_user: UserModel,
    title: str,
    content: str,
    notification_type: str = "system",
) -> list[dict]:
    config = _get_user_robot_webhook_config(db, current_user, masked=False)
    scope_key = _notification_scope_key(notification_type)
    if not bool((config.get("scope") or {}).get(scope_key, True)):
        return []
    title, rendered_content = _render_notification_template(
        config,
        notification_type,
        title,
        content,
    )
    results = []
    for provider in ROBOT_WEBHOOK_PROVIDERS:
        provider_config = config.get(provider) or {}
        if not provider_config.get("enabled"):
            continue
        result = _send_robot_webhook(provider, provider_config, title, rendered_content)
        results.append(result)
        if not result.get("ok"):
            print(f"[notification-webhook] delivery failed provider={provider}: {result.get('error')}")
    return results


