class UserDataImportRequest(BaseModel):
    data: Dict[str, Any]
    mode: str = "merge"


class UserDataDeleteRequest(BaseModel):
    sections: List[str] = list(USER_DATA_SECTIONS)
    confirm_text: str = ""


def _normalize_user_data_sections_param(*raw_values: Any) -> list[str]:
    selected: list[str] = []
    invalid: list[str] = []
    for raw_value in raw_values:
        if raw_value is None:
            continue
        values = raw_value if isinstance(raw_value, (list, tuple, set)) else [raw_value]
        for value in values:
            for part in str(value or "").split(","):
                key = part.strip()
                if not key:
                    continue
                if key not in USER_DATA_SECTIONS:
                    invalid.append(key)
                    continue
                if key not in selected:
                    selected.append(key)
    if invalid:
        raise HTTPException(status_code=400, detail=f"不支持的数据类型: {', '.join(invalid)}")
    return selected


def _filter_user_data_payload_sections(payload: dict, sections: list[str]) -> dict:
    selected = [section for section in sections if section in USER_DATA_SECTIONS]
    if not selected:
        return payload
    data_root = _dict_payload(payload.get("data"))
    counts = _dict_payload(payload.get("counts"))
    return {
        **payload,
        "data": {
            section: data_root.get(section)
            for section in selected
            if section in data_root
        },
        "counts": {section: int(counts.get(section) or 0) for section in selected},
    }


def _dt_json(value: Any) -> Optional[str]:
    if isinstance(value, datetime):
        return value.isoformat()
    return str(value) if value else None


def _parse_dt(value: Any) -> Optional[datetime]:
    if isinstance(value, datetime):
        return _as_naive_utc(value)
    text_value = str(value or "").strip()
    if not text_value:
        return None
    try:
        return _as_naive_utc(datetime.fromisoformat(text_value.replace("Z", "+00:00")))
    except Exception:
        return None


def _list_payload(value: Any) -> list:
    return value if isinstance(value, list) else []


def _dict_payload(value: Any) -> dict:
    return value if isinstance(value, dict) else {}


def _unique_user_data_name(
    db: Session,
    model_cls: Any,
    base_name: Any,
    *,
    max_length: int = 160,
) -> str:
    raw_name = str(base_name or "Imported").strip()[:max_length] or "Imported"
    existing = db.query(model_cls).filter(model_cls.name == raw_name).first()
    if not existing:
        return raw_name
    stamp = datetime.now().strftime("%Y%m%d%H%M%S")
    for index in range(1, 200):
        suffix = f" imported {stamp}" if index == 1 else f" imported {stamp}-{index}"
        candidate = f"{raw_name[: max(1, max_length - len(suffix) - 1)]} {suffix}"
        if not db.query(model_cls).filter(model_cls.name == candidate).first():
            return candidate
    return f"{raw_name[:80]} imported {uuid.uuid4().hex[:8]}"


def _user_strategy_rows(db: Session, user: UserModel) -> list[Strategy]:
    return (
        db.query(Strategy)
        .filter(Strategy.user_id == user.id)
        .order_by(Strategy.updated_at.desc(), Strategy.id.desc())
        .all()
    )


def _user_simulation_account_ids(db: Session, user: UserModel) -> list[int]:
    return [
        int(row.id)
        for row in db.query(SimulationAccount.id)
        .filter(SimulationAccount.user_id == user.id)
        .all()
    ]


def _user_data_counts(db: Session, user: UserModel) -> dict:
    from models import AIInsightTask as AIInsightTaskModel

    strategy_ids = [row.id for row in db.query(Strategy.id).filter(Strategy.user_id == user.id).all()]
    session_ids = [
        row.id
        for row in db.query(AgentAnalysisSession.id)
        .filter(AgentAnalysisSession.user_id == user.id)
        .all()
    ]
    account_ids = _user_simulation_account_ids(db, user)
    discussion_message_count = 0
    if session_ids:
        discussion_message_count = int(
            db.query(func.count(AgentAnalysisMessage.id))
            .filter(AgentAnalysisMessage.session_id.in_(session_ids))
            .scalar()
            or 0
        )
    discussion_count = len(session_ids) + discussion_message_count
    simulation_count = len(account_ids)
    if account_ids:
        simulation_count += int(
            db.query(func.count(SimulationPosition.id))
            .filter(SimulationPosition.account_id.in_(account_ids))
            .scalar()
            or 0
        )
        simulation_count += int(
            db.query(func.count(SimulationTradeRecord.id))
            .filter(SimulationTradeRecord.account_id.in_(account_ids))
            .scalar()
            or 0
        )
    return {
        "strategies": len(strategy_ids)
        + int(
            db.query(func.count(StrategyAutomation.id))
            .filter(StrategyAutomation.user_id == user.id)
            .scalar()
            or 0
        ),
        "factors": int(
            db.query(func.count(CustomFactorModel.id))
            .filter(CustomFactorModel.user_id == user.id, CustomFactorModel.is_builtin != 1)
            .scalar()
            or 0
        ),
        "research_reports": int(
            db.query(func.count(SmartResearchTask.id))
            .filter(SmartResearchTask.user_id == user.id)
            .scalar()
            or 0
        )
        + int(
            db.query(func.count(AIInsightTaskModel.id))
            .filter(AIInsightTaskModel.user_id == user.id)
            .scalar()
            or 0
        ),
        "discussion_records": discussion_count
        + int(
            db.query(func.count(FinancialAgentProfile.id))
            .filter(FinancialAgentProfile.owner_user_id == user.id)
            .scalar()
            or 0
        ),
        "watchlist": int(
            db.query(func.count(Watchlist.id))
            .filter(Watchlist.user_id == user.id)
            .scalar()
            or 0
        ),
        "simulation_accounts": simulation_count,
    }


