def _factor_param(
    name: str,
    label: str,
    default: float,
    min_value: float,
    max_value: float,
    step: float = 1,
    param_type: str = "int",
) -> dict:
    return {
        "name": name,
        "label": label,
        "default": default,
        "min": min_value,
        "max": max_value,
        "step": step,
        "type": param_type,
    }


def _extract_periods(text: str) -> List[int]:
    periods = []
    for value in re.findall(r"(\d{1,3})\s*(?:日|天|周期|day|days|d)?", text, re.I):
        try:
            period = int(value)
        except ValueError:
            continue
        if 1 <= period <= 250:
            periods.append(period)
    return periods


def _default_factor_name(prompt: str, fallback: str) -> str:
    slug = re.sub(r"[^a-z0-9_]+", "_", prompt.lower()).strip("_")
    slug = re.sub(r"_+", "_", slug)
    if not slug:
        slug = fallback
    if not re.match(r"^[a-zA-Z_]", slug):
        slug = f"factor_{slug}"
    return slug[:48]


def _dedupe_factor_name(db: Session, base_name: str) -> str:
    name = base_name or "custom_factor"
    exists = (
        db.query(CustomFactorModel.id)
        .filter(CustomFactorModel.name == name)
        .first()
    )
    if not exists:
        return name
    for idx in range(2, 1000):
        candidate = f"{name}_{idx}"
        exists = (
            db.query(CustomFactorModel.id)
            .filter(CustomFactorModel.name == candidate)
            .first()
        )
        if not exists:
            return candidate
    return f"{name}_{int(datetime.now().timestamp())}"


def _normalize_factor_draft(raw: dict, prompt: str, db: Session) -> Optional[dict]:
    if not isinstance(raw, dict):
        return None
    categories = {"technical", "statistical", "fundamental", "composite", "custom"}
    output_types = {"scalar", "boolean"}
    expression = str(raw.get("expression") or "").strip()
    if not expression:
        return None
    params = []
    for item in raw.get("params") or []:
        if not isinstance(item, dict):
            continue
        name = re.sub(r"\W+", "_", str(item.get("name") or "")).strip("_")
        if not name:
            continue
        try:
            default = float(item.get("default", 20))
            min_value = float(item.get("min", 1))
            max_value = float(item.get("max", 250))
            step = float(item.get("step", 1))
        except (TypeError, ValueError):
            continue
        params.append(
            _factor_param(
                name=name[:32],
                label=str(item.get("label") or name)[:32],
                default=default,
                min_value=min_value,
                max_value=max_value,
                step=step,
                param_type=str(item.get("type") or "int")[:16],
            )
        )
    validation_params = {p["name"]: p["default"] for p in params}
    validation = factor_engine.validate_expression(expression, validation_params)
    if not validation.get("valid"):
        return None
    raw_name = str(raw.get("name") or "").strip()
    name = _default_factor_name(raw_name, "ai_factor")
    return {
        "name": _dedupe_factor_name(db, name),
        "display_name": str(raw.get("display_name") or raw.get("name") or "AI生成因子")[:64],
        "category": raw.get("category") if raw.get("category") in categories else "custom",
        "expression": expression,
        "description": str(raw.get("description") or prompt)[:500],
        "params": params,
        "output_type": raw.get("output_type") if raw.get("output_type") in output_types else "scalar",
        "default_filter": raw.get("default_filter") if isinstance(raw.get("default_filter"), dict) else None,
        "source": "llm",
    }


def _extract_json_object(text: str) -> Optional[dict]:
    try:
        return json.loads(text)
    except Exception:
        pass
    match = re.search(r"\{.*\}", text or "", re.S)
    if not match:
        return None
    try:
        return json.loads(match.group(0))
    except Exception:
        return None


def _try_llm_factor_draft(
    prompt: str,
    db: Session,
    current_user: UserModel,
    market: str = "CN",
    model_override: Optional[str] = None,
    usage_reference_id: Optional[str] = None,
) -> Optional[dict]:
    try:
        cfg = _llm_config_for_module(
            db,
            user_id=current_user.id,
            module_key="factor_generation",
            model_override=model_override,
        )
        if usage_reference_id:
            cfg["_usage_reference_id"] = usage_reference_id
        cfg["_usage_credits"] = _llm_tier_credit_cost(
            db,
            "factor_generation",
            model_override,
            current_user,
        )
        api_key = cfg.get("api_key")
        if not api_key or not _direct_llm_supported(cfg):
            return None
        market_code = _normalize_market_code(market)
        market_label = {"CN": "A股", "HK": "港股", "US": "美股"}[market_code]
        system_prompt = (
            f"你是{market_label}量化因子工程师。根据用户描述生成一个自定义因子草稿。"
            "只能使用变量 open, high, low, close, volume, amount, ma60；"
            "只能使用函数 MA, EMA, ROC, MOM, RSI, STD, ATR, BOLL_WIDTH, VOL_RATIO, "
            "OBV, VWAP, Ref, HHV, LLV, CROSS, IF, ABS, MAX, MIN, SUM, ATAN, DEGREES, SLOPE。"
            "参数必须用 $param_name。只返回JSON对象，字段为 name, display_name, category, "
            "output_type, description, expression, params, default_filter。"
        )
        content = _assistant_call_json_llm(
            cfg,
            [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": prompt},
            ],
            temperature=0.2,
            read_timeout=45,
        )
        raw = _extract_json_object(content)
        return _normalize_factor_draft(raw or {}, prompt, db)
    except Exception:
        return None


def _heuristic_factor_draft(prompt: str, db: Session) -> dict:
    text = (prompt or "").strip()
    lowered = text.lower()
    periods = _extract_periods(text)

    if any(k in text for k in ("金叉", "上穿")) or "cross" in lowered:
        short_period = periods[0] if periods else 5
        long_period = periods[1] if len(periods) > 1 else max(short_period * 4, 20)
        params = [
            _factor_param("short_period", "短周期", short_period, 2, 60),
            _factor_param("long_period", "长周期", long_period, 5, 250),
        ]
        draft = {
            "name": "ai_ma_cross",
            "display_name": "均线金叉信号",
            "category": "technical",
            "expression": "CROSS(MA(close, $short_period), MA(close, $long_period))",
            "description": text or "短期均线上穿长期均线形成的布尔信号。",
            "params": params,
            "output_type": "boolean",
            "default_filter": None,
            "source": "template",
        }
    elif any(k in text for k in ("放量", "量能", "成交量", "缩量")) or "volume" in lowered:
        short_period = periods[0] if periods else 5
        long_period = periods[1] if len(periods) > 1 else 20
        params = [
            _factor_param("short_window", "短期窗口", short_period, 2, 60),
            _factor_param("long_window", "长期窗口", long_period, 5, 250),
        ]
        draft = {
            "name": "ai_volume_ratio",
            "display_name": "量能比",
            "category": "technical",
            "expression": "MA(volume, $short_window) / MA(volume, $long_window)",
            "description": text or "短期均量与长期均量的比值。",
            "params": params,
            "output_type": "scalar",
            "default_filter": {"min": 1.5, "max": 10},
            "source": "template",
        }
    elif "rsi" in lowered or "相对强弱" in text:
        window = periods[0] if periods else 14
        params = [_factor_param("window", "窗口期", window, 2, 120)]
        draft = {
            "name": "ai_rsi",
            "display_name": "RSI相对强弱",
            "category": "technical",
            "expression": "RSI(close, $window)",
            "description": text or "RSI相对强弱指标。",
            "params": params,
            "output_type": "scalar",
            "default_filter": {"min": 20, "max": 80},
            "source": "template",
        }
    elif any(k in text for k in ("均线", "偏离", "乖离")) or "ma" in lowered:
        window = periods[0] if periods else 60
        params = [_factor_param("ma_period", "均线周期", window, 2, 250)]
        draft = {
            "name": "ai_ma_deviation",
            "display_name": f"{window}日均线偏离度",
            "category": "technical",
            "expression": "(close / MA(close, $ma_period) - 1) * 100",
            "description": text or "股价相对均线的偏离百分比。",
            "params": params,
            "output_type": "scalar",
            "default_filter": {"min": -15, "max": 15},
            "source": "template",
        }
    elif any(k in text for k in ("波动", "atr", "振幅")):
        window = periods[0] if periods else 14
        params = [_factor_param("window", "窗口期", window, 2, 120)]
        draft = {
            "name": "ai_atr",
            "display_name": "ATR波动率",
            "category": "technical",
            "expression": "ATR(high, low, close, $window)",
            "description": text or "基于真实波幅均值衡量价格波动。",
            "params": params,
            "output_type": "scalar",
            "default_filter": None,
            "source": "template",
        }
    elif any(k in text for k in ("突破", "新高", "位置")):
        window = periods[0] if periods else 60
        params = [_factor_param("window", "窗口期", window, 5, 250)]
        draft = {
            "name": "ai_price_position",
            "display_name": f"{window}日价格位置",
            "category": "technical",
            "expression": "(close - LLV(close, $window)) / (HHV(close, $window) - LLV(close, $window)) * 100",
            "description": text or "当前价格在指定窗口高低点区间中的位置。",
            "params": params,
            "output_type": "scalar",
            "default_filter": {"min": 70, "max": 100},
            "source": "template",
        }
    else:
        window = periods[0] if periods else 20
        params = [_factor_param("window", "窗口期", window, 2, 250)]
        draft = {
            "name": "ai_momentum",
            "display_name": f"{window}日动量",
            "category": "technical",
            "expression": "ROC(close, $window)",
            "description": text or "指定窗口内的价格变动率。",
            "params": params,
            "output_type": "scalar",
            "default_filter": {"min": -5, "max": 20},
            "source": "template",
        }

    draft["name"] = _dedupe_factor_name(db, draft["name"])
    validation_params = {p["name"]: p["default"] for p in draft["params"]}
    validation = factor_engine.validate_expression(draft["expression"], validation_params)
    draft["valid"] = validation.get("valid", False)
    draft["validation_error"] = validation.get("error")
    return draft


