@app.post("/api/factors/preview", dependencies=[Depends(require_permission("factors.manage"))])
def factor_preview(payload: FactorPreviewRequest, db: Session = Depends(get_db)):
    results = factor_engine.evaluate_factor_for_all(
        expression=payload.expression,
        params=payload.params,
        output_type=payload.output_type,
        filter_min=payload.filter_min,
        filter_max=payload.filter_max,
        limit=500,
        market=_normalize_market_code(payload.market),
    )
    total_stocks = 0
    try:
        total_stocks = (
            db.query(Stock)
            .filter(_stock_market_condition(payload.market))
            .count()
        )
    except Exception:
        total_stocks = len(results)
    hit_count = len(results)
    distribution = {}
    if results and payload.output_type == "scalar":
        values = [r["value"] for r in results]
        min_val = min(values) if values else 0
        max_val = max(values) if values else 0
        if max_val == min_val:
            distribution = {str(round(min_val, 2)): hit_count}
        else:
            bucket_size = (max_val - min_val) / 10
            for v in values:
                bucket_idx = min(int((v - min_val) / bucket_size), 9)
                bucket_start = round(min_val + bucket_idx * bucket_size, 2)
                key = str(bucket_start)
                distribution[key] = distribution.get(key, 0) + 1
    else:
        distribution = {"hit": hit_count, "miss": max(0, total_stocks - hit_count)}
    top_stocks = results[:10]
    return {
        "hit_count": hit_count,
        "total": total_stocks,
        "distribution": distribution,
        "top_stocks": top_stocks,
        "market": _normalize_market_code(payload.market),
    }


