@app.post("/api/factors/custom", dependencies=[Depends(require_permission("factors.manage"))])
def create_custom_factor(
    payload: CustomFactorCreate,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    existing = (
        db.query(CustomFactorModel)
        .filter(CustomFactorModel.name == payload.name)
        .first()
    )
    if existing:
        raise HTTPException(status_code=400, detail=f"因子名称 '{payload.name}' 已存在")
    params = {}
    if payload.params_json:
        try:
            param_list = json.loads(payload.params_json)
            params = {p["name"]: p["default"] for p in param_list}
        except Exception:
            params = {}
    validation = factor_engine.validate_expression(payload.expression, params)
    if not validation["valid"]:
        raise HTTPException(
            status_code=400, detail=f"表达式验证失败: {validation['error']}"
        )
    factor = CustomFactorModel(
        user_id=current_user.id,
        name=payload.name,
        display_name=payload.display_name or payload.name,
        category=payload.category,
        expression=payload.expression,
        description=payload.description,
        params_json=payload.params_json,
        output_type=payload.output_type,
        default_filter=payload.default_filter,
        group_name=payload.group_name,
        is_builtin=0,
        usage_count=0,
    )
    db.add(factor)
    db.commit()
    db.refresh(factor)
    return {"id": factor.id, "name": factor.name, "message": "因子创建成功"}


