@app.put("/api/factors/custom/{factor_id}", dependencies=[Depends(require_permission("factors.manage"))])
def update_custom_factor(
    factor_id: int,
    payload: CustomFactorUpdate,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    query = db.query(CustomFactorModel).filter(CustomFactorModel.id == factor_id)
    if normalize_user_role(current_user.role) == "admin":
        query = query.filter(
            or_(
                CustomFactorModel.user_id.is_(None),
                CustomFactorModel.user_id == current_user.id,
            )
        )
    else:
        query = query.filter(
            CustomFactorModel.user_id == current_user.id,
            CustomFactorModel.is_builtin != 1,
        )
    factor = query.first()
    if not factor:
        raise HTTPException(status_code=404, detail="因子不存在")
    if payload.expression is not None and payload.expression != factor.expression:
        params = {}
        params_json = payload.params_json or factor.params_json
        if params_json:
            try:
                param_list = json.loads(params_json)
                params = {p["name"]: p["default"] for p in param_list}
            except Exception:
                params = {}
        validation = factor_engine.validate_expression(payload.expression, params)
        if not validation["valid"]:
            raise HTTPException(
                status_code=400, detail=f"表达式验证失败: {validation['error']}"
            )
    update_data = payload.dict(exclude_unset=True)
    for key, value in update_data.items():
        setattr(factor, key, value)
    db.commit()
    db.refresh(factor)
    return {"id": factor.id, "name": factor.name, "message": "因子更新成功"}


