@app.post("/api/factors/init-builtin", dependencies=[Depends(require_permission("system.manage"))])
def init_builtin_factors(db: Session = Depends(get_db)):
    builtin_factors = factor_builtin.get_builtin_factors()
    added = 0
    updated = 0
    skipped = 0
    for fdef in builtin_factors:
        existing = (
            db.query(CustomFactorModel)
            .filter(CustomFactorModel.name == fdef["name"])
            .first()
        )
        if existing:
            if existing.is_builtin != 1:
                skipped += 1
                continue
            changed = False
            for field in (
                "display_name",
                "category",
                "expression",
                "params_json",
                "output_type",
                "default_filter",
                "description",
                "group_name",
            ):
                value = fdef[field]
                if getattr(existing, field) != value:
                    setattr(existing, field, value)
                    changed = True
            if changed:
                updated += 1
        else:
            factor = CustomFactorModel(
                name=fdef["name"],
                display_name=fdef["display_name"],
                category=fdef["category"],
                expression=fdef["expression"],
                description=fdef["description"],
                params_json=fdef["params_json"],
                output_type=fdef["output_type"],
                default_filter=fdef["default_filter"],
                group_name=fdef["group_name"],
                is_builtin=1,
                usage_count=0,
            )
            db.add(factor)
            added += 1
    db.commit()
    return {
        "message": "预置因子初始化完成",
        "added": added,
        "updated": updated,
        "skipped": skipped,
        "total": len(builtin_factors),
    }


# ─── Backtest Engine ──────────────────────────────────────────────────────────


def _build_strategy_runtime(strategy_code: str):
    """Return a per-stock strategy factory and entry label when code is executable."""
    if not (strategy_code or "").strip():
        return None, None
    try:
        import builtins as _builtins
        import math as _math

        safe_builtins = {
            "__build_class__": _builtins.__build_class__,
            "abs": abs,
            "bool": bool,
            "dict": dict,
            "enumerate": enumerate,
            "float": float,
            "int": int,
            "len": len,
            "list": list,
            "max": max,
            "min": min,
            "range": range,
            "round": round,
            "set": set,
            "sum": sum,
            "tuple": tuple,
        }
        namespace = {
            "__builtins__": safe_builtins,
            "__name__": "quartsys_strategy_backtest",
            "math": _math,
        }
        exec(compile(strategy_code, "<strategy_code>", "exec"), namespace, namespace)
        for value in namespace.values():
            if isinstance(value, type) and (
                callable(getattr(value, "on_bar", None))
                or callable(getattr(value, "on_tick", None))
            ):
                try:
                    instance = value()
                except Exception:
                    continue
                entry = "on_bar" if callable(getattr(instance, "on_bar", None)) else "on_tick"
                return value, f"{value.__name__}.{entry}"
    except Exception:
        return None, None
    return None, None


def _call_strategy_signal(instance, bar: dict):
    if callable(getattr(instance, "on_bar", None)):
        try:
            return instance.on_bar(bar)
        except TypeError:
            try:
                return instance.on_bar(
                    bar["date"],
                    bar["open"],
                    bar["high"],
                    bar["low"],
                    bar["close"],
                    bar["volume"],
                )
            except TypeError:
                pass
    if callable(getattr(instance, "on_tick", None)):
        try:
            return instance.on_tick(bar["close"], bar["date"])
        except TypeError:
            return instance.on_tick(bar["close"])
    return None


def _normalize_strategy_action(signal) -> str:
    if isinstance(signal, dict):
        action = signal.get("action") or signal.get("signal") or signal.get("side")
    else:
        action = signal
    if isinstance(action, bool):
        return "BUY" if action else "HOLD"
    text = str(action or "HOLD").strip().upper()
    if text in {"BUY", "LONG", "OPEN"}:
        return "BUY"
    if text in {"SELL", "EXIT", "CLOSE", "SHORT"}:
        return "SELL"
    return "HOLD"


class StrategyAutomationSaveRequest(BaseModel):
    id: Optional[int] = None
    name: Optional[str] = None
    strategy_id: int
    market: str = "CN"
    stock_pool_codes: List[str] = []
    factor_specs: List[Dict[str, object]] = []
    max_positions: int = 5
    per_trade_amount: float = 100000.0
    max_position_pct: float = 20.0
    run_interval_minutes: int = 5


def _json_or_default(raw: Optional[str], default):
    if not raw:
        return default
    try:
        parsed = json.loads(raw)
        return parsed if parsed is not None else default
    except Exception:
        return default


def _strategy_saved_factor_specs(db: Session, strategy: Strategy) -> tuple[list[int], list[dict]]:
    saved_params = _json_or_default(strategy.params_json, {})
    saved_specs = (
        saved_params.get("factor_specs")
        if isinstance(saved_params, dict)
        else None
    )
    if isinstance(saved_specs, list) and saved_specs:
        normalized_specs = [
            normalize_custom_factor_spec(spec)
            for spec in saved_specs
            if isinstance(spec, dict)
        ]
        factor_ids: list[int] = []
        for spec in normalized_specs:
            try:
                factor_id = int(spec.get("id") or spec.get("factor_id") or 0)
            except Exception:
                factor_id = 0
            if factor_id and factor_id not in factor_ids:
                factor_ids.append(factor_id)
        return factor_ids, normalized_specs

    factor_ids = _parse_strategy_factor_ids(strategy)
    factor_rows = _load_strategy_factor_rows(db, factor_ids)
    return factor_ids, _merge_strategy_factor_specs(factor_rows, [])


def _normalize_stock_pool_codes(
    values: list[str], market: str = "CN"
) -> list[str]:
    market_code = _normalize_market_code(market)
    result: list[str] = []
    seen: set[str] = set()
    for value in values or []:
        code = data_sources.normalize_stock_code(str(value or ""))
        if (
            not data_sources.is_supported_equity_code(code)
            or data_sources.equity_market(code) != market_code
            or code in seen
        ):
            continue
        seen.add(code)
        result.append(code)
        if len(result) >= 500:
            break
    return result


def _automation_factor_specs(row: StrategyAutomation) -> list[dict]:
    specs = _json_or_default(row.factor_specs_json, [])
    if not isinstance(specs, list):
        return []
    return [spec for spec in specs if isinstance(spec, dict)]


def _serialize_strategy_automation(db: Session, row: StrategyAutomation) -> dict:
    strategy = db.query(Strategy).filter(Strategy.id == row.strategy_id).first()
    last_result = _json_or_default(row.last_result_json, {})
    stock_pool_codes = _json_or_default(row.stock_pool_json, [])
    if not isinstance(stock_pool_codes, list):
        stock_pool_codes = []
    return {
        "id": row.id,
        "name": row.name,
        "status": row.status or "stopped",
        "market": _normalize_market_code(row.market),
        "strategy_id": row.strategy_id,
        "strategy_name": strategy.name if strategy else None,
        "stock_pool_codes": stock_pool_codes,
        "factor_specs": _automation_factor_specs(row),
        "max_positions": row.max_positions or 5,
        "per_trade_amount": row.per_trade_amount or 100000.0,
        "max_position_pct": row.max_position_pct or 20.0,
        "run_interval_minutes": row.run_interval_minutes or 5,
        "last_run_at": row.last_run_at.isoformat() if row.last_run_at else None,
        "last_error": row.last_error,
        "last_result": last_result if isinstance(last_result, dict) else {},
        "created_at": row.created_at.isoformat() if row.created_at else None,
        "updated_at": row.updated_at.isoformat() if row.updated_at else None,
    }


def _strategy_automation_for_user(
    db: Session, automation_id: int, user_id: int
) -> StrategyAutomation:
    row = (
        db.query(StrategyAutomation)
        .filter(
            StrategyAutomation.id == automation_id,
            StrategyAutomation.user_id == user_id,
        )
        .first()
    )
    if not row:
        raise HTTPException(status_code=404, detail="策略自动化绑定不存在")
    return row


def _strategy_automation_stock_pool(
    db: Session, automation: StrategyAutomation, strategy: Strategy
) -> tuple[list[str], str, dict]:
    market_code = _normalize_market_code(automation.market)
    manual_codes = _normalize_stock_pool_codes(
        _json_or_default(automation.stock_pool_json, []),
        market_code,
    )
    if manual_codes:
        return manual_codes, "manual_codes", {"manual_count": len(manual_codes)}

    factor_specs = _automation_factor_specs(automation)
    factor_ids: list[int] = []
    if not factor_specs:
        factor_ids, factor_specs = _strategy_saved_factor_specs(db, strategy)
    else:
        for spec in factor_specs:
            try:
                factor_id = int(spec.get("id") or spec.get("factor_id") or 0)
            except Exception:
                factor_id = 0
            if factor_id and factor_id not in factor_ids:
                factor_ids.append(factor_id)
    if factor_specs and factor_ids:
        limit = max(30, min(500, int((automation.max_positions or 5) * 20)))
        preview = preview_strategy_stock_pool(
            StrategyPoolPreviewRequest(
                factor_ids=factor_ids,
                factor_specs=factor_specs,
                limit=limit,
                universe_limit=1500,
                market=market_code,
            ),
            db,
        )
        rows = preview.get("rows") if isinstance(preview, dict) else []
        codes = _normalize_stock_pool_codes(
            [row.get("code") for row in rows or []], market_code
        )
        return codes, "strategy_factor_pool", {
            "factor_count": len(factor_specs),
            "preview_total": preview.get("total", 0) if isinstance(preview, dict) else 0,
        }

    latest_sq = latest_daily_subquery(db)
    rows = (
        db.query(Stock.code)
        .join(latest_sq, latest_sq.c.stock_code == Stock.code)
        .join(
            DailyPrice,
            and_(
                DailyPrice.stock_code == latest_sq.c.stock_code,
                DailyPrice.date == latest_sq.c.latest_date,
            ),
        )
        .filter(
            DailyPrice.close.isnot(None),
            _stock_market_condition(market_code),
        )
        .order_by(desc(func.coalesce(DailyPrice.amount, 0)))
        .limit(max(30, min(200, int((automation.max_positions or 5) * 20))))
        .all()
    )
    return _normalize_stock_pool_codes(
        [row[0] for row in rows], market_code
    ), "liquidity_fallback", {
        "message": "策略未配置因子或手动股票池，使用最新成交额靠前股票作为候选池",
    }


def _signal_requested_quantity(signal) -> Optional[int]:
    if not isinstance(signal, dict):
        return None
    for key in ("quantity", "shares", "size", "qty"):
        value = signal.get(key)
        try:
            parsed = int(float(value))
        except Exception:
            continue
        if parsed > 0:
            return parsed
    return None


def _align_buy_quantity(quantity: int, market: str = "CN") -> int:
    return _align_simulation_buy_quantity(quantity, market)


def _position_map_for_account(db: Session, account: SimulationAccount) -> dict[str, SimulationPosition]:
    rows = (
        db.query(SimulationPosition)
        .filter(SimulationPosition.account_id == account.id)
        .all()
    )
    return {
        data_sources.normalize_stock_code(row.stock_code): row
        for row in rows
        if row.stock_code
    }


def _account_mark_to_market_total(
    db: Session, account: SimulationAccount, positions: dict[str, SimulationPosition]
) -> float:
    total = float(account.balance or 0)
    for code, pos in positions.items():
        latest = (
            db.query(DailyPrice.close)
            .filter(DailyPrice.stock_code == code)
            .order_by(DailyPrice.date.desc())
            .first()
        )
        price = data_sources.safe_float(latest[0] if latest else None)
        if price is None:
            price = data_sources.safe_float(pos.current_price) or data_sources.safe_float(pos.avg_price) or 0
        total += float(pos.quantity or 0) * float(price or 0)
    return total


def _history_bar_from_row(row: dict, code: str, position_qty: int = 0) -> dict:
    open_v = data_sources.safe_float(row.get("开盘")) or 0
    high_v = data_sources.safe_float(row.get("最高")) or 0
    low_v = data_sources.safe_float(row.get("最低")) or 0
    close_v = data_sources.safe_float(row.get("收盘")) or 0
    volume_v = data_sources.safe_float(row.get("成交量")) or 0
    amount_v = data_sources.safe_float(row.get("成交额")) or 0
    return {
        "date": row.get("日期").isoformat() if hasattr(row.get("日期"), "isoformat") else str(row.get("日期")),
        "code": code,
        "open": float(open_v),
        "high": float(high_v),
        "low": float(low_v),
        "close": float(close_v),
        "volume": float(volume_v),
        "amount": float(amount_v),
        "position": position_qty,
    }


def _sync_strategy_instance_position(instance, position: Optional[SimulationPosition]) -> None:
    qty = int(position.quantity or 0) if position else 0
    if hasattr(instance, "position"):
        try:
            setattr(instance, "position", qty if qty > 0 else 0)
        except Exception:
            pass
    if position and hasattr(instance, "entry_price"):
        try:
            setattr(instance, "entry_price", float(position.avg_price or 0))
        except Exception:
            pass


_strategy_automation_run_lock = threading.RLock()


def _run_strategy_automation(
    db: Session,
    automation: StrategyAutomation,
    user: UserModel,
    *,
    triggered_by: str,
) -> dict:
    strategy = db.query(Strategy).filter(Strategy.id == automation.strategy_id).first()
    if not strategy:
        raise HTTPException(status_code=404, detail="策略不存在")
    strategy_cls, strategy_entry = _build_strategy_runtime(strategy.code or "")
    if strategy_cls is None:
        raise HTTPException(status_code=400, detail="策略代码不可执行，请先在 AI策略 页检查 on_bar/on_tick")

    market_code, market_config = _simulation_market_config(automation.market)
    minimum_quantity = int(market_config["min_quantity"])
    account = get_or_create_account(db, user, market_code)
    stock_codes, pool_source, pool_meta = _strategy_automation_stock_pool(
        db, automation, strategy
    )
    positions = _position_map_for_account(db, account)
    total_assets = _account_mark_to_market_total(db, account, positions)
    max_positions = max(1, min(int(automation.max_positions or 5), 50))
    per_trade_amount = max(1000.0, float(automation.per_trade_amount or 100000.0))
    max_position_pct = max(1.0, min(float(automation.max_position_pct or 20.0), 100.0))
    max_position_value = total_assets * max_position_pct / 100.0
    histories = load_screening_histories(db, stock_codes, None, 260)
    stock_rows = db.query(Stock).filter(Stock.code.in_(stock_codes)).all() if stock_codes else []
    stock_names = {row.code: row.name for row in stock_rows}

    actions: list[dict] = []
    buy_count = 0
    sell_count = 0
    hold_count = 0
    skipped_count = 0

    for code in stock_codes:
        hist_df = histories.get(code, pd.DataFrame())
        if hist_df.empty:
            skipped_count += 1
            actions.append({"code": code, "action": "SKIP", "reason": "缺少历史K线"})
            continue
        hist_df = hist_df.sort_values("日期")
        records = hist_df.to_dict("records")
        if not records:
            skipped_count += 1
            actions.append({"code": code, "action": "SKIP", "reason": "缺少历史K线"})
            continue
        try:
            instance = strategy_cls()
        except Exception as err:
            skipped_count += 1
            actions.append({"code": code, "action": "SKIP", "reason": f"策略实例化失败: {str(err)[:80]}"})
            continue

        position = positions.get(code)
        for raw in records[:-1]:
            try:
                _call_strategy_signal(instance, _history_bar_from_row(raw, code, 0))
            except Exception:
                continue
        _sync_strategy_instance_position(instance, position)
        latest_bar = _history_bar_from_row(
            records[-1],
            code,
            int(position.quantity or 0) if position else 0,
        )
        close_price = float(latest_bar.get("close") or 0)
        if close_price <= 0:
            skipped_count += 1
            actions.append({"code": code, "action": "SKIP", "reason": "最新价格无效"})
            continue

        try:
            signal = _call_strategy_signal(instance, latest_bar)
        except Exception as err:
            skipped_count += 1
            actions.append({"code": code, "action": "SKIP", "reason": f"策略信号失败: {str(err)[:80]}"})
            continue
        action = _normalize_strategy_action(signal)
        reason = signal.get("reason") if isinstance(signal, dict) else ""

        if action == "BUY":
            if position and position.quantity > 0:
                hold_count += 1
                actions.append({"code": code, "action": "HOLD", "reason": "已有持仓，跳过重复买入"})
                continue
            if len([p for p in positions.values() if (p.quantity or 0) > 0]) >= max_positions:
                skipped_count += 1
                actions.append({"code": code, "action": "SKIP", "reason": "达到最大持仓数"})
                continue
            order_cash = min(per_trade_amount, max_position_value, float(account.balance or 0))
            requested_qty = _signal_requested_quantity(signal)
            quantity = requested_qty if requested_qty else int(order_cash / close_price)
            quantity = _align_buy_quantity(quantity, market_code)
            if quantity < minimum_quantity:
                skipped_count += 1
                actions.append(
                    {
                        "code": code,
                        "action": "SKIP",
                        "reason": f"可用资金不足最小交易数量 {minimum_quantity} 股",
                    }
                )
                continue
            try:
                record = _execute_simulation_trade_order(
                    db,
                    account,
                    stock_code=code,
                    stock_name=stock_names.get(code) or code,
                    trade_type="buy",
                    quantity=quantity,
                    price=close_price,
                    market=market_code,
                )
                db.commit()
                buy_count += 1
                positions[code] = (
                    db.query(SimulationPosition)
                    .filter(
                        SimulationPosition.account_id == account.id,
                        SimulationPosition.stock_code == code,
                    )
                    .first()
                )
                actions.append(
                    {
                        "code": code,
                        "name": record.stock_name,
                        "action": "BUY",
                        "price": round(close_price, 2),
                        "quantity": quantity,
                        "reason": reason or "strategy_signal",
                    }
                )
            except HTTPException as err:
                db.rollback()
                skipped_count += 1
                actions.append({"code": code, "action": "SKIP", "reason": str(err.detail)[:120]})
        elif action == "SELL":
            if not position or position.quantity <= 0:
                hold_count += 1
                actions.append({"code": code, "action": "HOLD", "reason": "无持仓，忽略卖出信号"})
                continue
            requested_qty = _signal_requested_quantity(signal)
            quantity = min(int(position.quantity or 0), requested_qty or int(position.quantity or 0))
            if quantity < minimum_quantity:
                skipped_count += 1
                actions.append(
                    {
                        "code": code,
                        "action": "SKIP",
                        "reason": f"持仓不足最小交易数量 {minimum_quantity} 股",
                    }
                )
                continue
            try:
                record = _execute_simulation_trade_order(
                    db,
                    account,
                    stock_code=code,
                    stock_name=position.stock_name or stock_names.get(code) or code,
                    trade_type="sell",
                    quantity=quantity,
                    price=close_price,
                    market=market_code,
                )
                db.commit()
                sell_count += 1
                positions = _position_map_for_account(db, account)
                actions.append(
                    {
                        "code": code,
                        "name": record.stock_name,
                        "action": "SELL",
                        "price": round(close_price, 2),
                        "quantity": quantity,
                        "reason": reason or "strategy_signal",
                    }
                )
            except HTTPException as err:
                db.rollback()
                skipped_count += 1
                actions.append({"code": code, "action": "SKIP", "reason": str(err.detail)[:120]})
        else:
            hold_count += 1

    result = {
        "triggered_by": triggered_by,
        "market": market_code,
        "strategy_entry": strategy_entry,
        "pool_source": pool_source,
        "pool_meta": pool_meta,
        "candidate_count": len(stock_codes),
        "scanned_count": len(stock_codes),
        "buy_count": buy_count,
        "sell_count": sell_count,
        "hold_count": hold_count,
        "skipped_count": skipped_count,
        "actions": actions[-80:],
    }
    automation.last_run_at = datetime.utcnow()
    automation.last_error = None
    automation.last_result_json = json.dumps(result, ensure_ascii=False)
    automation.updated_at = datetime.utcnow()
    db.add(automation)
    db.commit()
    return result


