@app.post("/api/simulation/automation", dependencies=[Depends(require_permission("trading.use"))])
def save_strategy_automation(
    payload: StrategyAutomationSaveRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    strategy = db.query(Strategy).filter(Strategy.id == payload.strategy_id).first()
    if not strategy:
        raise HTTPException(status_code=404, detail="策略不存在")

    market_code = _normalize_market_code(payload.market)
    stock_pool_codes = _normalize_stock_pool_codes(
        payload.stock_pool_codes or [], market_code
    )
    factor_specs = [
        normalize_custom_factor_spec(spec)
        for spec in (payload.factor_specs or [])
        if isinstance(spec, dict)
    ]
    name = (payload.name or "").strip() or f"{strategy.name} 自动模拟"
    max_positions = max(1, min(int(payload.max_positions or 5), 50))
    per_trade_amount = max(1000.0, float(payload.per_trade_amount or 100000.0))
    max_position_pct = max(1.0, min(float(payload.max_position_pct or 20.0), 100.0))
    interval = max(1, min(int(payload.run_interval_minutes or 5), 240))

    if payload.id:
        row = _strategy_automation_for_user(db, payload.id, current_user.id)
    else:
        row = StrategyAutomation(user_id=current_user.id, status="stopped")
        db.add(row)

    row.strategy_id = strategy.id
    row.market = market_code
    row.name = name
    row.stock_pool_json = json.dumps(stock_pool_codes, ensure_ascii=False)
    row.factor_specs_json = json.dumps(factor_specs, ensure_ascii=False)
    row.max_positions = max_positions
    row.per_trade_amount = per_trade_amount
    row.max_position_pct = max_position_pct
    row.run_interval_minutes = interval
    row.updated_at = datetime.utcnow()
    db.commit()
    db.refresh(row)
    return _serialize_strategy_automation(db, row)


