@app.post("/api/simulation/automation/{automation_id}/run", dependencies=[Depends(require_permission("trading.use"))])
def run_strategy_automation_once(
    automation_id: int,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    row = _strategy_automation_for_user(db, automation_id, current_user.id)
    if not _strategy_automation_run_lock.acquire(blocking=False):
        raise HTTPException(status_code=409, detail="已有策略自动化任务正在执行")
    try:
        result = _run_strategy_automation(
            db,
            row,
            current_user,
            triggered_by="manual",
        )
    except HTTPException as err:
        row.last_run_at = datetime.utcnow()
        row.last_error = str(err.detail)
        row.last_result_json = json.dumps({"error": str(err.detail)}, ensure_ascii=False)
        row.updated_at = datetime.utcnow()
        db.add(row)
        db.commit()
        raise
    except Exception as err:
        db.rollback()
        row = _strategy_automation_for_user(db, automation_id, current_user.id)
        row.last_run_at = datetime.utcnow()
        row.last_error = str(err)[:300]
        row.last_result_json = json.dumps({"error": str(err)[:300]}, ensure_ascii=False)
        row.updated_at = datetime.utcnow()
        db.add(row)
        db.commit()
        raise HTTPException(status_code=500, detail=str(err)[:300])
    finally:
        _strategy_automation_run_lock.release()
    db.refresh(row)
    return {"automation": _serialize_strategy_automation(db, row), "result": result}


@app.delete("/api/simulation/automation/{automation_id}", dependencies=[Depends(require_permission("trading.use"))])
def delete_strategy_automation(
    automation_id: int,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    row = _strategy_automation_for_user(db, automation_id, current_user.id)
    db.delete(row)
    db.commit()
    return {"ok": True}


def scheduled_strategy_automation_runner():
    if not _strategy_automation_run_lock.acquire(blocking=False):
        return
    db = SessionLocal()
    try:
        now = datetime.utcnow()
        rows = (
            db.query(StrategyAutomation)
            .filter(StrategyAutomation.status == "running")
            .order_by(StrategyAutomation.last_run_at.asc())
            .limit(20)
            .all()
        )
        for row in rows:
            interval = max(1, int(row.run_interval_minutes or 5))
            last_run_at = row.last_run_at.replace(tzinfo=None) if row.last_run_at else None
            if last_run_at and (now - last_run_at).total_seconds() < interval * 60:
                continue
            user = db.query(UserModel).filter(UserModel.id == row.user_id).first()
            if not user:
                row.status = "failed"
                row.last_error = "用户不存在"
                row.updated_at = now
                db.commit()
                continue
            try:
                _run_strategy_automation(db, row, user, triggered_by="scheduler")
            except Exception as err:
                db.rollback()
                row = db.query(StrategyAutomation).filter(StrategyAutomation.id == row.id).first()
                if row:
                    row.last_run_at = now
                    row.last_error = str(getattr(err, "detail", err))[:300]
                    row.last_result_json = json.dumps(
                        {"error": row.last_error, "triggered_by": "scheduler"},
                        ensure_ascii=False,
                    )
                    row.updated_at = now
                    db.commit()
    finally:
        db.close()
        _strategy_automation_run_lock.release()


scheduler.add_job(
    scheduled_strategy_automation_runner,
    "interval",
    minutes=1,
    id="strategy_automation_runner",
    replace_existing=True,
    max_instances=1,
    coalesce=True,
    misfire_grace_time=90,
)


class BacktestRequest(BaseModel):
    strategy_code: str
    market: str = "CN"
    start_date: str
    end_date: Optional[str] = None
    initial_capital: float = 1000000.0
    commission: float = 0.0003
    factor_ids: List[int] = []
    factor_specs: List[Dict[str, object]] = []
    max_stocks: int = 1000


@app.post("/api/backtest/run", dependencies=[Depends(require_permission("backtest.run"))])
def run_backtest(
    payload: BacktestRequest,
    db: Session = Depends(get_db),
    current_user: UserModel = Depends(get_current_user),
):
    """简单回测引擎：基于策略筛选结果计算收益曲线"""
    try:
        from datetime import date as _date

        market_code = _normalize_market_code(payload.market)
        start = _date.fromisoformat(payload.start_date)
        requested_end_date = (payload.end_date or "").strip()
        continuous_to_latest = not bool(requested_end_date)
        if requested_end_date:
            end = _date.fromisoformat(requested_end_date)
        else:
            latest_date = (
                db.query(func.max(DailyPrice.date))
                .join(Stock, Stock.code == DailyPrice.stock_code)
                .filter(
                    DailyPrice.date >= start,
                    _stock_market_condition(market_code),
                )
                .scalar()
            )
            if latest_date is None:
                latest_date = (
                    db.query(func.max(DailyPrice.date))
                    .join(Stock, Stock.code == DailyPrice.stock_code)
                    .filter(_stock_market_condition(market_code))
                    .scalar()
                )
            if latest_date is None:
                return {"equity_curve": [], "metrics": {}, "trades": []}
            end = latest_date
        if start > end:
            raise ValueError("start_date cannot exceed end_date")

        factor_specs: List[Dict[str, object]] = []
        override_factor_ids: set[int] = set()
        for raw_spec in payload.factor_specs or []:
            if not isinstance(raw_spec, dict):
                continue
            try:
                factor_id = int(raw_spec.get("id") or raw_spec.get("factor_id") or 0)
            except Exception:
                factor_id = 0
            if factor_id:
                override_factor_ids.add(factor_id)
        default_factor_ids = [
            factor_id for factor_id in (payload.factor_ids or []) if factor_id not in override_factor_ids
        ]
        if default_factor_ids:
            factor_rows = (
                db.query(CustomFactorModel)
                .filter(CustomFactorModel.id.in_(default_factor_ids))
                .all()
            )
            factor_specs.extend(custom_factor_model_to_spec(f) for f in factor_rows)
        factor_specs.extend(
            normalize_custom_factor_spec(spec) for spec in (payload.factor_specs or [])
        )
        factor_specs = [spec for spec in factor_specs if spec.get("expression")]

        history_start = start - timedelta(days=420) if factor_specs else start
        max_stocks = max(50, min(int(payload.max_stocks or 1000), 5000))
        stock_universe_total = (
            db.query(func.count(func.distinct(DailyPrice.stock_code)))
            .join(Stock, Stock.code == DailyPrice.stock_code)
            .filter(
                DailyPrice.date >= start,
                DailyPrice.date <= end,
                _stock_market_condition(market_code),
            )
            .scalar()
            or 0
        )
        stock_universe_codes: List[str] = []
        stock_universe_limited = False
        if factor_specs and stock_universe_total > max_stocks:
            universe_rows = (
                db.query(
                    DailyPrice.stock_code,
                    func.coalesce(func.avg(DailyPrice.amount), 0).label("avg_amount"),
                )
                .join(Stock, Stock.code == DailyPrice.stock_code)
                .filter(
                    DailyPrice.date >= start,
                    DailyPrice.date <= end,
                    _stock_market_condition(market_code),
                )
                .group_by(DailyPrice.stock_code)
                .order_by(desc("avg_amount"))
                .limit(max_stocks)
                .all()
            )
            stock_universe_codes = [r.stock_code for r in universe_rows]
            stock_universe_limited = bool(stock_universe_codes)

        # 获取区间内所有日线数据；带因子时多取历史窗口用于滚动计算。
        price_query = (
            db.query(
                DailyPrice.date,
                DailyPrice.stock_code,
                DailyPrice.close,
                DailyPrice.open,
                DailyPrice.high,
                DailyPrice.low,
                DailyPrice.volume,
                DailyPrice.amount,
            )
            .join(Stock, Stock.code == DailyPrice.stock_code)
            .filter(
                DailyPrice.date >= history_start,
                DailyPrice.date <= end,
                _stock_market_condition(market_code),
            )
        )
        if stock_universe_codes:
            price_query = price_query.filter(DailyPrice.stock_code.in_(stock_universe_codes))
        rows = price_query.order_by(DailyPrice.stock_code, DailyPrice.date).all()
        if not rows:
            return {"equity_curve": [], "metrics": {}, "trades": []}

        # 按日期分组
        from collections import defaultdict

        daily_map: dict = defaultdict(list)
        history_map: dict = defaultdict(list)
        for r in rows:
            history_map[r.stock_code].append(
                {
                    "date": r.date,
                    "open": float(r.open or 0),
                    "close": float(r.close or 0),
                    "high": float(r.high or 0),
                    "low": float(r.low or 0),
                    "volume": float(r.volume or 0),
                    "amount": float(r.amount or 0),
                }
            )
            if r.date >= start:
                daily_map[r.date].append(r)

        dates = sorted(daily_map.keys())
        if not dates:
            return {"equity_curve": [], "metrics": {}, "trades": []}
        capital = payload.initial_capital
        equity = []
        trades = []
        factor_pass_map: Dict[str, Dict[object, bool]] = {}

        if factor_specs:
            for code, items in history_map.items():
                factor_df = prepare_factor_dataframe(pd.DataFrame(items))
                if factor_df.empty:
                    continue
                passed = pd.Series(True, index=factor_df.index)
                for spec in factor_specs:
                    passed = passed & factor_spec_pass_series(factor_df, spec)
                factor_pass_map[code] = {
                    factor_df.loc[idx, "date"]: bool(value)
                    for idx, value in passed.items()
                }

        strategy_cls, strategy_entry = _build_strategy_runtime(payload.strategy_code)
        if strategy_cls is not None:
            cash = payload.initial_capital
            positions: Dict[str, dict] = {}
            instances: Dict[str, object] = {}
            latest_close: Dict[str, float] = {}
            max_positions = 10

            for dt in dates:
                day_rows = daily_map[dt]
                if factor_specs:
                    day_rows = [
                        r
                        for r in day_rows
                        if factor_pass_map.get(r.stock_code, {}).get(dt, False)
                    ]
                signals = []
                for r in day_rows:
                    close_price = float(r.close or 0)
                    if close_price <= 0:
                        continue
                    latest_close[r.stock_code] = close_price
                    if r.stock_code not in instances:
                        try:
                            instances[r.stock_code] = strategy_cls()
                        except Exception:
                            continue
                    bar = {
                        "date": dt.isoformat(),
                        "code": r.stock_code,
                        "open": float(r.open or 0),
                        "high": float(r.high or 0),
                        "low": float(r.low or 0),
                        "close": close_price,
                        "volume": float(r.volume or 0),
                        "amount": float(r.amount or 0),
                        "position": positions.get(r.stock_code, {}).get("quantity", 0),
                    }
                    try:
                        signal = _call_strategy_signal(instances[r.stock_code], bar)
                    except Exception:
                        signal = None
                    action = _normalize_strategy_action(signal)
                    if action in {"BUY", "SELL"}:
                        signals.append((action, r, signal))

                for action, r, signal in signals:
                    if action != "SELL" or r.stock_code not in positions:
                        continue
                    close_price = float(r.close or 0)
                    pos = positions.pop(r.stock_code)
                    proceeds = pos["quantity"] * close_price * (1 - payload.commission)
                    cash += proceeds
                    trades.append(
                        {
                            "date": dt.isoformat(),
                            "stock_code": r.stock_code,
                            "action": "SELL",
                            "price": round(close_price, 2),
                            "quantity": pos["quantity"],
                            "reason": signal.get("reason") if isinstance(signal, dict) else "",
                        }
                    )

                buy_candidates = [
                    (r, signal)
                    for action, r, signal in signals
                    if action == "BUY" and r.stock_code not in positions
                ]
                slots = max(0, max_positions - len(positions))
                if slots and buy_candidates and cash > 0:
                    budget_each = cash / min(slots, len(buy_candidates))
                    for r, signal in buy_candidates[:slots]:
                        close_price = float(r.close or 0)
                        if close_price <= 0:
                            continue
                        quantity = int((budget_each * (1 - payload.commission)) / close_price)
                        if quantity <= 0:
                            continue
                        cost = quantity * close_price * (1 + payload.commission)
                        if cost > cash:
                            continue
                        cash -= cost
                        positions[r.stock_code] = {
                            "quantity": quantity,
                            "entry_price": close_price,
                        }
                        trades.append(
                            {
                                "date": dt.isoformat(),
                                "stock_code": r.stock_code,
                                "action": "BUY",
                                "price": round(close_price, 2),
                                "quantity": quantity,
                                "reason": signal.get("reason") if isinstance(signal, dict) else "",
                            }
                        )

                position_value = sum(
                    pos["quantity"] * latest_close.get(code, pos["entry_price"])
                    for code, pos in positions.items()
                )
                equity.append(
                    {
                        "date": dt.isoformat(),
                        "value": round(cash + position_value, 2),
                        "selected_count": len(day_rows),
                        "position_count": len(positions),
                    }
                )

            initial = payload.initial_capital
            final = equity[-1]["value"] if equity else initial
            total_return = (final - initial) / initial * 100
            days = (dates[-1] - dates[0]).days or 1
            annual_return = ((final / initial) ** (365 / days) - 1) * 100 if days > 0 and final > 0 else 0
            return {
                "equity_curve": equity,
                "metrics": {
                    "total_return": round(total_return, 2),
                    "annual_return": round(annual_return, 2),
                    "initial_capital": initial,
                    "final_capital": round(final, 2),
                    "trading_days": len(dates),
                    "factor_count": len(factor_specs),
                    "mode": "strategy_code",
                    "market": market_code,
                    "strategy_entry": strategy_entry,
                    "start_date": dates[0].isoformat() if dates else start.isoformat(),
                    "end_date": dates[-1].isoformat() if dates else end.isoformat(),
                    "continuous_to_latest": continuous_to_latest,
                    "stock_universe_count": len(stock_universe_codes) or stock_universe_total,
                    "stock_universe_total": stock_universe_total,
                    "stock_universe_limited": stock_universe_limited,
                },
                "trades": trades[-200:],
                "mode": "strategy_code",
                "market": market_code,
            }

        for dt in dates:
            day_rows = daily_map[dt]
            if factor_specs:
                day_rows = [
                    r
                    for r in day_rows
                    if factor_pass_map.get(r.stock_code, {}).get(dt, False)
                ]
            # 简单策略：等权持有当日涨幅前10%的股票
            changes = [
                (r.stock_code, (r.close - r.open) / r.open if r.open else 0)
                for r in day_rows
            ]
            changes.sort(key=lambda x: x[1], reverse=True)
            top = changes[: max(1, len(changes) // 10)]
            if top:
                avg_return = sum(c for _, c in top) / len(top)
                capital *= 1 + avg_return - payload.commission
            equity.append(
                {
                    "date": dt.isoformat(),
                    "value": round(capital, 2),
                    "selected_count": len(day_rows),
                }
            )

        initial = payload.initial_capital
        final = capital
        total_return = (final - initial) / initial * 100
        days = (dates[-1] - dates[0]).days or 1
        annual_return = ((final / initial) ** (365 / days) - 1) * 100 if days > 0 else 0

        return {
            "equity_curve": equity,
            "metrics": {
                "total_return": round(total_return, 2),
                "annual_return": round(annual_return, 2),
                "initial_capital": initial,
                "final_capital": round(final, 2),
                "trading_days": len(dates),
                "factor_count": len(factor_specs),
                "mode": "factor_top_decile",
                "market": market_code,
                "start_date": dates[0].isoformat() if dates else start.isoformat(),
                "end_date": dates[-1].isoformat() if dates else end.isoformat(),
                "continuous_to_latest": continuous_to_latest,
                "stock_universe_count": len(stock_universe_codes) or stock_universe_total,
                "stock_universe_total": stock_universe_total,
                "stock_universe_limited": stock_universe_limited,
            },
            "trades": trades,
            "mode": "factor_top_decile",
            "market": market_code,
        }
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


@app.get("/api/backtest/benchmark", dependencies=[Depends(require_permission("backtest.run"))])
def get_benchmark(
    start_date: str,
    end_date: str,
    code: str = "sh000300",
    db: Session = Depends(get_db),
):
    """获取回测基准指数，复用行情页指数目录。默认沪深300。"""
    try:
        from datetime import date as _date

        start = _date.fromisoformat(start_date)
        end = _date.fromisoformat(end_date)
        if start > end:
            raise ValueError("start_date cannot exceed end_date")
        index_meta = _market_index_by_code(code) or _market_index_by_code("sh000300")
        if not index_meta:
            raise ValueError("benchmark index not found")

        calendar_days = (end - start).days + 1
        history_days = max(90, min(calendar_days + 80, 1200))
        rows, source, source_error = _latest_index_history(index_meta, days=history_days)
        filtered_rows = []
        for item in rows:
            try:
                dt = _date.fromisoformat(str(item[0])[:10])
            except Exception:
                continue
            if start <= dt <= end:
                close_value = data_sources.safe_float(item[2])
                if close_value is not None and close_value > 0:
                    filtered_rows.append((dt, close_value))
        if filtered_rows:
            base = float(filtered_rows[0][1] or 1)
            return {
                "code": index_meta["code"],
                "name": index_meta["name"],
                "benchmark": [
                    {
                        "date": dt.isoformat(),
                        "value": round(close_value / base * 100, 2),
                        "return_pct": round((close_value / base - 1) * 100, 2),
                    }
                    for dt, close_value in filtered_rows
                ],
                "source": source,
                **({"error": source_error} if source_error else {}),
            }

        candidate_codes = list(
            {
                "".join(ch for ch in index_meta["code"] if ch.isdigit()),
                str(index_meta.get("cs_symbol") or ""),
            }
            - {""}
        )
        rows = (
            db.query(DailyPrice.date, DailyPrice.close)
            .filter(
                DailyPrice.stock_code.in_(candidate_codes),
                DailyPrice.date >= start,
                DailyPrice.date <= end,
            )
            .order_by(DailyPrice.date)
            .all()
        )
        if rows:
            base = float(rows[0].close or 1)
            return {
                "code": index_meta["code"],
                "name": index_meta["name"],
                "benchmark": [
                    {
                        "date": r.date.isoformat(),
                        "value": round(float(r.close or base) / base * 100, 2),
                        "return_pct": round(
                            (float(r.close or base) / base - 1) * 100, 2
                        ),
                    }
                    for r in rows
                ],
                "source": "database.daily_price",
            }

        value = 100.0
        points = []
        total_days = (end - start).days + 1
        for idx in range(total_days):
            current = start + timedelta(days=idx)
            if idx:
                seasonal = (((idx * 2) % 13) - 6) * 0.025
                drift = 0.018
                shock = -0.32 if idx % 31 == 0 else 0.0
                daily_return = drift + seasonal + shock
                value *= 1 + daily_return / 100
            points.append(
                {
                    "date": current.isoformat(),
                    "value": round(value, 2),
                    "return_pct": round(value - 100, 2),
                }
            )
        return {
            "code": index_meta["code"],
            "name": index_meta["name"],
            "benchmark": points,
            "source": "simulated_benchmark",
        }
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


if __name__ == "__main__":
    host = os.getenv("HOST", "0.0.0.0")
    port = int(os.getenv("PORT", "18427"))
    workers = max(1, int(os.getenv("WEB_CONCURRENCY", "1")))
    if workers > 1:
        uvicorn.run("main:app", host=host, port=port, workers=workers)
    else:
        uvicorn.run(app, host=host, port=port)
